// Close-out — "Contrôlé" = comportement actuel (delta zéro). Agressif :
// meilleur contest sur les tirs extérieurs (mid/3pts) réellement pris, mais
// avantage offensif accru sur les tirs à l'intérieur — le risque de
// pénétration/dribble derrière une fermeture trop appuyée, décrit par
// l'utilisateur.
const CLOSEOUT_STYLES = {
  "Contrôlé": { perimDefMod: 0,   insideMismatchMod: 0 },
  // Recalibré le 2026-09-29 (mesuré : gagnant partout, même face au jeu
  // en pénétration) : la pénétration derrière la fermeture coûte plus cher.
  "Agressif": { perimDefMod: .04, insideMismatchMod: 14 },
};

// Rebond offensif — "Normal" = comportement actuel (delta zéro). Agressif :
// plus de rebonds offensifs captés (offRebWeightMod positif), mais si le
// rebond est malgré tout perdu, la défense qui récupère bénéficie d'un
// petit bonus de transition sur SA possession suivante (repli plus lent —
// contrepartie explicitement demandée par l'utilisateur, "risque de prendre
// des contre-attaques"). Prudent : l'inverse, moins de rebonds offensifs
// mais jamais de bonus de transition donné à l'adversaire.
const OFF_REBOUND_STYLES = {
  // `transitionGuard` (audit 2026-09-29 : « Prudent » coûtait 2 pts sans
  // contrepartie) : joueurs déjà repliés, moins de contre-attaques adverses
  // après un rebond défensif.
  "Prudent":  { offRebWeightMod: -.15, transitionRisk: 0, transitionGuard: .22 },
  "Normal":   { offRebWeightMod: 0,    transitionRisk: 0 },
  "Agressif": { offRebWeightMod: .28,  transitionRisk: .40 },
};

// Gestion de fin de match (retour utilisateur, 2026-09 — "lever le pied" en
// cas de gros écart, gérer le "money time" à ±5 pts ; nommé ainsi plutôt que
// "gestion du rythme" pour ne pas se confondre avec Team.rhythm/RHYTHMS, le
// réglage de tempo Lent/Normal/Rapide qui existe déjà) : comportement
// AUTOMATIQUE (pas un choix par possession), donc volontairement PAS
// rattaché au tier tactique — dispo aux deux niveaux. "Standard" = comportement actuel
// inchangé : les mécanismes déjà existants de faute intentionnelle et de
// ralentissement du chrono en fin de match (voir playPossession/simulate)
// restent les SEULS effets de money-time. "Adaptatif" ajoute un vrai
// "garbage time" dès qu'un écart de 10+ points existe à partir du Q3
// (moins de hero-ball côté équipe qui mène large, un peu plus d'imprécision
// des deux côtés), et accentue légèrement le rythme des ~5 dernières
// minutes de match quand l'écart repasse sous les 5 points.
const ENDGAME_MANAGEMENT = {
  "Standard":  { blowoutThreshold: null, blowoutHeroMod: 0,    blowoutTovMod: 0,    closeGameTempoMod: 0 },
  // Audit 2026-09-29 : coûtait 1,5 pt sans contrepartie (pertes de balle en
  // garbage time) — plus de malus de pertes ; les titulaires sont mis au
  // repos dans un match plié (voir restStartersInBlowout), ce qui ménage
  // leur forme physique pour les matchs suivants.
  "Adaptatif": { blowoutThreshold: 10,   blowoutHeroMod: -.35, blowoutTovMod: 0,    closeGameTempoMod: .10, restStartersLead: 18 },
};

// Probabilité de base de blessure, par joueur sur le terrain et par possession
// (modulée par la fatigue dans applyFatigue). Calibré pour rester rare — voir
// rapport de calibrage : cible ~1 match sur 6-8 avec au moins une blessure.
const BASE_INJURY_RATE = 0.00013;

let __uid = 1;
function uid() { return __uid++; }

// Corrige à la racine le bug "Cette enchère est déjà terminée" (retour
// utilisateur Discord, 2026-09 — voir le commentaire sur refreshTransferMarket
// côté moteurbasket3.html pour le détail du symptôme et le premier correctif
// partiel, dd27f48) : `__uid` ci-dessus repart de 1 à chaque redémarrage du
// PROCESS SERVEUR (chaque déploiement Render, pas seulement chaque
// rechargement de page navigateur — dd27f48 n'empêchait que la génération
// locale côté navigateur en ligue partagée, jamais ce cas-ci). Si le marché
// (transferts/entraîneurs/analystes/recruteurs) doit se réapprovisionner
// juste après un redémarrage, les nouveaux id générés (1, 2, 3...) peuvent
// entrer en collision avec ceux, bien plus élevés, déjà utilisés par
// d'anciennes entités (joueurs, annonces déjà closes...) encore présentes
// dans la sauvegarde — `Array.prototype.find(l => l.id === listingId)`
// renvoie alors la MAUVAISE entité (souvent une annonce déjà fermée),
// exactement le symptôme observé, alors même que l'annonce affichée à
// l'écran (filtrée sur "open") reste la bonne.
//
// `bumpUidFloor` relève le plancher de `__uid` (jamais vers le bas, un appel
// tardif/redondant reste sans danger) ; `reseedUidFromSave` parcourt tout
// l'objet de sauvegarde brut (avant reconstruction des classes Team/League)
// à la recherche du plus grand champ numérique `id` déjà utilisé, où qu'il
// soit niché (joueurs, annonces de marché, entrées d'historique de
// matchs...) — un parcours générique plutôt qu'une liste figée des
// emplacements connus, pour ne jamais désynchroniser ce correctif d'un futur
// nouvel usage de uid(). Appelée à CHAQUE chargement d'une sauvegarde (voir
// server/store.js:deserialize/deserializeMultiLeague, et loadMyTeam côté
// moteurbasket3.html pour le miroir client) : rien à faire de spécial au
// démarrage du process, le tout premier chargement s'en charge déjà.
function scanMaxId(node, depth = 0) {
  if (depth > 40 || node == null || typeof node !== "object") return 0;
  let best = 0;
  if (Array.isArray(node)) {
    for (const item of node) {
      const v = scanMaxId(item, depth + 1);
      if (v > best) best = v;
    }
    return best;
  }
  for (const key of Object.keys(node)) {
    const v = node[key];
    if (key === "id" && typeof v === "number" && Number.isFinite(v)) {
      if (v > best) best = v;
    } else if (v && typeof v === "object") {
      const nested = scanMaxId(v, depth + 1);
      if (nested > best) best = nested;
    }
  }
  return best;
}
function bumpUidFloor(min) {
  if (Number.isFinite(min) && min > __uid) __uid = min;
}
function reseedUidFromSave(data) {
  const maxId = scanMaxId(data);
  if (maxId > 0) bumpUidFloor(maxId + 1);
}
// Réparation au chargement (bug du 2026-10-06, voir clockUidFloor) : deux
// joueurs d'une même ligue avec le même id. Le joueur d'un club de manager
// garde son id ; l'autre (club IA, centre de formation, agent libre) en
// reçoit un nouveau, reporté dans les références de SON club (composition,
// créneaux d'entraînement) et dans ses annonces du marché. Renvoie la liste
// des changements { from, to, name }.
function repairDuplicatePlayerIds(league) {
  if (!league || !Array.isArray(league.teams)) return [];
  const seen = new Map();
  const entries = [];
  league.teams.forEach((team, idx) => {
    if (!team) return;
    (team.players || []).forEach(p => entries.push({ p, team, idx, kind: "pro" }));
    (team.youthPlayers || []).forEach(p => entries.push({ p, team, idx, kind: "youth" }));
  });
  (league.freeAgents || []).forEach(p => entries.push({ p, team: null, idx: null, kind: "free" }));
  entries.forEach(e => {
    if (!e.p || e.p.id == null) return;
    const list = seen.get(e.p.id) || [];
    list.push(e); seen.set(e.p.id, list);
  });
  const changes = [];
  const remap = (node, from, to, depth = 0) => {
    if (!node || typeof node !== "object" || depth > 4) return;
    Object.keys(node).forEach(k => {
      if (node[k] === from) node[k] = to;
      else if (node[k] && typeof node[k] === "object") remap(node[k], from, to, depth + 1);
    });
  };
  seen.forEach(list => {
    if (list.length < 2) return;
    const keep = list.find(e => e.team && e.team.isHuman && e.kind === "pro") || list.find(e => e.team && e.team.isHuman) || list[0];
    list.filter(e => e !== keep).forEach(e => {
      const from = e.p.id, to = newPlayerId();
      e.p.id = to;
      if (e.team) {
        if (e.team.lineup) remap(e.team.lineup, from, to);
        (e.team.trainingSlots || []).forEach(sl => { if (sl && sl.playerId === from) sl.playerId = to; });
      }
      (league.transferListings || []).forEach(l => {
        if (l.playerId !== from) return;
        if ((e.kind === "free" && l.freeAgent) || (e.team && !l.freeAgent && l.sellerIdx === e.idx)) l.playerId = to;
      });
      changes.push({ from, to, name: e.p.name, team: e.team ? e.team.name : null });
    });
  });
  return changes;
}

// IDs de joueurs (demande utilisateur 2026-10-06 : « chaque joueur doit
// avoir un ID de 10 caractères ; un ID déjà pris par un joueur ne peut pas
// être réattribué ») : 10 chiffres (1000000000 à 9999999999), tirés au
// hasard et vérifiés contre le REGISTRE de tous les IDs déjà donnés (jamais
// vidé, même quand le joueur part à la retraite). Côté serveur, le registre
// est chargé depuis le stockage avant toute ligue et chaque nouvel ID y est
// ajouté (server/store.js : loadPlayerIdRegistry / flushPlayerIdRegistry).
const PLAYER_ID_MIN = 1000000000;
const PLAYER_ID_SPAN = 9000000000;
const usedPlayerIds = new Set();
const pendingPlayerIds = [];
function isPlayerIdFormat(id) {
  return Number.isInteger(id) && id >= PLAYER_ID_MIN && id < PLAYER_ID_MIN + PLAYER_ID_SPAN;
}
function registerPlayerIds(ids) {
  for (const id of ids || []) if (isPlayerIdFormat(id)) usedPlayerIds.add(id);
}
// Tirage indépendant de Math.random (que des tests et le moteur peuvent
// figer) : générateur cryptographique du serveur ou du navigateur.
let nodeCrypto = null;
try { if (typeof require === "function" && typeof window === "undefined") nodeCrypto = require("crypto"); } catch (e) { nodeCrypto = null; }
function randomPlayerIdOffset() {
  if (nodeCrypto && typeof nodeCrypto.randomInt === "function") return nodeCrypto.randomInt(0, PLAYER_ID_SPAN);
  const c = typeof globalThis !== "undefined" && globalThis.crypto && typeof globalThis.crypto.getRandomValues === "function" ? globalThis.crypto : null;
  if (c) { const a = new Uint32Array(2); c.getRandomValues(a); return (a[0] * 4294967296 + a[1]) % PLAYER_ID_SPAN; }
  return Math.floor(Math.random() * PLAYER_ID_SPAN);
}
function newPlayerId() {
  let id = PLAYER_ID_MIN + randomPlayerIdOffset();
  // Filet de sécurité : jamais de boucle sans fin, même avec un tirage figé
  // (place libre suivante).
  for (let tries = 0; usedPlayerIds.has(id); tries++) {
    id = tries < 20 ? PLAYER_ID_MIN + randomPlayerIdOffset() : PLAYER_ID_MIN + ((id - PLAYER_ID_MIN + 1) % PLAYER_ID_SPAN);
  }
  usedPlayerIds.add(id);
  pendingPlayerIds.push(id);
  return id;
}
// Nouveaux IDs pas encore enregistrés dans le stockage (vidé par l'appelant).
function takePendingPlayerIds() { return pendingPlayerIds.splice(0); }
function requeuePendingPlayerIds(ids) { pendingPlayerIds.push(...(ids || [])); }
function playerIdRegistrySize() { return usedPlayerIds.size; }

// Plancher d'horloge (bug du 2026-10-06, « joueur mis aux enchères sans
// raison ») : reseedUidFromSave ne voit que les championnats CHARGÉS depuis
// le redémarrage. Un nouvel id pouvait donc reprendre celui d'un joueur d'un
// championnat pas encore chargé ; un transfert entre championnats amenait
// ensuite deux joueurs de même id dans une ligue. Au démarrage, les ids
// repartent au-dessus de (ms écoulées depuis le 2026-01-01) × 10 : toujours
// au-delà de tout id déjà émis (jamais 10 ids par ms en moyenne sur la vie
// d'un process), et loin sous Number.MAX_SAFE_INTEGER.
const UID_CLOCK_EPOCH = Date.UTC(2026, 0, 1);
function clockUidFloor(now = Date.now()) {
  return Math.max(1, Math.floor((now - UID_CLOCK_EPOCH) * 10));
}
if (typeof module === "object" && module.exports && typeof window === "undefined") bumpUidFloor(clockUidFloor());

// Jeton privé non-devinable pour un lien de manager (retour utilisateur,
// 2026-09 : jusqu'à 10 vrais managers humains dans UNE ligue partagée — voir
// Team.managerLinkToken plus bas, généré une fois pour toutes à la création
// d'une équipe humaine). Cross-environnement (Node côté serveur ET
// navigateur côté client, voir wrapper UMD en tête de fichier) : préfère
// `crypto.randomBytes` de Node (résolu par un `require` PARESSEUX, jamais
// atteint côté navigateur où `require` n'existe simplement pas), sinon le
// Web Crypto du navigateur (`crypto.getRandomValues`, disponible partout où
// ce jeu tourne), et ne retombe sur Math.random() que si aucune des deux API
// n'est disponible (environnement de test minimal) — jamais le cas en
// production, juste pour ne jamais planter.
function randomHexToken(byteLength) {
  if (typeof require === "function") {
    try {
      const nodeCrypto = require("crypto");
      return nodeCrypto.randomBytes(byteLength).toString("hex");
    } catch (e) { /* pas un environnement Node avec le module crypto — on continue */ }
  }
  if (typeof crypto !== "undefined" && crypto && typeof crypto.getRandomValues === "function") {
    const bytes = new Uint8Array(byteLength);
    crypto.getRandomValues(bytes);
    return Array.from(bytes, b => b.toString(16).padStart(2, "0")).join("");
  }
  let out = "";
  for (let i = 0; i < byteLength * 2; i++) out += Math.floor(Math.random() * 16).toString(16);
  return out;
}

// Hasard du moteur (audit 2026-09-29, « une graine par match ») : tout le
// hasard de engine.js passe par rand01(). Hors match, c'est Math.random()
// (lu à chaque appel : les tests qui figent Math.random continuent de
// marcher). Pendant MatchEngine.simulate(), c'est un générateur à graine
// (mulberry32, voir withSeededRandom) : même graine + mêmes équipes + même
// instant => exactement le même match, événement par événement.
let seededRandom = null;
function rand01() { return seededRandom ? seededRandom() : Math.random(); }
// Générateur 32 bits déterministe, rapide et suffisant pour un jeu.
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
// Graine neuve (entier 32 bits non signé), tirée hors de tout générateur à
// graine pour que deux matchs ne partagent jamais la même par construction.
function newMatchSeed() { return Math.floor(Math.random() * 4294967296) >>> 0; }
// Exécute fn() avec rand01() branché sur la graine `seed`, puis restaure le
// générateur précédent (même en cas d'exception). Synchrone uniquement.
function withSeededRandom(seed, fn) {
  const previous = seededRandom;
  seededRandom = mulberry32(seed);
  try { return fn(); } finally { seededRandom = previous; }
}

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function rand(lo, hi) { return lo + rand01() * (hi - lo); }
function pick(arr) { return arr[Math.floor(rand01() * arr.length)]; }
function weightedPick(items, weightFn) {
  const weights = items.map(weightFn).map(w => Math.max(w, 0.0001));
  const total = weights.reduce((a, b) => a + b, 0);
  let r = rand01() * total;
  for (let i = 0; i < items.length; i++) {
    r -= weights[i];
    if (r <= 0) return items[i];
  }
  return items[items.length - 1];
}

// ---------------------------------------------------------------------
// COMMENTAIRES — banques de formulations pour varier le fil d'événements
// ---------------------------------------------------------------------
function say(templates, vars) {
  const t = pick(templates);
  // Élision (retour utilisateur 2026-09-25, refonte du live) : « de » devant
  // un nom qui commence par une voyelle ou un h devient « d' » — « Tir manqué
  // d'Adama Diallo », jamais « de Adama Diallo ».
  return t.replace(/(\bde )?\{(\w+)\}/g, (m, de, k) => {
    if (vars[k] === undefined) return m;
    const v = String(vars[k]);
    return de ? elideDe(v) : v;
  });
}
function elideDe(name) {
  return (/^[aeiouyàâäéèêëîïôöùûüh]/i.test(name) ? "d'" : "de ") + name;
}

