const NAME_POOL_CACHE = {};
// Réservoir complet d'une culture : historique + ajouts, sans doublon.
function namePoolOf(key) {
  if (NAME_POOL_CACHE[key]) return NAME_POOL_CACHE[key];
  const base = NAME_POOLS[key] || NAME_POOLS.fr;
  const extra = NAME_POOLS_EXTRA[key] || { first: [], last: [] };
  const uniq = list => list.filter((x, i) => list.indexOf(x) === i);
  NAME_POOL_CACHE[key] = { first: uniq(base.first.concat(extra.first)), last: uniq(base.last.concat(extra.last)) };
  return NAME_POOL_CACHE[key];
}
const FRANCE_FOREIGN_WEIGHT = 12;
function randomNationality(homeCountry = "fr") {
  if (!homeCountry || homeCountry === "fr" || !NATION_BY_CODE[homeCountry]) {
    return pickWeightedNation(NATIONS, Math.random()).code;
  }
  if (Math.random() < HOME_NATIONALITY_SHARE) return homeCountry;
  const others = NATIONS.filter(n => n.code !== homeCountry)
    .map(n => n.code === "fr" ? { ...n, weight: FRANCE_FOREIGN_WEIGHT } : n);
  return pickWeightedNation(others, Math.random()).code;
}

// Nationalité d'un joueur qui n'en a pas encore (sauvegarde d'avant les
// nationalités) : parmi les pays dont le réservoir de noms contient son
// nom de famille (un "Nakamura" sera japonais, un "Jokic" des Balkans…),
// pondérés comme d'habitude — sinon parmi tous les pays. Tirage
// DÉTERMINISTE (hash du nom complet), de sorte que le serveur et le
// navigateur tombent d'accord sans migration ; la valeur est ensuite
// sauvegardée avec le joueur et ne bouge plus jamais.
function nationalityFromName(name) {
  const full = String(name || "");
  const lastName = full.split(" ").slice(1).join(" ");
  const candidates = NATIONS.filter(n => (NAME_POOLS[n.pool]?.last || []).includes(lastName));
  const r = nationHash(full) / 4294967296;
  return pickWeightedNation(candidates.length ? candidates : NATIONS, r).code;
}

// Identité complète d'un NOUVEAU joueur : nationalité tirée d'abord, puis
// prénom/nom dans le réservoir de ce pays. `usedLastNames` (Set optionnel,
// voir pickUniqueLastName) évite les doublons de nom dans un même effectif.
// `homeCountry` (2026-09-28, pays des championnats) : pays du CLUB qui
// génère ce joueur — HOME_NATIONALITY_SHARE (60 %) de joueurs de ce pays,
// le reste tiré parmi les autres pays (la France n'y pèse alors plus que
// FRANCE_FOREIGN_WEIGHT, comme n'importe quelle nation de basket). Pour un
// club français, c'est exactement le tirage historique (France 60 %).
function generatePlayerIdentity(usedLastNames, homeCountry = "fr") {
  const nationality = randomNationality(homeCountry);
  const pool = namePoolOf(NATION_BY_CODE[nationality].pool);
  const lastName = usedLastNames ? pickUniqueLastName(pool.last, usedLastNames) : pick(pool.last);
  return { name: `${pick(pool.first)} ${lastName}`, nationality };
}

function nationName(code) {
  return NATION_BY_CODE[code]?.name || "";
}

// ---------------------------------------------------------------------
// Retraite des joueurs (retour utilisateur, 2026-09-28 : "comment tu
// gérerais ça", puis "comme pour le joueur qui souhaite partir parce qu'il
// est démotivé, il faudrait pouvoir le convaincre de jouer un peu plus",
// "3 par saison c'est bien, au début, à la moitié, à la fin", "gratuit").
// 1) ANNONCE : à la mise à jour qui clôt une saison (voir
//    League.announceRetirements, appelée après le vieillissement), un
//    vétéran peut annoncer que la saison qui commence sera sa dernière —
//    chance selon l'âge (RETIREMENT_ANNOUNCE_CHANCE_BY_AGE), réduite pour un
//    titulaire, augmentée pour un réserviste ; certaine à 39 ans (personne
//    ne joue au-delà de 40 ans).
// 2) DISCUSSION : pendant cette dernière saison, le manager peut tenter de
//    le convaincre de continuer (Team.talkRetirement), une fois par tiers
//    de saison (début / milieu / fin, RETIREMENT_TALK_PERIOD_WEEKS), soit 3
//    tentatives au plus, gratuitement. Pas de pourcentage affiché, un indice
//    (Team.retirementTalkStatus). Réussite : il joue une saison de plus et
//    repasse le tirage de l'annonce l'année suivante, un an plus vieux.
// 3) DÉPART : à la mise à jour de fin de saison suivante (League.
//    retireAnnouncedPlayers, AVANT le vieillissement), il quitte l'effectif
//    (enchère en cours annulée). Un club de l'IA le remplace aussitôt par un
//    jeune de niveau comparable ; un club humain qui tomberait sous
//    MIN_ROSTER_SIZE reçoit des joueurs de complément.
// ---------------------------------------------------------------------
const RETIREMENT_ANNOUNCE_CHANCE_BY_AGE = { 34: 0.10, 35: 0.25, 36: 0.45, 37: 0.65, 38: 0.85 };
const RETIREMENT_FORCED_AGE = 39; // annonce certaine, et plus aucune discussion possible
const RETIREMENT_ROLE_ANNOUNCE_FACTOR = { starter: 2 / 3, rotation: 1, reserve: 1.5 };
const RETIREMENT_TALK_BASE_CHANCE = 0.30;
const RETIREMENT_TALK_MENTAL_BONUS = 0.20; // jusqu'à +20 % pour un Mental à 100
const RETIREMENT_TALK_ROLE_BONUS = { starter: 0.15, rotation: 0.05, reserve: -0.10 };
const RETIREMENT_TALK_MOTIVATED_BONUS = 0.10; // motivation >= 85 (Très motivé)
const RETIREMENT_TALK_DEMOTIVATED_MALUS = 0.15; // motivation < 25 (Démotivé)
const RETIREMENT_TALK_AGE_PENALTY = 0.10; // par an au-delà de 36 ans
const RETIREMENT_TALK_MAX_CHANCE = 0.90;
const RETIREMENT_TALK_PERIOD_WEEKS = 4; // semaines 1-4, 5-8, 9-11
const RETIREMENT_TALK_PERIODS = 3;
const RETIREMENT_TALK_PERIOD_LABELS = ["début de saison", "milieu de saison", "fin de saison"];
const RETIREMENT_TALK_HOPEFUL_CHANCE = 0.45; // au-dessus : « Il hésite encore »
const RETIREMENT_ANNOUNCE_QUOTES = [
  "\"Cette saison sera ma dernière, je veux la vivre à fond\", annonce {player}.",
  "\"Le corps commence à dire stop. Je raccrocherai à la fin de la saison\", confie {player}.",
  "\"J'ai tout donné à ce sport, il est temps de penser à la suite après cette saison\", déclare {player}.",
  "\"Une dernière saison, et après je laisse la place aux jeunes\", sourit {player}.",
];

function retirementAnnounceQuoteFor(playerName) {
  return pick(RETIREMENT_ANNOUNCE_QUOTES).replace("{player}", playerName);
}

// Chance d'annoncer sa dernière saison à l'âge atteint (après le
// vieillissement de fin de saison) et selon son rôle dans la compo.
function retirementAnnounceChance(age, role) {
  if (age >= RETIREMENT_FORCED_AGE) return 1;
  const base = RETIREMENT_ANNOUNCE_CHANCE_BY_AGE[age] || 0;
  return clamp(base * (RETIREMENT_ROLE_ANNOUNCE_FACTOR[role] || 1), 0, 1);
}

// Tiers de la dernière saison (0 début, 1 milieu, 2 fin) d'après les mises
// à jour hebdomadaires écoulées depuis l'annonce (Player.retirementWeeks).
function retirementTalkPeriod(player) {
  return Math.min(RETIREMENT_TALK_PERIODS - 1, Math.floor((player.retirementWeeks || 0) / RETIREMENT_TALK_PERIOD_WEEKS));
}

// Chance qu'une discussion le convainque de continuer (jamais affichée
// telle quelle : voir Team.retirementTalkStatus).
function retirementTalkChance(player, role) {
  if (player.age >= RETIREMENT_FORCED_AGE) return 0;
  let chance = RETIREMENT_TALK_BASE_CHANCE
    + (mentalAverage(player) / 100) * RETIREMENT_TALK_MENTAL_BONUS
    + (RETIREMENT_TALK_ROLE_BONUS[role] || 0);
  if (player.form >= 85) chance += RETIREMENT_TALK_MOTIVATED_BONUS;
  else if (player.form < 25) chance -= RETIREMENT_TALK_DEMOTIVATED_MALUS;
  chance -= RETIREMENT_TALK_AGE_PENALTY * Math.max(0, player.age - 36);
  return clamp(chance, 0, RETIREMENT_TALK_MAX_CHANCE);
}

// Voir Player.eff : plancher du produit des facteurs de forme du moment.
const EFF_FACTOR_FLOOR = 0.5;

class Player {
  constructor({ name, position, height, age, attrs, aggressiveness, nationality, id = null }) {
    // ID à 10 chiffres jamais réattribué (voir newPlayerId) ; `id` fourni =
    // joueur rechargé d'une sauvegarde (son ID est alors inscrit au registre).
    if (id != null) { this.id = id; registerPlayerIds([id]); } else this.id = newPlayerId();
    this.name = name;
    // Nationalité (voir NATIONS) : fournie par generatePlayerIdentity pour un
    // nouveau joueur, ou par la sauvegarde ; à défaut (ancienne sauvegarde),
    // déduite du nom une fois pour toutes (nationalityFromName).
    this.nationality = NATION_BY_CODE[nationality] ? nationality : nationalityFromName(name);
    this.position = position;
    this.height = height;
    this.age = age;
    this.attrs = attrs; // {midRange, threePoint, inside, pass, rebound, block, dribble, agility, defOutside, defInside}
    this.aggressiveness = aggressiveness; // caractéristique cachée 1-100
    this.form = clamp(Math.round(rand(55, 90)), 1, 100);

    // Forme physique (voir CONDITION_STATES/currentCondition/
    // conditionLossForMinutes plus haut) : démarre fraîche (haut de la
    // fourchette "Pas de fatigue"/"Légèrement fatigué"), un joueur qui
    // rejoint l'effectif n'a par définition subi aucune charge de matchs
    // récente. `conditionUpdatedAt` : posé à la génération, sert de point de
    // départ pour la récupération (voir currentCondition).
    this.condition = clamp(Math.round(rand(80, 100)), 0, 100);
    this.conditionUpdatedAt = Date.now();

    // Blessure PERSISTANTE en cours, le cas échéant (voir INJURY_TYPES/
    // rollInjury/isCurrentlyInjured plus haut) : `null` = pas blessé. Un
    // joueur qui rejoint l'effectif n'a par définition aucune blessure en
    // cours. Contrairement à `injured` (état de match ci-dessous, remis à
    // false à CHAQUE match), ces deux champs survivent d'un match à l'autre.
    this.injuryType = null;
    this.injuryUntil = null;

    // Bonus temporaire de MVP (retour utilisateur, 2026-09 : "le mvp d'un
    // match doit avoir un petit bonus pour le match [...] +2 sur toutes ses
    // caracs") : posé par awardMatchMvp, lu en direct par eff() ci-dessous
    // (jamais overall(), volontairement, pour ne pas gonfler la note/le
    // salaire affiché d'un joueur pour une seule bonne performance), effacé
    // par recordMatchStatsForTeam dès qu'il a servi pour le tout PROCHAIN
    // match réellement joué par ce joueur (secondsPlayed > 0) — un seul
    // match "boosté", jamais plus. PAS remis à zéro par resetForMatch
    // ci-dessous (à dessein : il doit survivre jusqu'au prochain match
    // réellement joué, même si ce joueur reste sur le banc entre-temps).
    this.pendingMatchBoost = 0;

    // Potentiel GLOBAL (un seul plafond, échelle "overall" 1-99), fixé une
    // fois pour toutes à la génération du joueur — représente son talent
    // brut, pas encore révélé. Dépasser son potentiel n'empêche pas de
    // continuer à progresser, mais ça devient beaucoup, beaucoup plus dur
    // (voir trainWeek).
    {
      const [lo, hi] = potentialHeadroom(this.age);
      this.potential = clamp(Math.round(this.overall() + rand(lo, hi)), 1, 99);
    }

    // Potentiels PHYSIQUE et MENTAL (retour utilisateur, 2026-09 : "le
    // physique ne bouge qu'un peu au cours de la carrière du joueur, alors
    // que le mental peut bien évoluer et progresse durant toute la carrière
    // du joueur", voir le grand commentaire au-dessus de PHYSICAL_ATTRS/
    // MENTAL_ATTRS) : même principe que le potentiel global ci-dessus
    // (valeur ACTUELLE + marge selon l'âge, voir physicalPotentialHeadroom/
    // mentalPotentialHeadroom), mais un plafond PAR CARACTÉRISTIQUE plutôt
    // qu'un seul chiffre global — la progression naturelle hebdomadaire de
    // chaque caractéristique physique/mentale (voir Player.trainWeek) vise
    // son propre plafond ici, indépendamment des autres. Recalculés à
    // chaque construction (génération OU rechargement de sauvegarde), sauf
    // écrasement explicite par playerFromSave juste après si une valeur
    // sauvegardée existe déjà (mêmes raisons que Player.potential : sinon
    // ça se recalculerait au hasard à chaque rechargement, et un joueur déjà
    // entraîné directement sur ces caractéristiques avant ce changement de
    // règle garde ici un plafond dérivé de SA valeur actuelle, jamais une
    // réinitialisation).
    {
      const [plo, phi] = physicalPotentialHeadroom(this.age);
      this.physicalPotential = {};
      PHYSICAL_ATTRS.forEach(a => {
        this.physicalPotential[a] = clamp(Math.round((this.attrs[a] || 50) + rand(plo, phi)), 1, 99);
      });
      const [mlo, mhi] = mentalPotentialHeadroom(this.age);
      this.mentalPotential = {};
      MENTAL_ATTRS.forEach(a => {
        this.mentalPotential[a] = clamp(Math.round((this.attrs[a] || 25) + rand(mlo, mhi)), 1, 99);
      });
    }

    // Salaire hebdomadaire — voir salaryForOverall (grille salariale) :
    // dépend du niveau ACTUEL du joueur au poste où ses caractéristiques le
    // valorisent le mieux (voir levelCoefficientFor), pas d'une simple
    // moyenne brute — recalculé une fois par saison (voir Team.trainWeek),
    // jamais à la génération seule. `effectivePosition` (le poste retenu
    // pour ce calcul) est conservé à titre indicatif, pour l'UI.
    {
      const level = levelCoefficientFor(this.attrs, this.position);
      this.effectivePosition = level.position;
      this.salary = salaryForOverall(level.coefficient);
    }

    // Accumulateur fractionnaire caché : les gains hebdomadaires sont souvent
    // < 1 point. Sans ça, arrondir chaque semaine effacerait toute progression
    // lente (un joueur ne bougerait jamais si son gain hebdo reste sous 0,5).
    this._trainProgress = {};
    ATTRS.forEach(a => this._trainProgress[a] = 0);

    // état de match (réinitialisé à chaque simulate())
    this.fatigue = 0;       // 0 = frais, 100 = épuisé
    // Seuils de fatigue déclenchant un repos (voir MatchEngine.
    // substituteIfNeeded) — INDIVIDUELS et tirés au sort à CHAQUE match (voir
    // resetForMatch, même logique que le reste de resetForMatch pour tout ce
    // qui doit varier d'un match à l'autre). Deux seuils, pas un seul (voir
    // le grand commentaire dans resetForMatch pour le contexte complet et
    // pourquoi UN SEUL seuil bas, essayé d'abord, était une erreur) :
    // firstRestThreshold (bas) pour LA toute première sortie de CE joueur ce
    // match, restThreshold (haut, proche de l'ancienne constante à 82) pour
    // toutes les suivantes une fois la rotation initiale posée.
    this.firstRestThreshold = 82;
    this.restThreshold = 82;
    this.hasHadFirstRest = false;
    this.fouls = 0;
    this.disqualified = false;
    // Compteur de fautes techniques pour indiscipline (voir Sang-froid dans
    // le grand commentaire au-dessus d'ATTRS et MatchEngine.
    // maybeEjectForComposure) : deux fautes techniques dans le même match
    // valent exclusion, comme la vraie règle du basket. Remis à zéro à
    // chaque match dans resetForMatch ci-dessous, initialisé ici comme
    // fouls/disqualified juste au-dessus.
    this.technicalFouls = 0;
    // Compteur de fautes antisportives (retour utilisateur, 2026-09 : "les
    // fautes antisportives [...] Comme pour les fautes techniques 2
    // antisportives c'est exclusion. 1 antisportive et une technique c'est
    // exclusion aussi") : contact jugé excessif en défense plutôt qu'une
    // dissipation hors ballon (voir Discipline dans le grand commentaire
    // au-dessus d'ATTRS et MatchEngine.maybeCommitUnsportsmanlikeFoul) —
    // combiné à technicalFouls ci-dessus par MatchEngine.shouldEjectForFouls
    // pour décider de l'exclusion (2 antisportives, OU 1 antisportive + 1
    // technique). Même traitement que technicalFouls : remis à zéro à chaque
    // match dans resetForMatch, jamais persisté (stat de match uniquement).
    this.unsportsmanlikeFouls = 0;
    this.injured = false;
    this.onCourt = false;
    // Blessure PERSISTANTE encore en cours à l'entrée de CE match (voir
    // isCurrentlyInjured/injuryUntil plus haut) : snapshot pris UNE FOIS au
    // coup d'envoi (comme matchCondition), jamais recalculé pendant le match
    // — Team.resetForMatch s'en sert pour ne PAS aligner ce joueur (voir son
    // commentaire), et Team.backupsForSlot pour l'exclure du banc disponible.
    this.matchInjuryLocked = false;
    // Série de ratés/pertes de balle d'affilée EN MATCH (voir "mental" au-dessus
    // d'ATTRS) : incrémentée sur un tir manqué ou une perte de balle, remise à
    // 0 sur un tir réussi (voir playPossession) - alimente le malus de "tilt"
    // qui s'aggrave ou s'atténue selon mentalAverage(joueur) (voir plus haut,
    // au-dessus de PHYSICAL_ATTRS).
    this.consecutiveMisses = 0;
    // Poste occupé DANS CE MATCH (peut différer de this.position si le
    // joueur est aligné comme remplaçant sur un autre poste que le sien —
    // voir Team.lineup). Fixé à l'entrée sur le terrain (titulaire ou
    // remplacement), conservé jusqu'à la sortie du joueur.
    this.matchPosition = null;
    this.secondsPlayed = 0;
    // Temps de jeu de CE match, ventilé par poste RÉELLEMENT joué (clé =
    // matchPosition au moment où le temps est comptabilisé). Alimente le
    // journal de match (Player.matchLog, voir recordMatchStatsForTeam) et
    // les box-scores, PAS l'entraînement depuis le calendrier ancré
    // quotidien (voir trainingSecondsPlayedByPosition ci-dessous), remis à
    // zéro à CHAQUE match (voir resetForMatch), donc ne reflète jamais plus
    // que le dernier match joué.
    this.secondsPlayedByPosition = {};
    // Temps de jeu ventilé par poste, CUMULÉ sur tous les matchs du cycle
    // d'entraînement en cours (retour utilisateur, 2026-09 : "la semaine est
    // en fait une journée avec 3 matchs [...] un joueur doit jouer 30 min au
    // poste déterminé sur sa semaine pour prendre l'entrainement"). PAS
    // remis à zéro par resetForMatch (contrairement à secondsPlayedByPosition
    // ci-dessus) : accumulé match après match par applyFatigue, jusqu'à ce
    // que Team.trainWeek le consomme et le remette à zéro. Seul champ lu par
    // Team.trainablySecondsFor pour décider de l'entraînement.
    this.trainingSecondsPlayedByPosition = {};
    this.stats = this.emptyStats();

    // Mise en vente forcée en cas de déficit économique prolongé (voir
    // DEFICIT_ALERT_THRESHOLD/DEFICIT_GRACE_WEEKS et Team.trainWeek) — pas
    // encore un vrai marché des transferts, juste ce mécanisme de dernier
    // recours. `salePrice` reste `null` tant que le joueur n'est pas listé.
    this.forSale = false;
    this.salePrice = null;

    // Journal des matchs de la saison (retour utilisateur, 2026-09 : stats
    // de la Ligue + MVP de la dernière journée + pages joueur avec
    // "match par match + une moyenne") : une entrée par match RÉELLEMENT
    // joué (secondsPlayed > 0), jamais pour un forfait — voir
    // recordMatchStatsForTeam ci-dessous, seul point d'écriture. Remis à
    // zéro au passage de SAISON (voir Team.trainWeek), pas de semaine en
    // semaine : les stats affichées couvrent la saison EN COURS.
    this.matchLog = [];

    // Demande de transfert (voir le grand commentaire au-dessus de
    // TRANSFER_REQUEST_MOTIVATION_THRESHOLD) : `weeksAtLowMotivation` compte
    // les semaines CONSÉCUTIVES (voir Team.updateTransferRequests, appelée
    // chaque semaine) où ce joueur est resté sous le seuil de motivation
    // "proche de 0", remis à 0 dès qu'il repasse au-dessus (peu importe la
    // cause : discussion réussie, ou simplement une bonne interview de
    // jalon). `transferRequestActive` bascule à `true` une fois ce compteur
    // au seuil (3 semaines), et le reste jusqu'à ce que la motivation
    // remonte (voir updateTransferRequests) ou qu'une discussion réussisse
    // (voir Team.discussTransferRequest), jamais résolu par la simple vente
    // du joueur, qui le retire de l'effectif de toute façon.
    // `transferRequestQuote` : citation de presse figée au moment où la
    // demande démarre (voir transferRequestQuoteFor), affichée telle quelle
    // tant que `transferRequestActive` reste vrai.
    this.weeksAtLowMotivation = 0;
    this.transferRequestActive = false;
    this.transferRequestQuote = null;
    // Une seule discussion par demande de transfert (retour utilisateur,
    // 2026-09-28 : "il faut pouvoir le faire une seule fois, sinon c'est
    // abusé") : passe à `true` après une discussion ratée, remis à `false`
    // quand la demande se referme ou qu'une nouvelle démarre.
    this.transferRequestDiscussed = false;

    // Retraite (voir le grand commentaire de RETIREMENT_ANNOUNCE_CHANCE_BY_AGE) :
    // `retiringAfterSeason` = a annoncé que la saison en cours est sa
    // dernière ; `retirementWeeks` = mises à jour hebdomadaires écoulées
    // depuis l'annonce (donne le tiers de saison) ; `retirementTalks` = tiers
    // (0/1/2) où une discussion a déjà échoué ; `retirementQuote` = citation
    // de presse figée à l'annonce.
    this.retiringAfterSeason = false;
    this.retirementWeeks = 0;
    this.retirementTalks = [];
    this.retirementQuote = null;

    // Contrat (voir CONTRACT_MIN_SEASONS, demande du 2026-10-01) : posé par
    // League.ensureContracts (ou à la signature), jamais à la génération.
    this.contractUntilSeason = null;
    this.nextSalary = null;
    this.lastContractOfferWeek = null;
    this.contractRefusals = 0;
    this.raiseRequest = null;
    this.raiseRequestSeason = null;
    this.extensionRequestSeason = null;
  }

  // Applique une semaine d'entraînement. `attrWeights` est une map
  // {caractéristique: poids} calculée par Team.trainWeek pour CE joueur —
  // elle combine déjà tout ce qui influe sur le rendement : le poids de la
  // caractéristique dans le programme choisi (plein pour un programme "pur",
  // dilué pour un programme composite — voir TRAINING_PROGRAMS), l'aptitude
  // de son poste sur CETTE caractéristique précise, le gabarit, la dilution
  // liée au nombre de postes couverts cette semaine, et la proportion du
  // dernier match jouée. Un poids de 0 (ou absent) = caractéristique non
  // entraînée cette semaine pour ce joueur : elle ne bouge plus du tout par
  // l'entraînement (seuls le vieillissement/déclin s'appliquent encore).
  // `trainerMult` (>= 1) est le bonus apporté par l'entraîneur du club
  // (staff, sans aucun effet sur les matchs) ; s'applique à toute la
  // progression de la semaine. `synergyAttrs` (optionnel, Set<string>) liste
  // les caractéristiques dont le poids vient UNIQUEMENT de la synergie (voir
  // TRAINING_SYNERGY côté Team.trainWeek), pas du programme choisi lui-même —
  // voir plus bas pourquoi c'est nécessaire pour respecter la règle "une
  // caractéristique liée progresse toujours moins qu'une caractéristique
  // directement travaillée". Renvoie la liste des caractéristiques qui ont
  // bougé, sous la forme [{attr, before, after}, ...].
  // Retour utilisateur (2026-09 : "on ne dit plus entrainement individuel
  // mais entrainement des fondamentaux, et ça ne doit entrainer que les
  // fondamentaux" — puis "le physique ne bouge qu'un peu au cours de la
  // carrière du joueur, alors que le mental peut bien évoluer et progresse
  // durant toute la carrière du joueur") : 3 boucles distinctes désormais,
  // une par catégorie (voir le grand commentaire au-dessus de
  // PHYSICAL_ATTRS/MENTAL_ATTRS/FUNDAMENTAL_ATTRS) au lieu d'une seule
  // boucle ATTRS.forEach uniforme.
  // `opts` (retour utilisateur 2026-10-01, entraînement v2) : { ceilingBonus
  // (plafond repoussé par l'entraîneur), ceilingWeights (poids nominal du
  // programme pour le plafond), mentalMult (expérience/parrainage) }.
  trainWeek(attrWeights, trainerMult = 1, synergyAttrs = null, opts = null) {
    const gains = [];
    const ceilingBonus = (opts && opts.ceilingBonus) || 0;
    const ceilingWeights = (opts && opts.ceilingWeights) || null;
    const mentalMult = opts && typeof opts.mentalMult === "number" ? opts.mentalMult : 1;
    const roomDivisor = (opts && opts.roomDivisor) || TRAINING_ROOM_DIVISOR;
    const growth = growthFactorForAge(this.age);
    const decline = declineFactorForAge(this.age);
    const physGrowth = physicalGrowthFactorForAge(this.age);
    const physDecline = physicalDeclineFactorForAge(this.age);
    const mentGrowth = mentalGrowthFactorForAge(this.age);

    // Matérialise un delta fractionnaire sur une caractéristique, factorisé
    // ici, partagé par les 3 catégories ci-dessous (avant : dupliqué dans la
    // seule boucle ATTRS.forEach d'origine).
    const applyDelta = (a, before, delta) => {
      this._trainProgress[a] = (this._trainProgress[a] || 0) + delta;
      const whole = Math.trunc(this._trainProgress[a]);
      if (whole !== 0) {
        this._trainProgress[a] -= whole;
        const after = clamp(before + whole, 1, 99);
        if (after !== before) {
          gains.push({ attr: a, before, after });
        }
        this.attrs[a] = after;
      }
    };

    // Fondamentaux : SEULE catégorie entraînable directement (voir
    // TRAINING_PROGRAMS, désormais restreint aux 13 fondamentaux) — logique
    // de progression/déclin INCHANGÉE, juste restreinte à FUNDAMENTAL_ATTRS
    // au lieu de la totalité d'ATTRS.
    FUNDAMENTAL_ATTRS.forEach(a => {
      const before = this.attrs[a];
      const weight = clamp((attrWeights && attrWeights[a]) || 0, 0, 2);
      let delta = 0;

      if (growth > 0 && weight > 0) {
        // Le potentiel est GLOBAL (un seul chiffre), mais chaque caractéristique
        // garde son propre plafond dérivé de ce chiffre : une caractéristique
        // entraînée peut être poussée un peu au-dessus de la moyenne du
        // joueur, mais rien ne grimpe vers 99 sans rapport avec son potentiel.
        // Au-delà de son propre plafond, une caractéristique peut toujours
        // progresser, mais beaucoup plus difficilement (facteur ~1/8) —
        // jamais un mur infranchissable.
        // Plafond souple + bonus d'entraîneur (retour utilisateur 2026-10-01).
        const ceilWeight = ceilingWeights && ceilingWeights[a] != null ? ceilingWeights[a] : weight;
        const ceiling = clamp(this.potential + 12 * Math.min(ceilWeight, 1) + ceilingBonus, 1, 99);
        const gap = ceiling - before;
        // `progressRoom` grandit avec l'écart à combler : c'est ce qui permet
        // à une caractéristique très en retard sur un potentiel élevé de
        // rattraper vite (retour utilisateur d'origine). Mais SANS
        // correction, ce même mécanisme retournait le classement : une
        // caractéristique de synergie (poids réduit, ex. x0.4 — voir
        // TRAINING_SYNERGY) partant très bas profitait d'un écart énorme et
        // finissait par progresser AUTANT, voire PLUS, que la caractéristique
        // réellement entraînée cette semaine-là (retour utilisateur : "il
        // prend l'entraînement comme il faut en DE mais il monte mieux sur
        // les autres caracs") — alors que le commentaire de la synergie,
        // plus haut, promet l'inverse. Pour une caractéristique de synergie,
        // la marge de progression est donc elle aussi réduite au prorata de
        // son poids (déjà < 1 par construction) : ça préserve le rattrapage
        // rapide vers un fort potentiel pour la caractéristique VRAIMENT
        // entraînée (poids proche de 1, `roomScale` alors inchangé), tout en
        // garantissant qu'une caractéristique de synergie reste structurellement
        // plus lente (poids² au lieu de poids). Les programmes composites
        // (plusieurs caractéristiques du même programme, voir
        // WEIGHT_BY_PROGRAM_SIZE) ne sont eux jamais concernés : ce ne sont
        // pas des caractéristiques de synergie.
        const roomScale = (synergyAttrs && synergyAttrs.has(a)) ? clamp(weight, 0, 1) : 1;
        const progressRoom = trainingProgressRoom(gap, roomDivisor) * roomScale;
        // `weight` porte déjà tout ce qui module le rendement (voir
        // Team.trainWeek) : une caractéristique NON entraînée cette semaine
        // (poids 0) ne bouge plus DU TOUT — seuls les joueurs alignés sur
        // le(s) poste(s) entraîné(s) progressent (demande explicite de
        // septembre 2026 : "pour les joueurs qui ne correspondent pas au
        // poste(s) entrainé(s) aucune caractéristique ne doit monter").
        // Détermination (audit des attributs 2026-10-06) : un joueur
        // déterminé progresse plus vite sur ses programmes.
        delta += growth * weight * progressRoom * rand(0.5, 1.3) * trainerMult * determinationTrainingMult(this);
      }
      if (decline > 0) {
        // Une caractéristique entraînée cette semaine décline moins vite.
        const declineReduction = weight > 0 ? clamp(1 - 0.6 * Math.min(weight, 1), 0.2, 1) : 1;
        delta -= decline * rand(0.3, 1.0) * declineReduction;
      }
      applyDelta(a, before, delta);
    });

    // Physique : progression NATURELLE seule (indépendante de attrWeights,
    // donc de l'entraînement des fondamentaux choisi cette semaine, retiré
    // de TRAINING_PROGRAMS), vise physicalPotential[a] jusqu'à maturité
    // (~27/28 ans, physicalGrowthFactorForAge), puis décline à partir de 34
    // ans (physicalDeclineFactorForAge). PLUS un tout petit supplément de
    // synergie : si une caractéristique fondamentale liée à celle-ci a été
    // entraînée cette semaine (voir TRAINING_SYNERGY plus haut, qui reprend
    // déjà ces associations, ex. "Jeu intérieur" → Force), `attrWeights[a]`
    // porte alors le poids dilué de cette synergie (voir Team.trainWeek) —
    // un simple supplément, jamais un second levier d'entraînement à part
    // entière (coefficient volontairement petit, 0.04, face à progressRoom
    // ~0.10-1.1 du terme naturel juste au-dessus). Comme le terme naturel,
    // actif seulement tant que le joueur progresse encore physiquement
    // (physGrowth > 0, jamais après le début du déclin à 34 ans).
    PHYSICAL_ATTRS.forEach(a => {
      const before = this.attrs[a];
      let delta = 0;
      const ceiling = (this.physicalPotential && this.physicalPotential[a]) || before;
      // `crossWeight` : un attribut Physique n'est plus JAMAIS entraîné
      // directement (retiré de TRAINING_PROGRAMS), donc tout poids non-nul
      // ici vient forcément de TRAINING_SYNERGY (voir Team.trainWeek). Même
      // correction que pour les fondamentaux de synergie ci-dessus (roomScale
      // au prorata du poids) : SANS ça, un attribut Physique très en retard
      // sur son propre plafond peut rattraper plus vite, cette semaine-là,
      // que le fondamental réellement entraîné — exactement le bug corrigé
      // plus haut (voir synergy_training_test.js, désormais aussi couvert
      // pour le cas fondamental → synergie physique). Quand crossWeight est
      // nul (aucune synergie active cette semaine sur cet attribut précis),
      // la progression naturelle reste intégrale (roomScale = 1) : le
      // Physique continue bien d'évoluer tout seul, indépendamment de ce qui
      // est entraîné, comme voulu. `crossWeight²` (et non simplement
      // `crossWeight`) : la marge de synergie du fondamental (poids déjà
      // dilué ×0.4, voir TRAINING_SYNERGY) reste petite, mais un fondamental
      // synergique peut partir d'un très gros écart à son propre plafond
      // (potential + 12) tout comme un attribut Physique peut partir d'un
      // gros écart à SON plafond (physicalPotential) — la seule dilution
      // ×poids ne suffit alors pas à garder le fondamental réellement
      // entraîné devant (constaté par synergy_training_test.js) ; au carré,
      // la marge de rattrapage synergique reste toujours structurellement
      // plus lente, quel que soit l'écart de départ des deux côtés.
      const crossWeight = clamp((attrWeights && attrWeights[a]) || 0, 0, 1);
      if (physGrowth > 0) {
        const gap = ceiling - before;
        const beyondCeilingMult = gap > 0 ? 1 : 0.12;
        const roomScale = crossWeight > 0 ? crossWeight * crossWeight : 1;
        const progressRoom = (Math.max(gap, 0) / 20 + 0.10) * roomScale;
        delta += physGrowth * progressRoom * beyondCeilingMult * rand(0.5, 1.3);
        if (crossWeight > 0) {
          delta += physGrowth * crossWeight * 0.04 * rand(0.5, 1.3);
        }
      }
      if (physDecline > 0) {
        delta -= physDecline * rand(0.3, 1.0);
      }
      applyDelta(a, before, delta);
    });

    // Mental : même principe que le Physique ci-dessus (progression
    // NATURELLE + petit supplément de synergie, voir TRAINING_SYNERGY), vise
    // mentalPotential[a], ralentit avec l'âge (mentalGrowthFactorForAge)
    // mais NE DÉCLINE JAMAIS (aucun terme négatif ici, volontairement —
    // retour utilisateur : "le mental peut bien évoluer et progresse durant
    // toute la carrière du joueur"). Coefficient de synergie (0.03) encore
    // un peu plus petit que celui du Physique (0.04) : le Mental progresse
    // déjà plus lentement par nature (`progressRoom` vise un écart deux fois
    // plus large, /25 contre /20).
    MENTAL_ATTRS.forEach(a => {
      const before = this.attrs[a];
      const ceiling = (this.mentalPotential && this.mentalPotential[a]) || before;
      const gap = ceiling - before;
      const beyondCeilingMult = gap > 0 ? 1 : 0.15;
      // Même correction roomScale que pour le Physique juste au-dessus (voir
      // son commentaire, y compris le choix de `crossWeight²`) : un attribut
      // Mental n'est lui non plus jamais entraîné directement, tout poids
      // ici vient de TRAINING_SYNERGY.
      const crossWeight = clamp((attrWeights && attrWeights[a]) || 0, 0, 1);
      const roomScale = crossWeight > 0 ? crossWeight * crossWeight : 1;
      const progressRoom = (Math.max(gap, 0) / 25 + 0.08) * roomScale;
      // Expérience (minutes) et parrainage (retour utilisateur 2026-10-01).
      let delta = mentGrowth * progressRoom * beyondCeilingMult * rand(0.5, 1.3) * mentalMult;
      if (crossWeight > 0 && mentGrowth > 0) {
        delta += mentGrowth * crossWeight * 0.03 * rand(0.5, 1.3);
      }
      applyDelta(a, before, delta);
    });

    return gains;
  }

  emptyStats() {
    return {
      pts: 0, reb: 0, oreb: 0, dreb: 0, ast: 0, stl: 0, blk: 0, tov: 0, pf: 0,
      fgm2: 0, fga2: 0, fgm3: 0, fga3: 0, ftm: 0, fta: 0,
      // paintAtt/paintMade (retour utilisateur, 2026-09, "rapport de scouting" :
      // tendances chiffrées d'un adversaire, coïncidant avec de vrais leviers
      // tactiques déjà en jeu). Sous-ensemble de fga2/fgm2 ne comptant QUE les
      // tirs pris en zone "inside" (raquette/poste), fga2/fgm2 eux-mêmes
      // INCHANGÉS (toujours inside+mid confondus) : ajout strictement additif,
      // aucun comportement de simulation existant ne change. Sert à calculer,
      // côté UI, la part des tirs pris dans la raquette (utile pour distinguer
      // un adversaire tourné vers l'intérieur d'un adversaire de périmètre),
      // voir computeScoutingTendencies dans moteurbasket3.html.
      paintAtt: 0, paintMade: 0,
      // Origine des points marqués (retour utilisateur 2026-09-24, repris
      // le 2026-09-28 : "comment ils marquent leurs points"), classée par le
      // moteur au moment du panier (voir playPossession) :
      // - par type de tir (chaque point une fois, avec ftm) : ptsPaint
      //   (raquette), ptsMid, pts3 ;
      // - par situation (cumulables) : ptsSecondChance (après rebond
      //   offensif) ou ptsTransition (contre-attaque), jamais les deux,
      //   lancers francs de la possession compris ; ptsAssisted / ptsSolo
      //   (panier sur passe décisive ou non, hors lancers francs).
      ptsPaint: 0, ptsMid: 0, pts3: 0, ptsSecondChance: 0, ptsTransition: 0, ptsAssisted: 0, ptsSolo: 0,
      // +/- (retour utilisateur, 2026-09 : "ajouté les colonnes de stats :
      // évaluation et +/- [...] dans les box score (match terminé et aussi
      // sur les live)") : différentiel de points marqués/encaissés pendant
      // que CE joueur était sur le terrain, voir
      // MatchEngine.applyPlusMinusForPoints (mis à jour à CHAQUE panier/
      // lancer franc marqué, jamais recalculé après coup).
      plusMinus: 0,
    };
  }

  resetForMatch(now = Date.now(), recoveryPerDay = CONDITION_RECOVERY_PER_DAY) {
    this.fatigue = 0;
    // Rotations/temps de jeu (retour utilisateur, 2026-09-24 : "pas un seul
    // changement au bout de 13 min ? et ils sont trop propres, très souvent
    // tous les remplaçants ont le même temps de jeu"). Diagnostic (voir
    // scripts de calibration en scratchpad, sub_diag2/3.js) : le seuil de
    // repos fatigue >= 82 (constante partagée par TOUS les joueurs) n'était
    // quasiment JAMAIS le déclencheur réel d'un changement (0 fois sur 20
    // matchs simulés avec le taux de fautes actuel) — ce sont les fautes
    // personnelles (p.fouls >= 4) qui déclenchaient presque tous les premiers
    // changements, souvent tard (médiane ~17-18 min de jeu écoulé dans ces
    // mêmes 20 matchs) ET de façon groupée : les 5 titulaires accumulent des
    // minutes IDENTIQUES depuis l'entre-deux, donc une fatigue quasi
    // identique à endurance égale (formule 100% déterministe, voir
    // MatchEngine.applyFatigue) - dès qu'un seuil UNIQUE partagé est
    // atteint, plusieurs titulaires le franchissent en même temps, d'où le
    // banc qui rentre "en bloc" et ressort "en bloc" avec des temps de jeu
    // identiques.
    //
    // Premier essai (abandonné) : UN SEUL seuil bas (30-60) pour TOUTES les
    // sorties du match, pas seulement la première. Ça corrigeait bien le
    // symptôme signalé (premier changement ramené à une médiane ~9 min,
    // 100% des matchs avec un changement avant 13 min - voir
    // rotation_calib.js) mais cassait autre chose, découvert seulement en
    // recalibrant les passes décisives (déjà calibrées plus tôt ce jour,
    // voir plus haut) avec assist_calib2.js : le titulaire le PLUS utilisé
    // d'une équipe ne jouait plus que ~19.8 min/match en moyenne (voir
    // minutes_check.js) au lieu d'environ 28-34 min pour un titulaire
    // réaliste - un seuil bas appliqué à CHAQUE repos, y compris ceux d'un
    // remplaçant qui vient d'entrer, aplatit tout le temps de jeu de
    // l'effectif au lieu de simplement avancer LE PREMIER changement. Passer
    // l'exposant de concentration des passes décisives de 2.3 à 7 a
    // seulement à moitié compensé (top 5 remonté à 5.09 pd/match, sous la
    // cible 5.7-7.4) avec une valeur d'exposant absurde - signe qu'il
    // fallait corriger la VRAIE cause (la répartition des minutes) plutôt
    // que forcer un symptôme en aval.
    //
    // Correctif retenu : DEUX seuils par joueur (voir firstRestThreshold/
    // restThreshold/hasHadFirstRest ci-dessus) - un seuil bas et tiré au
    // sort UNIQUEMENT pour la toute première sortie de CE joueur ce match
    // (fait intervenir la fatigue tôt, avant que les fautes n'aient le temps
    // de s'accumuler - un vrai coach fait souffler un titulaire autour de
    // 5-8 min) ; une fois cette première sortie posée
    // (hasHadFirstRest = true dans MatchEngine.substituteIfNeeded), tous les
    // repos suivants de ce joueur (titulaire de retour comme remplaçant
    // installé) utilisent restThreshold, un seuil haut proche de l'ancienne
    // constante à 82 (jitté pour rester désynchronisé) - la rotation
    // s'installe puis les temps de jeu redeviennent proches de l'ancien
    // comportement (calibré) pour le reste du match, au lieu de s'aplatir.
    // Calibré empiriquement (voir rotation_calib2.js/minutes_check2.js en
    // scratchpad) : voir le résultat mesuré dans DEV_NOTES.md.
    // Deuxième correctif (voir Team.resetForMatch, où isStarterThisMatch est
    // posé) : firstRestThreshold ne s'applique qu'aux 5 titulaires DU match,
    // jamais à un remplaçant qui vient d'entrer — sinon CHAQUE joueur du
    // banc récupère lui aussi un seuil bas artificiel dès son entrée, ce qui
    // le fait ressortir presque aussitôt et aplatit le temps de jeu de tout
    // l'effectif au lieu d'avancer seulement le premier changement des
    // titulaires (mesuré : le titulaire le plus utilisé tombait à ~20
    // min/match, moyenne top 5 passes à 3.3 pd/match, cible 5.7-7.4 cassée -
    // voir minutes_check.js/assist_calib2.js en scratchpad).
    this.isStarterThisMatch = false;
    this.matchStartPosition = null;
    this.firstRestThreshold = rand(20, 50);
    this.restThreshold = rand(75, 90);
    this.hasHadFirstRest = false;
    // Repos planifié DANS LE TEMPS (retour utilisateur 2026-09-26, boxscore
    // Lyon-Rennes où les 10 titulaires avaient joué tout le 1er
    // quart-temps : "que tu aies un ou deux joueurs qui jouent tout le
    // premier quart temps ça peut arriver. Mais les 5 des deux équipes non
    // jamais"). Le seuil de fatigue bas ci-dessus ne suffisait pas : un Q1
    // complet n'apporte que ~20-25 de fatigue à endurance moyenne, donc 59 %
    // des équipes ne faisaient AUCUN changement en Q1 (mesuré sur
    // league.json). firstRestAt = secondes jouées au bout desquelles un
    // TITULAIRE sort pour sa première pause, quel que soit son niveau de
    // fatigue : ~65 % entre 4,5 et 9,5 min, ~35 % "gros temps de jeu" qui
    // enchaînent tout le Q1 (10-14 min) — un ou deux titulaires qui jouent
    // tout le Q1 reste donc possible, les cinq quasiment jamais.
    this.firstRestAt = rand01() < 0.35 ? rand(600, 840) : rand(270, 570);
    // Relais court d'un remplaçant entré pendant la première pause d'un
    // titulaire (voir MatchEngine.substituteIfNeeded) : id du titulaire à
    // faire revenir et secondes jouées au bout desquelles il revient.
    this.returnStarterId = null;
    this.stintEndAt = Infinity;
    // Pauses suivantes d'un titulaire revenu en jeu : nextRestAt (secondes
    // jouées) repoussé de 11 à 17 min à chaque retour (7 à 12 avant l'audit
    // 2026-09-29 : 26 changements par équipe, 15-20 en vrai), pour qu'un titulaire
    // ne reste pas ensuite jusqu'au seuil de fatigue haut (~30 min d'affilée).
    this.nextRestAt = this.firstRestAt;
    // Temps de jeu cible par poste (voir Team.slotMinuteShares et
    // MatchEngine.substituteToTarget) : secondes jouées à la dernière
    // entrée en jeu, durée minimale d'un passage et écart toléré à la cible
    // avant de changer — tirés au sort pour que deux matchs ne donnent pas
    // exactement les mêmes minutes.
    this.stintStartSecs = 0;
    this.minStintSecs = rand(150, 260);
    this.paceMarginSecs = rand(120, 220);
    this.fouls = 0;
    this.disqualified = false;
    this.technicalFouls = 0;
    this.unsportsmanlikeFouls = 0;
    this.injured = false;
    this.onCourt = false;
    // Blessure PERSISTANTE (voir son commentaire au constructeur, et
    // isCurrentlyInjured plus haut) : snapshot pris ICI, une fois par match,
    // à partir de injuryUntil (qui, lui, n'est jamais remis à zéro ici -
    // seule l'échéance du temps réel qui passe le fait expirer).
    this.matchInjuryLocked = isCurrentlyInjured(this, now);
    this.consecutiveMisses = 0;
    this.matchPosition = null;
    this.secondsPlayed = 0;
    this.secondsPlayedByPosition = {};
    // trainingSecondsPlayedByPosition N'EST PAS remis à zéro ici, à dessein
    // (voir son commentaire au constructeur) : il doit survivre aux DEUX
    // autres matchs du jour, jusqu'à ce que Team.trainWeek le consomme.
    this.stats = this.emptyStats();
    // Forme physique (voir currentCondition/CONDITION_STATES plus haut) :
    // snapshot pris UNE FOIS au coup d'envoi (jours de repos déjà rattrapés
    // par currentCondition), lu par eff() pendant tout le match, jamais
    // recalculé possession par possession (contrairement à fatigue, qui
    // évolue EN DIRECT). La perte liée à CE match n'est appliquée qu'ensuite,
    // une fois les minutes réellement jouées connues (voir
    // recordMatchStatsForTeam). `recoveryPerDay` : taux du CLUB (voir
    // Team.conditionRecoveryPerDay/collectiveTraining), transmis par
    // Team.resetForMatch ci-dessous, défaut CONDITION_RECOVERY_PER_DAY pour
    // un appel direct sans équipe (tests).
    this.matchCondition = currentCondition(this, now, recoveryPerDay);
  }

  // Moyenne des 20 caractéristiques (voir le grand commentaire au-dessus
  // d'ATTRS) : les 7 dernières ajoutées comptent ici exactement comme les
  // 13 précédentes, mêmes citoyens à part entière (contrairement à
  // aggressiveness, caractéristique cachée volontairement EXCLUE d'overall,
  // voir le constructeur plus haut). Calculée dynamiquement sur ATTRS
  // plutôt qu'une somme figée, pour ne plus jamais se désynchroniser si
  // ATTRS change encore.
  overall() {
    const a = this.attrs;
    return ATTRS.reduce((sum, key) => sum + a[key], 0) / ATTRS.length;
  }

  // Statistique effective en jeu = (base + bonus MVP éventuel) * forme * fatigue * forme physique * alchimie d'équipe * connaissance tactique
  eff(stat) {
    const base = this.attrs[stat] + (this.pendingMatchBoost || 0);
    const formFactor = 0.85 + (this.form / 100) * 0.30;      // 0.85 → 1.15
    // Concentration (audit 2026-09-29 : ne jouait que sur les lancers
    // francs) : un joueur concentré reste lucide quand la fatigue monte —
    // de −28 % (Concentration 100) à −42 % (Concentration 0) à fatigue
    // maximale, −35 % à 50 comme avant.
    const focusMult = 1.2 - ((this.attrs.focus ?? 50) / 100) * 0.4;
    const fatigueFactor = 1 - (this.fatigue / 100) * 0.35 * focusMult;
    // Forme physique (voir CONDITION_STATES plus haut) : lit matchCondition
    // (snapshot posé par resetForMatch), jamais Player.condition directement
    // (pas encore rattrapé/perdu pour CE match tant que resetForMatch n'est
    // pas passé), `?? this.condition` en dernier recours si eff() était
    // jamais appelée hors match (aucun appel de ce genre aujourd'hui, voir
    // les usages dans playPossession, mais un filet de sécurité coûte peu).
    const conditionFactor = conditionStateFor(this.matchCondition ?? this.condition).perfFactor;
    // Alchimie d'équipe (voir Team.chemistryFactor/resetForMatch plus haut) :
    // lit matchChemistryFactor (snapshot d'ÉQUIPE posé par Team.resetForMatch),
    // `?? 1` en dernier recours si eff() était jamais appelée hors match.
    const chemistryFactor = this.matchChemistryFactor ?? 1;
    // Connaissance tactique (voir Team.tacticalKnowledgeFactor/resetForMatch
    // plus bas) : même snapshot d'ÉQUIPE, SÉPARÉ de chemistryFactor
    // ci-dessus (les deux se cumulent), `?? 1` même filet de sécurité.
    const tacticalKnowledgeFactor = this.matchTacticalKnowledgeFactor ?? 1;
    // Avantage du terrain (retour communauté 2026-09 : "avantage d'être à
    // domicile, à l'exterieur desavantage") : snapshot posé par
    // MatchEngine.simulate quand l'option homeAdvantage est active
    // (HOME_ADVANTAGE_FACTOR pour l'équipe qui reçoit, l'inverse pour celle
    // qui se déplace), `?? 1` sur terrain neutre. Depuis le 2026-09-29,
    // actif en championnat, Coupe, play-offs et amicaux, plus seulement en
    // ligue privée (voir server/liveMatch.js:computeLiveMatch).
    const venueFactor = this.matchVenueFactor ?? 1;
    // Plancher (audit 2026-09-29) : cumulés, fatigue, méforme, forme
    // physique « épuisé », alchimie et connaissance tactique au plus bas
    // pouvaient ramener un joueur à ≈35 % de sa valeur — des matchs
    // grotesques pour un club mal géré. La sanction reste forte (jusqu'à
    // −50 %), mais jamais au-delà ; les bonus ne sont pas concernés.
    const factor = Math.max(EFF_FACTOR_FLOOR, formFactor * fatigueFactor * conditionFactor * chemistryFactor * tacticalKnowledgeFactor * venueFactor);
    return clamp(base * factor, 1, 130);
  }
}

// ---------------------------------------------------------------------
// Clé composite pour Team.plannedTactics (voir le constructeur ci-dessous) :
// "{compétition}:{journée}" plutôt qu'un simple numéro de journée. Retour
// utilisateur (2026-09) : "il faut pouvoir donner ses ordres pour chaque
// match. Plus tard on ajoutera les matchs internationaux, il faudra aussi
// pouvoir le faire" — un tour de Coupe et une journée de championnat sont
// numérotés CHACUN à partir de 0 (CUP_STAGE_NAMES/round.index côté Coupe,
// totalement indépendant du round 0-17 du championnat) : sans cette clé
// composite, planifier les deux à la fois pour le même numéro les ferait
// s'écraser l'un l'autre dans le même objet plannedTactics. `competition`
// omis équivaut à "championship" (comportement historique, avant que la
// Coupe n'ait elle-même de planification à l'avance).
function planKey(round, competition) {
  return `${competition || "championship"}:${round}`;
}

// ---------------------------------------------------------------------
// ALCHIMIE D'ÉQUIPE (retour utilisateur, 2026-09 : "l'alchimie du groupe
// elle doit avoir un impact positif ou négatif sur les performances
// d'équipe [...] elle peut être impactée : par le coach lors de ses
// interviews [...] par les changements fréquents de joueurs (jamais une
// base de joueurs fixes, donc il faut recreer du lien entre les joueurs),
// mais changer un joueur majeur d'une équipe doit forcément avoir bcp plus
// d'impact que de changer le 12 homme (qui doit être très faible)").
// `Team.chemistry` : 0-100, MÊME convention que Team.fanMorale (neutre à 50
// à la création, voir le constructeur plus bas) — mais, contrairement à
// fanMorale, ne bouge QUE par les leviers listés ci-dessous (le 3e, à la
// hausse, ajouté le 2026-09-26 — voir CHEMISTRY_MATCH_TOGETHER_GAIN),
// jamais de dérive naturelle dans le temps :
//   1) Interviews de jalon (voir MILESTONE_INTERVIEW_TONES.chemistryWin/
//      chemistryLoss, appliqué par Team.resolveInterview) : le ton choisi
//      par le coach peut construire ou abîmer la cohésion du groupe, dans
//      un sens ou dans l'autre (positif OU négatif, comme demandé).
//   2) Changements d'effectif (voir chemistryRosterImportance/rosterRankOf
//      ci-dessous, appliqué par League._resolveListing au marché des
//      transferts et par Team.sellPlayer à la vente forcée) : TOUJOURS un
//      malus (jamais un bonus, un club ne "gagne" pas en cohésion en
//      brassant son effectif), pondéré par l'importance du joueur parti/
//      arrivé dans l'effectif.
// Un troisième levier a existé un temps ici (changer trop souvent de
// tactique pénalisait l'alchimie) : retiré (retour utilisateur, 2026-09,
// "sur la partie connaissance tactique, on va modifier un peu la chose. ajd
// ça impacte l'alchimie d'équipe. on va enlever ça et créer une jauge
// connaissance tactique qui impactera le niveau de l'équipe") au profit
// d'une jauge séparée, voir le grand commentaire CONNAISSANCE TACTIQUE plus
// bas (Team.tacticalKnowledge/updateTacticalKnowledge) : changer de
// tactique n'affecte donc plus JAMAIS Team.chemistry, seulement la
// connaissance tactique.
// Lu par Team.chemistryFactor() (voir Player.eff()/Team.resetForMatch plus
// bas) pour un effet MODESTE sur la performance de TOUTE l'équipe (jamais
// aussi marqué que la forme physique ou la fatigue d'UN seul joueur) : la
// cohésion collective aide ou pénalise le groupe entier, pas un joueur en
// particulier.
const CHEMISTRY_ROSTER_CHANGE_MAX_RANK = 12; // "le 12 homme" (retour utilisateur, littéral)
const CHEMISTRY_ROSTER_CHANGE_BASE = 8;
// Une arrivée pèse moitié moins qu'un départ (retour utilisateur 2026-10-03).
const CHEMISTRY_ARRIVAL_SHARE = 0.5; // malus max, pour le tout meilleur joueur de l'effectif

// Leviers À LA HAUSSE (retour utilisateur 2026-09-26 : "faisons la vivre
// davantage à la hausse, ça tire trop vers le bas là" — seuls les 5
// interviews de jalon pouvaient la faire monter, +2 max chacune, contre
// jusqu'à -8 par transfert) : chaque match RÉELLEMENT joué ensemble soude un
// peu le groupe, un peu plus encore si le cinq de départ est le même qu'au
// match précédent (stabilité). Appliqué par Team.updateChemistryAfterMatch
// (voir recordMatchStatsForTeam). Doublé le 2026-09-26 ("on a une vingtaine
// de matchs par saison, ce n'est pas assez. double tes ratios") : sur ~20
// matchs, un effectif stable gagne ~+40, un effectif qui tourne ~+20.
// Retour utilisateur 2026-10-01 (« les victoires ne devraient pas impacter
// plus la cohésion ? ») : le simple fait de jouer ensemble ne vaut plus que
// +0,5, le RÉSULTAT devient le principal moteur (voir CHEMISTRY_WIN_GAIN…
// et Team.applyChemistryResult).
// Plancher de l'alchimie (retour utilisateur 2026-10-03 : « j'ai recruté
// quelques joueurs et je suis maintenant à 3, c'est un peu hard ») : une
// équipe ne descend jamais sous 40.
const CHEMISTRY_MIN = 40;
function vestiaireApi() { return Vestiaire; }
const CHEMISTRY_MATCH_TOGETHER_GAIN = 0.5; // par match joué
const CHEMISTRY_SAME_FIVE_GAIN = 1; // en plus, si même cinq de départ qu'au match précédent
// Résultat du match (officiel, jamais un amical) : victoire +2 (+3 à partir
// de 3 victoires de suite, ce match compris), défaite −1 (−2 à partir de 3
// défaites de suite), −1 de plus pour une défaite de plus de 20 points.
const CHEMISTRY_WIN_GAIN = 2;
const CHEMISTRY_WIN_STREAK_GAIN = 3;
const CHEMISTRY_LOSS = 1;
const CHEMISTRY_LOSS_STREAK = 2;
const CHEMISTRY_STREAK_LENGTH = 3;
const CHEMISTRY_BLOWOUT_MARGIN = 20;
const CHEMISTRY_BLOWOUT_EXTRA = 1;

// ---------------------------------------------------------------------
// CONNAISSANCE TACTIQUE (retour utilisateur, 2026-09 : "sur la partie
// connaissance tactique, on va modifier un peu la chose. ajd ça impacte
// l'alchimie d'équipe. on va enlever ça et créer une jauge connaissance
// tactique qui impactera le niveau de l'équipe [...] l'entrainement
// augmente la connaissance tactique"). Remplace l'ancien troisième levier
// d'alchimie (voir le grand commentaire ALCHIMIE D'ÉQUIPE ci-dessus) :
// changer de tactique n'abîme plus la cohésion du groupe, mais fait chuter
// une jauge SÉPARÉE qui mesure à quel point l'équipe maîtrise son plan de
// jeu.
//
// DEUXIÈME révision (retour utilisateur, 2026-09 : "il faudrait qu'il y ait
// une jauge par type d'attaque, une par rythme et une par défense [...]
// comme ça on verrait bien les tactiques que l'on maîtrise ou pas [...] il
// faudrait que ce soit plus progressif. après un match on n'oublie pas.
// après 2 matchs on commence à oublier. après 3 encore plus etc [...] si on
// joue un match on apprend mais on est pas direct au taquet et ce n'est pas
// direct la tactique de référence") : `Team.tacticalKnowledge` suit
// désormais CHAQUE option précise SÉPARÉMENT, pas 3 grandes catégories :
//   tacticalKnowledge.offense[priorité] pour CHACUNE des 10 priorités
//     offensives possibles (voir OFFENSE_PROFILES), même celles que
//     l'équipe ne joue pas actuellement (elle n'en joue que 3 à la fois),
//   tacticalKnowledge.defense[type] pour CHACUN des 5 types de défense
//     possibles (voir DEFENSES),
//   tacticalKnowledge.rhythm[rythme] pour CHACUN des 3 rythmes possibles
//     (voir RHYTHMS),
// chaque valeur 0-100, neutre à 50 à la création (même convention que
// Team.chemistry, voir le constructeur plus bas).
//
// Bouge à CHAQUE match réellement joué (voir Team.updateTacticalKnowledge
// plus bas, appelée depuis recordMatchStatsForTeam, jamais pendant la
// simple planification à l'avance via stagePlanForRound) : pour CHACUNE des
// 18 options ci-dessus, on regarde si elle vient d'être jouée CE match-là
// ou non, PROGRESSIVEMENT plutôt qu'en tout-ou-rien :
//   - jouée : la maîtrise MONTE (voir tacticalKnowledgeGainForStreak),
//     d'autant plus vite qu'elle est jouée plusieurs matchs DE SUITE, jamais
//     un saut direct à la maîtrise maximale dès le premier match ("pas
//     direct au taquet"),
//   - délaissée : la maîtrise BAISSE (voir tacticalKnowledgeLossForStreak),
//     mais SEULEMENT à partir du 2e match d'absence consécutif — un
//     aller-retour d'un seul match ne coûte donc RIEN ("après un match on
//     n'oublie pas"), puis la perte s'accélère plus l'absence se prolonge.
// Team.tacticalKnowledgeStreaks (même forme imbriquée que tacticalKnowledge
// ci-dessus) garde, PAR OPTION, le nombre de matchs consécutifs où elle
// vient d'être jouée (positif) ou délaissée (négatif) — sert uniquement à
// calculer le prochain mouvement, aucune autre lecture ailleurs.
//
// Remplace l'ancienne "tactique établie" (un seul instantané de référence,
// bascule binaire après 2 matchs identiques de suite, retour gratuit ou
// perte pleine selon les cas) : chaque option a maintenant sa PROPRE
// mémoire continue, donc revenir à une tactique délaissée plusieurs matchs
// remonte progressivement, au même rythme que si on l'apprenait pour la
// première fois : jamais gratuit, jamais un mur non plus.
//
// L'entraînement collectif "tactique" (Team.trainedTactics/
// daysTrainedForTarget, inchangé depuis la première version) ajoute un
// BONUS de gain PAR-DESSUS la courbe ci-dessus, uniquement sur l'option
// RÉELLEMENT jouée ce match (voir TACTICAL_KNOWLEDGE_DAILY_GAIN plus bas) :
// une préparation en avance sur une option pas encore jouée en live
// n'accélère donc rien tant que l'ordre live n'a pas effectivement changé,
// le crédit banqué reste en attente jusque-là.
//
// Lu par Team.tacticalKnowledgeFactor() (voir Player.eff()/
// Team.resetForMatch plus bas) : moyenne des 3 options ACTUELLEMENT jouées
// (les 3 priorités offensives + la défense + le rythme en cours), pour un
// effet MODESTE sur la performance de TOUTE l'équipe, SÉPARÉ de
// chemistryFactor() (les deux se cumulent) — même ordre de grandeur
// (+/-6%).
// ---------------------------------------------------------------------
// Courbe de gain, par match consécutif où une option reste jouée : monte
// progressivement puis plafonne (jamais un saut direct au maximum, même en
// restant indéfiniment sur la même tactique : l'entraînement ciblé reste le
// seul moyen d'accélérer, voir TACTICAL_KNOWLEDGE_DAILY_GAIN ci-dessous).
// TACTIQUES ENREGISTRÉES (onglet Tactiques, demande du 2026-09-27 :
// "pouvoir programmer 3 tactiques max, qu'on pourra retrouver très
// facilement dans ordres et mettre en place en 1 seconde", "tout, joueurs
// compris", "pouvoir donner un nom à la tactique") : Team.tacticPresets,
// jusqu'à TACTIC_PRESETS_MAX ordres complets nommés (attaque, défense,
// rythme, consignes confirmées, convocation, cinq, rotation, temps de jeu).
// Les « postes à surveiller » (watchAssignments) n'en font PAS partie : ils
// visent des joueurs d'un adversaire précis.
// Premium (retour utilisateur, 2026-09-27) : 6 tactiques enregistrées au
// lieu de 3 (TACTIC_PRESETS_FREE_MAX) — voir Team.tacticPresetsMax. Une
// tactique enregistrée pendant le Premium reste utilisable après.
const TACTIC_PRESETS_MAX = 6;
const TACTIC_PRESETS_FREE_MAX = 3;
const TACTIC_PRESET_NAME_MAX = 30;
// Nombre de matchs dont on garde les ordres complets (Team.ordersHistory).
// Joueur esseulé (retour utilisateur 2026-10-03) : part de tirs au-delà de
// laquelle la part d'un seul joueur est comprimée de moitié, et défense
// resserrée au-delà de ISOLATED_GAP_FREE points d'écart avec ses coéquipiers.
const ISOLATED_SHARE_CAP = 0.30;
const ISOLATED_GAP_FREE = 20;
const ISOLATED_GAP_PENALTY = 0.25;
const ORDERS_HISTORY_MAX = 20;
const TACTIC_PRESET_FIELDS = ["offensivePriorities", "defense", "rhythm", "tacticalTier", "screenDefense", "helpDefense", "postDefense", "closeoutStyle", "offRebStyle", "endgameManagement"];
// Copie profonde d'un jeu d'ordres (forme snapshotTactics) en tactique
// enregistrable : sans watchAssignments.
function tacticPresetOrdersFrom(snap) {
  const out = {};
  TACTIC_PRESET_FIELDS.forEach(k => { if (snap[k] !== undefined) out[k] = Array.isArray(snap[k]) ? [...snap[k]] : snap[k]; });
  const l = snap.lineup || {};
  out.lineup = {
    starters: { ...(l.starters || {}) },
    backupPositions: Object.fromEntries(Object.entries(l.backupPositions || {}).map(([id, positions]) => [id, [...positions]])),
    ...(l.minutes ? { minutes: Object.fromEntries(Object.entries(l.minutes).map(([pos, m]) => [pos, { ...m }])) } : {}),
    ...(Array.isArray(l.convoked) ? { convoked: [...l.convoked] } : {}),
  };
  return out;
}

const TACTICAL_KNOWLEDGE_GAIN_BASE = 6; // 1er match consécutif sur cette option
const TACTICAL_KNOWLEDGE_GAIN_STEP = 2; // += par match consécutif supplémentaire
const TACTICAL_KNOWLEDGE_GAIN_MAX = 12; // plafond (atteint au 4e match consécutif)
function tacticalKnowledgeGainForStreak(playStreak) {
  if (playStreak <= 0) return 0;
  return Math.min(TACTICAL_KNOWLEDGE_GAIN_MAX, TACTICAL_KNOWLEDGE_GAIN_BASE + (playStreak - 1) * TACTICAL_KNOWLEDGE_GAIN_STEP);
}

// Courbe de perte, par match consécutif où une option reste délaissée :
// AUCUNE perte aux TACTICAL_KNOWLEDGE_LOSS_GRACE premiers matchs d'absence,
// puis la perte accélère avant de plafonner.
// Adoucie le 2026-09-26 (remarque d'un joueur relayée par l'utilisateur :
// "la perte pour les entraînements collectifs est énorme non ?", option 1
// retenue) : avant, 0/-4/-8/-12/-16 par match (plafond -16 > gain max +12),
// soit -88 en 8 matchs d'absence — 4 jours à 2 matchs par jour. Désormais
// 0/0/-2/-4/-6 (plafond -6, sous le gain max) : -30 en 8 matchs.
const TACTICAL_KNOWLEDGE_LOSS_GRACE = 2; // matchs d'absence gratuits
const TACTICAL_KNOWLEDGE_LOSS_STEP = 2; // += par match d'absence au-delà de la période de grâce
const TACTICAL_KNOWLEDGE_LOSS_MAX = 6; // plafond (atteint au 5e match d'absence)
// Plancher de connaissance tactique (retour utilisateur 2026-09-27 : "ça
// reste des joueurs pro, peut être pas besoin de descendre aussi bas, sinon
// on change jamais de tactique") : un système délaissé redescend au plus à
// ce niveau (« Système encore hésitant »), jamais à « pas du tout assimilé ».
// Les sauvegardes plus basses sont remontées au chargement.
const TACTICAL_KNOWLEDGE_FLOOR = 40;
function tacticalKnowledgeLossForStreak(awayStreak) {
  if (awayStreak <= TACTICAL_KNOWLEDGE_LOSS_GRACE) return 0;
  return Math.min(TACTICAL_KNOWLEDGE_LOSS_MAX, (awayStreak - TACTICAL_KNOWLEDGE_LOSS_GRACE) * TACTICAL_KNOWLEDGE_LOSS_STEP);
}

// Gain quotidien de connaissance tactique par jour d'entraînement collectif
// "tactique" RÉELLEMENT banqué (voir Team.daysTrainedForTarget) sur
// l'option EXACTEMENT en train d'être jouée : bonus ADDITIF par-dessus
// tacticalKnowledgeGainForStreak ci-dessus, inchangé depuis la première
// version de cette fonctionnalité ("l'entrainement augmente la
// connaissance tactique", littéralement).
const TACTICAL_KNOWLEDGE_DAILY_GAIN = 4;
// CONNAISSANCE TACTIQUE INDIVIDUELLE (retour utilisateur 2026-10-03 :
// "J'ai changé 80% de l'équipe et ça n'a pas bougé", "il faudrait que la
// connaissance tactique soit au niveau individuel", solution B retenue) :
// pour un club humain, chaque joueur a SA maîtrise de chacune des 18 options
// (Player.tacticalKnowledge, même forme que Team.tacticalKnowledge). Une
// recrue arrive à PLAYER_TACTICAL_KNOWLEDGE_RECRUIT partout ; un match
// officiel fait gagner +3, +4, +5 puis +6 au plus (série de l'option, voir
// playerTacticalKnowledgeGainForStreak) au prorata des minutes jouées
// (plein gain dès TACTICAL_FULL_GAIN_SECONDS) ; le jour « Tactique » profite
// à tout l'effectif. Team.tacticalKnowledge devient la jauge d'équipe :
// moyenne pondérée par les minutes prévues au prochain match (voir
// Team.recomputeTacticalKnowledge). Les clubs IA gardent la connaissance
// collective d'avant. La ligue privée n'y touche pas.
const PLAYER_TACTICAL_KNOWLEDGE_GAIN_BASE = 3;
const PLAYER_TACTICAL_KNOWLEDGE_GAIN_STEP = 1;
const PLAYER_TACTICAL_KNOWLEDGE_GAIN_MAX = 6;
const PLAYER_TACTICAL_KNOWLEDGE_RECRUIT = 40;
const TACTICAL_FULL_GAIN_SECONDS = 30 * 60;
function playerTacticalKnowledgeGainForStreak(playStreak) {
  if (playStreak <= 0) return 0;
  return Math.min(PLAYER_TACTICAL_KNOWLEDGE_GAIN_MAX, PLAYER_TACTICAL_KNOWLEDGE_GAIN_BASE + (playStreak - 1) * PLAYER_TACTICAL_KNOWLEDGE_GAIN_STEP);
}
// Copie d'une maîtrise par option (forme defaultTacticalKnowledgeShape),
// valeurs manquantes à `fallback`.
function copyTacticalKnowledge(src, fallback = PLAYER_TACTICAL_KNOWLEDGE_RECRUIT) {
  const out = defaultTacticalKnowledgeShape(fallback);
  ["offense", "defense", "rhythm"].forEach(cat => {
    const s = src && src[cat];
    if (!s || typeof s !== "object") return;
    Object.keys(out[cat]).forEach(key => {
      if (typeof s[key] === "number" && Number.isFinite(s[key])) out[cat][key] = clamp(s[key], TACTICAL_KNOWLEDGE_FLOOR, 100);
    });
  });
  return out;
}
// Maîtrise moyenne (0-100) d'une tactique (priorités offensives, défense,
// rythme) selon une maîtrise par option.
function tacticalKnowledgeAverage(k, priorities, defense, rhythm) {
  const off = (priorities || []).map(p => (k.offense || {})[p] ?? 50);
  const offAvg = off.length ? off.reduce((a, b) => a + b, 0) / off.length : 50;
  return (offAvg + ((k.defense || {})[defense] ?? 50) + ((k.rhythm || {})[rhythm] ?? 50)) / 3;
}
// Historique du joueur et suivi des blessures (retour utilisateur
// 2026-10-03, façon BuzzerBeater) : journaux PORTÉS PAR LE JOUEUR (ils le
// suivent d'un club à l'autre, sauvegardés avec lui).
//  - Player.historyLog : transferts, signatures d'agent libre, promotion de
//    l'académie, gros matchs (voir BIG_GAME_THRESHOLDS) — du plus récent au
//    plus ancien ;
//  - Player.injuryHistory : une entrée par blessure (date, type, durée,
//    retour, contexte, niveau du médecin).
const PLAYER_HISTORY_LOG_MAX = 60;
const PLAYER_INJURY_HISTORY_MAX = 40;
const BIG_GAME_THRESHOLDS = { pts: 25, reb: 14, ast: 10, stl: 6, blk: 6 };
function teamSeasonNo(team) {
  return ((team && team.seasonHistory) || []).length + 1;
}
// Feuilles de match figées (retour utilisateur 2026-10-04 : « j'ai vendu des
// joueurs et ils n'apparaissent plus sur la feuille ») : quand un joueur
// quitte un club en cours de saison, ses lignes de match pour CE club sont
// gardées par le club (team.departedMatchLog, remis à zéro chaque saison)
// pour reconstituer les feuilles de match déjà jouées.
const DEPARTED_MATCH_LOG_MAX = 600;
function archiveDepartedMatchLog(team, p) {
  // Tout départ passe ici (transfert, vente, licenciement, fin de contrat) :
  // journal du vestiaire mis à jour tout de suite (voir assets/vestiaire.js).
  Vestiaire.noteRoster(team, p, "departure");
  if (!team || !p || !Array.isArray(p.matchLog) || !p.matchLog.length) return;
  const rows = p.matchLog
    .filter(e => e && e.competition !== "friendly" && (!e.team || e.team === team.name))
    .map(e => ({ ...e, playerId: p.id, name: p.name, position: p.position }));
  if (!rows.length) return;
  const kept = (Array.isArray(team.departedMatchLog) ? team.departedMatchLog : []).filter(r => r.playerId !== p.id);
  team.departedMatchLog = kept.concat(rows).slice(-DEPARTED_MATCH_LOG_MAX);
}

// Restauration des feuilles de match vidées par des départs survenus AVANT
// l'archivage au départ (retour utilisateur 2026-10-04). Pour chaque club,
// les joueurs du monde dont l'historique montre un transfert depuis ce club
// sont relus (journal de saison et lignes mises de côté) ; une ligne n'est
// rendue au club que si elle appartient à l'un de SES matchs : même
// compétition, même journée et même score par quart-temps que les lignes
// de ses joueurs actuels. Rien n'est inventé, rien n'est supprimé, aucun
// doublon (joueur + compétition + journée). Renvoie les ajouts par club.
function restoreDepartedMatchLogs(leagues) {
  const all = [];
  for (const lg of leagues) {
    if (!lg) continue;
    (lg.teams || []).forEach(t => (t && t.players || []).forEach(p => all.push(p)));
    (lg.freeAgents || []).forEach(p => all.push(p));
  }
  const leftFrom = new Map();
  all.forEach(p => (p.historyLog || []).forEach(ev => {
    if (!ev || ev.type !== "transfer" || !ev.from) return;
    if (!leftFrom.has(ev.from)) leftFrom.set(ev.from, new Set());
    leftFrom.get(ev.from).add(p);
  }));
  const k = e => `${e.competition || "championship"}:${e.round}`;
  const qs = e => (e && e.quarterScores && Array.isArray(e.quarterScores.home) && Array.isArray(e.quarterScores.away)) ? JSON.stringify(e.quarterScores) : null;
  const out = [];
  for (const lg of leagues) {
    if (!lg) continue;
    (lg.teams || []).forEach(t => {
      const cands = t && leftFrom.get(t.name);
      if (!cands) return;
      const sig = new Map();
      t.players.forEach(p => (p.matchLog || []).forEach(e => {
        if (e && e.competition !== "friendly" && (!e.team || e.team === t.name) && qs(e)) sig.set(k(e), qs(e));
      }));
      (t.departedMatchLog || []).forEach(r => { if (qs(r)) sig.set(k(r), qs(r)); });
      const have = new Set((t.departedMatchLog || []).map(r => `${r.playerId}|${k(r)}`));
      const added = [];
      cands.forEach(p => {
        if (t.players.includes(p)) return;
        [...(p.matchLog || []), ...(p.archivedMatchLog || [])].forEach(e => {
          if (!e || e.competition === "friendly" || (e.team && e.team !== t.name)) return;
          const s = sig.get(k(e));
          if (!s || qs(e) !== s) return;
          const key = `${p.id}|${k(e)}`;
          if (have.has(key)) return;
          have.add(key);
          added.push({ ...e, team: t.name, playerId: p.id, name: p.name, position: p.position });
        });
      });
      if (added.length) {
        t.departedMatchLog = (Array.isArray(t.departedMatchLog) ? t.departedMatchLog : []).concat(added);
        out.push({ leagueId: lg.leagueId || null, team: t.name, rows: added });
      }
    });
  }
  return out;
}

// ---------------------------------------------------------------------
// ARCHIVES DE SAISON (retour utilisateur 2026-10-04 : « on aura toujours
// accès aux matchs des saisons précédentes pour consulter les box
// scores ? »). En fin de saison, AVANT la remise à zéro des journaux de
// match, chaque match officiel (championnat, play-offs, coupe, supercoupe)
// est figé : les deux équipes, le score par quart-temps et la ligne de
// chaque joueur (nom compris), indépendamment des effectifs futurs. Les
// lignes sont des tableaux (colonnes dans ARCHIVE_ROW_COLS) pour rester
// légères ; stockées à part (server/store.js:saveSeasonArchive) et lues
// seulement à la demande.
const ARCHIVE_ROW_COLS = ["id", "name", "position", "starter", "isMvp", "min", "pts", "reb", "oreb", "ast", "stl", "blk", "tov", "pf", "fgm2", "fga2", "fgm3", "fga3", "ftm", "fta", "plusMinus"];
function buildSeasonArchive(league, opts = {}) {
  const qsKey = e => (e && e.quarterScores && Array.isArray(e.quarterScores.home) && Array.isArray(e.quarterScores.away)) ? JSON.stringify(e.quarterScores) : null;
  const sum = a => a.reduce((x, y) => x + (y || 0), 0);
  const groups = new Map();
  (league.teams || []).forEach(t => {
    if (!t) return;
    const seen = new Set();
    const entries = [];
    (t.players || []).forEach(p => (p.matchLog || []).forEach(e => entries.push({ id: p.id, name: p.name, position: p.position, e })));
    (t.departedMatchLog || []).forEach(r => entries.push({ id: r.playerId, name: r.name, position: r.position, e: r }));
    entries.forEach(({ id, name, position, e }) => {
      if (!e || e.competition === "friendly" || (e.team && e.team !== t.name)) return;
      const q = qsKey(e);
      if (!q) return;
      const comp = e.competition || "championship";
      const dk = `${id}|${comp}|${e.round}`;
      if (seen.has(dk)) return;
      seen.add(dk);
      const key = `${comp}|${e.round}|${q}`;
      if (!groups.has(key)) groups.set(key, { competition: comp, round: e.round, quarterScores: JSON.parse(q), sides: new Map() });
      const g = groups.get(key);
      if (!g.sides.has(t.name)) g.sides.set(t.name, { team: t.name, isHome: null, opponent: null, at: null, rows: [] });
      const side = g.sides.get(t.name);
      if (side.isHome == null && typeof e.isHome === "boolean") side.isHome = e.isHome;
      if (!side.opponent && e.opponent) side.opponent = e.opponent;
      if (side.at == null && typeof e.at === "number") side.at = e.at;
      const row = { id, name, position, starter: !!e.starter, isMvp: !!e.isMvp, min: e.min, pts: e.pts, reb: e.reb, oreb: e.oreb || 0, ast: e.ast, stl: e.stl, blk: e.blk, tov: e.tov, pf: e.pf,
        fgm2: e.fgm2, fga2: e.fga2, fgm3: e.fgm3, fga3: e.fga3, ftm: e.ftm, fta: e.fta, plusMinus: e.plusMinus || 0 };
      side.rows.push(ARCHIVE_ROW_COLS.map(c => (row[c] === undefined ? null : row[c])));
    });
  });
  const nameOf = idx => (league.teams[idx] || {}).name;
  const resultHome = (round, a, b) => {
    const r = (league.results || []).find(x => x.round === round && ((nameOf(x.home) === a && nameOf(x.away) === b) || (nameOf(x.home) === b && nameOf(x.away) === a)));
    return r ? nameOf(r.home) : null;
  };
  const ptsOf = side => side.rows.reduce((n, r) => n + (r[ARCHIVE_ROW_COLS.indexOf("pts")] || 0), 0);
  const matches = [];
  groups.forEach(g => {
    const totH = sum(g.quarterScores.home), totA = sum(g.quarterScores.away);
    const sides = [...g.sides.values()];
    const used = new Set();
    const pushMatch = (home, away) => {
      const at = (home && home.at) || (away && away.at) || (typeof opts.timeOf === "function" ? opts.timeOf(g.competition, g.round) : null);
      const pack = s => ({ team: s.team, rows: s.rows.sort((x, y) => (y[3] - x[3]) || ((y[5] || 0) - (x[5] || 0))) });
      matches.push({ competition: g.competition, round: g.round, at: at || null, quarterScores: g.quarterScores, scoreHome: totH, scoreAway: totA, home: pack(home), away: pack(away) });
    };
    sides.forEach(a => {
      if (used.has(a)) return;
      // Adversaire : par son nom (matchs récents), sinon le seul autre côté.
      const b = sides.find(x => x !== a && !used.has(x) && (a.opponent ? x.team === a.opponent : (!x.opponent || x.opponent === a.team)));
      used.add(a);
      if (b) used.add(b);
      let homeIsA;
      if (a.isHome != null) homeIsA = a.isHome;
      else if (b && b.isHome != null) homeIsA = !b.isHome;
      else if (b && resultHome(g.round, a.team, b.team)) homeIsA = resultHome(g.round, a.team, b.team) === a.team;
      else homeIsA = Math.abs(ptsOf(a) - totH) <= Math.abs(ptsOf(a) - totA);
      // Autre côté sans lignes connues (club repris avec un effectif neuf,
      // adversaire d'un autre championnat) : son nom seul, aucune ligne
      // inventée. Nom relu dans les résultats de la ligue si besoin.
      const res = !b && !a.opponent && g.competition === "championship"
        ? (league.results || []).find(x => x.round === g.round && (nameOf(x.home) === a.team || nameOf(x.away) === a.team))
        : null;
      const resOpp = res ? (nameOf(res.home) === a.team ? nameOf(res.away) : nameOf(res.home)) : null;
      if (res && a.isHome == null) homeIsA = nameOf(res.home) === a.team;
      const other = b || { team: a.opponent || resOpp || "Adversaire", rows: [] };
      pushMatch(homeIsA ? a : other, homeIsA ? other : a);
    });
  });
  matches.sort((x, y) => ((x.at || 0) - (y.at || 0)) || (x.round - y.round));
  return {
    version: 1, leagueId: opts.leagueId || league.leagueId || null, label: opts.label || null,
    season: league.seasonNumber || 1, totalRounds: league.totalRounds, archivedAt: opts.now || Date.now(),
    cols: ARCHIVE_ROW_COLS, teams: (league.teams || []).filter(Boolean).map(t => t.name), matches,
  };
}

function recordPlayerEvent(p, ev) {
  if (!p || !ev) return;
  // Saison d'arrivée dans son club actuel (succès « garder un joueur N
  // saisons », 2026-10-04) : tout transfert / signature / promotion passe ici.
  if ((ev.type === "transfer" || ev.type === "promotion") && typeof ev.season === "number") p.clubSinceSeason = ev.season;
  if (!Array.isArray(p.historyLog)) p.historyLog = [];
  p.historyLog.unshift(ev);
  if (p.historyLog.length > PLAYER_HISTORY_LOG_MAX) p.historyLog.length = PLAYER_HISTORY_LOG_MAX;
}
// ---------------------------------------------------------------------
// HISTORIQUE DES TRANSFERTS D'UN CLUB (retour utilisateur 2026-10-05 : « qui
// est arrivé, qui est parti, d'où il venait ou où il est parti, combien il
// a coûté ou rapporté »). Team.transferHistory : entrées PERSISTANTES,
// écrites au moment du mouvement (jamais reconstruites depuis l'effectif),
// la plus récente en tête. Une entrée par club concerné : un achat écrit
// « buy » chez l'acheteur ET « sell » chez le vendeur, avec le même
// identifiant de mouvement (`id` + sens → jamais de doublon).
//   kind : buy (arrivée payante) · sell (départ payant) · free_in (agent
//          libre signé ; prix = prime de signature, 0 si aucune) · release
//          (licencié → agent libre ; l'indemnité n'est pas un prix de
//          transfert, elle est notée à part) · expiry (fin de contrat) ·
//          retire (retraite) · liquidation (vente d'urgence hors du
//          championnat) · loan_in / loan_out / loan_end (prévus pour un
//          futur système de prêt : aucun prêt n'existe dans le jeu).
//   from / to : { name, leagueId, idx } (null = agent libre / hors club).
//   human : opération décidée par le manager du club (enchère, vente,
//          licenciement, signature) → « Mon historique » du marché.
// ---------------------------------------------------------------------
const TEAM_TRANSFER_HISTORY_MAX = 150;
const TRANSFER_KIND_DIR = { buy: "in", free_in: "in", loan_in: "in", sell: "out", release: "out", expiry: "out", retire: "out", liquidation: "out", loan_out: "out", loan_end: "out" };
function transferTeamRef(team, leagueId, idx) {
  if (!team) return null;
  return { name: team.name, leagueId: leagueId || null, idx: Number.isInteger(idx) && idx >= 0 ? idx : null };
}
function recordTeamTransfer(team, e) {
  if (!team || !e || !e.kind || !e.player) return null;
  if (!Array.isArray(team.transferHistory)) team.transferHistory = [];
  const dir = TRANSFER_KIND_DIR[e.kind] || "in";
  const id = `${e.id}:${dir}`;
  if (team.transferHistory.some(x => x && x.id === id)) return null;
  const p = e.player;
  const entry = {
    id, at: typeof e.at === "number" ? e.at : Date.now(), season: typeof e.season === "number" ? e.season : teamSeasonNo(team), kind: e.kind, dir,
    playerId: p.id, playerName: p.name, position: p.position || null, age: typeof p.age === "number" ? p.age : null,
    from: e.from || null, to: e.to || null,
    fee: Math.max(0, Math.round(Number(e.fee) || 0)),
    human: !!e.human,
    ...(e.formerClub ? { formerClub: e.formerClub } : {}),
    ...(e.indemnity ? { indemnity: Math.round(e.indemnity) } : {}),
  };
  team.transferHistory.unshift(entry);
  if (team.transferHistory.length > TEAM_TRANSFER_HISTORY_MAX) team.transferHistory.length = TEAM_TRANSFER_HISTORY_MAX;
  if (!String(e.id).startsWith("seed:")) { try { historyAfterTransfer(team, entry, p); } catch (err) { /* confort */ } }
  // Succès « Premier recrutement » : signature décidée par le manager
  // (enchère gagnée ou agent libre), jamais la reprise des anciens transferts.
  if (entry.human && (entry.kind === "buy" || entry.kind === "free_in") && !String(e.id).startsWith("seed:")) achAdd(team, "signings", 1, entry.at);
  return entry;
}
// Mémoire historique (assets/history.js) : carrière d'un joueur AU club
// (saisons archivées + saison en cours), pour son palier de légende.
function histCareerAt(team, p) {
  const prev = (team.allTimePlayers || {})[p.id];
  const e = prev ? { ...prev, seasons: (prev.seasons || []).slice() } : { id: p.id, name: p.name, position: p.position, games: 0, pts: 0, reb: 0, ast: 0, seasons: [] };
  const log = (p.matchLog || []).filter(m => m && m.competition !== "friendly" && m.competition !== "lp");
  if (log.length) {
    e.games += log.length; e.pts += log.reduce((a, m) => a + (m.pts || 0), 0);
    const cur = histSeasonOf(team);
    if (!e.seasons.includes(cur)) e.seasons.push(cur);
  }
  e.homegrown = !!p.homegrownClub && p.homegrownClub === String(team.name || "").trim().toLowerCase();
  e.awards = (p.awards || []).filter(a => a && a.teamName === team.name).length;
  return e;
}
function historyAfterTransfer(team, entry, p) {
  const now = entry.at, season = histSeasonOf(team);
  const fromName = entry.from && entry.from.name, toName = entry.to && entry.to.name;
  if (entry.kind === "retire") {
    const t = History.legendTier(histCareerAt(team, p));
    if (!t || t.rank < 2) return;
    const ev = History.push({ type: "LEGEND_RETIREMENT", importance: t.rank >= 3 ? 4 : 3, season, at: now, teams: [team.name], players: [p.id],
      description: `${p.name}, ${t.label.toLowerCase()} du club, prend sa retraite.`, tags: ["retraite", t.label] });
    histFeed(team, ev, "Une page se tourne", now);
    return;
  }
  if (entry.kind === "sell" && toName) {
    const t = History.legendTier(histCareerAt(team, p));
    const rival = History.rivalryOf(team, toName, now);
    const toRival = rival && rival.s >= History.CFG.rivalryCreatedAt;
    if (t && t.rank >= 2 && toRival) {
      const ev = History.push({ type: "CONTROVERSIAL_TRANSFER", importance: 3, season, at: now, teams: [team.name, toName], players: [p.id], competition: "transfer",
        description: `${p.name}, ${t.label.toLowerCase()} de ${team.name}, rejoint le rival ${toName}` + (entry.fee ? ` (${entry.fee.toLocaleString("fr-FR")} $).` : "."), rivalryImpact: 8, tags: ["trahison"] });
      histFeed(team, ev, "Départ chez le rival", now);
    } else if ((t && t.rank >= 2) || entry.fee >= History.CFG.majorTransferFee) {
      History.push({ type: "MAJOR_TRANSFER", importance: t && t.rank >= 2 ? 3 : 2, season, at: now, teams: [team.name, toName], players: [p.id], competition: "transfer",
        description: `${p.name}${t && t.rank >= 2 ? `, ${t.label.toLowerCase()} de ${team.name},` : ""} part de ${team.name} pour ${toName}` + (entry.fee ? ` (${entry.fee.toLocaleString("fr-FR")} $).` : "."), statistics: { fee: entry.fee }, tags: ["transfert"] });
    }
    return;
  }
  if ((entry.kind === "buy" || entry.kind === "free_in") && team.allTimePlayers && team.allTimePlayers[p.id]) {
    // Retour d'un ancien joueur marquant du club.
    const t = History.legendTier({ ...team.allTimePlayers[p.id], homegrown: !!p.homegrownClub && p.homegrownClub === String(team.name || "").trim().toLowerCase() });
    if (!t) return;
    const ev = History.push({ type: "MAJOR_TRANSFER", importance: 3, season, at: now, teams: [team.name].concat(fromName ? [fromName] : []), players: [p.id], competition: "transfer",
      description: `Retour au club de ${p.name} (${t.label.toLowerCase()} de ${team.name}).`, tags: ["retour"] });
    histFeed(team, ev, "Le retour", now);
  }
}

// Bilan d'une liste d'entrées : dépenses (arrivées payantes et primes de
// signature), recettes (départs payants), solde = recettes − dépenses.
function transferHistoryTotals(entries) {
  let spent = 0, earned = 0, arrivals = 0, departures = 0, freeArrivals = 0;
  (entries || []).forEach(e => {
    if (!e) return;
    if (e.dir === "in") { arrivals++; if (e.kind === "free_in" && !e.fee) freeArrivals++; spent += e.fee || 0; }
    else { departures++; earned += e.fee || 0; }
  });
  return { spent, earned, balance: earned - spent, arrivals, departures, freeArrivals };
}

function recordPlayerInjury(p, ev) {
  if (!p || !ev) return;
  if (!Array.isArray(p.injuryHistory)) p.injuryHistory = [];
  p.injuryHistory.unshift(ev);
  if (p.injuryHistory.length > PLAYER_INJURY_HISTORY_MAX) p.injuryHistory.length = PLAYER_INJURY_HISTORY_MAX;
}
// Recrue : maîtrise remise à PLAYER_TACTICAL_KNOWLEDGE_RECRUIT partout.
function resetPlayerTacticalKnowledge(p) {
  if (p) p.tacticalKnowledge = defaultTacticalKnowledgeShape(PLAYER_TACTICAL_KNOWLEDGE_RECRUIT);
}
// Amical : poids d'une minute jouée selon le rôle du joueur (voir
// Team.gainTacticalKnowledgeFromFriendly).
const FRIENDLY_TACTICAL_ROLE_WEIGHTS = { starter: 1, rotation: 0.5, reserve: 0 };

// Construit la forme imbriquée par défaut de Team.tacticalKnowledge/
// tacticalKnowledgeStreaks (une entrée par option possible des 3
// catégories, voir le grand commentaire CONNAISSANCE TACTIQUE ci-dessus) :
// `value` = valeur de départ identique pour toutes les options (50 pour la
// maîtrise, neutre comme Team.chemistry ; 0 pour les séries, "pas encore de
// match de référence").
function defaultTacticalKnowledgeShape(value) {
  const build = keys => keys.reduce((o, k) => { o[k] = value; return o; }, {});
  return {
    offense: build(Object.keys(OFFENSE_PROFILES)),
    defense: build(Object.keys(DEFENSES)),
    rhythm: build(Object.keys(RHYTHMS)),
  };
}

// Poids d'un changement de joueur selon son RANG dans l'effectif (1 = tout
// meilleur joueur au sens overall(), voir rosterRankOf ci-dessous) :
// décroît LINÉAIREMENT jusqu'à 0 au rang CHEMISTRY_ROSTER_CHANGE_MAX_RANK
// (le "12e homme" pèse donc quasiment rien, comme demandé), et reste à 0
// au-delà (un effectif de 22 joueurs maximum, voir MAX_ROSTER_SIZE, peut
// avoir un rang 13+ qui ne compte simplement plus du tout).
function chemistryRosterImportance(rank) {
  return clamp(1 - (rank - 1) / (CHEMISTRY_ROSTER_CHANGE_MAX_RANK - 1), 0, 1);
}

// Rang (1 = meilleur) d'un joueur PRÉCIS dans une liste de joueurs donnée,
// d'après overall() — à appeler au moment EXACT où ce joueur quitte ou
// rejoint un effectif (avant le splice() côté vendeur, après le push() côté
// acheteur, voir League._resolveListing/Team.sellPlayer), jamais après
// coup : le rang d'un joueur qui vient de partir n'a plus de sens une fois
// qu'il n'est plus dans la liste.
function rosterRankOf(players, playerId) {
  const sorted = [...players].sort((a, b) => b.overall() - a.overall());
  const idx = sorted.findIndex(p => p.id === playerId);
  return idx === -1 ? sorted.length + 1 : idx + 1;
}

// État affiché pour Team.chemistry (voir moraleLabel plus haut, mêmes
// seuils, même esprit : la valeur exacte reste interne, seul l'état est
// montré au manager).
// Recalibré le 2026-10-06 sur la plage RÉELLE 40-100 (plancher CHEMISTRY_MIN) :
// « Vestiaire fracturé » était devenu inatteignable.
function chemistryLabel(chemistry) {
  if (chemistry >= 88) return "Alchimie parfaite";
  if (chemistry >= 74) return "Bonne cohésion";
  if (chemistry >= 60) return "Cohésion correcte";
  if (chemistry >= 48) return "Tensions dans le groupe";
  return "Vestiaire fracturé";
}

// ---------------------------------------------------------------------
// Fil d'actualité du tableau de bord (refonte "Soir de match", 2026-09-24)
// — logique de fil d'actualité PURE (aucun accès DOM), portée depuis le
// livrable prestataire `tableau-de-bord/newsFeed.js` (voir INTEGRATION.md et
// DEV_NOTES.md point 10 pour le contexte complet). Un fil par équipe
// (Team.feed, voir plus bas), sérialisé dans la sauvegarde comme le reste de
// l'état (serializeTeam/teamFromSave) — MÊME MIROIR EXACT dans
// moteurbasket3.html que le reste de ce moteur (convention du projet).
// Quelques noms renommés par rapport au livrable d'origine pour éviter toute
// ambiguïté dans ce fichier déjà très chargé en identifiants globaux :
// CATEGORIES → FEED_CATEGORIES, MAX_ENTRIES → FEED_MAX_ENTRIES, TEMPLATES →
// FEED_TEMPLATES, pick/fill/trim/euros (locaux au livrable) → feedPick/
// fillTemplate/trimFeedEntries/feedEuros (`pick` existe déjà plus haut dans
// ce fichier avec une signature différente). Comportement et contrat de
// données INCHANGÉS par rapport au livrable (voir ses propres tests
// `newsFeed.test.mjs`, réécrits dans le style du projet sous
// `dashboard_feed_test.js`).
// ---------------------------------------------------------------------

const FEED_CATEGORIES = ["club", "ligue", "presse", "marche", "supporters"];
const FEED_MAX_ENTRIES = 40;

/** Crée un fil vide, ou restaure un fil sauvegardé (objet JSON). */
function createFeed(saved) {
  return {
    entries: saved && saved.entries ? [...saved.entries] : [],
    nextId: (saved && saved.nextId) || 1,
  };
}

/** Objet sérialisable à mettre dans la sauvegarde de la partie. */
function serializeFeed(feed) {
  return { entries: feed.entries, nextId: feed.nextId };
}

/**
 * Ajoute une entrée. Si `key` est fourni et qu'une entrée avec la même clé
 * existe déjà, elle est remplacée (évite les doublons : une seule alerte
 * "staff vide", un seul récap de journée, etc.).
 */
function pushEntry(feed, entry) {
  if (!FEED_CATEGORIES.includes(entry.category)) {
    throw new Error(`Catégorie de fil d'actualité inconnue : ${entry.category}`);
  }
  const full = Object.assign({
    id: `evt_${feed.nextId++}`,
    priority: "normal",
    read: false,
    createdAt: Date.now(),
    action: null,
    key: null,
  }, entry);
  if (full.key) {
    feed.entries = feed.entries.filter(e => e.key !== full.key);
  }
  feed.entries.unshift(full);
  trimFeedEntries(feed);
  return full;
}

/** Retire une entrée par clé (ex. quand le problème d'une alerte est réglé). */
function removeByKey(feed, key) {
  feed.entries = feed.entries.filter(e => e.key !== key);
}

function markAllRead(feed) {
  feed.entries.forEach(e => { e.read = true; });
}

function unreadCount(feed) {
  return feed.entries.filter(e => !e.read).length;
}

/**
 * Entrées à afficher : alertes d'abord, puis les plus récentes.
 * `category` = "tout" ou une des FEED_CATEGORIES.
 */
function getVisibleEntries(feed, opts) {
  const category = (opts && opts.category) || "tout";
  const limit = (opts && opts.limit) || 8;
  return feed.entries
    .filter(e => category === "tout" || e.category === category)
    .sort((a, b) => {
      if (a.priority !== b.priority) return a.priority === "alert" ? -1 : 1;
      if (a.week !== b.week) return b.week - a.week;
      return b.createdAt - a.createdAt;
    })
    .slice(0, limit);
}

function trimFeedEntries(feed) {
  if (feed.entries.length <= FEED_MAX_ENTRIES) return;
  // On ne supprime jamais une alerte active : on retire les plus anciennes normales.
  const normals = feed.entries.filter(e => e.priority !== "alert");
  const excess = feed.entries.length - FEED_MAX_ENTRIES;
  const toDrop = new Set(
    normals.sort((a, b) => a.createdAt - b.createdAt).slice(0, excess).map(e => e.id)
  );
  feed.entries = feed.entries.filter(e => !toDrop.has(e.id));
}

const FEED_TEMPLATES = {
  victoire: {
    title: ["Victoire face à {adv}", "{club} s'impose contre {adv}", "Succès contre {adv}"],
    text: [
      "{club} gagne {score}{lieu}. {top} termine meilleur marqueur avec {pts} points.",
      "Score final {score}{lieu}. {top} a porté l'équipe ({pts} points).",
    ],
  },
  defaite: {
    title: ["Défaite contre {adv}", "{adv} fait tomber {club}", "Revers face à {adv}"],
    text: [
      "{club} s'incline {score}{lieu}. {top} a tenté de maintenir l'équipe à flot ({pts} points).",
      "Score final {score}{lieu}. Seul {top} a surnagé avec {pts} points.",
    ],
  },
  blessure: {
    title: ["{joueur} blessé", "Coup dur : {joueur} à l'infirmerie"],
    text: ["Indisponible environ {duree} semaine(s).", "Le staff médical prévoit {duree} semaine(s) d'absence."],
  },
  arrivee: {
    title: ["{joueur} rejoint {club}", "Recrue : {joueur}"],
    text: ["Arrivée en provenance de {origine} pour {montant}.", "Transfert conclu avec {origine} ({montant})."],
  },
  depart: {
    title: ["{joueur} quitte le club", "Départ de {joueur}"],
    text: ["Il rejoint {destination} pour {montant}.", "Transfert vers {destination} ({montant})."],
  },
  offre: {
    title: ["Offre reçue pour {joueur}", "{acheteur} s'intéresse à {joueur}"],
    text: ["{acheteur} propose {montant}. Réponse avant la semaine {limite}."],
  },
  staff: {
    title: ["{nom} nommé {poste}", "Nouveau {poste} : {nom}"],
    text: ["Le poste de {poste} est désormais pourvu.", "{nom} prend ses fonctions cette semaine."],
  },
};

function fillTemplate(template, vars) {
  return template.replace(/\{(\w+)\}/g, (_, k) => (vars[k] != null ? vars[k] : `{${k}}`).toString());
}

function feedPick(list, rng) {
  return list[Math.floor(rng() * list.length)];
}

function feedFromTemplate(type, vars, rng) {
  const t = FEED_TEMPLATES[type];
  return { title: fillTemplate(feedPick(t.title, rng), vars), text: fillTemplate(feedPick(t.text, rng), vars) };
}

function feedEuros(n) {
  return `${n.toLocaleString("fr-FR")} $`;
}

/**
 * Point d'entrée unique pour le moteur. `event.type` décide du traitement.
 * `ctx` = { clubName, rng } (rng optionnel, Math.random par défaut).
 */
function handleGameEvent(feed, event, ctx) {
  const rng = (ctx && ctx.rng) || Math.random;
  const club = ctx && ctx.clubName;
  const w = event.week;

  switch (event.type) {
    case "match_played": {
      const win = event.pointsFor > event.pointsAgainst;
      const vars = {
        club,
        adv: event.opponent,
        score: `${event.pointsFor}-${event.pointsAgainst}`,
        lieu: event.home ? " à domicile" : ` à ${event.opponent}`,
        top: (event.topScorer && event.topScorer.name) || "Personne",
        pts: (event.topScorer && event.topScorer.points) || 0,
      };
      return pushEntry(feed, Object.assign({
        category: "club",
        week: w,
        action: { label: "Voir le match", href: `/match/${event.matchId}` },
      }, feedFromTemplate(win ? "victoire" : "defaite", vars, rng)));
    }

    case "league_round": {
      // Un seul récap par journée, même si on l'appelle plusieurs fois.
      const lines = event.results.map(r => `${r.home} ${r.homePts}-${r.awayPts} ${r.away}`);
      return pushEntry(feed, {
        key: `league_round_${w}`,
        category: "ligue",
        week: w,
        title: `Journée ${event.round} : ${event.results.length} résultats`,
        text: lines.slice(0, 2).join(" · ") + (lines.length > 2 ? "…" : ""),
        action: { label: "Classement", href: "/ligue" },
      });
    }

    // Changement de poste de carte (voir Team.syncCardPositions).
    case "position_change": {
      const sh = pos => CARD_POSITION_SHORT[pos] || pos;
      return pushEntry(feed, {
        key: `poschange_${event.playerId}`,
        category: "club",
        week: w,
        title: `${event.playerName} joue désormais ${event.to} (note ${event.ratingTo} en ${sh(event.to)} contre ${event.ratingFrom} en ${sh(event.from)})`,
        text: "Son poste suit désormais ses caractéristiques. Son salaire, lui, reste celui de son contrat.",
        action: { label: "Effectif", href: "/effectif" },
      });
    }

    case "injury":
      return pushEntry(feed, Object.assign({
        key: `injury_${event.playerId}`,
        category: "club",
        priority: event.weeks >= 3 ? "alert" : "normal",
        week: w,
        action: { label: "Effectif", href: "/effectif" },
      }, feedFromTemplate("blessure", { joueur: event.playerName, duree: event.weeks }, rng)));

    case "injury_healed":
      removeByKey(feed, `injury_${event.playerId}`);
      return pushEntry(feed, {
        category: "club",
        week: w,
        title: `${event.playerName} de retour`,
        text: "Remis de sa blessure, il est de nouveau disponible.",
      });

    case "transfer_in":
      return pushEntry(feed, Object.assign({
        category: "marche", push: true,
        week: w,
        action: { label: "Voir le joueur", href: `/joueur/${event.playerId}` },
      }, feedFromTemplate("arrivee", {
        club, joueur: event.playerName, origine: event.from, montant: feedEuros(event.fee),
      }, rng)));

    case "transfer_out":
      return pushEntry(feed, Object.assign({
        category: "marche", push: true,
        week: w,
      }, feedFromTemplate("depart", {
        joueur: event.playerName, destination: event.to, montant: feedEuros(event.fee),
      }, rng)));

    case "offer_received":
      return pushEntry(feed, Object.assign({
        key: `offer_${event.offerId}`,
        category: "marche",
        priority: "alert",
        week: w,
        action: { label: "Répondre", href: `/marche/offre/${event.offerId}` },
      }, feedFromTemplate("offre", {
        joueur: event.playerName, acheteur: event.buyer, montant: feedEuros(event.amount), limite: event.deadlineWeek,
      }, rng)));

    case "offer_closed":
      removeByKey(feed, `offer_${event.offerId}`);
      return null;

    case "staff_hired":
      return pushEntry(feed, Object.assign({
        category: "club",
        week: w,
      }, feedFromTemplate("staff", { nom: event.name, poste: event.role }, rng)));

    case "interview":
      // Retiré du fil (retour utilisateur, 2026-09-25 : "fil d'actualité et
      // cette semaine, ça ne fait pas un peu doublon ?", voir DEV_NOTES.md
      // point 14) : cette même interview en attente est DÉJÀ affichée dans
      // la tâche "Cette semaine" du tableau de bord (dashBuildTasks, même
      // titre, même bouton "Répondre") tant qu'elle n'est pas traitée — plus
      // besoin de la pousser AUSSI dans le fil. `interview_done` ci-dessous
      // reste inchangé (removeByKey) : il nettoie sans condition toute
      // entrée `interview_<id>` déjà poussée AVANT ce correctif (sauvegarde
      // existante avec une interview en attente au moment du déploiement),
      // qui serait sinon restée coincée indéfiniment dans le fil.
      return null;

    case "interview_done":
      removeByKey(feed, `interview_${event.interviewId}`);
      return null;

    default:
      return null; // Événement non concerné par le fil.
  }
}

const FEED_STAFF_LABELS = { coach: "entraîneur", analyst: "analyste vidéo", scout: "recruteur", doctor: "médecin", physio: "kiné", assistant: "entraîneur adjoint" };
// Variante capitalisée (rôle "staff_hired" du contrat newsFeed.js, ex.
// "Nouveau Entraîneur : Niveau 5") — mêmes 3 rôles que FEED_STAFF_LABELS
// ci-dessus, juste la casse.
const FEED_STAFF_ROLE_LABELS = { coach: "Entraîneur", analyst: "Analyste vidéo", scout: "Recruteur", doctor: "Médecin", physio: "Kiné", assistant: "Entraîneur adjoint" };
// Le staff n'a pas de nom propre dans ce jeu (seulement un niveau, voir
// Team.trainer/videoAnalyst/recruiter) — placeholder EXPLICITEMENT documenté
// (voir DEV_NOTES.md point 10, question ouverte "staff nommé") plutôt que
// d'inventer un nom : "Niveau N", cohérent avec l'adaptateur du tableau de
// bord (moteurbasket3.html) qui affiche le même texte pour staff.coach.name.
function feedStaffPlaceholderName(level) {
  return `Niveau ${level}`;
}

function feedMoodEntry(feed, week, category, value, cfg) {
  const key = `mood_${cfg.keyPrefix || category}`;
  // Seuils propres à la jauge (alchimie : plage réelle 40-100, voir CHEMISTRY_MIN).
  const zone = value < (cfg.lowBelow ?? 30) ? "low" : value > (cfg.highAbove ?? 70) ? "high" : null;
  const existing = feed.entries.find(e => e.key === key);
  if (!zone) {
    removeByKey(feed, key);
    return;
  }
  if (existing && existing.zone === zone) return; // Déjà signalé, pas de spam chaque semaine.
  const [title, text] = cfg[zone];
  pushEntry(feed, {
    key, zone, category,
    priority: zone === "low" ? "alert" : "normal",
    week, title,
    text: fillTemplate(text, { v: Math.round(value) }),
    action: { label: "Détail", href: cfg.href },
  });
}

/**
 * state = { week, budget, supporters, chemistry, staff: { coach, analyst, scout } }
 * (supporters et chemistry sur 100 ; staff : true si le poste est pourvu)
 */
function checkThresholds(feed, state) {
  const w = state.week;

  // alert_staff / alert_budget : retirés du fil (retour utilisateur,
  // 2026-09-25, même correctif que "interview" ci-dessus, voir
  // DEV_NOTES.md point 14) — dashBuildTasks (tableau de bord) affiche déjà
  // "Staff : N/3 postes pourvus" et "Budget dans le rouge" dans la carte
  // "Cette semaine", mêmes conditions exactement (missing.length > 0 /
  // budget < 0). Le nettoyage reste INCONDITIONNEL (plus de branche
  // `else`) pour retirer, dès le prochain passage, toute entrée déjà
  // poussée avant ce correctif sur une sauvegarde existante.
  removeByKey(feed, "alert_staff");
  removeByKey(feed, "alert_budget");

  feedMoodEntry(feed, w, "supporters", state.supporters, {
    low: ["Les supporters grondent", "Humeur à {v}/100. Les tribunes attendent une réaction."],
    high: ["Les supporters sont conquis", "Humeur à {v}/100. La salle devrait être pleine."],
    href: "/supporters",
  });
  feedMoodEntry(feed, w, "club", state.chemistry, {
    lowBelow: 50, highAbove: 85,
    low: ["Tensions dans le vestiaire", "Alchimie à {v}/100. Les résultats risquent d'en pâtir."],
    high: ["Un groupe soudé", "Alchimie à {v}/100. L'équipe joue ensemble."],
    href: "/vestiaire",
    keyPrefix: "chemistry",
  });
}

/** state = { clubName, week, rounds, firstOpponent, firstMatchHome, firstMatchDate, supporters } */
function seedSeasonStart(feed, state) {
  pushEntry(feed, {
    key: "season_start",
    category: "ligue",
    week: state.week,
    title: "Le championnat est lancé",
    text: `${state.rounds} journées au programme. ${state.clubName} ouvre ${
      state.firstMatchHome ? "à domicile" : "à l'extérieur"
    } face à ${state.firstOpponent} ${state.firstMatchDate}.`,
    action: { label: "Calendrier", href: "/calendrier" },
  });
  pushEntry(feed, {
    key: "season_start_supporters",
    category: "supporters",
    week: state.week,
    title: "Les supporters attendent de voir",
    text: `Humeur à ${state.supporters}/100 : le premier match comptera.`,
    action: { label: "Détail", href: "/supporters" },
  });
}

// ---------------------------------------------------------------------
// ÉQUIPE
// ---------------------------------------------------------------------
// Convocation : nombre maximum de joueurs sur la feuille de match.
const CONVOCATION_MAX = 12;

// Remplaçants max par poste (1 remplaçant + 1 réserviste), voir
// Team.toggleBackupPosition.
const MAX_BACKUPS_PER_POSITION = 2;

class Team {
  constructor({ name, players, country }) {
    this.name = name;
    // Pays du club (2026-09-28, championnats par pays) : celui de son
    // championnat ; pilote la nationalité des jeunes de son centre de
    // formation (voir generateYouthCandidate). "fr" pour tout club d'avant.
    this.country = country || "fr";
    this.players = players; // 15 joueurs (3 par poste)

    this.autoAssignLineup();

    this.offensivePriorities = ["Équilibrée", "Pick & Roll", "Jeu en mouvement"];
    this.defense = "Homme à homme";
    this.rhythm = "Normal";

    // Tactique confirmée (retour utilisateur, 2026-09 — voir le grand
    // commentaire au-dessus de SCREEN_DEFENSES) : "tacticalTier" ne
    // sert qu'à choisir quels réglages proposer côté interface — TOUS
    // les champs ci-dessous existent déjà pour une équipe "débutant", à
    // leur valeur standard, pour que le moteur n'ait jamais besoin de
    // tester le tier lui-même. Ne JAMAIS changer une de ces valeurs par
    // défaut sans revérifier qu'elle reste un delta de zéro dans les
    // tables SCREEN_DEFENSES/HELP_DEFENSE_LEVELS/POST_DEFENSES/
    // CLOSEOUT_STYLES/OFF_REBOUND_STYLES/ENDGAME_MANAGEMENT ci-dessus.
    this.tacticalTier = "débutant"; // "débutant" | "confirmée"
    this.screenDefense = "Aucune consigne"; // clé de SCREEN_DEFENSES
    this.helpDefense = "Moyenne";           // clé de HELP_DEFENSE_LEVELS
    this.watchAssignments = [];             // jusqu'à 3 × { position, focus } — voir WATCH_FOCUS_EFFECTS
    this.postDefense = "Classique";         // clé de POST_DEFENSES
    this.closeoutStyle = "Contrôlé";        // clé de CLOSEOUT_STYLES
    this.offRebStyle = "Normal";            // clé de OFF_REBOUND_STYLES
    this.endgameManagement = "Standard";    // clé de ENDGAME_MANAGEMENT — indépendant du tier

    // Tutoriel d'accueil (retour utilisateur, 2026-09 : "on est d'accord
    // qu'on ne peut le faire qu'une fois ? quand il a été fait le bouton
    // dans le guide doit s'enlever") : jamais lu par le moteur de
    // simulation lui-même, mais DOIT quand même exister ici : c'est CE
    // fichier (mirroir exact, voir l'en-tête du fichier) qui reconstruit
    // team côté serveur à chaque sauvegarde (server/store.js ->
    // teamFromSave/serializeTeam plus bas), donc un champ absent d'ici est
    // silencieusement perdu à chaque aller-retour serveur, même s'il existe
    // côté client. Voir server/actions.js:setOnboardingTourCompleted pour
    // l'écriture côté serveur en ligue partagée (où saveMyTeam() ne peut
    // pas persister ce champ, voir moteurbasket3.html).
    this.onboardingTourCompleted = false;

    // Primes du tutoriel déjà créditées (retour utilisateur, 2026-09 :
    // "Mets les vrais primes sur le tutoriel") : liste des clés `topic` de
    // TOUR_REWARD_BY_TOPIC déjà payées à CE club, une fois pour toutes,
    // quel que soit le nombre de fois où le tutoriel est relancé ou
    // abandonné en cours de route (voir claimTutorialReward plus bas) :
    // sans ce ledger, redémarrer le tutoriel après l'avoir quitté avant la
    // fin (onboardingTourCompleted encore à `false`) permettrait de
    // retoucher indéfiniment les primes des thèmes déjà vus.
    this.tutorialRewardsClaimed = [];

    this.maintainDespiteFouls = new Set();
    // Plans d'ordres préparés À L'AVANCE pour une journée future (retour
    // utilisateur, 2026-09 : "sur buzzerbeater on peut faire pour tous les
    // matchs de la saison, [...] pratique de pouvoir préparer sa semaine en
    // avance"), valeur = un instantané complet des ordres
    // {offensivePriorities, defense, rhythm, lineup, ...}. Clé = planKey(round,
    // competition) ci-dessus ("championship:<round>" ou "cup:<round>"),
    // PAS un simple numéro de journée (correctif 2026-09, retour
    // utilisateur : "il faut pouvoir donner ses ordres pour chaque match" —
    // championnat et Coupe numérotent chacun leurs journées/tours à partir
    // de 0, une clé composite évite qu'ils s'écrasent l'un l'autre). Les
    // champs "en direct" (this.offensivePriorities/defense/rhythm/lineup
    // ci-dessus) restent la SEULE source lue au moment de simuler la
    // PROCHAINE journée à résoudre ; un plan stocké ici n'est appliqué à ces
    // champs qu'au moment où SA journée devient celle qu'on résout (voir
    // applyPlannedTacticsForRound, appelé depuis server/liveMatch.js) —
    // jusque-là, préparer une journée future ne change rien au match
    // immédiat. Vide par défaut : aucune journée future préparée,
    // comportement strictement identique à avant cette fonctionnalité tant
    // qu'elle n'est pas utilisée. Migration des sauvegardes plus anciennes
    // (clé = bare round number, forcément championnat à l'époque) vers ce
    // nouveau format : voir teamFromSave plus bas.
    this.plannedTactics = {};
    // Tactiques enregistrées (voir TACTIC_PRESETS_MAX) : [{ name, savedAt, orders }].
    this.tacticPresets = [];
    // Ordres complets des derniers matchs joués (voir ORDERS_HISTORY_MAX,
    // recordOrdersHistory) : « partir d'un match précédent » dans l'onglet
    // Tactiques. Le plus récent en tête.
    this.ordersHistory = [];
    // Historique des transferts du club (voir recordTeamTransfer) et date
    // de prise de fonction du manager actuel (« Mon historique » du marché).
    this.transferHistory = [];
    this.managerSince = null;
    // Succès (voir achEvaluate) : club créé avec le nouveau système, rien
    // à reprendre d'un ancien format.
    this.achStats = { migrated: true };
    this.achTiers = {};
    this.achLog = [];
    this.achSeenAt = 0;
    // Rivalités et note des managers (voir recordHumanRivalry).
    this.rivalries = {};
    // Parquet aux couleurs du club (Premium, voir courtStyleFor).
    this.courtStyle = null;
    // Mise en scène du direct (2026-10-08) : apparence du coach (tous) et
    // mascotte (Premium) — voir normalizeCoachLook / mascotFor.
    this.coachLook = null;
    this.mascot = null;
    // Salle personnalisée (Premium, voir arenaStyleFor).
    this.arenaStyle = null;
    this.managerRating = null;
    this.managerRatedGames = 0;

    // Fil d'actualité du tableau de bord (voir le grand commentaire au-dessus
    // de FEED_CATEGORIES) : un fil par équipe, vide à la création — rempli
    // via handleGameEvent/checkThresholds au fil de la saison. Toujours créé
    // (même pour une équipe CPU, jamais affiché ni consulté dans ce cas)
    // pour que serializeTeam/teamFromSave restent uniformes.
    this.feed = createFeed();

    this.week = 1; // semaine d'entraînement courante (pas de calendrier complet pour l'instant)
    // Retour utilisateur (2026-09) : "au dessus de ces temps de jeu, il
    // faudrait ajouter un historique des ups et downs de la derniere
    // semaine d'entrainement" : dernier rapport renvoyé par trainWeek()
    // ci-dessous, conservé pour un réaffichage persistant sur l'onglet
    // Entraînement (voir renderLastTrainingReport côté client). Ce même
    // rapport n'était jusqu'ici affiché qu'UNE fois, de façon éphémère,
    // dans le récapitulatif "Pendant votre absence" (voir
    // trainingReportHtml/showCatchupSummaryIfAny, pendingEvents jamais
    // sauvegardé). `null` tant qu'aucune semaine d'entraînement n'a encore
    // été jouée.
    this.lastTrainingReport = null;
    // Historique de l'entraînement (Premium, retour utilisateur 2026-09-27) :
    // les TRAINING_HISTORY_MAX derniers bilans hebdomadaires, allégés (seuls
    // les joueurs dont une caractéristique a bougé) — voir trainWeek.
    this.trainingHistory = [];
    // Marché (Premium) : liste de suivi et alertes, voir MARKET_WATCHLIST_MAX.
    this.marketWatchlist = []; // [{ playerId, since }]
    // Signets du manager (2026-10-04) : n'importe quel joueur du jeu, par son
    // id unique ; leagueId = dernier championnat connu (le serveur le met à
    // jour s'il est transféré ailleurs, voir server/bookmarks.js).
    this.bookmarks = []; // [{ playerId, leagueId, since }]
    this.marketAlerts = []; // [{ id, createdAt, pos, age, pot, price, crit }]
    this.marketAlertSeen = {}; // { listingId: 1 (annonce signalée) | 2 (fin proche signalée) }
    // Entraînement hebdomadaire à la BuzzerBeater : UNE compétence pour tout
    // le club, appliquée à un ensemble de postes (1 à 5). Ce n'est pas un
    // choix joueur par joueur : chaque joueur profite (ou pas) de la semaine
    // selon son propre poste et selon s'il a assez joué au dernier match.
    // Retour utilisateur (2026-09) : "enleve l'entrainement aucune
    // (entrainement général uniquement)" — il n'existe plus d'option "pas de
    // focus cette semaine" (voir populateTrainingSkillSelect côté client,
    // qui ne propose plus cette option, et setTraining côté serveur, qui
    // n'accepte plus `null`) : une compétence est TOUJOURS sélectionnée, par
    // défaut "Lancer franc" (freeThrow) pour une toute nouvelle équipe.
    this.trainingSkill = "freeThrow"; // une clé de TRAINING_PROGRAMS, jamais null
    this.trainingPositions = [];    // 1, 2, 3 ou 5 postes parmi POSITIONS

    // Entraînement v2 (retour utilisateur 2026-10-01) : plans individuels
    // (un joueur + un programme par place, nombre de places selon
    // l'entraîneur, voir TRAINING_SLOTS_BY_COACH_LEVEL), intensité de la
    // semaine, parrainages, plan collectif jour par jour, bilan collectif de
    // la semaine en cours et semaines sans progrès (conseils).
    // trainingSkill/trainingPositions ci-dessus ne servent plus qu'à la
    // migration des anciennes sauvegardes.
    this.trainingSlots = [];          // [{ playerId, program, intensity }]
    this.mentorships = [];            // [{ youngId, veteranId }]
    this.collectiveDayPlan = {};      // { [dayIndex]: { collectiveTraining, trainedTactics } }
    this.collectiveWeek = null;       // bilan collectif de la semaine en cours
    this.trainingStalls = {};         // { [playerId]: { program, weeks } }
    this.friendlyPlayersByDay = {};   // { [dayIndex]: [ids des joueurs alignés en amical] }

    // Entraînement collectif (retour utilisateur, 2026-09 : "je souhaite
    // mettre en place maintenant l'entrainement collectif [...] soit bosser
    // une nouvelle tactique [...] soit bosser la récupération") : un réglage
    // SÉPARÉ de trainingSkill ci-dessus, les deux tournent EN MÊME TEMPS
    // (l'un porte sur les caractéristiques individuelles d'un groupe de
    // postes, l'autre sur le collectif de toute l'équipe). `null` = aucun
    // focus collectif cette semaine (comportement par défaut, inchangé pour
    // les parties déjà en cours). "tactique" : ajoute un bonus de gain sur
    // l'aspect précis travaillé (voir Team.trainedTactics/
    // TACTICAL_KNOWLEDGE_DAILY_GAIN/updateTacticalKnowledge).
    // "recuperation" :
    // porte la récupération de forme physique quotidienne à CONDITION_
    // RECOVERY_PER_DAY_TRAINED au lieu de CONDITION_RECOVERY_PER_DAY (voir
    // conditionRecoveryPerDay ci-dessous/currentCondition plus haut).
    this.collectiveTraining = null; // null | "tactique" | "recuperation" | "physique" (retour utilisateur 2026-10-01)

    // Tactique précisément travaillée à l'entraînement (retour utilisateur,
    // 2026-09 : "il faut effectivement choisir ce qui est bossé comme
    // tactique si c'est ce qui est choisi (exemple zone extérieure)", puis
    // "sachant que tu n'as qu'un jour pour faire cet entrainement [...] un
    // seul aspect et pas tous les aspects") : UN SEUL aspect précis à la
    // fois (jamais plusieurs catégories en même temps comme dans une
    // première version de cette fonctionnalité) — pertinent UNIQUEMENT
    // quand collectiveTraining === "tactique", ignoré sinon. `category`
    // désigne QUELLE des 3 catégories lues par Team.updateTacticalKnowledge
    // est travaillée, `value` LA valeur précise de cette catégorie (une
    // priorité offensive pour "offense", un nom de défense pour "defense",
    // un rythme pour "rhythm") — voir Team.updateTacticalKnowledge plus bas
    // pour le détail de l'appariement.
    this.trainedTactics = null; // null | { category: "offense"|"defense"|"rhythm", value: string }

    // Historique quotidien de l'entraînement collectif DEPUIS LE DERNIER
    // MATCH (retour utilisateur, 2026-09 : "si tu as 3 jours de repos, tu
    // divises à chaque fois par 2 le malus [...] par jour d'entrainement sur
    // la tactique [...] si le vendredi on fait entrainement récup [...] on
    // doit quand même avoir le malus divisé par deux du mercredi et par deux
    // encore une fois le jeudi" — formulé à l'origine pour l'alchimie,
    // conservé à l'identique pour la connaissance tactique) : UNE entrée par
    // jour civil (voir
    // Team.syncCollectiveTrainingLog/parisCalendarDayIndex plus bas),
    // reconduite automatiquement d'un jour à l'autre si rien ne change,
    // JAMAIS effacée par un jour "récupération" intercalé (seul un vrai
    // match remet ce compteur à zéro, voir tacticsCycleStartDayIndex
    // ci-dessous) — permet de compter, au moment d'un match, combien de
    // jours de repos ont précisément porté sur LA MÊME tactique que celle
    // effectivement jouée ce jour-là (voir Team.daysTrainedForTarget).
    this.collectiveTrainingLog = []; // [{ dayIndex, collectiveTraining, trainedTactics }]
    // Jour civil (voir parisCalendarDayIndex) du DERNIER match réellement
    // joué : sert de repère pour ignorer tout jour de collectiveTrainingLog
    // antérieur (ou identique) à ce match — "depuis le dernier match"
    // s'applique littéralement, jamais un historique plus ancien. `null`
    // tant qu'aucun match n'a encore été joué.
    this.tacticsCycleStartDayIndex = null;
    // Jours civils (parisCalendarDayIndex) où le club a joué un AMICAL (voir
    // Team.markFriendlyDay) : pas des jours de repos, donc ni entraînement
    // collectif tactique ni récupération ces jours-là.
    this.friendlyDayIndexes = [];

    // Staff : l'entraîneur n'a d'effet QUE sur la vitesse d'entraînement
    // (jamais sur les matchs). Pas d'entraîneur par défaut.
    this.trainer = null; // { level, weeksEmployed } ou null

    // Analyste vidéo (retour utilisateur, 2026-09 : "il faudrait pouvoir
    // scouter l'effectif de son adversaire [...] en engageant un staff plus
    // ou moins compétent, on peut voir plus ou moins de caractéristiques de
    // l'adversaire en faisant une séance vidéo") : un DEUXIÈME rôle de staff,
    // structurellement identique à l'entraîneur (même forme { level,
    // weeksEmployed, baseSalary }, même marché aux enchères — voir plus bas
    // League.analystListings/generateAnalystCandidate/placeAnalystBid/
    // _resolveAnalystListing/refreshAnalystMarket/fireTeamVideoAnalyst,
    // calqués sur leurs équivalents "entraîneur") — mais un effet totalement
    // différent : aucun impact sur l'entraînement, il débloque des SÉANCES
    // VIDÉO (voir League.runVideoSession plus bas) qui révèlent
    // progressivement les caractéristiques cachées des adversaires.
    this.videoAnalyst = null; // { level, weeksEmployed, baseSalary } ou null

    // Scoutisme adverse : nom/poste/taille/salaire sont TOUJOURS visibles
    // pour n'importe quel adversaire (aucun besoin de staff) — voir
    // moteurbasket3.html (panneau de scoutisme sur l'écran Classement). Les
    // 10 caractéristiques (ATTRS), elles, restent cachées tant qu'aucune
    // séance vidéo n'a permis de les révéler : `scoutedAttrs` associe
    // l'INDEX de chaque adversaire déjà scouté (converti en chaîne — une clé
    // d'objet JS est toujours une chaîne) au tableau des clés ATTRS déjà
    // révélées pour lui. Les caractéristiques révélées le restent pour le
    // reste de la saison même si l'analyste est ensuite congédié (une vidéo
    // déjà visionnée ne s'"oublie" pas) — voir League.runVideoSession, seul
    // endroit qui écrit dans cette carte, jamais une lecture qui la ferait
    // rétrécir. `lastVideoSessionAt` : horodatage RÉEL (epoch ms) de la
    // dernière séance vidéo de CE club, tous adversaires confondus — une
    // seule séance par JOUR CIVIL À PARIS (voir sameParisCalendarDay plus
    // bas), le même ancrage que le rythme quotidien entraînement/économie de
    // la ligue multi-manager (retour utilisateur : implicitement "1 séance
    // par jour", même esprit que "training/economy once per day").
    this.scoutedAttrs = {};
    this.lastVideoSessionAt = null;
    // Rapports de l'analyste vidéo par club adverse (assets/scouting-fog.js),
    // par saison, avec historique : remplace scoutedAttrs (indexé par la
    // position du club dans la ligue, qui change avec les montées).
    this.scoutReports = {};

    // Scouting Pro (retour utilisateur, 2026-09 : "analyse des équipes
    // adverses (« Scouting Pro ») en mode payant + accès gratuit via pub
    // récompensée") : un DEUXIÈME rapport d'adversaire, séparé du rapport
    // tactique déjà existant et déjà gratuit (voir tacticalReportHtml/
    // computeScoutingTendencies côté navigateur, qui restent inchangés) —
    // celui-ci ajoute forme récente, bilan domicile/extérieur, séries,
    // historique des confrontations, zones de tir et joueurs clés, gagné
    // soit en visionnant une pub (factice pour l'instant, voir
    // server/scouting.js), soit via `scoutingPremium` ci-dessous. Clé de
    // `scoutingUnlocks`/décision de "premium ou pas" : l'INDEX de
    // l'adversaire au sein de la ligue (même convention que scoutedAttrs
    // juste au-dessus), PAS un identifiant de match précis — ce rapport
    // porte sur l'adversaire lui-même (tout son historique de saison), pas
    // sur une seule confrontation à venir, exactement comme le rapport
    // tactique gratuit déjà existant qui, lui non plus, n'est lié à aucun
    // match précis (voir runVideoSession, même principe).
    //
    // "Passer Pro" (retour utilisateur : "Bouton 'Passer Pro' factice pour
    // le moment [...] pas de vrai paiement") : bascule dev UNIQUEMENT,
    // aucune notion de paiement réel tant qu'aucune régie n'est branchée —
    // voir server/actions.js:setScoutingPremium. Un club Premium voit TOUS
    // les rapports Pro débloqués en permanence, jamais besoin de pub.
    this.scoutingPremium = false;
    // Rapports Pro déjà débloqués : { [opponentIdx]: { level: "full",
    // unlockedAt, source: "ad"|"premium", gamesPlayedAtUnlock } }.
    // `gamesPlayedAtUnlock` (nombre de matchs de l'adversaire déjà comptés
    // à ce moment-là, voir server/scouting.js:buildScoutingReport) sert à
    // détecter la péremption : dès que l'adversaire a disputé un nouveau
    // match depuis ce déblocage, les données ont changé, le rapport doit
    // être redébloqué (pub ou Premium) pour rester à jour — plus simple et
    // plus robuste qu'une expiration calée sur un horaire de coup d'envoi
    // précis (jamais qu'UN SEUL adversaire par entrée ici, pas de clé
    // composite round/compétition nécessaire, voir le commentaire ci-dessus).
    this.scoutingUnlocks = {};
    // Horodatages (ms) des pubs (factices) effectivement COMPLÉTÉES par ce
    // club, tous adversaires confondus — sert uniquement à compter le quota
    // quotidien de 3 (DAILY_AD_UNLOCK_CAP, voir server/scouting.js),
    // recalculé à la demande par jour civil à Paris (parisCalendarDayIndex,
    // même esprit que collectiveTrainingLog plus haut) plutôt que maintenu
    // par un compteur séparé, pour ne jamais risquer un désync entre les
    // deux. Jamais purgé (les entrées d'un jour révolu ne comptent
    // simplement plus dans le quota, mais restent en historique).
    this.scoutingAdWatchLog = [];
    // Tickets de pub (factice) en attente de complétion : { [ticketId]:
    // { opponentIdx, createdAt } }. Créé par POST /api/scouting/ad-ticket
    // (juste avant d'afficher l'écran gris), consommé par POST
    // /api/scouting/ad-complete (après le décompte côté client) — un ticket
    // garantit que ad-complete ne peut débloquer QUE ce que ad-ticket a
    // explicitement autorisé, et rend la complétion idempotente (un ticket
    // déjà consommé, supprimé de cette carte, ne peut plus l'être une
    // deuxième fois).
    this.scoutingAdTickets = {};

    // Retour utilisateur (2026-09) : "quand les ordres ont été validés, il
    // faudrait [...] que le bouton donnez vos ordres deviennent : Modifier
    // vos ordres". Numéro de journée (league round) pour laquelle CE club a
    // explicitement cliqué "✅ Valider les ordres" en dernier (voir
    // validateOrdres/markOrdresValidated côté navigateur), distinct de
    // "des ordres existent" (toujours vrai, ce sont les ordres EN DIRECT,
    // voir Team.offensivePriorities et consorts) : sert uniquement à ce
    // badge d'interface, jamais lu par la simulation elle-même. `null` tant
    // qu'aucune validation explicite n'a eu lieu ; redevient "obsolète" tout
    // seul dès que la journée courante avance (comparé à currentMatch.round
    // côté navigateur), sans logique de remise à zéro dédiée nécessaire.
    this.ordresValidatedRound = null;

    // Recruteur — TROISIÈME rôle de staff (retour utilisateur, 2026-09 :
    // académie de jeunes), même forme que l'entraîneur/l'analyste vidéo
    // ci-dessus ({ level, weeksEmployed, baseSalary }, même marché aux
    // enchères — voir plus bas League.recruiterListings/
    // generateRecruiterCandidate/placeRecruiterBid/_resolveRecruiterListing/
    // refreshRecruiterMarket/fireTeamRecruiter) — mais un TROISIÈME effet,
    // différent des deux autres : tant qu'il est sous contrat, ce club (et
    // lui SEUL, voir this.youthCandidates ci-dessous) reçoit périodiquement
    // de nouvelles propositions de jeunes prospects.
    this.recruiter = null; // { level, weeksEmployed, baseSalary } ou null

    // Staff médical (voir MEDICAL_STAFF_ROLES plus haut) : médecin (durée
    // des blessures) et kiné (récupération + risque de blessure), même forme
    // que les trois rôles ci-dessus.
    this.doctor = null; // { level, weeksEmployed, baseSalary } ou null
    // Entraîneur adjoint (voir ASSISTANT_SPECIALTIES) : un seul par club.
    this.assistantCoach = null; // { level, weeksEmployed, baseSalary, specialty } ou null
    this.physio = null; // { level, weeksEmployed, baseSalary } ou null

    // Académie de jeunes — pipeline PRIVÉ de prospects (15-17 ans), jamais
    // partagé avec les autres managers (contrairement au marché aux
    // enchères de l'entraîneur/l'analyste/le recruteur ci-dessus, où TOUS
    // les managers voient et enchérissent sur les mêmes candidats) : voir
    // League.refreshYouthCandidates... non, cette maintenance vit sur Team
    // lui-même (Team.refreshYouthCandidates), CE flux n'appartenant qu'à ce
    // club précis, pas à la ligue entière. `youthCandidates` : propositions
    // EN ATTENTE d'une décision (signer/ignorer, voir Team.signYouthCandidate/
    // declineYouthCandidate) — attributs ACTUELS visibles immédiatement,
    // potentiel réel TOUJOURS caché (voir youthProspectLabel plus bas), même
    // règle qu'un joueur pro normal (potentialTierLabel) : un prospect de
    // l'académie tire son potentiel EXACTEMENT comme n'importe quel joueur
    // (potentialHeadroom(age) + overall() + clamp(1,99), AUCUN plafond
    // spécifique — retour utilisateur explicite : "un joueur du centre de
    // formation doit pouvoir avoir un potentiel jusqu'à 99 [...] doit pouvoir
    // devenir une superstar"), seul l'AFFICHAGE diffère : pendant toute la
    // phase académie (candidat NON signé OU jeune déjà signé mais pas encore
    // promu), le manager ne voit qu'un label grossier à 3 bandes
    // (youthProspectLabel), plus flou que le potentialTierLabel normal (10
    // paliers) utilisé pour un pro — voir le grand commentaire sur
    // youthProspectLabel plus bas pour le détail des 3 bandes.
    // `youthPlayers` : jeunes déjà SIGNÉS (jusqu'à MAX_YOUTH_ROSTER_SIZE),
    // MÊME masquage à 3 bandes que ci-dessus tant qu'ils ne sont pas promus
    // (voir Team.promoteYouthPlayer : c'est LA promotion vers l'effectif pro,
    // pas la signature, qui expose enfin le potentialTierLabel normal). Ces
    // joueurs ne jouent JAMAIS de match et n'ont AUCUN programme
    // d'entraînement à choisir (délibéré, pas de micro-management — voir
    // Team.growYouthPlayers, progression entièrement automatique, PLAFONNÉE
    // caractéristique par caractéristique à 50 — voir son commentaire —
    // indépendamment du potentiel réel qui, lui, n'est jamais plafonné). Au
    // passage d'une saison (voir Team.trainWeek), un jeune qui atteint 18 ans
    // est retiré de la gestion automatique et placé en attente d'une
    // décision manager explicite (voir this.pendingYouthDecisions ci-dessous)
    // plutôt que promu/libéré automatiquement.
    this.youthCandidates = [];
    this.youthPlayers = [];

    // Centre de formation — facilité tiered comme la salle (voir
    // TRAINING_CENTER_LEVELS/Team.nextTrainingCenterLevel/
    // upgradeTrainingCenter plus bas) : démarre au palier 1 comme
    // this.arenaLevel, un palier plus élevé accélère la progression
    // automatique des jeunes (voir Team.growYouthPlayers).
    this.trainingCenterLevel = 1;

    // Décisions manager en attente pour un jeune qui vient d'avoir 18 ans
    // (voir Team.trainWeek/promoteYouthPlayer/releaseYouthPlayer) : tableau
    // d'id de joueurs ENCORE présents dans this.youthPlayers (pas encore
    // déplacés/retirés) — si le manager ne tranche pas avant le PROCHAIN
    // passage de saison, le joueur est auto-libéré par défaut (voir
    // Team.trainWeek : ne jamais laisser une décision ignorée bloquer
    // indéfiniment une place de l'effectif jeunes).
    this.pendingYouthDecisions = [];

    // Palmarès du club (retour utilisateur, 2026-09, sur l'onglet Académie
    // de jeunes : "il faut trouver du contenu à ajouter", le haut de la
    // page jugé "affreusement vide") : nombre total de jeunes formés par
    // l'académie et promus en pro au fil de l'histoire du club (voir
    // Team.promoteYouthPlayer, seul point d'incrément). Jamais décrémenté,
    // même si le joueur est ensuite vendu, libéré ou prend sa retraite : un
    // compteur historique, pas un effectif courant.
    this.academyGraduates = 0;
    // Retour utilisateur (2026-09) : "l'historique du centre de formation,
    // c'est les joueurs qui étaient dans le centre de formation et qui sont
    // passés pro" : liste (pas juste un compteur) des jeunes promus, dans
    // l'ordre chronologique, affichée par renderAcademyGraduatesStat (côté
    // client) à la place du simple total ci-dessus. Chaque entrée est un
    // instantané figé au moment de la promotion (nom, poste).
    this.academyGraduatesHistory = [];

    this.budget = CLUB_STARTING_BUDGET;

    // Salle (voir ARENA_LEVELS) + un prix de billet par catégorie de place
    // (voir SEAT_CATEGORIES), la boutique des supporters (voir
    // FAN_SHOP_LEVELS, revenu hebdomadaire fixe payé dans trainWeek), et le
    // journal des transactions (recettes/dépenses les plus récentes, pour
    // l'écran "Économie") — voir recordTransaction().
    this.arenaLevel = 1;
    this.seats = null; // { gradins, tribune, courtside, loge } une fois la salle agrandie librement (voir buildSeats)
    this.ticketPrices = {};
    SEAT_CATEGORIES.forEach(cat => { this.ticketPrices[cat.key] = cat.defaultPrice; });
    this.fanShopLevel = 0;
    // Autres infrastructures (voir CLUB_FACILITIES ci-dessus) : un niveau par
    // clé, 0 = rien construit — toujours un objet complet (jamais nul/absent),
    // pour que facilityInjuryRiskMult()/facilityFatigueMult() n'aient jamais
    // à gérer un cas manquant.
    this.facilityLevels = { tvStation: 0, gym: 0, wellness: 0 };
    this.transactions = [];
    this.financeLedger = {}; // voir recordTransaction / FINANCE_CATEGORIES

    // Humeur des supporters (voir attendanceBaseForMorale / moraleForgiveness
    // / moraleLabel) : neutre au départ, évolue avec les résultats et le
    // confort tarifaire — voir applyMoraleForResult et trainWeek.
    this.fanMorale = 50;
    this.prestige = null; // voir clubPrestigeDetail (mis à jour chaque semaine par trainWeek)
    this.moraleHistory = [];

    // Objectif de saison fixé par le conseil d'administration (retour
    // utilisateur, 2026-09, voir le grand commentaire au-dessus de
    // SEASON_OBJECTIVE_TIERS plus bas) : `null` tant qu'aucune ligue n'a
    // encore été générée pour ce club (assignSeasonObjectives, appelée par
    // buildLeagueWithHumanTeams, le pose dès la création/régénération de la
    // ligue), une des 5 clés de SEASON_OBJECTIVE_TIERS une fois posé.
    this.seasonObjective = null;
    // Retour utilisateur (2026-09) : "pour les équipes de milieu de
    // classement (ni PO ni barrage) et celles qui descendent tout de
    // suite, il ne faut pas qu'un signal et pas deux [...] la fin de la
    // saison régulière correspond à la fin de la saison pour ces équipes
    // là" : ces équipes reçoivent leur VRAI verdict de saison (voir
    // seasonObjectiveVerdict) dès la fin de la saison régulière (voir
    // server/liveMatch.js:finalizeRound), jamais un second signal plus
    // tard. Ce drapeau évite qu'il soit réappliqué une seconde fois côté
    // navigateur (voir startNewSeason) une fois la ligue entière terminée,
    // pour les équipes qui, elles, n'avaient reçu qu'un simple aperçu
    // provisoire à ce moment-là (play-offs/barrage encore à jouer).
    // Remis à `false` par assignSeasonObjectives à chaque nouvelle saison.
    this.seasonObjectiveVerdictSettled = false;

    // Alchimie d'équipe (voir le grand commentaire au-dessus de
    // CHEMISTRY_ROSTER_CHANGE_MAX_RANK plus haut) : neutre au départ, comme
    // fanMorale.
    this.chemistry = 50;
    // Cinq de départ du dernier match joué (ids triés, voir
    // updateChemistryAfterMatch) : null tant qu'aucun match n'a été joué.
    this.lastStartersKey = null;
    // Série de résultats officiels pour l'alchimie (voir applyChemistryResult) :
    // > 0 victoires consécutives, < 0 défaites consécutives.
    this.chemistryResultStreak = 0;
    // Dynamique de groupe (voir assets/vestiaire.js) : relevés hebdo,
    // événements de vestiaire, dernier état connu, relations fortes.
    this.locker = vestiaireApi() ? vestiaireApi().emptyLocker() : { history: [], log: [], last: null, relations: {} };
    // Connaissance tactique (voir le grand commentaire CONNAISSANCE
    // TACTIQUE au-dessus de TACTICAL_KNOWLEDGE_GAIN_BASE plus haut) : neutre
    // au départ sur CHACUNE des 18 options possibles (10 priorités
    // offensives + 5 défenses + 3 rythmes, voir defaultTacticalKnowledgeShape),
    // même convention que chemistry ci-dessus. tacticalKnowledgeStreaks
    // (même forme, valeur de départ 0) garde le compteur de série par
    // option qui pilote la courbe de gain/perte progressive.
    this.tacticalKnowledge = defaultTacticalKnowledgeShape(50);
    this.tacticalKnowledgeStreaks = defaultTacticalKnowledgeShape(0);

    // Médias : interviews de jalon en attente d'un ton de réponse (retour
    // utilisateur, 2026-09 : "Interview d'après match qui pourrait influencer
    // sur les supporters et les joueurs [...] une petite interaction à choix
    // multiples [...] qui influence légèrement le moral ou l'humeur des
    // supporters. Peu coûteux à développer, et cela ajoute de la
    // personnalité") : un tableau, alimenté par applyMoraleForResult
    // ci-dessous UNIQUEMENT aux 5 moments clés de la saison (voir
    // MILESTONE_INTERVIEW_TYPES), vidé au fur et à mesure par
    // resolveInterview/skipInterview (voir MILESTONE_INTERVIEW_TONES plus
    // bas), même esprit de file d'attente que pendingYouthDecisions plus
    // haut, jamais bloquant pour la simulation elle-même. L'interview
    // classique d'après CHAQUE match (V1, fanMorale seul) a été retirée
    // (retour utilisateur, 2026-09 : "on enlève ça") au profit du seul
    // système de jalon, qui fait aussi bouger Player.form.
    this.pendingInterviews = [];

    // MVP automatique du dernier match joué par ce club (retour utilisateur,
    // 2026-09 : "mettre ses citations sur la page tableau de bord [...] et
    // sur le box score du match fini") : posé pour les DEUX équipes (celle
    // du MVP et son adversaire) par awardMatchMvp (voir server/liveMatch.js),
    // que le MVP appartienne à ce club ou à l'adversaire : un club n'a sinon
    // aucun moyen de savoir qui a été élu MVP de son dernier match si ce
    // n'était pas l'un de ses propres joueurs. `null` tant qu'aucun match
    // n'a encore été joué.
    this.lastMatchMvp = null;

    // Identité du club : logo et maillots (retour utilisateur, 2026-09 :
    // "une petite page d'accueil pour les autres équipes [...] le logo de
    // l'équipe doit être type dès lors que l'équipe ne paie pas [...] pour
    // les équipes qui paient, elles doivent pouvoir charger leur propre
    // image [...] une équipe gratuite doit pouvoir choisir uniquement entre
    // 2 formes de maillot et 5 couleurs [...] le logo et les maillots
    // doivent pouvoir être modifiés dans le tableau de bord"). Voir
    // JERSEY_COLORS/JERSEY_SHAPES/MAX_TEAM_LOGO_DATA_URL_LENGTH plus haut et
    // setJersey/setCustomLogo/setPaying plus bas. `isPaying` : pas de vrai
    // système de paiement pour l'instant, interrupteur manuel en attendant.
    // `customLogoDataUrl` : ignoré au RENDU dès que `isPaying` est faux
    // (jamais effacé pour autant, voir setPaying) plutôt qu'un logo type
    // toujours régénéré depuis le nom/la couleur de maillot du club, sans
    // rien stocker (voir teamLogoHtml côté moteurbasket3.html).
    this.isPaying = false;
    // Trigramme personnalisé (retour communauté 2026-09 : "Pouvoir choisir
    // son trigramme", "qui peut être que 2 lettres") : 2 ou 3 lettres A-Z,
    // unique dans la ligue, `null` = calculé
    // depuis le nom (voir teamTrigram). trigramChangedAt limite les
    // changements à un tous les TRIGRAM_CHANGE_COOLDOWN_MS (classements
    // lisibles pour les autres managers).
    this.trigram = null;
    this.trigramChangedAt = null;
    // Pseudo du manager (voir checkManagerPseudo) et date du dernier
    // changement (0 = premier choix, sans délai ; null = jamais choisi).
    this.managerPseudo = null;
    this.managerPseudoChangedAt = null;
    // Nom de salle personnalisé (retour communauté 2026-09 : "Modifier le
    // nom de sa salle") : `null` = nom du palier ARENA_LEVELS (voir
    // teamArenaName).
    this.arenaName = null;
    // Premium TEMPORAIRE (voir DEV_NOTES.md point 11, "Hoop Shows" —
    // pronostics d'avant-match/mi-temps) : lot de fin de saison pour le
    // vainqueur du classement mondial des pronostics ("1 mois de Premium",
    // décision Antony). Délibérément SÉPARÉ d'`isPaying` ci-dessus (qui reste
    // un interrupteur manuel permanent, jamais un statut avec date
    // d'expiration) plutôt que de réutiliser `isPaying` tel quel : un lot
    // "temporaire" a besoin d'une échéance, qu'`isPaying` n'a jamais eue.
    // Voir `hasActivePremium` plus bas, qui combine les deux (permanent OU
    // temporaire en cours) — c'est CETTE méthode, jamais `isPaying` seul, que
    // lit le lecteur d'émission (showPlayer `premium`) pour sauter la page de
    // pub. `null` = aucun Premium temporaire en cours.
    this.premiumUntil = null;
    // Fonctionnalités en bêta ouvertes à CE club seulement (2026-10-07,
    // « ajouter ce mode à un seul joueur pour qu'il teste avant la prod ») :
    // noms de fonctionnalités, posés par POST /api/admin/beta-feature.
    // Exemple : ["live2d"] = terrain animé du direct.
    this.betaFeatures = [];
    this.customLogoDataUrl = null;
    this.jerseyShape = JERSEY_SHAPES[0];
    this.jerseyColor = Object.keys(JERSEY_COLORS)[0];
    // Motif de maillot (retour utilisateur : "ajoute des maillots avec des
    // dessins particuliers (rayure, degrade...)" pour le mode payant) : voir
    // JERSEY_PATTERNS/setJerseyPattern, même garde-fou "isPaying" que
    // customLogoDataUrl ci-dessus.
    this.jerseyPattern = JERSEY_PATTERNS[0];
    // Combinaison de 2 couleurs pour les motifs "rayures"/"degrade" (retour
    // utilisateur : "mets le choix de 2 couleurs [...] mets plus de choix")
    // : voir JERSEY_TWO_TONE_SETS/setJerseyTwoTone, même garde-fou
    // "isPaying" que jerseyPattern ci-dessus. Une valeur par défaut est
    // toujours définie (même pour un club gratuit qui ne la voit jamais au
    // rendu) pour ne jamais avoir à distinguer "pas encore choisi" de
    // "choisi mais ignoré".
    this.jerseyTwoTone = Object.keys(JERSEY_TWO_TONE_SETS)[0];

    // Maillot EXTÉRIEUR, indépendant du maillot domicile ci-dessus (retour
    // utilisateur, 2026-09 : "sur les maillots, il y a un problème, c'est
    // qu'on ne peut choisir que les maillots domiciles, il faudrait changer
    // ça" puis "Travaille sur les maillots extérieurs également") : même
    // forme que le domicile (jerseyShape, un club n'a qu'une seule coupe de
    // maillot), mais couleur/motif/combinaison propres, mêmes garde-fous
    // "isPaying" que jerseyPattern/jerseyTwoTone (voir
    // setAwayJerseyPattern/setAwayJerseyTwoTone plus bas). Couleur par
    // défaut choisie pour contraster avec le maillot domicile (voir
    // defaultAwayJerseyColor plus haut) plutôt qu'une couleur fixe, pour ne
    // pas avoir 2 maillots identiques dès la création d'un club.
    this.awayJerseyColor = defaultAwayJerseyColor(this.jerseyColor);
    this.awayJerseyPattern = JERSEY_PATTERNS[0];
    this.awayJerseyTwoTone = Object.keys(JERSEY_TWO_TONE_SETS)[0];

    // Date de création et trophées (retour utilisateur, 2026-09 : "on
    // pourrait ajouter les petites infos comme date de création, renommée et
    // trophée du club" en regardant la page "Aperçu"). `foundedYear` : voir
    // generateFoundedYear plus haut, tiré une seule fois puis figé par
    // serializeTeam/teamFromSave. `trophies` : alimenté par
    // League.recordTrophy (voir advanceCup/runPlayoffs plus bas), jamais
    // écrit ailleurs. La "renommée" n'a PAS de champ ici : voir
    // computeClubReputationStars plus haut, recalculée à l'affichage.
    this.foundedYear = generateFoundedYear();
    // Marqueur de migration (retour utilisateur, 2026-09 : "on a tjrs des
    // dates de création random") : distingue un foundedYear posé par la
    // logique RÉELLE actuelle (voir generateFoundedYear plus haut) d'un
    // foundedYear hérité de l'ancienne logique aléatoire (5 à 90 ans avant
    // aujourd'hui, avant le commit "Annee de fondation du club reelle").
    // Toujours vrai pour un club neuf ; voir teamFromSave plus bas pour la
    // migration ponctuelle des sauvegardes antérieures à ce marqueur.
    this.foundedYearRealDate = true;
    this.trophies = [];
    // Histoire du club (voir archiveSeasonForTeam plus bas) : une entrée
    // par saison archivée (la plus récente en premier), records et cumul
    // des joueurs passés par le club ; lastArchivedSeasonId rend
    // l'archivage idempotent.
    // Sponsors (voir le bloc SPONSORS plus bas) : offres en attente,
    // contrats actifs (une saison), historique, réputation 0-100 et date de
    // la dernière vague d'offres.
    this.sponsorOffers = [];
    this.sponsorContracts = [];
    this.sponsorHistory = [];
    this.sponsorReputation = SPONSOR_REPUTATION_DEFAULT;
    this.lastSponsorOfferAt = 0;
    this.seasonHistory = [];
    this.clubRecords = {};
    this.allTimePlayers = {};
    this.lastArchivedSeasonId = null;
    // Hall of Fame (voir Team.inductHallOfFame) : joueurs choisis par le
    // manager, maillot éventuellement retiré (affiché dans la salle).
    this.hallOfFame = [];

    // Affluence des derniers matchs à domicile (retour utilisateur, 2026-09 :
    // "sur l'onglet salle, il n'y a tjrs pas l'affluence des matchs
    // précédents (jusqu'à 10 matchs)") : même principe que moraleHistory
    // ci-dessus (unshift + plafond), mais plafonné à 10 plutôt que 40 (demande
    // explicite), alimenté par simulateHomeAttendance plus bas, un seul appel
    // par match à DOMICILE (jamais à l'extérieur, l'affluence de la salle
    // adverse n'est pas suivie ici).
    this.attendanceHistory = [];
    // Carnet des blessures (onglet Centre médical, retour utilisateur
    // 2026-09-27) : une entrée par blessure survenue en match, la plus
    // récente en tête, plafonné à INJURY_LOG_MAX (voir recordInjury).
    this.injuryLog = [];

    // Semaines CONSÉCUTIVES où le budget est resté sous DEFICIT_ALERT_THRESHOLD
    // (voir trainWeek) — remis à zéro dès que le budget repasse au-dessus.
    this.deficitWeeks = 0;

    // Identité manager (retour utilisateur, 2026-09 : jusqu'à 10 vrais
    // managers humains dans UNE seule ligue partagée, le reste comblé par des
    // adversaires CPU — voir generateMultiManagerLeague) : `false`/`null` par
    // défaut pour TOUTE équipe (y compris les adversaires CPU, qui ne portent
    // jamais ces champs) — seul le code qui construit une équipe pour un
    // VRAI manager (generateLeague pour le solo historique,
    // generateMultiManagerLeague pour plusieurs) met `isHuman` à `true` et
    // génère un `managerLinkToken` frais (voir randomHexToken ci-dessus).
    // Avant ce champ, "index 0 = le manager humain" était une simple
    // convention non écrite, partout dans League/server/ — ce flag la rend
    // explicite, ce qui permet à un manager humain d'occuper N'IMPORTE QUEL
    // index (voir buildLeagueWithHumanTeams). `managerLinkToken` est le seul
    // secret qui identifie une requête HTTP comme venant de CE manager (voir
    // server/store.js:resolveManagerTeam) — jamais affiché ni journalisé.
    this.isHuman = false;
    this.managerLinkToken = null;

    // Droit d'administration de ligue (2026-09, Phase B) : `false` par défaut
    // pour toute équipe. Un SEUL manager par ligue multi-managers peut porter
    // `isAdmin: true` (choisi à la création via `adminTeamName`, voir
    // server/store.js:generateMultiManagerLeague — par défaut le tout premier
    // nom de `teamNames`). Ce flag autorise ce manager à déclencher un reset
    // complet de la ligue depuis l'app (voir POST /api/reset-multi-league
    // côté serveur), sans jamais exposer le secret BASKET_ADMIN_TOKEN brut.
    this.isAdmin = false;
  }

  // ---------------------------------------------------------------------
  // Économie : toute variation de budget (recette ou dépense) passe par
  // recordTransaction, seule source de vérité pour le budget ET le journal
  // affiché sur l'écran "Économie" (les 40 entrées les plus récentes).
  // ---------------------------------------------------------------------
  recordTransaction(label, amount) {
    this.transactions = this.transactions || [];
    this.transactions.unshift({ week: this.week, label, amount: Math.round(amount) });
    if (this.transactions.length > 40) this.transactions.length = 40;
    this.budget += amount;
    // Cumul par poste et par semaine (voir FINANCE_CATEGORIES).
    if (!this.financeLedger || typeof this.financeLedger !== "object") this.financeLedger = {};
    const key = `${(this.seasonHistory || []).length + 1}:${this.week}`;
    const cat = financeCategoryOf(label, amount);
    const row = this.financeLedger[key] || (this.financeLedger[key] = {});
    row[cat] = Math.round((row[cat] || 0) + amount);
    const keys = Object.keys(this.financeLedger);
    if (keys.length > FINANCE_LEDGER_MAX) keys.slice(0, keys.length - FINANCE_LEDGER_MAX).forEach(k => delete this.financeLedger[k]);
  }

  // Humeur des supporters : toute variation passe par ici, seule source de
  // vérité pour fanMorale ET le journal affiché sur l'écran "Humeur des
  // supporters" (les 40 événements les plus récents). `extra` (optionnel) :
  // champs supplémentaires fusionnés dans l'entrée du journal, sans toucher
  // à fanMorale ni au calcul du delta, uniquement pour de l'information
  // d'affichage propre à certains appelants (voir resolveInterview
  // ci-dessous, qui y ajoute `quote`).
  recordMoraleEvent(label, delta, extra = {}) {
    this.moraleHistory = this.moraleHistory || [];
    const rounded = Math.round(delta * 10) / 10;
    // `after` : humeur réellement atteinte après cet événement (bornée 0-100),
    // pour que la courbe "Évolution sur la saison" de l'écran Humeur ne
    // dérive pas quand une variation bute sur 0 ou 100.
    const after = Math.round(clamp(this.fanMorale + delta, 0, 100) * 10) / 10;
    this.moraleHistory.unshift({ week: this.week, label, delta: rounded, ...extra, after });
    if (this.moraleHistory.length > 40) this.moraleHistory.length = 40;
    this.fanMorale = clamp(this.fanMorale + delta, 0, 100);
  }

  // Effet des résultats sportifs sur l'humeur : une victoire nette (gros
  // écart) enthousiasme un peu plus qu'une victoire courte, une défaite
  // sévère agace un peu plus qu'une défaite courte. Appelé à chaque match
  // (domicile ou extérieur). `round` : conservé sur l'entrée (utile aux
  // jalons de saison régulière, retrouvés par round côté navigateur), mais
  // NE crée plus d'interview à lui seul depuis le retrait de l'interview
  // classique d'après-match (retour utilisateur, 2026-09 : "on enlève ça") :
  // seul `milestone` déclenche désormais la mise en attente d'une interview
  // (voir pendingInterviews/MILESTONE_INTERVIEW_TONES ci-dessous).
  // `now` (optionnel, horodatage réel en millisecondes) : posé sur l'entrée
  // comme `at`, point de départ du délai de réponse (voir
  // MILESTONE_INTERVIEW_RESPONSE_DEADLINE_MS/pruneExpiredInterviews) ; par
  // défaut Date.now(), le vrai moment où ce résultat est traité, jamais une
  // date du calendrier simulé de la ligue.
  // `milestone` (optionnel, retour utilisateur 2026-09 : "elle doit avoir
  // lieu après le match de la mi saison [...] fin de la saison régulière
  // [...] demi finale de PO [...] finale de PO [...] début de saison") : une
  // des clés de MILESTONE_INTERVIEW_TYPES, seule condition de mise en
  // attente d'une interview (délai de 3 jours, tons/citations étoffés, effet
  // sur Player.form — voir pruneExpiredInterviews/resolveInterview), SANS
  // rien changer au delta de fanMorale immédiat calculé juste en dessous (le
  // résultat sportif du jour reste toujours traité pareil).
  // `explicitPlayerIds` (optionnel) : par défaut (`null`), les joueurs
  // affectés par une interview de jalon sont déduits de secondsPlayed > 0 AU
  // MOMENT de cet appel — correct pour début de saison/mi-saison/fin de
  // saison régulière (appelé juste après le match concerné, rien d'autre ne
  // s'est simulé entre-temps). NE MARCHE PAS pour la demi-finale de
  // play-offs : la finale se simule juste après dans la même série de tours,
  // et écraserait secondsPlayed des deux finalistes avant que
  // _queuePlayoffSeriesInterview n'ait la moindre chance de le lire, voir
  // League.recordPlayoffGameResult/_queuePlayoffSeriesInterview, qui passent
  // ici un instantané figé AU MOMENT de la demi-finale plutôt que de compter
  // sur ce repli automatique.
  applyMoraleForResult(won, scoreDiff, opponentName, round, now = Date.now(), milestone = null, explicitPlayerIds = null, derby = false) {
    this.pruneExpiredInterviews(now);
    const margin = clamp(Math.abs(scoreDiff) / 40, 0, 1);
    // Derby contre le rival du championnat (League.isDerbyMatch, 2026-09-29,
    // « affluence et humeur ») : l'humeur bouge DERBY_MORALE_MULT fois plus
    // fort, dans un sens comme dans l'autre.
    const mult = derby ? DERBY_MORALE_MULT : 1;
    const delta = (won ? rand(3, 6) + margin * 1.5 : -(rand(2, 5) + margin * 1.5)) * mult;
    this.recordMoraleEvent(derby
      ? (won ? `Derby gagné contre ${opponentName}` : `Derby perdu contre ${opponentName}`)
      : (won ? `Victoire contre ${opponentName}` : `Défaite contre ${opponentName}`), delta);
    if (milestone) {
      this.pendingInterviews = this.pendingInterviews || [];
      const entry = {
        id: uid(), round, opponentName, won, scoreDiff, at: now, milestone,
        // Joueurs affectés par l'effet sur Player.form à la résolution (voir
        // resolveInterview) : voir le commentaire d'explicitPlayerIds
        // au-dessus pour pourquoi un repli automatique ne suffit pas
        // toujours.
        playerIds: explicitPlayerIds || this.players.filter(p => p.secondsPlayed > 0).map(p => p.id),
      };
      this.pendingInterviews.push(entry);
      // Fil d'actualité du tableau de bord (voir FEED_CATEGORIES plus haut) :
      // même entrée `pendingInterviews` ci-dessus, juste projetée dans le fil
      // (clé `interview_<id>`, retirée par resolveInterview ci-dessous).
      // `daysLeft` toujours 3 à la création (voir MILESTONE_INTERVIEW_RESPONSE_
      // DEADLINE_MS, même délai que pruneExpiredInterviews).
      if (this.feed) {
        const milestoneInfo = MILESTONE_INTERVIEW_TYPES[milestone];
        handleGameEvent(this.feed, {
          type: "interview", week: this.week, interviewId: entry.id,
          subject: milestoneInfo ? milestoneInfo.label : "Interview de jalon",
          daysLeft: 3, title: milestoneInfo ? milestoneInfo.label : "Interview de jalon",
        }, { clubName: this.name });
      }
    }
    return delta;
  }

  // Retire silencieusement, sans le moindre effet sur l'humeur, toute
  // interview en attente depuis plus de MILESTONE_INTERVIEW_RESPONSE_
  // DEADLINE_MS (retour utilisateur : "on a 3 jours pour faire l'interview
  // sinon c'est neutre sur le moral") : un "sans commentaire" implicite pour
  // le manager qui n'a jamais répondu. Appelée systématiquement au début de
  // applyMoraleForResult/resolveInterview/skipInterview (housekeeping
  // automatique, jamais besoin d'un appel dédié) ET côté serveur à chaque
  // requête joueur (voir server/index.js:tick), pour que la file reste
  // propre même si le manager ne déclenche plus jamais aucune de ces trois
  // méthodes. Renvoie le nombre d'entrées retirées. Toute entrée SANS
  // `milestone` (résidu d'une sauvegarde antérieure au retrait de
  // l'interview classique d'après-match) est traitée comme déjà expirée et
  // retirée sans effet, plutôt que de garder vivant un système désormais
  // supprimé.
  pruneExpiredInterviews(now = Date.now()) {
    this.pendingInterviews = this.pendingInterviews || [];
    const before = this.pendingInterviews.length;
    this.pendingInterviews = this.pendingInterviews.filter(i => {
      return !!i.milestone && (now - i.at) < MILESTONE_INTERVIEW_RESPONSE_DEADLINE_MS;
    });
    return before - this.pendingInterviews.length;
  }

  // Résout une interview de jalon en attente avec le(s) ton(s) choisi(s) par
  // le manager (voir MILESTONE_INTERVIEW_TONES) : ajoute un delta d'humeur
  // des supporters ET un delta de forme pour TOUT L'EFFECTIF (correctif
  // 2026-09, retour utilisateur : "tous les joueurs doivent être impactés
  // par les interviews, les interviews sont sur des périodes de la saison
  // et pas uniquement un match", voir MILESTONE_INTERVIEW_TONES plus haut ;
  // `entry.playerIds`, figé à la mise en attente, ne sert donc plus qu'à
  // savoir qui a RÉELLEMENT joué le match ayant déclenché le jalon, plus à
  // scoper l'effet), dans le sens du résultat ORIGINAL du match concerné
  // (jamais l'inverse), puis retire l'entrée de la file. `tones` (correctif
  // 2026-09, retour utilisateur : "la possibilité de choisir le ton pour
  // chacune [des questions] et pas uniquement un ton pour toutes les
  // questions") : soit un TABLEAU (un ton par question), soit une chaîne
  // unique (compatibilité ascendante, appliquée à toutes les questions) —
  // voir interviewTranscriptFor pour le même contrat. Quand plusieurs tons
  // différents sont choisis, les deltas de CHAQUE ton sont MOYENNÉS (plutôt
  // que sommés) pour garder une magnitude globale comparable à l'ancien
  // système à ton unique. Renvoie { ok: true, delta, formDelta,
  // chemistryDelta, quotes } ou null (id introuvable/déjà traité, expiré
  // depuis plus de 3 jours, un ton inconnu, ou entrée sans `milestone` -
  // résidu d'une sauvegarde antérieure au retrait de l'interview classique,
  // voir pruneExpiredInterviews), jamais d'exception, comme le reste des
  // méthodes "résoudre une file d'attente" de cette classe (voir
  // promoteYouthPlayer). Construit aussi le transcript complet
  // {question, answer}[] (voir interviewTranscriptFor/
  // MILESTONE_INTERVIEW_QUESTIONS ci-dessus) et le fige dans le journal via
  // `recordMoraleEvent(..., { quotes, quote })` : `quote` (les réponses
  // mises bout à bout) reste affiché tel quel sur la page "Aperçu" (retour
  // utilisateur : "mets plutôt ce que le coach vraiment dit"), `quotes`
  // porte le détail question par question pour un affichage plus riche
  // (popup d'interview). `entry.opponentName` peut être `null` (interview
  // "debut-saison" d'avant-saison, voir queueSeasonPreviewInterview
  // ci-dessous, sans adversaire ni résultat concerné) : le libellé du
  // journal s'adapte alors pour ne mentionner ni victoire/défaite ni
  // adversaire.
  resolveInterview(id, tones, now = Date.now(), lockerAns = null) {
    this.pruneExpiredInterviews(now);
    this.pendingInterviews = this.pendingInterviews || [];
    const idx = this.pendingInterviews.findIndex(i => i.id === id);
    if (idx === -1) return null;
    const entry = this.pendingInterviews[idx];
    if (!entry.milestone) { this.pendingInterviews.splice(idx, 1); return null; }
    const questionCount = (MILESTONE_INTERVIEW_QUESTIONS[entry.milestone] || []).length || 2;
    const toneList = Array.isArray(tones) ? tones : Array(questionCount).fill(tones);
    if (!toneList.length || toneList.some(t => !MILESTONE_INTERVIEW_TONES[t])) return null;
    const toneConfigs = toneList.map(t => MILESTONE_INTERVIEW_TONES[t]);
    const avgOf = key => toneConfigs.reduce((sum, cfg) => sum + cfg[key], 0) / toneConfigs.length;
    const fanDelta = avgOf(entry.won ? "fanWin" : "fanLoss");
    const formDelta = avgOf(entry.won ? "formWin" : "formLoss");
    // Alchimie d'équipe (voir MILESTONE_INTERVIEW_TONES.chemistryWin/
    // chemistryLoss ci-dessus) : levier 1 des 3 (retour utilisateur).
    const chemistryDelta = avgOf(entry.won ? "chemistryWin" : "chemistryLoss");
    const milestoneInfo = MILESTONE_INTERVIEW_TYPES[entry.milestone];
    const milestoneLabel = milestoneInfo ? milestoneInfo.label : "Interview de jalon";
    const quotes = interviewTranscriptFor(entry.milestone, toneList, entry.won, entry.opponentName, entry.playerName);
    const quote = quotes.map(q => q.answer).filter(Boolean).join(" ");
    const toneLabel = toneList.every(t => t === toneList[0]) ? toneList[0].toLowerCase() : toneList.map(t => t.toLowerCase()).join("/");
    const label = entry.opponentName
      ? `${milestoneLabel} (ton ${toneLabel}) après ${entry.won ? "la victoire" : "la défaite"} contre ${entry.opponentName}`
      : `${milestoneLabel} (ton ${toneLabel})`;
    this.recordMoraleEvent(label, fanDelta, { quote, quotes, milestone: entry.milestone });
    // TOUT l'effectif (pas seulement entry.playerIds, voir le commentaire de
    // cette méthode plus haut) : une interview de jalon porte sur toute une
    // période de la saison, jamais sur le seul match qui l'a déclenchée.
    this.players.forEach(p => { p.form = clamp(Math.round(p.form + formDelta), 1, 100); });
    this.applyChemistryDelta(chemistryDelta);
    // Dynamique de groupe : intervention du coach journalisée (assets/vestiaire.js).
    if (vestiaireApi()) vestiaireApi().pushLog(this, { t: chemistryDelta > 0 ? "interview-up" : chemistryDelta < 0 ? "interview-down" : "interview", x: chemistryDelta });
    // Entretiens & communication (2026-10-08) : la déclaration est mémorisée ;
    // la question tirée du vestiaire (lockerAns) fait réagir chaque joueur.
    let statement = null;
    if (vestiaireApi()) {
      const V = vestiaireApi();
      V.recordComm(this, { quote: quotes.map(q => q.answer).filter(Boolean).join("\n"), milestone: entry.milestone, label: milestoneLabel, now, chem: chemistryDelta });
      if (lockerAns) statement = V.applyStatement(this, lockerAns, { milestone: entry.milestone, label: milestoneLabel, now, applyChemistry: d => this.applyChemistryDelta(d) });
    }
    this.pendingInterviews.splice(idx, 1);
    // Fil d'actualité (voir applyMoraleForResult ci-dessus, qui a créé
    // l'entrée `interview_<id>` correspondante) : retirée, l'interview est
    // répondue.
    if (this.feed) handleGameEvent(this.feed, { type: "interview_done", interviewId: entry.id }, { clubName: this.name });
    return { ok: true, delta: fanDelta, formDelta, chemistryDelta, quotes, statement };
  }

  // Interview d'AVANT-saison (correctif 2026-09, retour utilisateur : "la
  // première interview doit pouvoir se faire avant le début de saison et ne
  // doit pas porter sur le resultat du premier match mais sur la saison à
  // venir (objectif, joueur sur qui on compte...)") : remplace l'ancien
  // déclenchement (jalon "debut-saison" posé après le résultat de la
  // journée 0, voir l'ancien milestoneTypeForRound) par une mise en attente
  // dès la CRÉATION de la ligue, avant le moindre match joué (voir
  // Engine.buildLeagueWithHumanTeams, seul appelant). Contenu tourné vers
  // l'AVENIR plutôt qu'un résultat qui n'existe pas encore : `won` toujours
  // à `true` (cadrage positif/plein d'espoir, aucune variante "défaite" ne
  // sera jamais lue pour ce jalon précis, voir
  // MILESTONE_INTERVIEW_QUOTES["debut-saison"]), `opponentName` à `null`
  // (aucun match concerné), `playerIds` = tout l'effectif (discours de
  // rentrée adressé au groupe entier, pas seulement à ceux qui auront joué
  // un match qui n'a pas encore eu lieu). `playerName` : le joueur le mieux
  // noté de l'effectif à son poste (weightedRatingForPosition), substitué à
  // `{player}` dans les citations (voir interviewTranscriptFor). Ne fait
  // rien (renvoie `null`) si l'effectif est vide.
  queueSeasonPreviewInterview(now = Date.now()) {
    this.pruneExpiredInterviews(now);
    this.pendingInterviews = this.pendingInterviews || [];
    if (!this.players.length) return null;
    let keyPlayer = this.players[0];
    let bestRating = -Infinity;
    this.players.forEach(p => {
      const rating = weightedRatingForPosition(p.attrs, p.position);
      if (rating > bestRating) { bestRating = rating; keyPlayer = p; }
    });
    const entry = {
      id: uid(), round: null, opponentName: null, won: true, scoreDiff: null, at: now,
      milestone: "debut-saison",
      playerIds: this.players.map(p => p.id),
      playerName: keyPlayer.name,
    };
    this.pendingInterviews.push(entry);
    // Fil d'actualité (voir applyMoraleForResult pour le même principe sur
    // les autres jalons) : cette interview d'avant-saison n'y passe pas
    // (aucun résultat encore), d'où sa propre entrée ici.
    if (this.feed) {
      const milestoneInfo = MILESTONE_INTERVIEW_TYPES["debut-saison"];
      handleGameEvent(this.feed, {
        type: "interview", week: this.week, interviewId: entry.id,
        subject: milestoneInfo ? milestoneInfo.label : "Interview de jalon",
        daysLeft: 3, title: milestoneInfo ? milestoneInfo.label : "Interview de jalon",
      }, { clubName: this.name });
    }
    return entry;
  }

  // Applique un delta à Team.chemistry, toujours borné à [0, 100] (voir le
  // grand commentaire de CHEMISTRY_ROSTER_CHANGE_MAX_RANK plus haut pour les
  // 3 leviers qui l'appellent) : point d'entrée UNIQUE pour modifier
  // Team.chemistry, pour qu'aucun appelant ne puisse oublier le clamp.
  applyChemistryDelta(delta) {
    this.chemistry = clamp(this.chemistry + delta, CHEMISTRY_MIN, 100);
  }

  // Multiplicateur de performance lié à l'alchimie (voir Player.eff()/
  // Team.resetForMatch plus bas) : effet volontairement MODESTE (0.94 à
  // 1.06, +/-6%) — un "petit plus/petit moins" d'ensemble sur TOUTE
  // l'équipe, jamais un levier aussi fort que la forme physique ou la
  // fatigue d'UN joueur (voir CONDITION_STATES.perfFactor, qui va jusqu'à
  // -45%).
  // Leviers à la hausse de l'alchimie (voir CHEMISTRY_MATCH_TOGETHER_GAIN/
  // CHEMISTRY_SAME_FIVE_GAIN plus haut), une fois par match réellement joué.
  updateChemistryAfterMatch() {
    const starters = (this.lineup && this.lineup.starters) || {};
    const ids = POSITIONS.map(pos => starters[pos]).filter(id => id != null).map(String).sort();
    const key = ids.length === POSITIONS.length ? ids.join("|") : null;
    let gain = CHEMISTRY_MATCH_TOGETHER_GAIN;
    if (key && key === this.lastStartersKey) gain += CHEMISTRY_SAME_FIVE_GAIN;
    this.lastStartersKey = key;
    this.applyChemistryDelta(gain);
  }

  // Rôles de jeu, phase 4 (2026-10-06, voir assets/roles.js) : chaque
  // semaine, un titulaire dont le rôle joué à son poste ne correspond pas à
  // son rôle préféré perd un peu de motivation et le dit (au plus une fois
  // toutes les ROLE_MISMATCH_COOLDOWN_WEEKS semaines). Le manager peut
  // changer le joueur de poste, revoir son cinq ou accepter.
  applyRolePreferences(now = Date.now()) {
    const starters = (this.lineup && this.lineup.starters) || {};
    this.roleMismatchWeek = this.roleMismatchWeek && typeof this.roleMismatchWeek === "object" ? this.roleMismatchWeek : {};
    const out = [];
    POSITIONS.forEach(pos => {
      const p = this.players.find(x => x.id === starters[pos]);
      if (!p) return;
      const last = this.roleMismatchWeek[p.id];
      if (typeof last === "number" && this.week - last < ROLE_MISMATCH_COOLDOWN_WEEKS) return;
      let mm = null;
      try { mm = Roles.roleMismatch(p.attrs, positionRatings(p), p.position, p.id, pos); } catch (e) { mm = null; }
      if (!mm) return;
      this.roleMismatchWeek[p.id] = this.week;
      p.form = clamp(Math.round((p.form || 0) - ROLE_MISMATCH_FORM_MALUS), 1, 100);
      const quote = mm.kind === "usage" ? "Je pense que je ne suis pas suffisamment utilisé offensivement." : `Je me sens plus à l'aise comme ${mm.preferred.name}.`;
      if (this.feed) {
        pushEntry(this.feed, {
          key: `role_${p.id}`, category: "club", week: this.week, createdAt: now,
          title: `Le rôle de ${p.name} dans l'équipe ne correspond pas à son profil`,
          text: `« ${quote} » Il joue ${mm.played.name} au poste ${pos} ; il préfère ${mm.preferred.name}.`,
          action: { label: "Fiche joueur", href: `/joueur/${p.id}` },
        });
      }
      out.push({ playerId: p.id, ...mm });
    });
    return out;
  }

  // Résultat d'un match officiel (voir CHEMISTRY_WIN_GAIN plus haut) : `pf`
  // points marqués, `pa` encaissés. Égalité impossible au basket (ignorée).
  applyChemistryResult(pf, pa) {
    if (!Number.isFinite(pf) || !Number.isFinite(pa) || pf === pa) return 0;
    const prev = Number.isFinite(this.chemistryResultStreak) ? this.chemistryResultStreak : 0;
    let delta;
    if (pf > pa) {
      this.chemistryResultStreak = prev > 0 ? prev + 1 : 1;
      delta = this.chemistryResultStreak >= CHEMISTRY_STREAK_LENGTH ? CHEMISTRY_WIN_STREAK_GAIN : CHEMISTRY_WIN_GAIN;
    } else {
      this.chemistryResultStreak = prev < 0 ? prev - 1 : -1;
      delta = -(-this.chemistryResultStreak >= CHEMISTRY_STREAK_LENGTH ? CHEMISTRY_LOSS_STREAK : CHEMISTRY_LOSS);
      if (pa - pf > CHEMISTRY_BLOWOUT_MARGIN) delta -= CHEMISTRY_BLOWOUT_EXTRA;
      // Détermination (audit des attributs 2026-10-06) : après une défaite,
      // un joueur déterminé se remobilise (motivation en hausse), un joueur
      // qui l'est peu accuse le coup. Centré sur 50 : aucun effet moyen.
      this.players.forEach(p => {
        const d = Math.round(((p.attrs && p.attrs.determination) ?? 50) - 50) * DETERMINATION_LOSS_FORM_PER_POINT;
        if (Math.round(d)) p.form = clamp(Math.round((p.form || 0) + d), 1, 100);
      });
    }
    this.applyChemistryDelta(delta);
    Vestiaire.onResult(this, pf, pa);
    return delta;
  }

  chemistryFactor() {
    return 0.94 + (this.chemistry / 100) * 0.12;
  }

  // Historique quotidien de l'entraînement collectif (voir
  // Team.collectiveTrainingLog dans le constructeur pour le détail complet
  // de ce que ça représente et pourquoi) : à appeler à chaque fois qu'on a
  // l'occasion d'observer l'écoulement du temps réel pour CE club (voir
  // server/index.js:tick, appelé à CHAQUE requête joueur, et setTraining,
  // appelé à chaque changement de réglage) — jamais dépendant d'une boucle
  // qui avancerait "un jour à la fois" (ce jeu n'en a pas), donc comble
  // rétroactivement tout jour manqué depuis la dernière synchro en
  // reconduisant la config qui était alors active (voir la boucle
  // ci-dessous), plutôt que de perdre ces jours silencieusement.
  syncCollectiveTrainingLog(now = Date.now()) {
    const todayIndex = parisCalendarDayIndex(now);
    if (!Array.isArray(this.collectiveTrainingLog)) this.collectiveTrainingLog = [];
    const log = this.collectiveTrainingLog;
    // Plan jour par jour (retour utilisateur 2026-10-01) : chaque jour prend
    // son choix planifié, sinon le réglage courant (« à partir d'aujourd'hui »).
    const snapshotEntry = (dayIndex) => {
      const cfg = this.collectiveDayConfig(dayIndex);
      return {
        dayIndex,
        collectiveTraining: cfg.collectiveTraining,
        trainedTactics: cfg.trainedTactics ? { category: cfg.trainedTactics.category, value: cfg.trainedTactics.value } : null,
        // Intensité de chaque plan individuel ce jour-là (récupération).
        intensities: Object.fromEntries(this.activeTrainingSlots().map(sl => [String(sl.playerId), trainingIntensityOf(this, { id: sl.playerId })])),
      };
    };
    const last = log.length ? log[log.length - 1] : null;
    if (last && last.dayIndex === todayIndex) {
      // Même jour civil : dernier réglage du jour qui compte.
      log[log.length - 1] = snapshotEntry(todayIndex);
    } else {
      if (last) {
        for (let cursor = last.dayIndex + PARIS_DAY_MS; cursor < todayIndex; cursor += PARIS_DAY_MS) {
          // Jour manqué : son choix planifié, sinon le réglage encore actif
          // (setTraining synchronise AVANT de modifier quoi que ce soit).
          log.push(snapshotEntry(cursor));
        }
      }
      log.push(snapshotEntry(todayIndex));
    }
    this.applyRestDayRecovery(todayIndex);
    // Plan des jours passés : plus utile.
    if (this.collectiveDayPlan) {
      Object.keys(this.collectiveDayPlan).forEach(k => { if (Number(k) < todayIndex) delete this.collectiveDayPlan[k]; });
    }
    // Purge tout jour antérieur (ou identique) au dernier match joué.
    if (this.tacticsCycleStartDayIndex != null) {
      this.collectiveTrainingLog = this.collectiveTrainingLog.filter(e => e.dayIndex > this.tacticsCycleStartDayIndex);
    }
  }

  // Choix collectif d'un jour (retour utilisateur 2026-10-01) : plan du jour,
  // sinon réglage courant. { collectiveTraining, trainedTactics, planned }.
  collectiveDayConfig(dayIndex) {
    const p = this.collectiveDayPlan && this.collectiveDayPlan[dayIndex];
    if (p) {
      return {
        collectiveTraining: p.collectiveTraining || null,
        trainedTactics: p.trainedTactics || this.trainedTactics || null,
        planned: true,
      };
    }
    return { collectiveTraining: this.collectiveTraining || null, trainedTactics: this.trainedTactics || null, planned: false };
  }

  // Planifie le choix d'un jour de repos (aujourd'hui ou plus tard dans la
  // semaine). Aujourd'hui devient aussi le réglage par défaut des jours
  // suivants non planifiés. `trainedTactics` undefined = inchangé.
  setCollectiveDay(dayIndex, collectiveTraining, trainedTactics, now = Date.now()) {
    const todayIndex = parisCalendarDayIndex(now);
    if (!this.collectiveDayPlan || typeof this.collectiveDayPlan !== "object") this.collectiveDayPlan = {};
    const prev = this.collectiveDayConfig(dayIndex);
    const tactics = trainedTactics === undefined ? prev.trainedTactics : trainedTactics;
    const entry = {
      collectiveTraining: collectiveTraining || null,
      trainedTactics: tactics ? { category: tactics.category, value: tactics.value } : null,
    };
    if (dayIndex === todayIndex) {
      this.collectiveTraining = entry.collectiveTraining;
      if (trainedTactics !== undefined) this.trainedTactics = entry.trainedTactics;
    }
    this.collectiveDayPlan[dayIndex] = entry;
  }

  // Nombre de jours (depuis le dernier match, voir tacticsCycleStartDayIndex)
  // où l'entraînement collectif a porté EXACTEMENT sur `target` ({ category,
  // value }, voir Team.trainedTactics), utilisé par updateTacticalKnowledge
  // pour calculer le bonus de gain dû à l'entraînement (voir
  // TACTICAL_KNOWLEDGE_DAILY_GAIN). Un jour
  // "récupération" (ou tout autre focus) intercalé ne compte simplement
  // pas, mais n'efface pas non plus les jours déjà banqués (retour
  // utilisateur, 2026-09 : "si le vendredi on fait entrainement récup
  // [...] on doit quand même avoir le malus divisé par deux du mercredi et
  // par deux encore une fois le jeudi").
  // Focus collectif « Récupération » (retour utilisateur, 2026-09-27 :
  // "uniquement les jours de repos") : +CONDITION_RECOVERY_PER_DAY_TRAINED -
  // CONDITION_RECOVERY_PER_DAY (5) points de forme à tout l'effectif, une
  // fois par jour de repos ÉCOULÉ (dayIndex < aujourd'hui) passé sur ce
  // focus depuis le dernier match — un jour de match n'est jamais un jour de
  // repos : il est purgé du journal dès que le match est joué (voir
  // tacticsCycleStartDayIndex), avant d'être écoulé. Chaque jour n'est
  // crédité qu'une fois (recoveryApplied, sauvegardé). Appelée par
  // syncCollectiveTrainingLog, elle-même appelée juste avant chaque match
  // (voir Team.resetForMatch) pour que la forme au coup d'envoi en tienne
  // compte.
  // Match amical (retour utilisateur, 2026-09-27 : "un amical permet
  // d'engranger de la connaissance tactique, mais empêche de faire
  // l'entraînement collectif tactique ou de récupération") : le jour de
  // l'amical n'est plus un jour de repos (voir daysTrainedForTarget/
  // applyRestDayRecovery). Appelée par server/friendlies.js sur le VRAI club.
  markFriendlyDay(dayIndex, playerIds = null) {
    if (!Array.isArray(this.friendlyDayIndexes)) this.friendlyDayIndexes = [];
    if (!this.friendlyDayIndexes.includes(dayIndex)) this.friendlyDayIndexes.push(dayIndex);
    if (this.friendlyDayIndexes.length > 30) this.friendlyDayIndexes = this.friendlyDayIndexes.slice(-30);
    // Joueurs alignés en amical : exclus de la récupération/du physique du
    // jour (retour utilisateur 2026-10-01).
    if (Array.isArray(playerIds)) {
      if (!this.friendlyPlayersByDay || typeof this.friendlyPlayersByDay !== "object") this.friendlyPlayersByDay = {};
      this.friendlyPlayersByDay[dayIndex] = playerIds.slice();
      const keep = new Set(this.friendlyDayIndexes.map(String));
      Object.keys(this.friendlyPlayersByDay).forEach(k => { if (!keep.has(String(k))) delete this.friendlyPlayersByDay[k]; });
    }
  }
  isFriendlyDay(dayIndex) {
    return Array.isArray(this.friendlyDayIndexes) && this.friendlyDayIndexes.includes(dayIndex);
  }
  // Connaissance tactique gagnée en AMICAL (retour utilisateur, 2026-09-27 :
  // "si l'amical ne sert qu'à faire jouer les jeunes, c'est bizarre que ça
  // impacte fortement la tactique pour toute l'équipe" → gain réduit selon
  // les minutes des joueurs habituels, "base-toi sur les rôles des
  // joueurs") : chaque minute jouée pèse selon le rôle du joueur dans la
  // compo officielle actuelle — Titulaire 1, Joueur de rotation 0,5,
  // Réserviste ou jeune de l'académie 0 (FRIENDLY_TACTICAL_ROLE_WEIGHTS).
  // Pour chaque option jouée : gain d'un match (tacticalKnowledgeGainForStreak,
  // comme au prochain match de sa série) × cette part. Jamais de perte pour
  // les options non jouées, séries et jours d'entraînement collectif
  // accumulés inchangés (réservés au prochain match officiel).
  // `secondsByPlayerId` : secondes jouées dans l'amical par joueur (pros et
  // jeunes). Renvoie la part retenue (0 à 1).
  gainTacticalKnowledgeFromFriendly(secondsByPlayerId, youthPlayers = null) {
    // Club humain : chaque joueur (jeunes compris) apprend selon SES minutes
    // (voir PLAYER_TACTICAL_KNOWLEDGE_GAIN_BASE).
    if (this.isHuman) {
      const pool = [...(this.players || []), ...(youthPlayers || this.youthPlayers || [])];
      let gained = 0;
      Object.entries(secondsByPlayerId || {}).forEach(([id, secs]) => {
        if (!(secs > 0)) return;
        const p = pool.find(pl => String(pl.id) === String(id));
        if (!p) return;
        const isPro = (this.players || []).includes(p);
        const k = isPro ? this.ensurePlayerTacticalKnowledge(p) : (p.tacticalKnowledge = copyTacticalKnowledge(p.tacticalKnowledge));
        const share = Math.min(1, secs / TACTICAL_FULL_GAIN_SECONDS);
        const apply = (cat, key) => {
          if (!(key in k[cat])) return;
          const streak = ((this.tacticalKnowledgeStreaks || {})[cat] || {})[key] || 0;
          const gain = playerTacticalKnowledgeGainForStreak(streak > 0 ? streak + 1 : 1) * share;
          k[cat][key] = clamp(Math.round((k[cat][key] + gain) * 10) / 10, 0, 100);
        };
        new Set(this.offensivePriorities || []).forEach(o => apply("offense", o));
        apply("defense", this.defense);
        apply("rhythm", this.rhythm);
        gained++;
      });
      this.recomputeTacticalKnowledge();
      return gained > 0 ? 1 : 0;
    }
    let total = 0, weighted = 0;
    const backups = (this.lineup && this.lineup.backupPositions) || {};
    Object.entries(secondsByPlayerId || {}).forEach(([id, secs]) => {
      if (!(secs > 0)) return;
      total += secs;
      const p = (this.players || []).find(pl => String(pl.id) === String(id));
      if (!p) return; // jeune de l'académie : poids 0
      const w = this.starterPosition(p.id) ? FRIENDLY_TACTICAL_ROLE_WEIGHTS.starter
        : ((backups[p.id] || []).length ? FRIENDLY_TACTICAL_ROLE_WEIGHTS.rotation : FRIENDLY_TACTICAL_ROLE_WEIGHTS.reserve);
      weighted += secs * w;
    });
    const share = total > 0 ? clamp(weighted / total, 0, 1) : 0;
    if (share <= 0) return 0;
    const apply = (cat, key) => {
      const knowledge = this.tacticalKnowledge && this.tacticalKnowledge[cat];
      if (!knowledge || !(key in knowledge)) return;
      const streak = ((this.tacticalKnowledgeStreaks || {})[cat] || {})[key] || 0;
      const gain = tacticalKnowledgeGainForStreak(streak > 0 ? streak + 1 : 1) * share;
      knowledge[key] = clamp(Math.round((knowledge[key] + gain) * 10) / 10, 0, 100);
    };
    new Set(this.offensivePriorities || []).forEach(p => apply("offense", p));
    apply("defense", this.defense);
    apply("rhythm", this.rhythm);
    return share;
  }

  applyRestDayRecovery(todayIndex) {
    const bonus = CONDITION_RECOVERY_PER_DAY_TRAINED - CONDITION_RECOVERY_PER_DAY;
    const cycleStart = this.tacticsCycleStartDayIndex;
    (this.collectiveTrainingLog || []).forEach(e => {
      if (e.dayIndex >= todayIndex) return;
      if (cycleStart != null && e.dayIndex <= cycleStart) return;
      if (!e.intensityApplied) {
        e.intensityApplied = true;
        this.applyTrainingIntensityDay(e);
      }
      if (e.recoveryApplied) return;
      let option = e.collectiveTraining;
      if (!COLLECTIVE_DAY_OPTIONS.includes(option)) return;
      const friendly = this.isFriendlyDay(e.dayIndex);
      // Jour d'amical (retour utilisateur 2026-10-01) : pas de tactique pour
      // l'équipe, récupération/physique pour les joueurs non alignés. Une
      // tactique choisie avant que l'amical soit programmé devient une
      // récupération (retour utilisateur 2026-10-02 : la tactique doit être
      // impossible ce jour-là), comme l'affiche l'Entraînement.
      if (friendly && option === "tactique") option = "recuperation";
      e.recoveryApplied = true;
      const week = this.ensureCollectiveWeek();
      week.days[option] = (week.days[option] || 0) + 1;
      week.log.push({ dayIndex: e.dayIndex, option });
      if (option === "tactique") {
        this.applyTacticDay(e.trainedTactics);
        return;
      }
      const excluded = new Set(friendly ? (((this.friendlyPlayersByDay || {})[e.dayIndex]) || []).map(String) : []);
      const players = (this.players || []).filter(p => !excluded.has(String(p.id)));
      if (option === "recuperation") {
        players.forEach(p => { p.condition = clamp(p.condition + bonus, 0, 100); });
      } else {
        const mult = this.trainer && this.trainer.specialty === "physical" ? 1 + COACH_PHYSICAL_DAY_BONUS : 1;
        players.forEach(p => { week.physicalPoints += applyPhysicalDayTo(p, mult); });
      }
    });
  }

  // Intensité des plans individuels sur un jour de repos écoulé (retour
  // utilisateur 2026-10-01) : récupération réduite (recoveryPenalty) et,
  // en Intense, petit risque de blessure. Les joueurs alignés en amical ce
  // jour-là ne s'entraînent pas.
  applyTrainingIntensityDay(e) {
    const intensities = e.intensities || {};
    const excluded = new Set(this.isFriendlyDay(e.dayIndex) ? (((this.friendlyPlayersByDay || {})[e.dayIndex]) || []).map(String) : []);
    const at = e.dayIndex + 18 * 3600 * 1000;
    (this.players || []).forEach(p => {
      const key = intensities[String(p.id)];
      const intensity = key && TRAINING_INTENSITIES[key];
      if (!intensity || excluded.has(String(p.id)) || isCurrentlyInjured(p, at)) return;
      p.condition = clamp(p.condition - intensity.recoveryPenalty, 0, 100);
      if (!intensity.injuryChancePerDay) return;
      const form = currentCondition(p, at, this.conditionRecoveryPerDay());
      const chance = intensity.injuryChancePerDay * (form < TRAINING_INJURY_LOW_FORM ? TRAINING_INJURY_LOW_FORM_MULT : 1);
      const roll = typeof rand01 === "function" ? rand01() : Math.random();
      if (roll >= chance) return;
      const rolled = rollInjury(at, this.doctorInjuryDurationMult ? this.doctorInjuryDurationMult() : 1);
      p.injuryType = rolled.injuryType;
      p.injuryUntil = rolled.injuryUntil;
      const days = Math.max(1, Math.round((rolled.injuryUntil - at) / CONDITION_DAY_MS));
      this.recordInjury({ at, playerId: p.id, playerName: p.name, injuryType: rolled.injuryType, days, opponentName: null, training: true });
      if (this.isHuman && this.feed) {
        handleGameEvent(this.feed, { type: "injury", week: this.week, playerId: p.id, playerName: p.name, weeks: Math.max(1, Math.round(days / 7)) }, { clubName: this.name });
      }
    });
  }

  // Jour « Tactique » (retour utilisateur 2026-10-01) : gain immédiat sur
  // l'aspect travaillé, selon son niveau actuel (tacticDailyGainForLevel).
  applyTacticDay(target) {
    if (!target) return;
    const knowledge = this.tacticalKnowledge && this.tacticalKnowledge[target.category];
    if (!knowledge || !(target.value in knowledge)) return;
    const before = knowledge[target.value];
    let after;
    if (this.isHuman && (this.players || []).length) {
      // Connaissance individuelle : tout l'effectif présent travaille
      // l'aspect, chacun selon SON niveau.
      this.players.forEach(p => {
        const k = this.ensurePlayerTacticalKnowledge(p)[target.category];
        k[target.value] = clamp(Math.round((k[target.value] + tacticDailyGainForLevel(k[target.value])) * 10) / 10, 0, 100);
      });
      this.recomputeTacticalKnowledge();
      after = knowledge[target.value];
    } else {
      after = clamp(Math.round((before + tacticDailyGainForLevel(before)) * 10) / 10, 0, 100);
      knowledge[target.value] = after;
    }
    const week = this.ensureCollectiveWeek();
    const key = `${target.category}:${target.value}`;
    if (!week.tactics[key]) week.tactics[key] = { category: target.category, value: target.value, before, after };
    else week.tactics[key].after = after;
  }

  // Bilan collectif de la semaine en cours (repris par le bilan du lundi).
  ensureCollectiveWeek() {
    if (!this.collectiveWeek || typeof this.collectiveWeek !== "object") this.collectiveWeek = { days: {}, tactics: {}, physicalPoints: 0 };
    if (!this.collectiveWeek.days) this.collectiveWeek.days = {};
    if (!this.collectiveWeek.tactics) this.collectiveWeek.tactics = {};
    if (!Array.isArray(this.collectiveWeek.log)) this.collectiveWeek.log = [];
    if (typeof this.collectiveWeek.physicalPoints !== "number") this.collectiveWeek.physicalPoints = 0;
    return this.collectiveWeek;
  }

  // Plans individuels actifs (retour utilisateur 2026-10-01) : joueurs encore
  // dans l'effectif, programme connu, limités aux places de l'entraîneur.
  trainingSlotsMax() {
    return trainingSlotsForTrainer(this.trainer);
  }
  activeTrainingSlots() {
    const ids = new Set((this.players || []).map(p => String(p.id)));
    return (this.trainingSlots || [])
      .filter(s => s && ids.has(String(s.playerId)) && TRAINING_PROGRAMS[s.program])
      .slice(0, this.trainingSlotsMax());
  }
  // Parrainages encore valides (âges, poste, effectif).
  activeMentorships() {
    return (this.mentorships || [])
      .filter(m => m && !mentorshipPairError(this, m.youngId, m.veteranId))
      .slice(0, MENTORSHIP_MAX_PAIRS);
  }

  // `matchDayIndex` (optionnel, voir parisCalendarDayIndex) : jour du match
  // qui consomme le crédit — ce jour-là n'est PAS un jour de repos, il ne
  // compte donc jamais (retour utilisateur, 2026-09-27 : "les entrainements
  // collectifs eux, sont uniquement sur les jours de repos" ; avant, un
  // match de coupe le jeudi comptait le jeudi lui-même comme un jour
  // d'entraînement si le manager s'était connecté ce jour-là).
  daysTrainedForTarget(target, matchDayIndex = null) {
    if (!target || !Array.isArray(this.collectiveTrainingLog)) return 0;
    const cycleStart = this.tacticsCycleStartDayIndex;
    return this.collectiveTrainingLog.filter(e => {
      if (cycleStart != null && e.dayIndex <= cycleStart) return false;
      if (matchDayIndex != null && e.dayIndex >= matchDayIndex) return false;
      if (this.isFriendlyDay(e.dayIndex)) return false;
      return e.collectiveTraining === "tactique" && e.trainedTactics
        && e.trainedTactics.category === target.category && e.trainedTactics.value === target.value;
    }).length;
  }

  // Fait évoluer Team.tacticalKnowledge, PAR OPTION (voir le grand
  // commentaire CONNAISSANCE TACTIQUE au-dessus de
  // TACTICAL_KNOWLEDGE_GAIN_BASE plus haut) : pour chacune des 18 options
  // possibles (10 priorités offensives, 5 défenses, 3 rythmes), regarde si
  // elle vient d'être jouée CE match-là ou non, et applique la courbe de
  // gain (tacticalKnowledgeGainForStreak) ou de perte
  // (tacticalKnowledgeLossForStreak) correspondante, PROGRESSIVEMENT selon
  // la série en cours (Team.tacticalKnowledgeStreaks). Compare uniquement
  // l'identité tactique de FOND (attaque prioritaire, défense, rythme),
  // volontairement PAS les réglages fins (aide défensive, style de
  // contre-attaque, marquage individuel...). Appelée à chaque match
  // réellement simulé (voir recordMatchStatsForTeam), jamais pendant la
  // planification à l'avance (stagePlanForRound), qui ne représente encore
  // qu'une intention et non un ordre réellement donné. Anciennement
  // checkTacticsChemistry puis une première version basée sur un seul
  // instantané de référence (bascule binaire "tactique établie") ; cette
  // version-ci suit chaque option indépendamment, voir le grand commentaire
  // ci-dessus pour l'historique complet.
  updateTacticalKnowledge(now = Date.now()) {
    const playedOffense = new Set(this.offensivePriorities);

    // Entraînement collectif "tactique" (retour utilisateur, 2026-09 : "soit
    // bosser une nouvelle tactique [...] il faut effectivement choisir ce
    // qui est bossé comme tactique [...] un seul aspect et pas tous les
    // aspects") : UN SEUL aspect précis (voir Team.trainedTactics), lu
    // directement sur `this.trainedTactics`, PAS conditionné à
    // `collectiveTraining === "tactique"` À CET INSTANT PRÉCIS (retour
    // utilisateur, 2026-09 : "si le vendredi on fait entrainement récup
    // [...] on doit quand même avoir le malus divisé par deux du mercredi et
    // par deux encore une fois le jeudi", formulé à l'origine pour
    // l'atténuation de l'ancien système, vaut ici pour le bonus de gain) —
    // le focus du jour du MATCH lui-même ne compte de toute façon jamais
    // comme un jour d'entraînement (voir tacticsCycleStartDayIndex), donc
    // peu importe s'il a entre-temps changé ; seul le nombre de jours
    // RÉELLEMENT banqués dans collectiveTrainingLog (voir
    // daysTrainedForTarget) détermine le bonus ci-dessous.
    // Le jour « Tactique » crédite désormais directement la connaissance
    // (Team.applyTacticDay, retour utilisateur 2026-10-01) : plus de bonus
    // de jours banqués ici.

    // Applique le mouvement (gain ou perte) d'UNE option précise : `cat` la
    // catégorie ("offense"/"defense"/"rhythm"), `key` la valeur précise
    // (une priorité, un nom de défense, un rythme), `played` si elle vient
    // d'être jouée CE match. Le bonus d'entraînement ci-dessus ne s'applique
    // QUE sur l'option EXACTEMENT trainedTactics ET réellement jouée (une
    // préparation en avance sur une option pas encore en live n'accélère
    // rien tant que l'ordre live n'a pas changé, le crédit reste en
    // attente).
    // Club humain : connaissance individuelle (voir
    // PLAYER_TACTICAL_KNOWLEDGE_GAIN_BASE), gain au prorata des minutes
    // jouées CE match, perte des options délaissées pour tout l'effectif.
    const individual = this.isHuman && (this.players || []).length > 0;
    const roster = individual ? this.players.map(p => ({ k: this.ensurePlayerTacticalKnowledge(p), share: Math.min(1, (p.secondsPlayed || 0) / TACTICAL_FULL_GAIN_SECONDS) })) : [];
    const lose = (knowledge, key, loss) => {
      knowledge[key] = Math.max(Math.min(knowledge[key], TACTICAL_KNOWLEDGE_FLOOR), clamp(knowledge[key] - loss, TACTICAL_KNOWLEDGE_FLOOR, 100));
    };
    const updateOne = (cat, key, played) => {
      const streaks = this.tacticalKnowledgeStreaks[cat];
      const knowledge = this.tacticalKnowledge[cat];
      const prevStreak = streaks[key] || 0;
      if (played) {
        const streak = prevStreak > 0 ? prevStreak + 1 : 1;
        streaks[key] = streak;
        if (individual) {
          const gain = playerTacticalKnowledgeGainForStreak(streak);
          roster.forEach(r => { if (r.share > 0) r.k[cat][key] = clamp(Math.round((r.k[cat][key] + gain * r.share) * 10) / 10, 0, 100); });
        } else {
          const gain = tacticalKnowledgeGainForStreak(streak);
          knowledge[key] = clamp(knowledge[key] + gain, 0, 100);
        }
      } else {
        const streak = prevStreak < 0 ? prevStreak - 1 : -1;
        streaks[key] = streak;
        const loss = tacticalKnowledgeLossForStreak(-streak);
        if (individual) roster.forEach(r => lose(r.k[cat], key, loss));
        else lose(knowledge, key, loss);
      }
    };
    Object.keys(OFFENSE_PROFILES).forEach(p => updateOne("offense", p, playedOffense.has(p)));
    Object.keys(DEFENSES).forEach(d => updateOne("defense", d, d === this.defense));
    Object.keys(RHYTHMS).forEach(r => updateOne("rhythm", r, r === this.rhythm));
    if (individual) this.recomputeTacticalKnowledge();

    // Ce match consomme tout le crédit accumulé dans collectiveTrainingLog
    // (voir daysTrainedForTarget ci-dessus) : nouveau cycle à partir de
    // MAINTENANT, les prochains jours de repos recommencent à zéro (voir le
    // filtre `dayIndex > tacticsCycleStartDayIndex` dans syncCollectiveTrainingLog/
    // daysTrainedForTarget).
    this.tacticsCycleStartDayIndex = parisCalendarDayIndex(now);
  }

  // Multiplicateur de performance lié à la connaissance tactique (voir le
  // grand commentaire CONNAISSANCE TACTIQUE au-dessus de
  // TACTICAL_KNOWLEDGE_GAIN_BASE plus haut, et Player.eff()/
  // Team.resetForMatch plus bas) : SÉPARÉ de chemistryFactor() (les deux se
  // cumulent), même formule/même ordre de grandeur (0.94 à 1.06, +/-6%) —
  // moyenne des 3 options ACTUELLEMENT jouées (les 3 priorités offensives +
  // la défense + le rythme en cours, PAS les 18 options dans leur
  // ensemble), un "petit plus/petit moins" d'ensemble sur TOUTE l'équipe.
  // Tactiques enregistrées (voir TACTIC_PRESETS_MAX). `slot` 0..2 : remplace
  // la tactique de cet emplacement, ou l'ajoute à la suite.
  // Nombre de tactiques enregistrables : 6 en Premium, 3 sinon.
  // Signets (tous les joueurs, sans Premium) — voir BOOKMARKS_MAX.
  isBookmarked(playerId) {
    return (this.bookmarks || []).some(b => String(b.playerId) === String(playerId));
  }
  setBookmark(playerId, on, leagueId = null, now = Date.now()) {
    if (!Array.isArray(this.bookmarks)) this.bookmarks = [];
    const exists = this.isBookmarked(playerId);
    if (on && !exists) {
      if (this.bookmarks.length >= BOOKMARKS_MAX) return { ok: false, error: `${BOOKMARKS_MAX} joueurs en signets au maximum.` };
      this.bookmarks.push({ playerId, leagueId: leagueId || null, since: now });
      // Succès « Œil du recruteur » : joueurs distincts mis en signet.
      achAddUnique(this, "bookmarked", playerId, now);
    } else if (!on && exists) {
      this.bookmarks = this.bookmarks.filter(b => String(b.playerId) !== String(playerId));
    }
    return { ok: true, bookmarked: this.isBookmarked(playerId) };
  }
  // Marché — liste de suivi (Premium). Renvoie { ok, watching } ou { ok:false, error }.
  isWatchingPlayer(playerId) {
    return (this.marketWatchlist || []).some(w => String(w.playerId) === String(playerId));
  }
  setMarketWatch(playerId, watch, now = Date.now()) {
    if (!this.hasActivePremium(now)) return { ok: false, error: "La liste de suivi du marché est réservée au Premium." };
    if (!Array.isArray(this.marketWatchlist)) this.marketWatchlist = [];
    const exists = this.isWatchingPlayer(playerId);
    if (watch && !exists) {
      if (this.marketWatchlist.length >= MARKET_WATCHLIST_MAX) return { ok: false, error: `${MARKET_WATCHLIST_MAX} joueurs suivis au maximum.` };
      this.marketWatchlist.push({ playerId, since: now });
    } else if (!watch && exists) {
      this.marketWatchlist = this.marketWatchlist.filter(w => String(w.playerId) !== String(playerId));
    }
    return { ok: true, watching: this.isWatchingPlayer(playerId) };
  }
  // Marché — alertes (recherches enregistrées, Premium).
  saveMarketAlert(raw, now = Date.now()) {
    if (!this.hasActivePremium(now)) return { ok: false, error: "Les alertes du marché sont réservées au Premium." };
    const clean = sanitizeMarketAlert(raw);
    if (!clean) return { ok: false, error: "Choisissez au moins un filtre pour créer une alerte." };
    if (!Array.isArray(this.marketAlerts)) this.marketAlerts = [];
    if (this.marketAlerts.length >= MARKET_ALERTS_MAX) return { ok: false, error: `${MARKET_ALERTS_MAX} alertes au maximum.` };
    const alert = { id: `al_${now}_${this.marketAlerts.length}`, createdAt: now, ...clean };
    this.marketAlerts.push(alert);
    return { ok: true, alert };
  }
  deleteMarketAlert(id) {
    const before = (this.marketAlerts || []).length;
    this.marketAlerts = (this.marketAlerts || []).filter(a => a.id !== id);
    return this.marketAlerts.length !== before;
  }
  tacticPresetsMax(now = Date.now()) {
    return this.hasActivePremium(now) ? TACTIC_PRESETS_MAX : TACTIC_PRESETS_FREE_MAX;
  }
  saveTacticPreset(slot, name, snap, now = Date.now()) {
    if (!Array.isArray(this.tacticPresets)) this.tacticPresets = [];
    const clean = String(name || "").trim().slice(0, TACTIC_PRESET_NAME_MAX) || `Tactique ${slot + 1}`;
    const preset = { name: clean, savedAt: now, orders: tacticPresetOrdersFrom(snap) };
    if (slot < this.tacticPresets.length) this.tacticPresets[slot] = preset;
    else if (this.tacticPresets.length < this.tacticPresetsMax(now)) this.tacticPresets.push(preset);
    else return null;
    // Succès « À vos ordres » (Bronze) : tactique enregistrée.
    achAdd(this, "presetsSaved", 1, now);
    return preset;
  }
  renameTacticPreset(slot, name) {
    const p = (this.tacticPresets || [])[slot];
    const clean = String(name || "").trim().slice(0, TACTIC_PRESET_NAME_MAX);
    if (!p || !clean) return false;
    p.name = clean;
    return true;
  }
  deleteTacticPreset(slot) {
    if (!Array.isArray(this.tacticPresets) || !this.tacticPresets[slot]) return false;
    this.tacticPresets.splice(slot, 1);
    return true;
  }
  // Ordres prêts à appliquer (patch pour les ordres en direct ou
  // stagePlanForRound) : copie profonde, joueurs partis retirés.
  tacticPresetPatch(slot) {
    const p = (this.tacticPresets || [])[slot];
    if (!p) return null;
    const patch = tacticPresetOrdersFrom(p.orders);
    const ids = new Set((this.players || []).map(pl => pl.id));
    const keep = id => ids.has(Number(id));
    const l = patch.lineup;
    Object.keys(l.starters).forEach(pos => { if (l.starters[pos] != null && !keep(l.starters[pos])) l.starters[pos] = null; });
    Object.keys(l.backupPositions).forEach(id => { if (!keep(id)) delete l.backupPositions[id]; });
    if (l.minutes) Object.values(l.minutes).forEach(m => Object.keys(m).forEach(id => { if (!keep(id)) delete m[id]; }));
    if (l.convoked) l.convoked = l.convoked.filter(keep);
    return patch;
  }
  // Maîtrise moyenne (0-100) des options d'une tactique enregistrée, même
  // moyenne que tacticalKnowledgeFactor ci-dessous.
  tacticPresetKnowledge(slot) {
    const p = (this.tacticPresets || [])[slot];
    if (!p) return null;
    return Math.round(tacticalKnowledgeAverage(this.tacticalKnowledge, p.orders.offensivePriorities, p.orders.defense, p.orders.rhythm));
  }

  // Maîtrise individuelle d'un joueur de l'effectif (voir
  // PLAYER_TACTICAL_KNOWLEDGE_GAIN_BASE) : créée au besoin depuis la jauge
  // d'équipe (joueur d'avant la connaissance individuelle : rien ne bouge
  // au déploiement). Une recrue est remise à 40 par
  // resetPlayerTacticalKnowledge au moment de son arrivée.
  ensurePlayerTacticalKnowledge(p) {
    if (!p.tacticalKnowledge || typeof p.tacticalKnowledge !== "object" || !p.tacticalKnowledge.offense) {
      p.tacticalKnowledge = copyTacticalKnowledge(this.tacticalKnowledge, 50);
    }
    return p.tacticalKnowledge;
  }
  // Lecture seule (pas de création) : sa maîtrise, sinon la jauge d'équipe.
  playerTacticalKnowledgeOf(p) {
    return (this.isHuman && p && p.tacticalKnowledge && p.tacticalKnowledge.offense) ? p.tacticalKnowledge : this.tacticalKnowledge;
  }
  // Maîtrise (0-100) d'un joueur pour la tactique ACTUELLE du club.
  playerSystemMastery(p) {
    return tacticalKnowledgeAverage(this.playerTacticalKnowledgeOf(p), this.offensivePriorities, this.defense, this.rhythm);
  }
  // Minutes prévues au prochain match par joueur : minutes réglées du poste,
  // sinon la répartition proposée (defaultSlotMinutes) ; 0 hors convocation.
  plannedMinutesByPlayer() {
    const out = {};
    if (!this.lineup || !this.lineup.starters) return out;
    POSITIONS.forEach(pos => {
      const mins = (this.lineup.minutes && this.lineup.minutes[pos]) || this.defaultSlotMinutes(pos);
      Object.entries(mins).forEach(([id, m]) => { out[id] = (out[id] || 0) + (Number(m) || 0); });
    });
    if (Array.isArray(this.lineup.convoked)) {
      const convoked = new Set(this.lineup.convoked.map(String));
      Object.keys(out).forEach(id => { if (!convoked.has(String(id))) out[id] = 0; });
    }
    return out;
  }
  // Jauge d'équipe (Team.tacticalKnowledge) d'un club humain : moyenne des
  // maîtrises individuelles pondérée par les minutes prévues au prochain
  // match (effectif entier à parts égales si aucune minute n'est prévue).
  recomputeTacticalKnowledge() {
    if (!this.isHuman || !(this.players || []).length) return this.tacticalKnowledge;
    const planned = this.plannedMinutesByPlayer();
    let weights = this.players.map(p => planned[String(p.id)] || 0);
    if (!weights.some(w => w > 0)) weights = this.players.map(() => 1);
    const total = weights.reduce((a, b) => a + b, 0);
    const ks = this.players.map(p => this.ensurePlayerTacticalKnowledge(p));
    ["offense", "defense", "rhythm"].forEach(cat => {
      Object.keys(this.tacticalKnowledge[cat]).forEach(key => {
        let sum = 0;
        ks.forEach((k, i) => { sum += (k[cat][key] ?? 50) * weights[i]; });
        this.tacticalKnowledge[cat][key] = Math.round((sum / total) * 10) / 10;
      });
    });
    return this.tacticalKnowledge;
  }

  // Multiplicateur individuel en match : sa propre maîtrise du système.
  playerTacticalKnowledgeFactor(p) {
    return 0.92 + (this.playerSystemMastery(p) / 100) * 0.16;
  }

  tacticalKnowledgeFactor() {
    const offenseValues = this.offensivePriorities.map(p => this.tacticalKnowledge.offense[p] ?? 50);
    const offenseAvg = offenseValues.length
      ? offenseValues.reduce((sum, v) => sum + v, 0) / offenseValues.length
      : 50;
    const defenseVal = this.tacticalKnowledge.defense[this.defense] ?? 50;
    const rhythmVal = this.tacticalKnowledge.rhythm[this.rhythm] ?? 50;
    const avg = (offenseAvg + defenseVal + rhythmVal) / 3;
    // ±8 % aux extrêmes (retour utilisateur 2026-10-01, avant ±6 %).
    return 0.92 + (avg / 100) * 0.16;
  }

  // Taux de récupération de forme physique quotidien de ce club (retour
  // utilisateur, 2026-09, voir Team.collectiveTraining/CONDITION_RECOVERY_
  // PER_DAY_TRAINED plus haut) : CONDITION_RECOVERY_PER_DAY_TRAINED (15/jour,
  // la valeur historique) si le focus collectif de la semaine est
  // "recuperation", sinon CONDITION_RECOVERY_PER_DAY (10/jour, le nouveau
  // défaut). Lu par Team.resetForMatch/recordMatchStatsForTeam (voir plus
  // bas) et par l'affichage de la forme physique côté client
  // (currentCondition).
  conditionRecoveryPerDay() {
    // Le focus « Récupération » est crédité jour de repos par jour de repos
    // (voir Team.applyRestDayRecovery), l'intensité des plans individuels
    // aussi (Team.applyTrainingIntensityDay).
    const base = CONDITION_RECOVERY_PER_DAY;
    // Kiné (voir MEDICAL_STAFF_ROLES) : +1 à +5 par jour selon son niveau.
    return base + (this.physioRecoveryBonus ? this.physioRecoveryBonus() : 0);
  }

  // Ignore une interview en attente ("pas de commentaire") : aucun effet sur
  // l'humeur, retire simplement l'entrée de la file. Renvoie true si une
  // entrée correspondante a bien été trouvée et retirée (false si déjà
  // traitée, ou déjà expirée et retirée par pruneExpiredInterviews ci-dessus).
  skipInterview(id, now = Date.now()) {
    this.pruneExpiredInterviews(now);
    this.pendingInterviews = this.pendingInterviews || [];
    const before = this.pendingInterviews.length;
    this.pendingInterviews = this.pendingInterviews.filter(i => i.id !== id);
    return this.pendingInterviews.length !== before;
  }

  // Choix de maillot d'un club (retour utilisateur : "une équipe gratuite
  // doit pouvoir choisir uniquement entre 2 formes de maillot et 5
  // couleurs [...] les maillots doivent pouvoir être modifiés dans le
  // tableau de bord") : validé contre JERSEY_SHAPES/JERSEY_COLORS, jamais
  // stocké sans validation. Même palette pour un club payant (voir le
  // commentaire sur JERSEY_COLORS plus haut).
  setJersey(shape, color) {
    if (!JERSEY_SHAPES.includes(shape)) return { ok: false, error: "Forme de maillot inconnue." };
    const c = normalizeJerseyColor(color);
    if (!c) return { ok: false, error: "Couleur de maillot inconnue." };
    // Couleur libre (HEX) réservée au Premium (retour utilisateur
    // 2026-10-04) : un club gratuit garde les 8 couleurs de JERSEY_COLORS
    // (sa couleur actuelle reste acceptée telle quelle).
    if (!JERSEY_COLORS[c] && c !== this.jerseyColor && !(typeof this.hasActivePremium === "function" ? this.hasActivePremium() : this.isPaying)) return { ok: false, error: "Couleur libre réservée au Premium." };
    this.jerseyShape = shape;
    this.jerseyColor = c;
    return { ok: true };
  }

  // Motif de maillot (retour utilisateur : "Pour le mode payant ajoute des
  // maillots avec des dessins particuliers (rayure, degrade...)") : "uni"
  // (retour au maillot standard) toujours autorisé, un motif personnalisé
  // (JERSEY_PATTERNS[1+]) réservé à un club `isPaying`, même garde-fou que
  // setCustomLogo ci-dessous. Jamais effacé en repassant gratuit (voir
  // setPaying) : seul le RENDU l'ignore tant que le club n'est pas payant
  // (voir effectiveJerseyPattern côté moteurbasket3.html).
  setJerseyPattern(pattern) {
    if (!JERSEY_PATTERNS.includes(pattern)) return { ok: false, error: "Motif de maillot inconnu." };
    if (pattern !== JERSEY_PATTERNS[0] && !this.hasActivePremium()) {
      return { ok: false, error: "Passez Premium pour un motif de maillot personnalisé." };
    }
    this.jerseyPattern = pattern;
    return { ok: true };
  }

  // Hall of Fame (retour utilisateur, 2026-09-26 : "légende du club, mets
  // plutôt un hall of famer, c'est plus sympa et on mettra les joueurs
  // qu'on veut dedans", "quand un joueur voit son maillot retiré, il faut
  // l'afficher sur le visuel de la salle") : le manager y fait entrer qui
  // il veut parmi les joueurs ayant disputé un match officiel pour le club
  // (entry = ligne de liveAllTimePlayers, vérifiée côté serveur) ; numéro
  // de maillot retiré facultatif (0-99, unique), null = pas retiré. Entrée
  // et maillot retiré sont définitifs.
  inductHallOfFame(entry, now = Date.now()) {
    if (!entry || !Number.isFinite(Number(entry.id))) return { ok: false, error: "Joueur inconnu." };
    this.hallOfFame = Array.isArray(this.hallOfFame) ? this.hallOfFame : [];
    const id = Number(entry.id);
    if (this.hallOfFame.some(h => h.id === id)) return { ok: false, error: "Ce joueur est déjà au Hall of Fame." };
    if (this.hallOfFame.length >= HALL_OF_FAME_MAX) return { ok: false, error: `Le Hall of Fame est plein (${HALL_OF_FAME_MAX} joueurs).` };
    this.hallOfFame.push({
      id, name: String(entry.name || "?"), position: entry.position || "",
      games: entry.games || 0, pts: entry.pts || 0, reb: entry.reb || 0, ast: entry.ast || 0,
      inductedAt: now, retiredNumber: null,
    });
    return { ok: true };
  }

  setRetiredJersey(playerId, number) {
    const id = Number(playerId);
    const entry = (this.hallOfFame || []).find(h => h.id === id);
    if (!entry) return { ok: false, error: "Seul un joueur du Hall of Fame peut voir son maillot retiré." };
    // Définitif (retour utilisateur, 2026-09-26 : "une fois au hall of fame,
    // on ne peut plus enlever") : ni sortie du Hall of Fame, ni retour sur
    // un maillot retiré.
    if (Number.isInteger(entry.retiredNumber)) return { ok: false, error: "Ce maillot est déjà retiré." };
    const n = Number(number);
    if (!Number.isInteger(n) || n < 0 || n > 99) return { ok: false, error: "Numéro de maillot entre 0 et 99." };
    if (this.hallOfFame.some(h => h.id !== id && h.retiredNumber === n)) return { ok: false, error: `Le numéro ${n} est déjà retiré.` };
    entry.retiredNumber = n;
    return { ok: true };
  }

  // Combinaison de 2 couleurs pour les motifs "rayures"/"degrade" (retour
  // utilisateur : "ajoute un peu plus de couleur pour le mode payant, et
  // mets le choix de 2 couleurs [...] mets plus de choix") : réservée à un
  // club `isPaying`, sans exception (contrairement à setJerseyPattern
  // ci-dessus, il n'y a pas d'équivalent "uni" neutre ici : une combinaison
  // de 2 couleurs n'a de sens que pour un motif payant). Jamais effacée en
  // repassant gratuit (voir setPaying) : seul le RENDU l'ignore tant que le
  // club n'est pas payant (voir effectiveJerseyTwoTone côté
  // moteurbasket3.html), même principe que jerseyPattern.
  setJerseyTwoTone(key) {
    key = normalizeJerseyPair(key);
    if (!key) return { ok: false, error: "Combinaison de couleurs inconnue." };
    if (!this.hasActivePremium()) {
      return { ok: false, error: "Passez Premium pour choisir une combinaison de couleurs." };
    }
    this.jerseyTwoTone = key;
    return { ok: true };
  }

  // Couleur du maillot EXTÉRIEUR (voir Team.awayJerseyColor plus haut) :
  // même palette et même validation que setJersey ci-dessus, mais la forme
  // (jerseyShape) reste PARTAGÉE avec le maillot domicile, un club n'ayant
  // qu'une seule coupe de maillot. Couleur libre pour tous les clubs, comme
  // jerseyColor (seuls le motif et la combinaison 2 couleurs sont réservés
  // au mode payant, voir setAwayJerseyPattern/setAwayJerseyTwoTone
  // ci-dessous).
  setAwayJerseyColor(color) {
    const c = normalizeJerseyColor(color);
    if (!c) return { ok: false, error: "Couleur de maillot inconnue." };
    // Couleur libre (HEX) réservée au Premium (retour utilisateur
    // 2026-10-04) : un club gratuit garde les 8 couleurs de JERSEY_COLORS
    // (sa couleur actuelle reste acceptée telle quelle).
    if (!JERSEY_COLORS[c] && c !== this.awayJerseyColor && !(typeof this.hasActivePremium === "function" ? this.hasActivePremium() : this.isPaying)) return { ok: false, error: "Couleur libre réservée au Premium." };
    this.awayJerseyColor = c;
    return { ok: true };
  }

  // Motif du maillot EXTÉRIEUR (voir Team.awayJerseyPattern plus haut) :
  // même garde-fou "isPaying" que setJerseyPattern ci-dessus, "uni" toujours
  // autorisé. Jamais effacé en repassant gratuit, seul le rendu l'ignore
  // tant que le club n'est pas payant (voir effectiveAwayJerseyPattern côté
  // moteurbasket3.html).
  setAwayJerseyPattern(pattern) {
    if (!JERSEY_PATTERNS.includes(pattern)) return { ok: false, error: "Motif de maillot inconnu." };
    if (pattern !== JERSEY_PATTERNS[0] && !this.hasActivePremium()) {
      return { ok: false, error: "Passez Premium pour un motif de maillot personnalisé." };
    }
    this.awayJerseyPattern = pattern;
    return { ok: true };
  }

  // Combinaison de 2 couleurs du maillot EXTÉRIEUR (voir
  // Team.awayJerseyTwoTone plus haut) : même garde-fou "isPaying" strict
  // que setJerseyTwoTone ci-dessus, pas d'équivalent "uni" neutre. Jamais
  // effacée en repassant gratuit, seul le rendu l'ignore (voir
  // effectiveAwayJerseyTwoTone côté moteurbasket3.html).
  setAwayJerseyTwoTone(key) {
    key = normalizeJerseyPair(key);
    if (!key) return { ok: false, error: "Combinaison de couleurs inconnue." };
    if (!this.hasActivePremium()) {
      return { ok: false, error: "Passez Premium pour choisir une combinaison de couleurs." };
    }
    this.awayJerseyTwoTone = key;
    return { ok: true };
  }

  // Logo personnalisé (retour utilisateur : "pour les équipes qui paient,
  // elles doivent pouvoir charger leur propre image") : réservé aux clubs
  // `isPaying` (voir setPaying ci-dessous), `dataUrl` = null retire le logo
  // personnalisé (retour au logo type). Validation minimale du format
  // (image PNG/JPEG/WebP encodée en data URL) et de la taille (voir
  // MAX_TEAM_LOGO_DATA_URL_LENGTH) : le vrai redimensionnement/compression a
  // déjà eu lieu côté client avant l'envoi (voir resizeImageFileToDataUrl
  // dans moteurbasket3.html), ceci n'est qu'un garde-fou serveur.
  setCustomLogo(dataUrl) {
    if (!this.hasActivePremium()) return { ok: false, error: "Passez Premium pour charger un logo personnalisé." };
    if (dataUrl === null) {
      this.customLogoDataUrl = null;
      return { ok: true };
    }
    if (typeof dataUrl !== "string" || !/^data:image\/(png|jpe?g|webp);base64,/.test(dataUrl)) {
      return { ok: false, error: "Image invalide (formats acceptés : PNG, JPEG, WebP)." };
    }
    if (dataUrl.length > MAX_TEAM_LOGO_DATA_URL_LENGTH) {
      return { ok: false, error: "Image trop lourde." };
    }
    this.customLogoDataUrl = dataUrl;
    return { ok: true };
  }

  // Statut "club payant" (voir le grand commentaire sur JERSEY_COLORS plus
  // haut) : simple interrupteur manuel pour l'instant, aucun vrai système de
  // paiement derrière. Ne PAS effacer customLogoDataUrl en repassant à
  // `false` : un club qui redevient payant plus tard retrouve directement
  // son logo précédent, jamais besoin de le recharger (voir teamLogoHtml
  // côté moteurbasket3.html, qui ignore déjà customLogoDataUrl tant
  // qu'isPaying est faux, sans avoir besoin que ce champ soit vidé ici).
  setPaying(isPaying) {
    this.isPaying = !!isPaying;
    this.scoutingPremium = false; // ancien interrupteur « Passer Pro », fusionné (voir teamFromSave)
    return { ok: true };
  }

  // Vrai si ce club profite du statut Premium MAINTENANT, que ce soit via
  // l'interrupteur manuel permanent (`isPaying`) ou un Premium temporaire en
  // cours (`premiumUntil` pas encore atteint — voir son commentaire au
  // constructeur). Seul point de lecture pour "ce club est-il Premium ?" côté
  // Hoop Shows (server/shows.js) : jamais `isPaying`/`premiumUntil` lus
  // séparément ailleurs, pour ne pas dupliquer cette règle.
  hasBetaFeature(name) {
    return Array.isArray(this.betaFeatures) && this.betaFeatures.includes(name);
  }
  setBetaFeature(name, enabled) {
    const list = Array.isArray(this.betaFeatures) ? this.betaFeatures.filter(f => f !== name) : [];
    if (enabled) list.push(name);
    this.betaFeatures = list;
    return list;
  }
  hasActivePremium(now = Date.now()) {
    return !!this.isPaying || (typeof this.premiumUntil === "number" && now < this.premiumUntil);
  }

  // Accorde un Premium temporaire de `durationMs` à partir de `now` (lot de
  // fin de saison des pronostics, voir server/shows.js:grantSeasonPrize) —
  // repousse l'échéance si un Premium temporaire était déjà en cours (jamais
  // raccourci), n'affecte jamais `isPaying`.
  grantTemporaryPremium(durationMs, now = Date.now()) {
    const until = now + durationMs;
    this.premiumUntil = Math.max(this.premiumUntil || 0, until);
    return { ok: true, premiumUntil: this.premiumUntil };
  }

  // Marque le tutoriel d'accueil comme terminé (retour utilisateur,
  // 2026-09 : "on est d'accord qu'on ne peut le faire qu'une fois ? [...]
  // le bouton dans le guide doit s'enlever") : à sens unique (jamais remis
  // à `false`), déclenché aussi bien en allant jusqu'au bout du tutoriel
  // qu'en le passant (voir tourEndTour côté moteurbasket3.html). Existe
  // désormais aussi côté serveur (server/actions.js) pour la ligue
  // partagée, où saveMyTeam() (seul point d'écriture jusqu'ici, solo
  // uniquement) ne peut pas persister ce champ : sans ce point d'entrée
  // dédié, le bouton "Lancer le tutoriel" réapparaissait à chaque
  // rechargement de page pour un manager de ligue partagée, malgré le
  // tutoriel déjà terminé.
  markOnboardingTourCompleted() {
    this.onboardingTourCompleted = true;
    return { ok: true };
  }

  // Réinitialise UNIQUEMENT le drapeau ci-dessus, jamais accessible au
  // joueur lui-même (aucune route publique, voir server/index.js :
  // /api/admin/reset-onboarding-tour, même authentification X-Admin-Token
  // que /api/admin/credit-team) : bouche-trou déjà bricolé une première
  // fois à la main pour Ariane (voir le commentaire de /api/admin/
  // credit-team) faute d'un vrai outil - onboardingTourCompleted étant à
  // sens unique par design (voir markOnboardingTourCompleted ci-dessus),
  // rien côté joueur ne permet de relancer le tutoriel une fois terminé ou
  // passé, ce qui bloque définitivement quiconque s'y retrouve coincé par
  // erreur (retour utilisateur Discord, 2026-09, "Skyzer10" : le bouton a
  // disparu après un aller-retour dans le tutoriel). Ne touche JAMAIS
  // Team.tutorialRewardsClaimed : les primes déjà réellement créditées
  // restent acquises (protection anti-double-dépense inchangée, voir
  // claimTutorialReward ci-dessous) - seul le PARCOURS peut être refait, pas
  // l'argent regagné.
  resetOnboardingTour() {
    this.onboardingTourCompleted = false;
    return { ok: true };
  }

  // Crédite la prime d'un thème du tutoriel d'accueil terminé (retour
  // utilisateur, 2026-09 : "Mets les vrais primes sur le tutoriel") : voir
  // TOUR_REWARD_BY_TOPIC plus haut pour le montant par thème et
  // Team.tutorialRewardsClaimed pour la protection anti-doublon. Idempotent
  // à dessein (`alreadyClaimed: true, amount: 0` plutôt qu'une erreur) : le
  // tutoriel côté client appelle ce point d'entrée à chaque fois qu'un
  // thème à prime est terminé, y compris si le joueur relance le tutoriel
  // après l'avoir déjà fini une première fois (ex. via les outils de
  // développement) : jamais une double dépense pour le club.
  claimTutorialReward(topic) {
    const amount = TOUR_REWARD_BY_TOPIC[topic];
    if (!amount) return { ok: false, error: "Thème de tutoriel inconnu." };
    this.tutorialRewardsClaimed = this.tutorialRewardsClaimed || [];
    if (this.tutorialRewardsClaimed.includes(topic)) {
      return { ok: true, alreadyClaimed: true, amount: 0, budget: this.budget };
    }
    this.tutorialRewardsClaimed.push(topic);
    this.recordTransaction(`Tutoriel d'accueil : ${topic}`, amount);
    return { ok: true, alreadyClaimed: false, amount, budget: this.budget };
  }

  // Vend un joueur LISTÉ (voir Player.forSale/salePrice) : liquidation
  // D'URGENCE à 1 $, réservée à la mise en vente forcée en cas de déficit
  // prolongé (voir trainWeek) — un mécanisme séparé et bien plus rapide que
  // le vrai marché des transferts aux enchères (voir League.listPlayerForSale
  // / placeBid / refreshMarket), pour un club qui n'a plus le temps d'attendre
  // 3 jours d'enchères. Encaisse le prix, retire le joueur de l'effectif et
  // réassigne la feuille de match. AUCUN plancher d'effectif (retour
  // utilisateur explicite : "on peut vendre tout son effectif si on le
  // souhaite") — un club peut se vendre entièrement, y compris jusqu'à zéro
  // joueur ; voir MatchEngine/League.simulateOrForfeit pour ce qui se passe
  // alors au prochain match (forfait 20-0, pas un crash ni un blocage).
  // Renvoie true si la vente a eu lieu.
  sellPlayer(playerId) {
    const idx = this.players.findIndex(p => p.id === playerId);
    if (idx === -1 || !this.players[idx].forSale) return false;
    // Alchimie d'équipe (voir chemistryRosterImportance/rosterRankOf plus
    // haut, levier 2 des 3) : rang AVANT le splice() ci-dessous, aucun
    // acheteur ici (liquidation d'urgence, pas un vrai transfert), donc
    // malus uniquement pour ce club.
    const departureImportance = chemistryRosterImportance(rosterRankOf(this.players, playerId));
    const [p] = this.players.splice(idx, 1);
    archiveDepartedMatchLog(this, p);
    this.applyChemistryDelta(-CHEMISTRY_ROSTER_CHANGE_BASE * departureImportance);
    this.recordTransaction(`Vente de ${p.name}`, p.salePrice || 0);
    recordTeamTransfer(this, { id: `Q${p.id}:${Date.now()}`, at: Date.now(), kind: "liquidation", player: p, from: { name: this.name, leagueId: null, idx: null }, to: null, fee: p.salePrice || 0, human: !!this.isHuman });
    // Retour utilisateur (2026-09) : "en cas d'indisponibilité pour vente
    // d'un joueur, qui avait été mis dans la composition, il doit être
    // enlevé de la composition" — PAS une reconstruction complète façon
    // autoAssignLineup() (qui reconsidère TOUS les postes et pourrait
    // déloger d'autres choix déjà faits manuellement). Voir
    // handleStarterDeparture : promeut automatiquement le remplaçant déjà
    // désigné pour CE poste précis s'il y en a un ("si [...] au moins un
    // remplaçant [...] il ne faut pas mettre un forfait dans ce type de
    // cas" — retour utilisateur), sinon laisse le trou, détecté par
    // missingStarterPositions()/hasValidLineup() — et c'est précisément ce
    // qui doit déclencher un forfait si la feuille de match n'est pas
    // corrigée avant le coup d'envoi (voir POSITIONS_MISSING côté
    // server/liveMatch.js). Cette méthode n'est appelée que pour le club DU
    // JOUEUR (seul à avoir une interface de gestion pour "refaire la
    // compo") — jamais pour un club CPU.
    this.handleStarterDeparture(playerId);
    return true;
  }

  // Capacité totale = somme des places de chaque catégorie (voir
  // Team.seats / categoryCapacity).
  arenaCapacity() {
    return SEAT_CATEGORIES.reduce((s, cat) => s + this.categoryCapacity(cat.key), 0);
  }

  // Places par type, figées à la première construction libre. Avant ça (ou
  // pour une sauvegarde d'avant ce changement), on reprend la répartition
  // historique du palier de la salle (SEAT_CATEGORIES.shareOfCapacity).
  currentSeats() {
    if (this.seats) return { ...this.seats };
    return seatsForCapacity(arenaInfo(this.arenaLevel).capacity);
  }

  // Ajoute des places (retour utilisateur 2026-09-27, voir
  // SEAT_CATEGORY_MAX_SEATS) : `add` = { gradins, tribune, courtside, loge } (entiers
  // >= 0). Refuse tout ou rien : { ok: false, reason: "empty" | "cap" |
  // "insufficient-budget", category? } ; sinon { ok: true, cost, added }.
  // Budget dépensable (retour utilisateur 2026-10-03 : « j'ai enchéri mais
  // l'argent n'est pas bloqué, j'ai pu agrandir ma salle et je suis en
  // négatif ») : budget moins les enchères où le club est en tête
  // (reservedForBids, posé par League.syncReservedBids, jamais sauvegardé).
  spendableBudget() {
    return (this.budget || 0) - (this.reservedForBids || 0);
  }

  buildSeats(add) {
    const cur = this.currentSeats();
    const clean = {};
    let added = 0;
    for (const c of SEAT_CATEGORIES) {
      const n = Math.max(0, Math.floor(Number(add && add[c.key]) || 0));
      // Plafond vérifié seulement pour un type de gradin qu'on agrandit :
      // une salle d'avant le choix des gradins peut dépasser un plafond
      // (2 550 loges VIP pour 2 500) sans bloquer les autres types.
      if (n > 0 && cur[c.key] + n > SEAT_CATEGORY_MAX_SEATS[c.key]) return { ok: false, reason: "cap", category: c.key };
      clean[c.key] = n;
      added += n;
    }
    if (!added) return { ok: false, reason: "empty" };
    const cost = seatBuildCost(clean);
    if (this.spendableBudget() < cost) return { ok: false, reason: "insufficient-budget", cost };
    this.recordTransaction(`Agrandissement de la salle (+${added.toLocaleString("fr-FR")} places)`, -cost);
    SEAT_CATEGORIES.forEach(c => { cur[c.key] += clean[c.key]; });
    this.seats = cur;
    this.arenaLevel = arenaLevelForCapacity(this.arenaCapacity());
    return { ok: true, cost, added };
  }

  nextArenaLevel() {
    return ARENA_LEVELS.find(a => a.level === this.arenaLevel + 1) || null;
  }

  // Agrandit la salle d'un palier si le budget le permet. Renvoie true si
  // l'agrandissement a eu lieu.
  upgradeArena() {
    const next = this.nextArenaLevel();
    if (!next || this.spendableBudget() < next.upgradeCost) return false;
    this.recordTransaction(`Agrandissement de la salle (${next.name})`, -next.upgradeCost);
    this.arenaLevel = next.level;
    return true;
  }

  nextTrainingCenterLevel() {
    return TRAINING_CENTER_LEVELS.find(t => t.level === this.trainingCenterLevel + 1) || null;
  }

  // Agrandit le Centre de formation d'un palier si le budget le permet —
  // MÊME contrat que upgradeArena ci-dessus (un palier à la fois, vérifié
  // par le budget, coût unique prélevé immédiatement). Renvoie true si
  // l'agrandissement a eu lieu.
  upgradeTrainingCenter() {
    const next = this.nextTrainingCenterLevel();
    if (!next || this.spendableBudget() < next.upgradeCost) return false;
    this.recordTransaction(`Centre de formation : ${next.name}`, -next.upgradeCost);
    this.trainingCenterLevel = next.level;
    return true;
  }

  // Multiplicateur de progression automatique des jeunes (voir
  // growYouthPlayers) — palier ACTUEL du Centre de formation.
  trainingCenterGrowthMultiplier() {
    return trainingCenterInfo(this.trainingCenterLevel).growthMultiplier;
  }

  // Capacité de la salle réservée à une catégorie de place donnée (part
  // fixe de la capacité totale — voir SEAT_CATEGORIES.shareOfCapacity).
  categoryCapacity(categoryKey) {
    const key = seatCategoryInfo(categoryKey).key;
    if (this.seats && typeof this.seats[key] === "number") return this.seats[key];
    return seatsForCapacity(arenaInfo(this.arenaLevel).capacity)[key];
  }

  setTicketPrice(categoryKey, price) {
    const cat = seatCategoryInfo(categoryKey);
    if (!this.ticketPrices) this.ticketPrices = {};
    this.ticketPrices[cat.key] = clamp(Math.round(price), cat.minPrice, cat.maxPrice);
  }

  // Taux de remplissage PROJETÉ à domicile POUR UNE CATÉGORIE, au prix du
  // billet actuel de cette catégorie — l'humeur des supporters relève la
  // base de remplissage (attendanceBaseForMorale) ET assouplit le plafond de
  // confort tarifaire (moraleForgiveness : des supporters contents tolèrent
  // un prix plus élevé avant de déserter cette catégorie).
  projectedAttendanceRateFor(categoryKey) {
    return this.projectedAttendanceRateAtPrice(categoryKey, (this.ticketPrices || {})[categoryKey]);
  }

  // Même calcul que projectedAttendanceRateFor, mais pour un prix
  // HYPOTHÉTIQUE, sans toucher à this.ticketPrices — sert à l'aperçu en
  // direct du curseur de prix de l'onglet Salle (refonte 2026-09-25 : recette
  // et affluence mises à jour pendant qu'on fait glisser le curseur, avant
  // même de valider le nouveau prix).
  projectedAttendanceRateAtPrice(categoryKey, price) {
    const forgiveness = moraleForgiveness(this.fanMorale);
    const comfort = ticketPriceComfortFactor(price / forgiveness, categoryKey);
    return clamp(attendanceBaseForMorale(this.fanMorale) * prestigeAttendanceMult(this.prestige) * comfort, 0.08, 0.98);
  }

  // Taux de remplissage PROJETÉ global (moyenne pondérée par la part de
  // capacité de chaque catégorie) — sert d'aperçu synthétique (tableau de
  // bord du club) avant le prochain match.
  projectedAttendanceRate() {
    return SEAT_CATEGORIES.reduce((sum, cat) => sum + this.projectedAttendanceRateFor(cat.key) * cat.shareOfCapacity, 0);
  }

  // Calcule (et enregistre) la recette de billetterie d'un match à domicile,
  // catégorie de place par catégorie de place : seule la fréquentation
  // réelle du soir (légèrement aléatoire autour de la projection) compte
  // pour la recette encaissée. Renvoie le détail par catégorie pour l'UI.
  simulateHomeAttendance(opponentName, derby = false) {
    let totalAttendance = 0, totalRevenue = 0;
    // Derby (voir League.isDerbyMatch) : la salle se remplit davantage.
    const derbyBoost = derby ? DERBY_ATTENDANCE_BOOST : 1;
    const breakdown = SEAT_CATEGORIES.map(cat => {
      const rate = clamp(this.projectedAttendanceRateFor(cat.key) * rand(0.85, 1.05) * derbyBoost, 0.05, 1);
      const capacity = this.categoryCapacity(cat.key);
      const attendance = Math.round(capacity * rate);
      const revenue = attendance * (this.ticketPrices || {})[cat.key];
      totalAttendance += attendance;
      totalRevenue += revenue;
      return { key: cat.key, name: cat.name, rate, capacity, attendance, revenue };
    });
    this.recordTransaction(`Billetterie${derby ? " (derby)" : ""} vs ${opponentName} (${totalAttendance} spect.)`, totalRevenue);
    // Historique d'affluence (voir attendanceHistory ci-dessus) : même
    // rythme que recordTransaction/recordMoraleEvent (unshift + plafond),
    // pour afficher "jusqu'à 10 matchs" sur l'onglet Salle sans redemander
    // au moteur de reconstituer cet historique à partir des transactions
    // (qui mélangent billetterie et tout le reste, et ne gardent que 40
    // entrées au total, pas 40 matchs à domicile).
    this.attendanceHistory = this.attendanceHistory || [];
    const totalCapacity = SEAT_CATEGORIES.reduce((s, cat) => s + this.categoryCapacity(cat.key), 0);
    // Détail catégorie de place par catégorie de place (retour utilisateur,
    // 2026-09, sur l'historique lui-même une fois affiché : "sur l'affluence,
    // c'est bien, mais je mettrai le détail catégorie de place par catégorie
    // place") : réutilise le `breakdown` déjà calculé ci-dessus plutôt que de
    // le recalculer, allégé aux seuls champs affichés (name/attendance/
    // capacity), `rate` et `revenue` par catégorie étant redondants avec
    // attendance/capacity et le total déjà stocké juste au-dessus.
    const categoryBreakdown = breakdown.map(b => ({ key: b.key, name: b.name, attendance: b.attendance, capacity: b.capacity }));
    this.attendanceHistory.unshift({ week: this.week, opponentName, attendance: totalAttendance, revenue: Math.round(totalRevenue), capacity: totalCapacity, breakdown: categoryBreakdown });
    if (this.attendanceHistory.length > 10) this.attendanceHistory.length = 10;
    return { attendance: totalAttendance, revenue: totalRevenue, breakdown };
  }

  nextFanShopLevel() {
    return FAN_SHOP_LEVELS.find(f => f.level === this.fanShopLevel + 1) || null;
  }

  // Achète (ou agrandit) la boutique des supporters : coût UNIQUE prélevé
  // immédiatement, puis revenu hebdomadaire fixe payé dans trainWeek() tant
  // que le club la possède.
  upgradeFanShop() {
    const next = this.nextFanShopLevel();
    if (!next || this.spendableBudget() < next.cost) return false;
    this.recordTransaction(`Boutique des supporters : ${next.name}`, -next.cost);
    this.fanShopLevel = next.level;
    return true;
  }

  nextFacilityLevel(key) {
    const cfg = CLUB_FACILITIES[key];
    if (!cfg) return null;
    const cur = (this.facilityLevels && this.facilityLevels[key]) || 0;
    return cfg.levels.find(l => l.level === cur + 1) || null;
  }

  // Achète (ou améliore) une infrastructure d'UN palier — même contrat que
  // upgradeArena/upgradeFanShop/upgradeTrainingCenter ci-dessus (un palier à
  // la fois, vérifié par le budget, coût unique prélevé immédiatement).
  upgradeFacility(key) {
    const cfg = CLUB_FACILITIES[key];
    if (!cfg) return false;
    const next = this.nextFacilityLevel(key);
    if (!next || this.spendableBudget() < next.cost) return false;
    this.recordTransaction(`${cfg.name} : ${next.name}`, -next.cost);
    if (!this.facilityLevels) this.facilityLevels = { tvStation: 0, gym: 0, wellness: 0 };
    this.facilityLevels[key] = next.level;
    return true;
  }

  // Multiplicateur de risque de blessure en match (voir MatchEngine.
  // applyFatigue) — palier ACTUEL de la salle de musculation, 1 = aucun
  // effet (aucune salle construite).
  facilityInjuryRiskMult() {
    const level = (this.facilityLevels && this.facilityLevels.gym) || 0;
    const info = facilityInfo("gym", level);
    return info ? info.injuryRiskMult : 1;
  }

  // Multiplicateur d'accumulation de fatigue en match (voir MatchEngine.
  // applyFatigue) — palier ACTUEL de l'espace bien-être, 1 = aucun effet
  // (aucun espace bien-être construit).
  facilityFatigueMult() {
    const level = (this.facilityLevels && this.facilityLevels.wellness) || 0;
    const info = facilityInfo("wellness", level);
    return info ? info.fatigueMult : 1;
  }

  // Dilution du rendement selon le nombre de postes couverts cette semaine.
  trainingDilution() {
    return trainingDilutionFor(this.trainingSkill, this.trainingPositions.length);
  }

  // Temps RÉELLEMENT joué par ce joueur, CUMULÉ sur tous les matchs du cycle
  // d'entraînement en cours (calendrier ancré quotidien : jusqu'à 3 matchs
  // par jour civil, championnat + coupe éventuelle, voir
  // Player.trainingSecondsPlayedByPosition, retour utilisateur, 2026-09 :
  // "la semaine est en fait une journée avec 3 matchs [...] un joueur doit
  // jouer 30 min au poste déterminé sur sa semaine pour prendre
  // l'entrainement"), aux poste(s) couverts par l'entraînement de la
  // semaine (this.trainingPositions). PAS son temps de jeu total, ni son
  // poste "de carte" (this.position) : un remplaçant polyvalent peut avoir
  // été aligné sur un poste différent du sien (voir Team.lineup et
  // Player.matchPosition), auquel cas c'est le temps passé À CE poste
  // précis qui doit compter pour son entraînement, où qu'il joue
  // habituellement. Renvoie { byPosition, total } (secondes).
  trainablySecondsFor(player) {
    const byPosition = {};
    let total = 0;
    (this.trainingPositions || []).forEach(pos => {
      const s = (player.trainingSecondsPlayedByPosition && player.trainingSecondsPlayedByPosition[pos]) || 0;
      if (s > 0) { byPosition[pos] = s; total += s; }
    });
    return { byPosition, total };
  }

  // Aperçu (lecture seule, ne modifie rien) de ce que vaudrait l'entraînement
  // de la semaine pour CE joueur, avec la compétence et les postes
  // actuellement sélectionnés (this.trainingSkill / this.trainingPositions).
  // Utilisé par l'écran de préparation pour afficher "concerné à X%" avant
  // validation, et par trainWeek() pour construire ses valeurs
  // "représentatives" (une seule source de vérité pour ce calcul).
  trainingPreviewFor(player) {
    const skill = this.trainingSkill;
    const program = skill ? TRAINING_PROGRAMS[skill] : null;
    const { byPosition, total } = this.trainablySecondsFor(player);
    const posSelected = Boolean(program) && total > 0;
    const attendanceFactor = attendanceFactorForSeconds(total);
    if (!posSelected) {
      return { posSelected: false, trainedSeconds: total, attendanceFactor, positionEfficiency: null, heightMultiplier: null, finalPct: 0 };
    }
    const dilution = this.trainingDilution();
    let progEffSum = 0;
    Object.entries(byPosition).forEach(([pos, secs]) => { progEffSum += positionEfficiencyForProgram(skill, pos) * secs; });
    const positionEfficiency = Math.round(progEffSum / total);
    const heightMultiplier = heightMultiplierForProgram(skill, player.height);
    const finalPct = Math.round((positionEfficiency / 100) * (1 - dilution) * heightMultiplier * attendanceFactor * 100);
    return { posSelected: true, trainedSeconds: total, attendanceFactor, positionEfficiency, heightMultiplier, finalPct };
  }

  trainerSalary() {
    return this.trainer ? trainerWeeklySalary(this.trainer.level, this.trainer.weeksEmployed, this.trainer.baseSalary) : 0;
  }

  trainerBonusMultiplier() {
    return this.trainer ? 1 + (TRAINER_TRAINING_BONUS[this.trainer.level] || 0) : 1;
  }

  // Congédie l'entraîneur actuel (s'il y en a un) puis en embauche un nouveau
  // au niveau demandé : le salaire repart de sa valeur de départ (weeksEmployed
  // = 0), c'est tout l'intérêt de "racheter" un entraîneur une fois que le
  // salaire de l'ancien est devenu trop élevé. `baseSalary` (optionnel) :
  // salaire de départ RÉEL — utilisé par League._resolveCoachListing avec la
  // mise gagnante d'une enchère (voir marché des entraîneurs plus haut dans
  // le fichier) ; par défaut (appel direct, hors enchère) le tarif fixe
  // TRAINER_BASE_SALARY[level] comme avant.
  // `specialty` (retour utilisateur 2026-10-01) : spécialité de l'annonce,
  // sinon une spécialité déterministe.
  hireTrainer(level, baseSalary, specialty = null) {
    if (!TRAINER_LEVELS.includes(level)) return;
    const base = baseSalary != null ? baseSalary : (TRAINER_BASE_SALARY[level] || 0);
    this.trainer = {
      level, weeksEmployed: 0, baseSalary: base,
      specialty: COACH_SPECIALTIES[specialty] ? specialty : deterministicCoachSpecialty(`${this.name}|${level}|${base}`),
    };
  }

  fireTrainer() {
    this.trainer = null;
  }

  // Analyste vidéo — même forme/mêmes méthodes que l'entraîneur ci-dessus
  // (trainerSalary/hireTrainer/fireTrainer), voir le commentaire sur
  // this.videoAnalyst (constructeur) pour ce que ce rôle apporte réellement
  // (des séances vidéo, voir League.runVideoSession, PAS un effet sur
  // l'entraînement ou les matchs). `trainerWeeklySalary` est déjà
  // agnostique du rôle de staff (ne lit que level/weeksEmployed/baseOverride,
  // jamais `this.trainer` lui-même) : la réutiliser ici évite de dupliquer le
  // calcul d'escalade hebdomadaire (TRAINER_WEEKLY_GROWTH) pour ce second
  // rôle.
  videoAnalystSalary() {
    return this.videoAnalyst ? trainerWeeklySalary(this.videoAnalyst.level, this.videoAnalyst.weeksEmployed, this.videoAnalyst.baseSalary) : 0;
  }

  // Congédie l'analyste actuel (s'il y en a un) puis en embauche un nouveau
  // au niveau demandé — même contrat que Team.hireTrainer (`baseSalary`
  // optionnel : mise gagnante d'une enchère via League._resolveAnalystListing,
  // sinon repli sur le tarif fixe TRAINER_BASE_SALARY[level]). Réutilise
  // TRAINER_LEVELS (1 à 5) comme paliers de compétence de l'analyste : aucune
  // raison de lui inventer une échelle de niveaux différente de celle de
  // l'entraîneur.
  hireVideoAnalyst(level, baseSalary) {
    if (!TRAINER_LEVELS.includes(level)) return;
    this.videoAnalyst = { level, weeksEmployed: 0, baseSalary: baseSalary != null ? baseSalary : (TRAINER_BASE_SALARY[level] || 0) };
  }

  fireVideoAnalyst() {
    this.videoAnalyst = null;
  }

  // Recruteur — TROISIÈME rôle de staff, même forme/mêmes méthodes que
  // l'entraîneur/l'analyste vidéo ci-dessus (recruiterSalary/hireRecruiter/
  // fireRecruiter, réutilisant trainerWeeklySalary comme videoAnalystSalary
  // le fait déjà) — voir le commentaire sur this.recruiter (constructeur)
  // pour ce que ce rôle apporte réellement (un flux PRIVÉ de propositions de
  // jeunes prospects, voir refreshYouthCandidates plus bas, PAS un effet sur
  // l'entraînement pro ni les matchs).
  recruiterSalary() {
    return this.recruiter ? trainerWeeklySalary(this.recruiter.level, this.recruiter.weeksEmployed, this.recruiter.baseSalary) : 0;
  }

  hireRecruiter(level, baseSalary) {
    if (!TRAINER_LEVELS.includes(level)) return;
    this.recruiter = { level, weeksEmployed: 0, baseSalary: baseSalary != null ? baseSalary : (TRAINER_BASE_SALARY[level] || 0) };
  }

  fireRecruiter() {
    this.recruiter = null;
  }

  // Staff médical (voir MEDICAL_STAFF_ROLES) — `role` vaut "doctor" ou
  // "physio". Même salaire croissant que les autres rôles de staff.
  medicalStaffSalary(role) {
    const m = MEDICAL_STAFF_ROLES[role] ? this[role] : null;
    return m ? trainerWeeklySalary(m.level, m.weeksEmployed, m.baseSalary) : 0;
  }
  doctorSalary() { return this.medicalStaffSalary("doctor"); }
  physioSalary() { return this.medicalStaffSalary("physio"); }

  hireMedicalStaff(role, level, baseSalary) {
    if (!MEDICAL_STAFF_ROLES[role] || !TRAINER_LEVELS.includes(level)) return;
    this[role] = { level, weeksEmployed: 0, baseSalary: baseSalary != null ? baseSalary : (TRAINER_BASE_SALARY[level] || 0) };
  }
  fireMedicalStaff(role) {
    if (MEDICAL_STAFF_ROLES[role]) this[role] = null;
  }
  hireDoctor(level, baseSalary) { this.hireMedicalStaff("doctor", level, baseSalary); }
  hirePhysio(level, baseSalary) { this.hireMedicalStaff("physio", level, baseSalary); }
  fireDoctor() { this.fireMedicalStaff("doctor"); }
  firePhysio() { this.fireMedicalStaff("physio"); }

  // Entraîneur adjoint (voir ASSISTANT_SPECIALTIES) — un seul par club :
  // en engager un autre remplace le précédent.
  assistantCoachSalary() {
    const a = this.assistantCoach;
    return a ? trainerWeeklySalary(a.level, a.weeksEmployed, a.baseSalary) : 0;
  }
  hireAssistantCoach(specialty, level, baseSalary) {
    if (!ASSISTANT_SPECIALTIES[specialty] || !TRAINER_LEVELS.includes(level)) return;
    this.assistantCoach = { level, weeksEmployed: 0, specialty, baseSalary: baseSalary != null ? baseSalary : (ASSISTANT_BASE_SALARY[level] || 0) };
  }
  fireAssistantCoach() { this.assistantCoach = null; }

  // Multiplicateur de durée d'une NOUVELLE blessure (voir rollInjury et
  // MatchEngine.applyFatigue) : 1 sans médecin, 0,65 avec un médecin 5★.
  doctorInjuryDurationMult() {
    return this.doctor ? 1 - (DOCTOR_INJURY_DURATION_REDUCTION_BY_LEVEL[this.doctor.level] || 0) : 1;
  }
  // Multiplicateur de risque de blessure en match (voir
  // MatchEngine.applyFatigue), cumulé avec facilityInjuryRiskMult.
  physioInjuryRiskMult() {
    return this.physio ? (PHYSIO_INJURY_RISK_MULT_BY_LEVEL[this.physio.level] || 1) : 1;
  }
  // Points de forme physique récupérés EN PLUS chaque jour (voir
  // conditionRecoveryPerDay).
  // Carnet des blessures (voir this.injuryLog au constructeur), alimenté par
  // MatchEngine.applyFatigue au moment où la blessure survient. `seasonNo`
  // suit la même convention que seasonPlayerTotalsForTeam
  // (seasonHistory.length + 1) pour filtrer « la saison en cours ».
  recordInjury(entry) {
    // Suivi des blessures porté par le joueur (pros et jeunes de l'académie).
    const injured = entry && ((this.players || []).find(p => p.id === entry.playerId) || (this.youthPlayers || []).find(p => p.id === entry.playerId));
    if (injured) {
      recordPlayerInjury(injured, {
        at: entry.at || Date.now(), season: teamSeasonNo(this), type: entry.injuryType || "Blessure", days: entry.days || null,
        until: typeof injured.injuryUntil === "number" ? injured.injuryUntil : null, club: this.name,
        opponent: entry.opponentName || null, training: !!entry.training, friendly: !!entry.friendly,
        doctor: this.doctor ? this.doctor.level : 0,
      });
    }
    if (!Array.isArray(this.injuryLog)) this.injuryLog = [];
    this.injuryLog.unshift({ seasonNo: (this.seasonHistory || []).length + 1, week: this.week, ...entry });
    if (this.injuryLog.length > INJURY_LOG_MAX) this.injuryLog.length = INJURY_LOG_MAX;
  }
  physioRecoveryBonus() {
    return this.physio ? (PHYSIO_RECOVERY_BONUS_BY_LEVEL[this.physio.level] || 0) : 0;
  }

  // ---------------------------------------------------------------------
  // ACADÉMIE DE JEUNES — pipeline PRIVÉ de prospects (voir le grand
  // commentaire sur this.youthCandidates au constructeur) : contrairement
  // aux marchés d'entraîneur/analyste/recruteur ci-dessus (partagés, aux
  // enchères entre TOUS les managers), rien ici ne touche `this.teams` d'une
  // League — ces méthodes vivent entièrement sur Team.
  // ---------------------------------------------------------------------

  // Fait vivre la file de propositions de CE club : expire d'abord les
  // propositions trop anciennes (YOUTH_CANDIDATE_EXPIRY_MS, même fenêtre que
  // le marché du staff), puis, si un recruteur est sous contrat et que la
  // file n'est pas déjà pleine (YOUTH_CANDIDATE_QUEUE_MAX), tire au sort une
  // nouvelle proposition selon YOUTH_CANDIDATE_DAILY_CHANCE_BY_LEVEL. `now`
  // explicite (voir Team.trainWeek, qui appelle ceci à son propre rythme
  // "une fois par tick") — jamais de Date.now() implicite ici.
  refreshYouthCandidates(now) {
    this.youthCandidates = (this.youthCandidates || []).filter(c => now < c.expiresAt);
    if (!this.recruiter) return; // aucune proposition sans recruteur sous contrat
    if (this.youthCandidates.length >= YOUTH_CANDIDATE_QUEUE_MAX) return; // file déjà pleine
    const chance = YOUTH_CANDIDATE_DAILY_CHANCE_BY_LEVEL[this.recruiter.level] || 0;
    if (rand01() >= chance) return;
    this.youthCandidates.push(generateYouthCandidate(now, this.recruiter.level, this.country));
  }

  // Signe un candidat en attente : le déplace de youthCandidates vers
  // youthPlayers (plafonné à MAX_YOUTH_ROSTER_SIZE), fixe son salaire au
  // tarif de stagiaire FIXE (YOUTH_TRAINEE_WEEKLY_SALARY, indépendant de ses
  // attributs/potentiel) — son potentiel réel (déjà tiré à la génération du
  // candidat, voir generateYouthCandidate) reste caché derrière le MÊME
  // label grossier à 3 bandes qu'avant la signature (voir
  // youthProspectLabel) : signer ne change RIEN à ce que le manager voit du
  // potentiel, seule la PROMOTION en pro (Team.promoteYouthPlayer) l'expose
  // enfin. Renvoie { ok: true, player } ou { ok: false, reason } — reasons :
  // "not-found" (id de candidat inconnu), "youth-roster-full" (déjà
  // MAX_YOUTH_ROSTER_SIZE jeunes signés).
  signYouthCandidate(candidateId) {
    if ((this.youthPlayers || []).length >= MAX_YOUTH_ROSTER_SIZE) return { ok: false, reason: "youth-roster-full" };
    const idx = (this.youthCandidates || []).findIndex(c => c.id === candidateId);
    if (idx === -1) return { ok: false, reason: "not-found" };
    const [player] = this.youthCandidates.splice(idx, 1);
    player.salary = YOUTH_TRAINEE_WEEKLY_SALARY;
    this.youthPlayers.push(player);
    return { ok: true, player };
  }

  // Décline un candidat en attente : simplement retiré de youthCandidates,
  // aucune place d'effectif jeunes consommée (il n'en occupait aucune tant
  // qu'il n'était pas signé). Renvoie { ok: true } ou { ok: false, reason:
  // "not-found" }.
  declineYouthCandidate(candidateId) {
    const idx = (this.youthCandidates || []).findIndex(c => c.id === candidateId);
    if (idx === -1) return { ok: false, reason: "not-found" };
    this.youthCandidates.splice(idx, 1);
    return { ok: true };
  }

  // Progression AUTOMATIQUE des jeunes déjà signés — AUCUNE sélection de
  // programme/poste (délibéré, pas de micro-management pour l'effectif
  // jeunes) : chaque jeune progresse un peu sur SES 10 caractéristiques à la
  // fois, à un rythme modeste (YOUTH_BASE_TRAINING_WEIGHT) mis à l'échelle
  // par le Centre de formation (trainingCenterGrowthMultiplier). Réutilise
  // TEL QUEL Player.trainWeek — même formule de progression selon l'âge
  // (growthFactorForAge) que l'effectif pro, PUIS plafonne CHAQUE
  // caractéristique à 50 (correctif 2026-09, retour utilisateur explicite :
  // "un joueur qui sort du centre de formation [...] ne doit pas avoir une
  // carac qui dépasse 50 [...] il doit pouvoir monter naturellement vers les
  // 50 (en sachant que 50 c'est exceptionnel)") — ce plafond porte
  // UNIQUEMENT sur les caractéristiques ACTUELLES pendant cette phase
  // académie, jamais sur le potentiel réel (qui peut valoir 85+, voir
  // generateYouthCandidate, et reste totalement invisible tant que le
  // joueur n'est pas promu). Volontairement appliqué ICI (un simple
  // Math.min après coup), PAS dans Player.trainWeek lui-même : une fois
  // promu en pro, ce même joueur repasse par le trainWeek NORMAL de
  // l'effectif pro (voir Team.trainWeek), sans aucun plafond à 50 — c'est ce
  // second passage, post-promotion, qui débloque vraiment le potentiel
  // élevé d'un prodige.
  growYouthPlayers() {
    const attrWeights = {};
    ATTRS.forEach(a => attrWeights[a] = YOUTH_BASE_TRAINING_WEIGHT);
    // Spécialité « Jeunes » de l'entraîneur : +15 % aussi pour l'académie
    // (retour utilisateur 2026-10-01).
    const mult = this.trainingCenterGrowthMultiplier() * (this.trainer && this.trainer.specialty === "youth" ? 1 + COACH_SPECIALTY_BONUS : 1);
    (this.youthPlayers || []).forEach(p => {
      p.trainWeek(attrWeights, mult, null, { roomDivisor: LEGACY_TRAINING_ROOM_DIVISOR });
      ATTRS.forEach(a => { if (p.attrs[a] > 50) p.attrs[a] = 50; });
    });
  }

  // Décision manager sur un jeune qui vient d'avoir 18 ans (voir
  // this.pendingYouthDecisions, alimenté par trainWeek au passage d'une
  // saison) — PROMOTION : rejoint l'effectif pro (this.players, plafonné à
  // MAX_ROSTER_SIZE), salaire recalculé à sa vraie valeur de marché (voir
  // salaryForOverall(player.overall()) — il cesse d'être un "stagiaire" pour
  // devenir un joueur normal, comme n'importe qui acheté sur le marché des
  // transferts). Renvoie { ok: true, player } ou { ok: false, reason } —
  // reasons : "not-found", "roster-full" (effectif pro déjà au plafond).
  // `now` (ms, comme Date.now()) : DOIT être passé explicitement par
  // l'appelant (retour utilisateur, 2026-09 : "ajoute la date à laquelle le
  // joueur est passé pro"), jamais de Date.now() implicite ici, même
  // convention que refreshMarket(now)/refreshRecruiterMarket(now) etc.
  // ci-dessus, pour rester testable de façon déterministe.
  // `season` (optionnel) : saison de contrat courante (League.contractSeason)
  // — contrat de YOUTH_PROMOTION_CONTRACT_SEASONS saisons au salaire de
  // promotion (demande du 2026-10-01).
  promoteYouthPlayer(playerId, now, season = null) {
    const idx = (this.youthPlayers || []).findIndex(p => p.id === playerId);
    if (idx === -1) return { ok: false, reason: "not-found" };
    if (this.players.length >= MAX_ROSTER_SIZE) return { ok: false, reason: "roster-full" };
    const [player] = this.youthPlayers.splice(idx, 1);
    this.pendingYouthDecisions = (this.pendingYouthDecisions || []).filter(id => id !== playerId);
    player.salary = salaryForOverall(levelCoefficientFor(player.attrs, player.position).coefficient);
    if (typeof season === "number") player.contractUntilSeason = season + YOUTH_PROMOTION_CONTRACT_SEASONS - 1;
    // Club formateur (apparence personnalisable, voir canCustomizePlayerLook).
    player.homegrownClub = String(this.name || "").trim().toLowerCase();
    recordPlayerEvent(player, { type: "promotion", at: Date.now(), season: teamSeasonNo(this), to: this.name });
    try { History.push({ type: "YOUTH_GRADUATE", importance: 1, season: histSeasonOf(this), at: Date.now(), teams: [this.name], players: [player.id], description: `${player.name} (${player.age} ans, ${player.position}) est promu de l'académie en équipe première.`, tags: ["formé au club"] }); } catch (e) { /* confort */ }
    // Jeune promu : garde ce qu'il a appris en amical, 40 ailleurs.
    player.tacticalKnowledge = copyTacticalKnowledge(player.tacticalKnowledge);
    this.players.push(player);
    Vestiaire.noteRoster(this, player, "youth", now);
    ensureJerseyNumbers(this);
    // Palmarès du club (voir this.academyGraduates au constructeur) : cette
    // promotion EST l'évènement qui compte pour ce compteur, incrémenté
    // uniquement ici (jamais à la signature du candidat, ni pendant la
    // croissance automatique tant qu'il n'a pas encore 18 ans).
    this.academyGraduates = (this.academyGraduates || 0) + 1;
    // Historique du centre de formation (voir this.academyGraduatesHistory
    // au constructeur) : même évènement que le compteur ci-dessus, mais
    // garde le nom/poste de CHAQUE jeune promu au lieu de se limiter à un
    // total, pour l'affichage détaillé côté client
    // (renderAcademyGraduatesStat, moteurbasket3.html). promotedAt : date
    // de cette promotion (voir le paramètre `now` ci-dessus), une entrée
    // restaurée d'une sauvegarde d'avant ce champ n'en a pas (undefined),
    // affichée sans date plutôt qu'avec une date inventée.
    (this.academyGraduatesHistory = this.academyGraduatesHistory || []).push({
      name: player.name, position: player.position, promotedAt: now,
    });
    // Rejoint le banc plutôt qu'un titulaire (même convention que l'achat
    // d'un joueur sur le marché des transferts, voir League._resolveListing)
    // pour ne jamais déloger un titulaire déjà choisi manuellement — sauf
    // pour une équipe CPU (qui n'a personne pour retoucher sa feuille
    // manuellement, voir Team.isHuman), reconstruite entièrement comme
    // ailleurs.
    if (!this.isHuman) this.autoAssignLineup();
    // Succès « Dénicheur de talents » (Bronze) : jeune du club dans l'effectif.
    achHomegrownCheck(this, now || Date.now());
    return { ok: true, player };
  }

  // LIBÉRATION : retiré définitivement, libère une place d'effectif jeunes.
  // Renvoie { ok: true } ou { ok: false, reason: "not-found" }.
  releaseYouthPlayer(playerId) {
    const idx = (this.youthPlayers || []).findIndex(p => p.id === playerId);
    if (idx === -1) return { ok: false, reason: "not-found" };
    this.youthPlayers.splice(idx, 1);
    this.pendingYouthDecisions = (this.pendingYouthDecisions || []).filter(id => id !== playerId);
    return { ok: true };
  }

  // Fait progresser/décliner tous les joueurs du club d'une semaine d'entraînement.
  // Renvoie un rapport détaillé par joueur pour l'UI : gains obtenus, et le
  // détail du calcul (poste concerné ou non, proportion du dernier match
  // jouée) pour expliquer pourquoi l'entraînement a plus ou moins pris.
  // `divisionLevel` (optionnel) : niveau de division ACTUEL du club, pour le
  // calcul des droits TV (voir TV_RIGHTS_WEEKLY_BY_LEVEL plus haut) —
  // transmis par l'appelant (voir League.divisionLevel côté UI), puisque le
  // Team ne connaît pas lui-même sa position dans la pyramide. Omis (ou
  // `null`/`undefined`) : aucun revenu de droits TV cette semaine-là (utile
  // pour un Team utilisé sans ligue, comme dans les tests directs du moteur).
  // Voir le grand commentaire de BENCH_FRUSTRATION_MAX_SECONDS plus haut :
  // érode Player.form pour tout non-titulaire n'ayant quasiment pas joué
  // cette semaine, plus sévèrement s'il note mieux que le titulaire
  // actuellement aligné à son poste. Appelée par trainWeek ci-dessous, mais
  // gardée comme méthode séparée pour rester testable indépendamment.
  applyBenchFrustration(now = Date.now()) {
    const starters = (this.lineup && this.lineup.starters) || {};
    const starterIds = new Set(Object.values(starters).filter(Boolean));
    this.players.forEach(p => {
      if (starterIds.has(p.id)) return; // titulaire : jamais concerné
      if (isCurrentlyInjured(p, now)) return; // ne pas jouer n'est alors pas un choix
      const secondsThisWeek = Object.values(p.trainingSecondsPlayedByPosition || {})
        .reduce((sum, s) => sum + s, 0);
      if (secondsThisWeek > BENCH_FRUSTRATION_MAX_SECONDS) return; // a quand même tourné un peu
      const ownRating = weightedRatingForPosition(p.attrs, p.position);
      const starterId = starters[p.position];
      const starter = starterId ? this.players.find(x => x.id === starterId) : null;
      const deservesToStart = !!starter && ownRating > weightedRatingForPosition(starter.attrs, p.position);
      const malus = BENCH_FRUSTRATION_BASE_MALUS * (deservesToStart ? BENCH_FRUSTRATION_DESERVING_MULT : 1);
      p.form = clamp(Math.round(p.form - malus), 1, 100);
    });
  }

  // Voir le grand commentaire de TRANSFER_REQUEST_MOTIVATION_THRESHOLD plus
  // haut : fait avancer, chaque semaine, le compteur de semaines
  // consécutives sous le seuil de motivation "proche de 0" pour chaque
  // joueur, et déclenche une demande de transfert une fois ce compteur au
  // seuil. Une motivation qui remonte au-dessus du seuil (discussion
  // réussie, bonne interview de jalon, ou tout simplement le temps de jeu
  // qui revient) remet le compteur à 0 ET referme une demande déjà active :
  // un joueur qui n'est plus malheureux n'a plus de raison de demander son
  // transfert. Appelée par trainWeek ci-dessous, mais gardée comme méthode
  // séparée pour rester testable indépendamment (même convention que
  // applyBenchFrustration juste au-dessus).
  updateTransferRequests(now = Date.now()) {
    this.players.forEach(p => {
      if (p.form <= TRANSFER_REQUEST_MOTIVATION_THRESHOLD) {
        p.weeksAtLowMotivation = (p.weeksAtLowMotivation || 0) + 1;
        if (!p.transferRequestActive && p.weeksAtLowMotivation >= TRANSFER_REQUEST_WEEKS_THRESHOLD) {
          p.transferRequestActive = true;
          p.transferRequestDiscussed = false;
          p.transferRequestQuote = transferRequestQuoteFor(p.name);
          this.recordMoraleEvent(`${p.name} demande son transfert dans la presse`, 0, { transferRequestPlayerId: p.id });
        }
      } else {
        p.weeksAtLowMotivation = 0;
        if (p.transferRequestActive) {
          p.transferRequestActive = false;
          p.transferRequestQuote = null;
        }
        p.transferRequestDiscussed = false;
      }
    });
  }

  // Action "discuter" du manager avec un joueur qui a demandé son transfert
  // (voir le grand commentaire de TRANSFER_REQUEST_MOTIVATION_THRESHOLD plus
  // haut) : chance de succès partant de TRANSFER_REQUEST_DISCUSS_BASE_CHANCE,
  // augmentée jusqu'à TRANSFER_REQUEST_DISCUSS_MENTAL_BONUS de plus pour un
  // Mental à 100 (un joueur mentalement fort se laisse plus facilement
  // convaincre, voir ATTRS). Un succès remotive franchement le joueur (+
  // TRANSFER_REQUEST_DISCUSS_SUCCESS_FORM_BOOST sur sa forme, ce qui
  // repasse largement le seuil et referme donc la demande) et journalise
  // l'issue positive ; un échec ne change RIEN (la demande reste active, le
  // manager peut retenter plus tard, ou vendre le joueur) — "ne marche pas à
  // chaque fois". Renvoie { ok: true, success, formBefore, formAfter } ou
  // { ok: false, reason } (joueur introuvable, ou n'ayant PAS demandé son
  // transfert), jamais d'exception, même convention que les autres méthodes
  // "action du manager" de cette classe (voir resolveInterview/sellPlayer).
  discussTransferRequest(playerId, now = Date.now()) {
    const p = this.players.find(pl => pl.id === playerId);
    if (!p) return { ok: false, reason: "not-found" };
    if (!p.transferRequestActive) return { ok: false, reason: "not-requesting" };
    if (p.transferRequestDiscussed) return { ok: false, reason: "already-discussed" };
    // "mental" n'est plus stocké individuellement (retour utilisateur,
    // 2026-09, voir mentalAverage() au-dessus de PHYSICAL_ATTRS) : on
    // utilise ici la moyenne des 8 traits de MENTAL_ATTRS.
    const chance = TRANSFER_REQUEST_DISCUSS_BASE_CHANCE + (mentalAverage(p) / 100) * TRANSFER_REQUEST_DISCUSS_MENTAL_BONUS;
    const success = rand01() < chance;
    const formBefore = p.form;
    if (success) {
      p.form = clamp(Math.round(p.form + TRANSFER_REQUEST_DISCUSS_SUCCESS_FORM_BOOST), 1, 100);
      p.weeksAtLowMotivation = 0;
      p.transferRequestActive = false;
      p.transferRequestQuote = null;
      p.transferRequestDiscussed = false;
      this.recordMoraleEvent(`Discussion réussie avec ${p.name}, la demande de transfert est retirée`, 0, { transferRequestPlayerId: p.id });
    } else {
      p.transferRequestDiscussed = true;
    }
    if (vestiaireApi()) vestiaireApi().pushLog(this, { t: success ? "talk-ok" : "talk-ko", p: p.id, n: p.name });
    return { ok: true, success, formBefore, formAfter: p.form };
  }

  // Rôle d'un joueur dans la compo officielle actuelle : "starter"
  // (titulaire), "rotation" (remplaçant d'au moins un poste) ou "reserve".
  playerRoleKey(playerId) {
    if (this.starterPosition(playerId)) return "starter";
    const backups = (this.lineup && this.lineup.backupPositions) || {};
    return (backups[playerId] || []).length ? "rotation" : "reserve";
  }

  // Où en est la discussion avec un joueur qui a annoncé sa dernière
  // saison (voir RETIREMENT_ANNOUNCE_CHANCE_BY_AGE). `null` s'il n'a rien
  // annoncé. `hint` : "hopeful" (Il hésite encore), "decided" (Il semble
  // décidé) ou "final" (Sa décision est prise : plus aucune tentative
  // possible cette saison, ou 39 ans et plus). `canTalk` : une tentative
  // est possible MAINTENANT (tiers en cours pas encore utilisé).
  retirementTalkStatus(playerId) {
    const p = this.players.find(pl => pl.id === playerId);
    if (!p || !p.retiringAfterSeason) return null;
    const talks = Array.isArray(p.retirementTalks) ? p.retirementTalks : [];
    const period = retirementTalkPeriod(p);
    const chance = retirementTalkChance(p, this.playerRoleKey(p.id));
    let remaining = 0;
    for (let i = period; i < RETIREMENT_TALK_PERIODS; i++) if (!talks.includes(i)) remaining++;
    const final = chance <= 0 || remaining === 0;
    const canTalk = !final && !talks.includes(period);
    const hint = final ? "final" : chance >= RETIREMENT_TALK_HOPEFUL_CHANCE ? "hopeful" : "decided";
    const hintLabel = { hopeful: "Il hésite encore", decided: "Il semble décidé", final: "Sa décision est prise" }[hint];
    const nextPeriod = canTalk ? period : (final ? null : period + 1);
    return {
      period, periodLabel: RETIREMENT_TALK_PERIOD_LABELS[period], canTalk, hint, hintLabel,
      attemptsUsed: talks.length, remaining,
      nextPeriodLabel: nextPeriod != null && nextPeriod < RETIREMENT_TALK_PERIODS ? RETIREMENT_TALK_PERIOD_LABELS[nextPeriod] : null,
    };
  }

  // Tente de convaincre un joueur de repousser sa retraite d'un an (voir
  // retirementTalkStatus). Gratuit ; une tentative par tiers de saison.
  // Renvoie { ok, success } ou { ok:false, reason } — "not-found",
  // "not-retiring", "decision-final", "already-talked".
  talkRetirement(playerId, now = Date.now(), rng = Math.random) {
    const p = this.players.find(pl => pl.id === playerId);
    if (!p) return { ok: false, reason: "not-found" };
    const status = this.retirementTalkStatus(playerId);
    if (!status) return { ok: false, reason: "not-retiring" };
    if (status.hint === "final") return { ok: false, reason: "decision-final" };
    if (!status.canTalk) return { ok: false, reason: "already-talked" };
    const chance = retirementTalkChance(p, this.playerRoleKey(p.id));
    const success = rng() < chance;
    if (success) {
      p.retiringAfterSeason = false;
      p.retirementWeeks = 0;
      p.retirementTalks = [];
      p.retirementQuote = null;
      if (this.feed) {
        pushEntry(this.feed, {
          key: `retiring_${p.id}`, category: "presse", week: this.week, createdAt: now,
          title: `${p.name} repousse sa retraite d'un an`,
          text: `Convaincu par le club, ${p.name} (${p.age} ans) jouera une saison de plus.`,
          action: { label: "Effectif", href: "/effectif" },
        });
      }
    } else {
      p.retirementTalks = [...(Array.isArray(p.retirementTalks) ? p.retirementTalks : []), status.period];
    }
    return { ok: true, success, status: this.retirementTalkStatus(playerId) };
  }

  // `opts.seasonEnd` (optionnel, booléen) : décide EXPLICITEMENT si cette
  // mise à jour clôt la saison (vieillissement, salaires recalculés, stats
  // de saison remises à zéro...). Passé par la ligue au rythme hebdomadaire
  // (voir server/autoSim.js:catchUpWeeklyRhythm) : `false` à chaque lundi de
  // la saison, `true` au lundi qui suit la finale des play-offs — jamais
  // plus le compteur team.week, faussé dans une ligue basculée en pleine
  // saison (il garde les jours du rythme quotidien). Absent : règle
  // historique, tous les SEASON_LENGTH_WEEKS (carrière solo, calendrier
  // classique).
  trainWeek(divisionLevel, now, opts = null) {
    // Prestige (voir clubPrestigeDetail) : ne change qu'avec l'histoire du
    // club et sa division, donc en pratique à chaque changement de saison.
    this.prestige = clubPrestigeDetail(this, divisionLevel).value;
    // Entraînement v2 (retour utilisateur 2026-10-01) : plans individuels
    // (un joueur + un programme par place, voir TRAINING_SLOTS_BY_COACH_LEVEL),
    // le poste n'intervient plus ; rendement = programme × gabarit × minutes
    // de la semaine (30 min = plein) × entraîneur × intensité × spécialité.
    // Les jours de repos écoulés (y compris dimanche) sont d'abord crédités.
    if (now != null && typeof this.syncCollectiveTrainingLog === "function") this.syncCollectiveTrainingLog(now);
    const nowMs = now != null ? now : Date.now();
    const trainerMult = this.trainerBonusMultiplier();
    const ceilingBonus = trainerCeilingBonus(this.trainer);
    const slotByPlayer = new Map(this.activeTrainingSlots().map(sl => [String(sl.playerId), sl.program]));
    const mentoredYoung = new Set(this.activeMentorships().map(m => String(m.youngId)));
    if (!this.trainingStalls || typeof this.trainingStalls !== "object") this.trainingStalls = {};
    const report = {};
    const slotReport = [];
    const advice = [];

    // AVANT la remise à zéro de trainingSecondsPlayedByPosition ci-dessous
    // (dans la boucle qui suit) : applyBenchFrustration a besoin du temps de
    // jeu de CETTE semaine qui s'achève, pas de la semaine suivante.
    this.applyBenchFrustration(now);
    // APRÈS applyBenchFrustration : se base sur Player.form déjà à jour de
    // cette semaine (malus du banc inclus) pour décider qui franchit le
    // seuil de motivation "proche de 0".
    this.updateTransferRequests(now);
    // Dynamique de groupe (voir assets/vestiaire.js:weeklyUpdate) : APRÈS la
    // forme de la semaine, AVANT la remise à zéro du temps de jeu ci-dessous.
    if (vestiaireApi()) vestiaireApi().weeklyUpdate(this, { now: now != null ? now : Date.now(), applyChemistry: d => this.applyChemistryDelta(d) });
    // Retraite : une semaine de plus depuis l'annonce (donne le tiers de
    // saison des discussions, voir retirementTalkPeriod). Les partants de
    // fin de saison ont déjà quitté l'effectif (League.retireAnnouncedPlayers).
    this.players.forEach(p => { if (p.retiringAfterSeason) p.retirementWeeks = (p.retirementWeeks || 0) + 1; });

    this.players.forEach(p => {
      const program = slotByPlayer.get(String(p.id)) || null;
      const weekSeconds = playerWeekSeconds(p);
      const attendanceFactor = attendanceFactorForSeconds(weekSeconds);
      let attrWeights = {};
      let synergyAttrs = new Set();
      let ceilingWeights = null;
      let mult = trainerMult;
      let efficiency = null;
      const intensityKey = trainingIntensityOf(this, p);
      const intensity = TRAINING_INTENSITIES[intensityKey];
      if (program) {
        ({ attrWeights, synergyAttrs, ceilingWeights } = slotTrainingWeightsFor(p, program));
        mult = trainerMult * intensity.mult * coachSpecialtyMultFor(this.trainer, program, p);
        efficiency = trainingEfficiencyFor(this, p, program).pct;
      }

      // Entraîneur adjoint (voir ASSISTANT_SPECIALTIES) : poids AJOUTÉ à celui
      // du programme, pour tout joueur non blessé, minutes jouées ou pas —
      // jamais compté comme une synergie (une carac travaillée par l'adjoint
      // garde sa marge de progression pleine, voir Player.trainWeek).
      if (this.assistantCoach && !isCurrentlyInjured(p, nowMs)) {
        Object.entries(assistantAttrWeightsFor(this.assistantCoach, p)).forEach(([attr, w]) => {
          if (!(w > 0)) return;
          attrWeights[attr] = (attrWeights[attr] || 0) + w;
          synergyAttrs.delete(attr);
        });
      }
      const programAttrs = program ? TRAINING_PROGRAMS[program].attrs.map(a => a.attr) : [];
      const before = {};
      programAttrs.forEach(a => { before[a] = p.attrs[a]; });
      // Mental : expérience (minutes de la semaine) et parrainage (retour
      // utilisateur 2026-10-01).
      const mentalMult = mentalExperienceMult(weekSeconds) * (mentoredYoung.has(String(p.id)) ? MENTORSHIP_MENTAL_MULT : 1);
      const gains = p.trainWeek(attrWeights, mult, synergyAttrs, { ceilingBonus, ceilingWeights, mentalMult });

      if (program) {
        const changes = programAttrs.map(a => ({ attr: a, before: before[a], after: p.attrs[a] }));
        const delta = changes.reduce((sum, c) => sum + (c.after - c.before), 0);
        const stall = this.trainingStalls[p.id];
        this.trainingStalls[p.id] = { program, weeks: delta > 0 ? 0 : (stall && stall.program === program ? stall.weeks + 1 : 1) };
        // Blessure à l'entraînement cette semaine (Intense, jour par jour,
        // voir Team.applyTrainingIntensityDay).
        const injured = (this.injuryLog || []).some(x => x.training && String(x.playerId) === String(p.id) && x.at > nowMs - 7 * CONDITION_DAY_MS);
        slotReport.push({ playerId: p.id, name: p.name, program, intensity: intensityKey, changes, delta, efficiency, injured });
        const tip = trainingAdviceFor(this, p, program);
        if (tip) advice.push({ ...tip, name: p.name });
      } else {
        delete this.trainingStalls[p.id];
      }
      report[p.id] = {
        name: p.name, position: p.position, height: p.height, gains,
        program, inSlot: !!program, attendanceFactor, efficiency, mentalMult,
        secondsPlayed: weekSeconds,
      };
      // Retour utilisateur, 2026-09 : "quand la maj est passée, les
      // compteurs de temps de jeu sur la page entrainement doivent être
      // remis à 0 et on doit voir les effets du dernier entrainement".
      p.trainingSecondsPlayedByPosition = {};
    });
    // Bilan collectif de la semaine (jours de repos crédités depuis le
    // dernier lundi), repris par le bilan du lundi puis remis à zéro.
    const cw = this.collectiveWeek || { days: {}, tactics: {}, physicalPoints: 0 };
    const collective = {
      days: { tactique: (cw.days || {}).tactique || 0, recuperation: (cw.days || {}).recuperation || 0, physique: (cw.days || {}).physique || 0 },
      tactics: Object.values(cw.tactics || {}).map(t => ({ ...t })),
      physicalPoints: cw.physicalPoints || 0,
    };
    this.collectiveWeek = null;

    // Académie de jeunes : progression AUTOMATIQUE des jeunes déjà signés
    // (voir Team.growYouthPlayers/youthPlayers ci-dessus) — au MÊME tick que
    // l'entraînement de l'effectif pro ci-dessus (retour utilisateur : "un
    // jeune progresse chaque jour civil comme l'effectif pro"), mais sans
    // AUCUNE sélection de programme/poste (délibéré, pas de rapport avec
    // `skill`/`program` ci-dessus).
    this.growYouthPlayers();

    // Subvention de démarrage : voir STARTUP_SUBSIDY_AMOUNT/WEEKS plus
    // haut — un coup de pouce hebdomadaire le temps que le club génère ses
    // premières vraies recettes (billetterie, boutique) et ajuste ses prix.
    if (this.week <= STARTUP_SUBSIDY_WEEKS) {
      this.recordTransaction("Subvention de démarrage", STARTUP_SUBSIDY_AMOUNT);
    }

    // Le staff est payé chaque semaine, entraînement ou pas — son salaire
    // grimpe avec l'ancienneté (voir trainerWeeklySalary). Aucun effet sur
    // les matchs : uniquement une ligne de dépense + le bonus ci-dessus.
    let trainerSalaryPaid = 0;
    if (this.trainer) {
      trainerSalaryPaid = this.trainerSalary();
      this.recordTransaction("Salaire du staff", -trainerSalaryPaid);
      this.trainer.weeksEmployed += 1;
    }

    // Analyste vidéo : même rythme de paiement que l'entraîneur ci-dessus
    // (chaque semaine, séance vidéo utilisée ou pas cette semaine-là) — voir
    // Team.videoAnalyst/videoAnalystSalary. Ligne de dépense SÉPARÉE de
    // "Salaire du staff" (plutôt que cumulée dans la même ligne) pour que le
    // détail des transactions reste lisible sur QUEL membre du staff coûte
    // quoi.
    let videoAnalystSalaryPaid = 0;
    if (this.videoAnalyst) {
      videoAnalystSalaryPaid = this.videoAnalystSalary();
      this.recordTransaction("Salaire du staff (analyste vidéo)", -videoAnalystSalaryPaid);
      this.videoAnalyst.weeksEmployed += 1;
    }

    // Recruteur : même rythme de paiement que l'entraîneur/l'analyste vidéo
    // ci-dessus — voir Team.recruiter/recruiterSalary. Ligne de dépense
    // SÉPARÉE (même raison que videoAnalystSalaryPaid ci-dessus).
    let recruiterSalaryPaid = 0;
    if (this.recruiter) {
      recruiterSalaryPaid = this.recruiterSalary();
      this.recordTransaction("Salaire du staff (recruteur)", -recruiterSalaryPaid);
      this.recruiter.weeksEmployed += 1;
    }

    // Staff médical (voir MEDICAL_STAFF_ROLES) : même rythme de paiement,
    // une ligne de dépense par rôle.
    let doctorSalaryPaid = 0;
    let physioSalaryPaid = 0;
    if (this.doctor) {
      doctorSalaryPaid = this.doctorSalary();
      this.recordTransaction(MEDICAL_STAFF_ROLES.doctor.txLabel, -doctorSalaryPaid);
      this.doctor.weeksEmployed += 1;
    }
    if (this.physio) {
      physioSalaryPaid = this.physioSalary();
      this.recordTransaction(MEDICAL_STAFF_ROLES.physio.txLabel, -physioSalaryPaid);
      this.physio.weeksEmployed += 1;
    }
    let assistantCoachSalaryPaid = 0;
    if (this.assistantCoach) {
      assistantCoachSalaryPaid = this.assistantCoachSalary();
      this.recordTransaction("Salaire du staff (entraîneur adjoint)", -assistantCoachSalaryPaid);
      this.assistantCoach.weeksEmployed += 1;
    }

    // Masse salariale des joueurs : payée CHAQUE semaine (voir
    // salaryForOverall — grille salariale), que le club entraîne ou pas,
    // comme le salaire du staff. Le salaire de chaque joueur, lui, ne
    // change pas semaine après semaine : voir plus bas, recalculé
    // seulement au passage d'une saison.
    const playerPayroll = this.players.reduce((s, p) => s + p.salary, 0);
    if (playerPayroll > 0) {
      this.recordTransaction("Salaires des joueurs", -playerPayroll);
    }

    // Masse salariale de l'académie de jeunes : tarif FIXE par stagiaire
    // (YOUTH_TRAINEE_WEEKLY_SALARY), indépendant de ses attributs/potentiel
    // — ligne SÉPARÉE de "Salaires des joueurs" ci-dessus (des stagiaires
    // non salariés au marché, jamais mélangés dans la même ligne).
    const youthPayroll = (this.youthPlayers || []).length * YOUTH_TRAINEE_WEEKLY_SALARY;
    if (youthPayroll > 0) {
      this.recordTransaction("Salaires du centre de formation", -youthPayroll);
    }

    // Boutique des supporters : revenu hebdomadaire FIXE (indépendant de la
    // fréquentation des matchs), tant que le club la possède (voir
    // upgradeFanShop — investissement unique, revenu récurrent).
    let fanShopRevenue = 0;
    if (this.fanShopLevel > 0) {
      fanShopRevenue = Math.round(fanShopInfo(this.fanShopLevel).weeklyRevenue * prestigeShopMult(this.prestige));
      this.recordTransaction(`Recettes boutique des supporters (${fanShopInfo(this.fanShopLevel).name})`, fanShopRevenue);
    }

    // Droits TV : revenu hebdomadaire FIXE selon la division actuelle (voir
    // TV_RIGHTS_WEEKLY_BY_LEVEL plus haut), que le club entraîne ou pas —
    // comme le salaire du staff et la masse salariale.
    let tvRightsRevenue = 0;
    if (divisionLevel && TV_RIGHTS_WEEKLY_BY_LEVEL[divisionLevel] != null) {
      tvRightsRevenue = TV_RIGHTS_WEEKLY_BY_LEVEL[divisionLevel];
      this.recordTransaction(`Droits TV (${divisionInfo(divisionLevel).name})`, tvRightsRevenue);
    }

    // Produits dérivés (maillots, écharpes… : voir MERCH_WEEKLY_BY_LEVEL),
    // à part de la Boutique des supporters (investissement du club).
    const merchRevenue = divisionLevel ? merchandiseWeeklyRevenue(this, divisionLevel) : 0;
    if (merchRevenue > 0) this.recordTransaction(`Produits dérivés (${divisionInfo(divisionLevel).name})`, merchRevenue);

    // Sponsors : fixe de chaque contrat actif, même cadence que les droits
    // TV (voir collectSponsorIncome ; la prime par victoire et le bonus
    // d'objectif tombent ailleurs : applySponsorWinPrimes /
    // settleSponsorsAtSeasonEnd).
    const sponsorRevenue = collectSponsorIncome(this);

    // Station TV (voir CLUB_FACILITIES) : revenu hebdomadaire FIXE
    // supplémentaire, exactement comme la boutique des supporters ci-dessus
    // — la salle de musculation et l'espace bien-être n'agissent qu'EN MATCH
    // (voir MatchEngine.applyFatigue), rien à encaisser ici pour elles.
    let tvStationRevenue = 0;
    const tvStationLevel = (this.facilityLevels && this.facilityLevels.tvStation) || 0;
    if (tvStationLevel > 0) {
      const tvStationTier = facilityInfo("tvStation", tvStationLevel);
      tvStationRevenue = tvStationTier.weeklyRevenue;
      this.recordTransaction(`Recettes station TV (${tvStationTier.name})`, tvStationRevenue);
    }

    // Humeur des supporters : dérive lente et indépendante des résultats,
    // selon le confort tarifaire MOYEN des catégories de place — des prix
    // durablement trop élevés agacent les supporters semaine après semaine,
    // des prix confortables les rassérènent doucement (voir
    // ticketPriceComfortFactor / moraleForgiveness).
    const forgiveness = moraleForgiveness(this.fanMorale);
    const avgComfort = SEAT_CATEGORIES.reduce((sum, cat) =>
      sum + ticketPriceComfortFactor(this.ticketPrices[cat.key] / forgiveness, cat.key), 0) / SEAT_CATEGORIES.length;
    let moraleDrift = 0;
    if (avgComfort < 0.6) moraleDrift = -1.5;
    else if (avgComfort >= 0.95) moraleDrift = 0.5;
    if (moraleDrift !== 0) {
      this.recordMoraleEvent(moraleDrift > 0 ? "Prix des billets jugés raisonnables" : "Prix des billets jugés trop élevés", moraleDrift);
    }

    // Alerte de déficit économique + mise en vente forcée (voir
    // DEFICIT_ALERT_THRESHOLD/DEFICIT_GRACE_WEEKS plus haut) : suit le nombre
    // de semaines CONSÉCUTIVES où le budget (une fois toutes les
    // transactions de la semaine passées) reste sous le seuil, remis à zéro
    // dès qu'il repasse au-dessus. Au bout de DEFICIT_GRACE_WEEKS semaines
    // sans redressement, tout l'effectif est listé à 1 $ (voir
    // Player.forSale/salePrice, Team.sellPlayer) — une seule fois, pas
    // reconduit chaque semaine tant que ça reste non résolu.
    let deficitAlert = false;
    let forcedFireSale = false;
    if (this.budget < DEFICIT_ALERT_THRESHOLD) {
      this.deficitWeeks = (this.deficitWeeks || 0) + 1;
      deficitAlert = true;
      if (this.deficitWeeks >= DEFICIT_GRACE_WEEKS && this.players.some(p => !p.forSale)) {
        this.players.forEach(p => { p.forSale = true; p.salePrice = 1; });
        forcedFireSale = true;
      }
    } else {
      this.deficitWeeks = 0;
    }

    // Poste de carte : suit les caractéristiques de la semaine (retour
    // utilisateur 2026-09-30, voir syncCardPositions), AVANT l'éventuel
    // recalcul des salaires de fin de saison ci-dessous (fait, lui, au poste
    // de carte du moment).
    this.syncCardPositions();

    // Succès : séances d'entraînement individuel de la semaine (Première
    // séance) et semaine bouclée dans le vert (Gestionnaire prudent) — solde
    // de toutes les lignes de la semaine qui se termine (billetterie,
    // salaires, droits TV, boutique…), voir recordTransaction.
    if (this.isHuman) {
      // Rôles de jeu, phase 4 : un titulaire placé loin du rôle qu'il aime.
      this.applyRolePreferences(now);
      if (slotReport.length) achAdd(this, "trainings", slotReport.length, now);
      const ledgerRow = (this.financeLedger || {})[`${(this.seasonHistory || []).length + 1}:${this.week}`];
      const net = ledgerRow ? Object.values(ledgerRow).reduce((a, v) => a + (Number(v) || 0), 0) : 0;
      if (net > 0) achAdd(this, "posWeeks", 1, now);
    }

    this.week++;
    // Une année d'âge par SAISON (11 semaines), pas par 52 semaines
    // calendaires : voir SEASON_LENGTH_WEEKS et `opts.seasonEnd` plus haut.
    // La grille salariale est recalculée à la même cadence (voir
    // salaryForOverall) : un joueur qui a progressé (ou décliné) pendant la
    // saison écoulée voit son salaire ajusté à son NOUVEAU niveau pour la
    // saison suivante — pas chaque semaine, ce qui serait illisible.
    const seasonEnd = opts && typeof opts.seasonEnd === "boolean"
      ? opts.seasonEnd
      : this.week % SEASON_LENGTH_WEEKS === 0;
    let salaryChanges = null;
    if (seasonEnd) {
      // Garde-fou (retour utilisateur 2026-09-28 : "il faut une heure unique
      // pour tous, sinon on va avoir des joueurs qui ne vieillissent pas ou
      // qui vieillissent deux fois") : un joueur ne vieillit qu'UNE fois par
      // numéro de saison (opts.seasonNo, voir League.seasonNumber), même s'il
      // change de club ou de ligue pendant la bascule.
      const seasonNo = opts && typeof opts.seasonNo === "number" ? opts.seasonNo : null;
      const ageUp = p => {
        if (seasonNo != null) {
          if (p.lastAgedSeasonNo === seasonNo) return;
          p.lastAgedSeasonNo = seasonNo;
        }
        p.age += 1;
        recordRoleHistory(p, seasonNo);
      };
      this.players.forEach(ageUp);
      salaryChanges = this.recalculateSalaries();

      // Journal de matchs (voir Player.matchLog/recordMatchStatsForTeam) :
      // remis à zéro au passage de SAISON, comme l'âge/le salaire ci-dessus
      // — les stats affichées (Ligue/pages joueur) couvrent la saison EN
      // COURS, jamais un mélange de plusieurs saisons aux numéros de
      // journée qui se chevauchent.
      this.players.forEach(p => { p.matchLog = []; });

      // Académie de jeunes : les stagiaires vieillissent au même rythme que
      // l'effectif pro (une année d'âge par saison — voir plus haut).
      (this.youthPlayers || []).forEach(ageUp);

      // Décisions en attente laissées SANS RÉPONSE depuis la saison
      // précédente : auto-LIBÉRATION par défaut (retour utilisateur
      // implicite : ne jamais laisser une décision ignorée bloquer
      // indéfiniment une place de l'effectif jeunes) — appliquée AVANT de
      // détecter les nouveaux 18 ans ci-dessous, pour ne jamais confondre
      // une décision fraîche (cette saison) avec une décision déjà expirée
      // (la précédente, jamais tranchée).
      (this.pendingYouthDecisions || []).forEach(id => {
        const idx = this.youthPlayers.findIndex(p => p.id === id);
        if (idx !== -1) this.youthPlayers.splice(idx, 1);
      });
      this.pendingYouthDecisions = [];

      // Nouveaux 18 ans cette saison : flag pour décision manager explicite
      // (promotion ou libération, voir promoteYouthPlayer/releaseYouthPlayer)
      // plutôt qu'une auto-promotion ou auto-libération IMMÉDIATE — le
      // manager garde jusqu'à la saison SUIVANTE pour trancher (voir
      // l'auto-libération par défaut ci-dessus).
      this.youthPlayers.forEach(p => {
        if (p.age >= 18) this.pendingYouthDecisions.push(p.id);
      });
    }

    // Académie de jeunes : fait vivre la file de propositions PRIVÉE de ce
    // club (voir refreshYouthCandidates) — au même tick que le reste de ce
    // rapport. `now` explicite, JAMAIS de Date.now() implicite ici (même
    // convention que le reste du moteur) : sans `now` (appel historique,
    // voir tous les appels existants de trainWeek() dans les tests), aucune
    // proposition n'est générée — comportement inchangé pour tout appelant
    // qui ne passe pas encore ce second paramètre.
    if (now != null) this.refreshYouthCandidates(now);

    // Fil d'actualité du tableau de bord (voir le grand commentaire au-dessus
    // de FEED_CATEGORIES) : rafraîchi une fois par semaine, au même rythme
    // que le reste de ce rapport, uniquement pour une équipe humaine.
    // - checkThresholds : alertes staff vide / budget négatif / supporters
    //   ou alchimie hors zone confortable (déjà idempotent, voir sa doc).
    // - "de retour" (injury_healed) : contrairement à "injury" (émis au
    //   moment RÉEL de la blessure, voir MatchEngine.applyFatigue), la fin
    //   d'une blessure n'a pas de "tick" dédié dans le moteur (isCurrentlyInjured
    //   est recalculée à la demande, jamais annoncée) — détecté ici PAR DIFF :
    //   toute entrée `injury_<id>` encore présente dans le fil pour un joueur
    //   qui n'est plus courrament blessé signale une guérison.
    if (this.isHuman && this.feed) {
      const nowForFeed = now != null ? now : Date.now();
      this.feed.entries
        .filter(e => e.key && e.key.startsWith("injury_"))
        .forEach(e => {
          const playerId = e.key.slice("injury_".length);
          // p.id est numérique (voir uid()) mais playerId est une chaîne
          // extraite de la clé du fil — comparaison par String() des deux
          // côtés pour ne jamais manquer le joueur (sinon repli silencieux
          // sur "Le joueur" à chaque guérison, cf. dashboard_feed_test.js).
          const player = this.players.find(p => String(p.id) === playerId);
          const stillInjured = player && isCurrentlyInjured(player, nowForFeed);
          if (!stillInjured) {
            handleGameEvent(this.feed, {
              type: "injury_healed", week: this.week, playerId,
              playerName: player ? player.name : "Le joueur",
            }, { clubName: this.name });
          }
        });
      checkThresholds(this.feed, {
        week: this.week,
        budget: this.budget,
        supporters: this.fanMorale,
        chemistry: this.chemistry,
        staff: { coach: !!this.trainer, analyst: !!this.videoAnalyst, scout: !!this.recruiter },
      });
    }

    // Courbe de progression (Premium) : note globale de chaque joueur à la
    // fin de chaque semaine d'entraînement (PLAYER_PROGRESS_MAX dernières).
    this.players.forEach(p => {
      if (!Array.isArray(p.progressLog)) p.progressLog = [];
      p.progressLog.push({ week: this.week - 1, at: now != null ? now : null, ovr: Math.round(p.overall() * 10) / 10 });
      if (p.progressLog.length > PLAYER_PROGRESS_MAX) p.progressLog = p.progressLog.slice(-PLAYER_PROGRESS_MAX);
    });

    const result = {
      players: report, slots: slotReport, advice, collective, trainerSalaryPaid, videoAnalystSalaryPaid, recruiterSalaryPaid, doctorSalaryPaid, physioSalaryPaid, assistantCoachSalaryPaid,
      playerPayroll, youthPayroll, fanShopRevenue, tvRightsRevenue, merchRevenue, tvStationRevenue, moraleDrift, salaryChanges,
      fanMorale: this.fanMorale, budget: this.budget, trainerMult,
      deficitAlert, forcedFireSale, deficitWeeks: this.deficitWeeks,
    };
    // Conservé pour un réaffichage persistant (voir this.lastTrainingReport
    // au constructeur), ÉCRASE le rapport de la semaine précédente, un
    // seul conservé à la fois ("la derniere semaine", pas un historique
    // multi-semaines).
    this.lastTrainingReport = result;
    // Historique de la saison (Premium) : `week` = semaine qui vient de
    // s'achever (même numéro que le bilan « semaine N » de la page).
    const compactPlayers = {};
    Object.entries(report).forEach(([id, e]) => {
      if (e && (e.gains || []).length) compactPlayers[id] = { name: e.name, position: e.position, gains: e.gains.map(g => ({ ...g })) };
    });
    if (!Array.isArray(this.trainingHistory)) this.trainingHistory = [];
    this.trainingHistory.push({
      week: this.week - 1, at: now != null ? now : null, players: compactPlayers,
      // Bilan du lundi (entraînement v2, retour utilisateur 2026-10-01).
      slots: slotReport.map(sl => ({ ...sl, changes: sl.changes.map(c => ({ ...c })) })),
      advice: advice.map(a => ({ ...a })),
      collective: JSON.parse(JSON.stringify(collective)),
    });
    if (this.trainingHistory.length > TRAINING_HISTORY_MAX) this.trainingHistory = this.trainingHistory.slice(-TRAINING_HISTORY_MAX);
    return result;
  }

  // Réévalue le salaire de chaque joueur d'après son coefficient de niveau
  // ACTUEL (voir levelCoefficientFor/salaryForOverall) — appelé au passage
  // d'une saison (voir trainWeek) et disponible séparément pour un futur
  // marché des transferts (comparer le salaire "juste" d'un joueur avant une
  // offre). Renvoie le détail des changements pour l'UI (qui a eu une
  // augmentation/baisse et de combien).
  // Poste de carte qui suit les caractéristiques (voir cardPositionChangeFor
  // et POSITION_CHANGE_MARGIN) : joueurs pro ET stagiaires de l'académie.
  // Club humain : une nouvelle dans le fil par joueur pro concerné (jamais
  // pour l'IA ; `opts.silent` pour la couper). Ne touche NI au salaire NI à
  // la feuille de match. Renvoie la liste des changements.
  syncCardPositions(opts = null) {
    const changes = [];
    const apply = (p, isPro) => {
      const c = cardPositionChangeFor(p);
      if (!c) return;
      p.previousCardPosition = c.from;
      p.position = c.to;
      changes.push(Object.assign({ playerId: p.id, name: p.name, pro: isPro }, c));
    };
    this.players.forEach(p => apply(p, true));
    (this.youthPlayers || []).forEach(p => apply(p, false));
    if (this.isHuman && this.feed && !(opts && opts.silent)) {
      changes.filter(c => c.pro).forEach(c => handleGameEvent(this.feed, {
        type: "position_change", week: this.week, playerId: c.playerId, playerName: c.name,
        from: c.from, to: c.to, ratingFrom: Math.round(c.ratingFrom), ratingTo: Math.round(c.ratingTo),
      }, { clubName: this.name }));
    }
    return changes;
  }

  // Contrats (demande du 2026-10-01) : un joueur sous contrat garde son
  // salaire ; seul un nouveau salaire déjà signé (prolongation, augmentation
  // acceptée : `nextSalary`) s'applique ici. Sans contrat : grille salariale.
  recalculateSalaries() {
    return this.players.map(p => {
      const before = p.salary;
      const level = levelCoefficientFor(p.attrs, p.position);
      p.effectivePosition = level.position;
      if (typeof p.nextSalary === "number") {
        p.salary = p.nextSalary;
        p.nextSalary = null;
      } else if (typeof p.contractUntilSeason !== "number") {
        p.salary = salaryForOverall(level.coefficient);
      }
      return { name: p.name, before, after: p.salary };
    }).filter(c => c.before !== c.after);
  }

  // Prolongation de contrat (demande du 2026-10-01) : pendant la DERNIÈRE
  // saison du contrat, offre de `terms.seasons` saisons (1 à 5, comptées à
  // partir de la saison suivante) à `terms.salary` $/sem, entre le salaire
  // demandé -10 % et le salaire demandé. Refus : motivation un peu en baisse,
  // nouvel essai possible la semaine de jeu suivante. Acceptée : nouveau
  // salaire à partir de la saison suivante (`nextSalary`). `season` = saison
  // de contrat courante (League.contractSeason). Renvoie { ok, accepted,
  // asked, salary, untilSeason } ou { ok: false, reason } — "not-found",
  // "not-last-season", "already-offered", "invalid-seasons", "invalid-salary".
  offerContractExtension(playerId, terms, season, now = Date.now(), rng = Math.random) {
    const p = this.players.find(pl => pl.id === playerId);
    if (!p) return { ok: false, reason: "not-found" };
    if (!isLastContractSeason(p, season)) return { ok: false, reason: "not-last-season" };
    if (p.lastContractOfferWeek === this.week) return { ok: false, reason: "already-offered" };
    const seasons = normalizeContractSeasons(terms && terms.seasons, null);
    if (seasons == null) return { ok: false, reason: "invalid-seasons" };
    const asked = askedSalary(p);
    const floor = contractExtensionFloor(p, asked);
    const salary = Math.round(Number(terms && terms.salary));
    if (!Number.isFinite(salary) || salary < floor || salary > asked) return { ok: false, reason: "invalid-salary", asked, floor };
    const accepted = rng() < contractAcceptanceChance(asked, salary, p.form, this.prestige);
    if (!accepted) {
      // Refus (rééquilibrage 2026-10-02) : motivation en baisse selon l'écart
      // (voir contractRefusalMoraleMalus), demande +3 %, et plus de marge
      // après CONTRACT_FIRM_AFTER_REFUSALS refus (voir contractExtensionFloor).
      const moraleLoss = contractRefusalMoraleMalus(asked, salary);
      p.lastContractOfferWeek = this.week;
      p.contractRefusals = (p.contractRefusals || 0) + 1;
      p.form = clamp(Math.round((p.form || 0) - moraleLoss), 0, 100);
      return { ok: true, accepted: false, asked, floor, moraleLoss, refusals: p.contractRefusals };
    }
    p.contractUntilSeason = season + seasons;
    p.nextSalary = salary;
    p.salaryGrid = 2;
    p.lastContractOfferWeek = null;
    p.contractRefusals = 0;
    p.raiseRequest = null;
    if (this.feed) removeByKey(this.feed, `contract_ext_${p.id}`);
    return { ok: true, accepted: true, asked, floor, salary, untilSeason: p.contractUntilSeason };
  }

  // Demande d'augmentation de mi-saison (voir League.weeklyContractsTick) :
  // acceptée = salaire demandé à partir de la saison suivante, durée du
  // contrat inchangée ; refusée (ou sans réponse) = motivation en baisse,
  // jamais de demande de transfert. Contre-offre (retour 2026-10-01 :
  // « accepter au prix, faire une contre-offre, refuser ») : `counter` entre
  // le salaire demandé -10 % et le salaire demandé, même tirage qu'une
  // prolongation ; refusée = comme un refus. Renvoie { ok, accepted,
  // salary?, countered? } ou { ok: false, reason: "not-found" | "no-request"
  // | "invalid-salary" }.
  respondToRaiseRequest(playerId, accept, counter = null, rng = Math.random) {
    const p = this.players.find(pl => pl.id === playerId);
    if (!p) return { ok: false, reason: "not-found" };
    if (!p.raiseRequest) return { ok: false, reason: "no-request" };
    const asked = p.raiseRequest.asked;
    let countered = false;
    if (counter != null) {
      const salary = Math.round(Number(counter));
      const floor = contractOfferFloor(asked);
      if (!Number.isFinite(salary) || salary < floor || salary > asked) return { ok: false, reason: "invalid-salary", asked, floor };
      countered = true;
      p.raiseRequest = null;
      if (this.feed) removeByKey(this.feed, `contract_raise_${p.id}`);
      if (rng() < contractAcceptanceChance(asked, salary, p.form, this.prestige)) {
        p.nextSalary = salary;
        return { ok: true, accepted: true, salary, countered };
      }
      p.form = clamp(Math.round((p.form || 0) - CONTRACT_RAISE_REFUSED_MORALE_MALUS), 0, 100);
      return { ok: true, accepted: false, countered };
    }
    p.raiseRequest = null;
    if (this.feed) removeByKey(this.feed, `contract_raise_${p.id}`);
    if (accept) {
      p.nextSalary = asked;
      return { ok: true, accepted: true, salary: asked };
    }
    p.form = clamp(Math.round((p.form || 0) - CONTRACT_RAISE_REFUSED_MORALE_MALUS), 0, 100);
    return { ok: true, accepted: false };
  }

  // Moyenne du "overall" (voir Player.overall) sur l'ensemble de l'effectif
  // — sert de jauge de niveau global pour comparer deux équipes (voir
  // Team.trainWeekCPU / League.trainCpuTeams).
  averageOverall() {
    if (!this.players.length) return 0;
    return this.players.reduce((s, p) => s + p.overall(), 0) / this.players.length;
  }

  // Progression hebdomadaire pour une équipe adverse (CPU). `overallGap`
  // (moyenne du club du joueur moins moyenne de CETTE équipe adverse — voir
  // League.trainCpuTeams) pilote un RATTRAPAGE DIRECT : au-delà d'un petit
  // écart tolérable (6 points de overall), l'équipe comble tout de suite
  // 35% de l'écart restant (attributs ET potentiel, à l'échelle, pour ne
  // pas juste retarder le mur du potentiel). Un entraînement hebdomadaire
  // "classique" (voir trainWeek) est plafonné par le potentiel FIXÉ à la
  // génération de chaque joueur adverse : beaucoup trop lent pour refermer
  // un écart déjà creusé (plusieurs saisons entières), que ce soit parce
  // qu'une partie en cours a pris du retard avant ce mécanisme, ou
  // simplement parce que le hasard de la génération a fait démarrer les
  // adversaires en dessous du club du joueur — d'où ce rattrapage direct,
  // en plus (pas à la place) d'une petite progression hebdomadaire pour
  // garder un peu de texture semaine après semaine. Ne joue JAMAIS à la
  // baisse : une équipe adverse déjà au niveau ou devant n'est jamais
  // affaiblie, seulement laissée à son rendement hebdomadaire normal.
  trainWeekCPU(overallGap = 0, implicitCoachLevel = CPU_IMPLICIT_COACH_LEVEL) {
    if (overallGap > 6) {
      const currentAvg = this.averageOverall();
      const targetAvg = currentAvg + overallGap * 0.35;
      const scale = targetAvg / Math.max(currentAvg, 1);
      this.players.forEach(p => {
        ATTRS.forEach(a => { p.attrs[a] = clamp(Math.round(p.attrs[a] * scale), 1, 99); });
        p.potential = clamp(Math.round(p.potential * scale), 1, 99);
      });
    }

    // Entraînement v2 (retour utilisateur 2026-10-01) : l'IA remplit ses
    // plans individuels toute seule (jeunes à fort potentiel, compétence clé
    // la plus faible), avec son entraîneur s'il en a un, sinon un entraîneur
    // « implicite » (CPU_IMPLICIT_COACH_LEVEL) ; le travail de fond sur les
    // caractéristiques du poste est conservé mais allégé
    // (CPU_BACKGROUND_TRAINING_WEIGHT) pour garder le même niveau moyen
    // qu'avant (calibré par simulation). Intensité normale, pas de parrainage.
    const coach = this.trainer || { level: implicitCoachLevel };
    this.trainingSlots = cpuTrainingSlots(this, trainingSlotsForTrainer(coach));
    const slotByPlayer = new Map(this.trainingSlots.map(sl => [String(sl.playerId), sl.program]));
    const ceilingBonus = trainerCeilingBonus(coach);
    this.players.forEach(p => {
      const weekSeconds = playerWeekSeconds(p);
      const program = slotByPlayer.get(String(p.id)) || null;
      const attrWeights = {};
      (POSITION_STRONG_ATTRS[p.position] || []).forEach(a => { attrWeights[a] = CPU_BACKGROUND_TRAINING_WEIGHT; });
      let synergyAttrs = null;
      let ceilingWeights = null;
      let mult = 1;
      if (program) {
        const w = slotTrainingWeightsFor(p, program);
        Object.entries(w.attrWeights).forEach(([a, v]) => { attrWeights[a] = Math.max(attrWeights[a] || 0, v); });
        synergyAttrs = new Set([...w.synergyAttrs].filter(a => !(POSITION_STRONG_ATTRS[p.position] || []).includes(a)));
        ceilingWeights = w.ceilingWeights;
        mult = trainerRateMultiplier(coach);
      }
      p.trainWeek(attrWeights, mult, synergyAttrs, { ceilingBonus: program ? ceilingBonus : 0, ceilingWeights, mentalMult: mentalExperienceMult(weekSeconds), roomDivisor: LEGACY_TRAINING_ROOM_DIVISOR });
      p.trainingSecondsPlayedByPosition = {};
    });
    // Poste de carte (voir syncCardPositions) : l'IA suit la même règle,
    // sans nouvelle.
    this.syncCardPositions();
  }

  // ---------------------------------------------------------------------
  // Feuille de match : qui est titulaire (1 par poste), remplaçant (0 à N
  // postes chacun — un même remplaçant peut couvrir plusieurs postes, mais
  // jamais être titulaire à plusieurs postes en même temps) et réserviste
  // (ni titulaire ni remplaçant nulle part, ne joue pas ce match).
  //   lineup.starters[poste] = id du joueur titulaire à ce poste (ou null)
  //   lineup.backupPositions[id] = [poste, poste, ...] postes couverts par
  //     ce joueur EN TANT QUE remplaçant (absent/vide = pas remplaçant)
  // ---------------------------------------------------------------------
  autoAssignLineup() {
    const starters = {};
    const backupPositions = {};
    POSITIONS.forEach(pos => {
      const atPos = this.players.filter(p => p.position === pos).sort((a, b) => b.overall() - a.overall());
      starters[pos] = atPos[0] ? atPos[0].id : null;
      atPos.slice(1).forEach(p => { backupPositions[p.id] = [pos]; });
    });
    // Poste sans joueur de ce poste de carte (les postes de carte suivent
    // les caractéristiques, retour utilisateur 2026-09-30 : un effectif peut
    // se retrouver avec 4 Arrières et 2 Meneurs) : le mieux noté À CE POSTE
    // (positionRating) parmi ceux qui ne sont titulaires nulle part.
    POSITIONS.forEach(pos => {
      if (starters[pos] != null) return;
      const taken = new Set(Object.values(starters).filter(id => id != null));
      const pick = this.players.filter(p => !taken.has(p.id))
        .sort((a, b) => positionRating(b, pos) - positionRating(a, pos))[0];
      if (!pick) return;
      starters[pos] = pick.id;
      delete backupPositions[pick.id];
    });
    this.lineup = { starters, backupPositions };
  }

  // ---------------------------------------------------------------------
  // Temps de jeu cible par poste (retour utilisateur 2026-09-26 : "choisir
  // les temps de jeu des joueurs [...] meneur c'est 30 min, remplaçant 10
  // [...] un temps idéal à atteindre, qui en cas de blessure ou fautes,
  // devra être modifié automatiquement par le moteur", "il faut aussi
  // pouvoir donner des minutes au réserviste", "on mettra les minutes par
  // poste").
  //   lineup.minutes[poste] = { [id]: minutes } — facultatif : un poste sans
  //   entrée garde la rotation automatique du moteur. Seuls comptent le
  //   titulaire du poste et les remplaçants qui le couvrent (un réserviste
  //   à qui l'on donne des minutes est d'abord ajouté comme remplaçant du
  //   poste). Total visé : 40 min ; le moteur ramène de toute façon les
  //   valeurs à des proportions (voir slotMinuteShares).
  // ---------------------------------------------------------------------
  slotPlayerIds(pos) {
    const ids = [];
    const s = this.lineup.starters[pos];
    if (s != null) ids.push(s);
    // Remplaçants du poste : le premier est "le" remplaçant, les suivants
    // des réservistes (carte Temps de jeu, répartition proposée par
    // defaultSlotMinutes). Quand des minutes sont réglées sur le poste,
    // c'est celui qui en a le plus qui est le remplaçant (retour utilisateur
    // 2026-09-26 : "si je mets plus de minutes au réserviste, il doit passer
    // automatiquement remplaçant") ; à égalité, ou sans réglage, du mieux
    // noté au moins bien noté.
    const mins = (this.lineup.minutes && this.lineup.minutes[pos]) || null;
    const minutesOf = p => (mins ? Number(mins[p.id]) || 0 : 0);
    this.players
      .filter(p => p.id !== s && (this.lineup.backupPositions[p.id] || []).includes(pos))
      .sort((a, b) => (minutesOf(b) - minutesOf(a)) || (b.overall() - a.overall()))
      .forEach(p => ids.push(p.id));
    return ids;
  }

  // Répartition proposée quand on active le réglage d'un poste (retour
  // utilisateur 2026-09-26 : "en automatique, pars plutôt sur un temps de
  // jeu plus faible pour le réserviste") : 28 min au titulaire, 12 au
  // remplaçant seul ; avec plusieurs remplaçants, 8 au premier (le mieux
  // noté, voir slotPlayerIds) et 4 à partager entre les réservistes. 40 au
  // titulaire seul.
  defaultSlotMinutes(pos) {
    const ids = this.slotPlayerIds(pos);
    const starter = this.lineup.starters[pos];
    const backups = ids.filter(id => id !== starter);
    const out = {};
    if (starter != null) out[starter] = backups.length ? 28 : 40;
    const share = (list, total) => list.forEach((id, i) => {
      const base = Math.floor(total / list.length);
      out[id] = base + (i < total - base * list.length ? 1 : 0);
    });
    if (starter == null) share(backups, 40);
    else if (backups.length === 1) out[backups[0]] = 12;
    else if (backups.length > 1) { out[backups[0]] = 8; share(backups.slice(1), 4); }
    return out;
  }

  enableSlotMinutes(pos) {
    if (!this.lineup.minutes) this.lineup.minutes = {};
    this.lineup.minutes[pos] = this.defaultSlotMinutes(pos);
  }

  clearSlotMinutes(pos) {
    if (!this.lineup.minutes) return;
    delete this.lineup.minutes[pos];
    if (!Object.keys(this.lineup.minutes).length) delete this.lineup.minutes;
  }

  setSlotMinutes(pos, playerId, minutes) {
    if (!this.lineup.minutes || !this.lineup.minutes[pos]) return;
    if (!this.slotPlayerIds(pos).includes(playerId)) return;
    const m = Math.round(Number(minutes));
    // Plafond : 40 min au total sur le poste (retour utilisateur 2026-09-26 :
    // "il faut bloquer les minutes pour ne pas pouvoir mettre plus que 40").
    this.lineup.minutes[pos][playerId] = Number.isFinite(m) ? clamp(m, 0, this.slotMinutesRoom(pos, playerId)) : 0;
  }

  // Minutes maximales que `playerId` peut recevoir sur `pos` : 40 moins ce
  // qui est déjà donné aux autres joueurs du poste.
  slotMinutesRoom(pos, playerId) {
    const m = (this.lineup.minutes && this.lineup.minutes[pos]) || {};
    let others = 0;
    Object.entries(m).forEach(([id, v]) => { if (String(id) !== String(playerId)) others += Number(v) || 0; });
    return Math.max(0, 40 - others);
  }

  hasSlotMinutes(pos) {
    return !!(this.lineup.minutes && this.lineup.minutes[pos]);
  }

  // Proportions de temps de jeu par joueur pour ce poste (somme = 1), ou
  // null si le poste est en rotation automatique (ou si le réglage ne
  // désigne plus personne de valide : joueur vendu, retiré du poste...).
  slotMinuteShares(pos) {
    if (!this.hasSlotMinutes(pos)) return null;
    const raw = this.lineup.minutes[pos];
    const shares = {};
    let total = 0;
    this.slotPlayerIds(pos).forEach(id => {
      const v = Number(raw[id]) || 0;
      if (v > 0) { shares[id] = v; total += v; }
    });
    if (total <= 0) return null;
    Object.keys(shares).forEach(id => { shares[id] /= total; });
    return shares;
  }

  // ---------------------------------------------------------------------
  // Convocation (retour utilisateur 2026-09-26 : "on pourrait ajouter un
  // endroit où choisir les joueurs qu'on convoque au match", 12 au maximum,
  // "un convoqué sans rôle dépanne si besoin").
  //   lineup.convoked = [id, ...] — facultatif. Absent : convocation par
  //   défaut (titulaires, puis remplaçants du mieux noté, puis le reste,
  //   dans la limite de 12). Un joueur non convoqué ne joue jamais ; un
  //   convoqué sans rôle n'entre qu'en dépannage (blessure, 5 fautes,
  //   exclusion sans remplaçant disponible, voir emergencyForSlot).
  // ---------------------------------------------------------------------
  convokedIds() {
    // Aussi appelée sur un plan préparé à l'avance (objet { lineup } sans
    // effectif) : la liste enregistrée est alors rendue telle quelle.
    if (!Array.isArray(this.players)) return Array.isArray(this.lineup.convoked) ? [...this.lineup.convoked] : [];
    const valid = new Set(this.players.map(p => p.id));
    if (Array.isArray(this.lineup.convoked)) return this.lineup.convoked.filter(id => valid.has(id));
    const out = [];
    const push = id => { if (id != null && valid.has(id) && !out.includes(id) && out.length < CONVOCATION_MAX) out.push(id); };
    // Ordre de priorité : titulaires, joueurs à qui des minutes sont
    // données (carte Temps de jeu), le premier remplaçant de chaque poste,
    // les autres remplaçants du mieux noté, puis le reste de l'effectif.
    POSITIONS.forEach(pos => push(this.lineup.starters[pos]));
    if (this.lineup.minutes) Object.values(this.lineup.minutes).forEach(m => {
      Object.entries(m).filter(([, v]) => Number(v) > 0).forEach(([id]) => { const p = this.players.find(x => String(x.id) === String(id)); if (p) push(p.id); });
    });
    POSITIONS.forEach(pos => push(Team.prototype.slotPlayerIds.call(this, pos).find(id => id !== this.lineup.starters[pos])));
    this.players.filter(p => (this.lineup.backupPositions[p.id] || []).length)
      .sort((a, b) => b.overall() - a.overall()).forEach(p => push(p.id));
    this.players.slice().sort((a, b) => b.overall() - a.overall()).forEach(p => push(p.id));
    return out;
  }

  isConvoked(playerId) {
    return this.convokedIds().includes(playerId);
  }

  // Convoque / retire de la convocation. Retirer un joueur lui enlève aussi
  // ses rôles (titulaire, remplaçant, minutes) : il est en tribune.
  setConvoked(playerId, on) {
    const list = Team.prototype.convokedIds.call(this);
    if (on) {
      if (!list.includes(playerId) && list.length < CONVOCATION_MAX) list.push(playerId);
    } else {
      const i = list.indexOf(playerId);
      if (i >= 0) list.splice(i, 1);
      POSITIONS.forEach(pos => { if (this.lineup.starters[pos] === playerId) this.lineup.starters[pos] = null; });
      delete this.lineup.backupPositions[playerId];
      if (this.lineup.minutes) Object.values(this.lineup.minutes).forEach(m => { delete m[playerId]; });
    }
    this.lineup.convoked = list;
  }

  // Dépannage en match : un convoqué disponible, du même poste naturel
  // d'abord, puis le mieux noté.
  emergencyForSlot(pos) {
    const pool = this.players.filter(p =>
      p.convokedThisMatch === true && !p.onCourt && !p.disqualified && !p.injured && !p.matchInjuryLocked
    );
    pool.sort((a, b) => ((b.position === pos) - (a.position === pos)) || (b.overall() - a.overall()));
    return pool[0] || null;
  }

  // Poste titulaire d'un joueur (ou null s'il n'est pas titulaire).
  starterPosition(playerId) {
    return POSITIONS.find(pos => this.lineup.starters[pos] === playerId) || null;
  }

  // Fixe le titulaire d'un poste. Si un autre joueur était déjà titulaire à
  // ce poste, il redevient réserviste (retiré de starters ET de backupPositions,
  // pour ne jamais avoir un joueur titulaire ET remplaçant en même temps).
  // Retire aussi le nouveau titulaire de tous ses postes de remplaçant.
  setStarter(pos, playerId) {
    if (!Array.isArray(this.lineup.convoked) && Array.isArray(this.players)) this.lineup.convoked = Team.prototype.convokedIds.call(this);
    if (playerId && Array.isArray(this.lineup.convoked) && !this.lineup.convoked.includes(playerId)) Team.prototype.setConvoked.call(this, playerId, true);
    // Temps de jeu cible (voir slotMinuteShares) : le nouveau titulaire
    // reprend les minutes de l'ancien à ce poste ; ses éventuelles minutes
    // de remplaçant ailleurs disparaissent avec ses postes de remplaçant.
    const mins = this.lineup.minutes;
    const previous = this.lineup.starters[pos];
    if (mins && playerId) {
      Object.keys(mins).forEach(p => {
        if (p !== pos) {
          delete mins[p][playerId];
          if (this.lineup.starters[p] === playerId) delete mins[p];
        }
      });
      if (mins[pos] && previous != null && previous !== playerId) {
        if (mins[pos][playerId] == null) mins[pos][playerId] = mins[pos][previous] || 0;
        delete mins[pos][previous];
      }
    }
    if (playerId) {
      // Un joueur ne peut être titulaire qu'à UN SEUL poste à la fois : s'il
      // était déjà titulaire ailleurs, ce poste-là redevient vacant (à
      // réassigner) plutôt que d'avoir le même joueur titulaire à deux
      // postes en même temps.
      POSITIONS.forEach(p => { if (p !== pos && this.lineup.starters[p] === playerId) this.lineup.starters[p] = null; });
      delete this.lineup.backupPositions[playerId];
    }
    this.lineup.starters[pos] = playerId || null;
  }

  // Nombre de remplaçants (remplaçant + réservistes) couvrant `pos`, hors
  // titulaire du poste.
  backupCountAt(pos) {
    const s = this.lineup.starters[pos];
    return Object.entries(this.lineup.backupPositions || {})
      .filter(([id, list]) => String(id) !== String(s) && (list || []).includes(pos)).length;
  }

  // Coche/décoche un poste de remplaçant pour un joueur. Un joueur titulaire
  // quelque part ne peut pas devenir remplaçant (il faut d'abord le retirer
  // du poste de titulaire) — no-op silencieux dans ce cas.
  toggleBackupPosition(playerId, pos, on) {
    if (!Array.isArray(this.lineup.convoked) && Array.isArray(this.players)) this.lineup.convoked = Team.prototype.convokedIds.call(this);
    if (this.starterPosition(playerId)) return;
    const list = this.lineup.backupPositions[playerId] || [];
    const has = list.includes(pos);
    // 3 joueurs max par poste : titulaire + remplaçant + réserviste (retour
    // utilisateur 2026-09-27 : "limite à 3 joueurs par poste (titu,
    // remplacant, reserviste)") — ajout refusé en silence au-delà. Les
    // anciennes sauvegardes qui en ont plus restent jouables telles quelles.
    if (on && !has && Team.prototype.backupCountAt.call(this, pos) >= MAX_BACKUPS_PER_POSITION) return;
    if (on && !has) this.lineup.backupPositions[playerId] = [...list, pos];
    if (on && Array.isArray(this.lineup.convoked) && !this.lineup.convoked.includes(playerId)) Team.prototype.setConvoked.call(this, playerId, true);
    if (this.lineup.minutes && this.lineup.minutes[pos]) {
      if (on && this.lineup.minutes[pos][playerId] == null) this.lineup.minutes[pos][playerId] = 0;
      if (!on) delete this.lineup.minutes[pos][playerId];
    }
    if (!on && has) {
      const next = list.filter(p => p !== pos);
      if (next.length) this.lineup.backupPositions[playerId] = next;
      else delete this.lineup.backupPositions[playerId];
    }
  }

  // ---------------------------------------------------------------------
  // Planification des ordres à l'avance (voir this.plannedTactics dans le
  // constructeur) : préparer une journée FUTURE sans toucher aux ordres
  // "en direct" (ceux lus au moment de résoudre la TOUTE PROCHAINE
  // journée), à la BuzzerBeater.
  // ---------------------------------------------------------------------

  // Instantané indépendant (deep clone) des ordres EN DIRECT actuels —
  // jamais de référence partagée avec offensivePriorities/lineup en cours,
  // sinon modifier les ordres du jour changerait silencieusement un plan
  // déjà sauvegardé (et vice-versa).
  snapshotTactics() {
    return {
      offensivePriorities: [...this.offensivePriorities],
      defense: this.defense,
      rhythm: this.rhythm,
      // Tactique confirmée — voir Team.constructor. Copie des valeurs EN
      // DIRECT actuelles (jamais de référence partagée, notamment pour le
      // tableau watchAssignments).
      tacticalTier: this.tacticalTier,
      screenDefense: this.screenDefense,
      helpDefense: this.helpDefense,
      watchAssignments: this.watchAssignments.map(a => ({ ...a })),
      postDefense: this.postDefense,
      closeoutStyle: this.closeoutStyle,
      offRebStyle: this.offRebStyle,
      endgameManagement: this.endgameManagement,
      lineup: {
      starters: { ...this.lineup.starters },
      backupPositions: Object.fromEntries(
        Object.entries(this.lineup.backupPositions).map(([id, positions]) => [id, [...positions]])
      ),
      ...(this.lineup.minutes ? { minutes: Object.fromEntries(Object.entries(this.lineup.minutes).map(([pos, m]) => [pos, { ...m }])) } : {}),
      ...(Array.isArray(this.lineup.convoked) ? { convoked: [...this.lineup.convoked] } : {}),
    },
    };
  }

  // Le plan déjà préparé pour `round`/`competition` (voir planKey), ou (à
  // défaut) un instantané des ordres en direct actuels — simple lecture, ne
  // crée PAS d'entrée dans plannedTactics (utilisé côté navigateur pour
  // préremplir l'écran "Ordres" d'une journée future pas encore préparée,
  // avec les réglages actuels comme point de départ raisonnable).
  // `competition` omis = "championship" (comportement historique).
  getPlanForRound(round, competition) {
    return this.plannedTactics[planKey(round, competition)] || this.snapshotTactics();
  }

  // Enregistre/complète le plan de `round`/`competition` : la première
  // modification pour cette journée part des ordres en direct actuels
  // (snapshotTactics), les suivantes fusionnent juste le(s) champ(s)
  // modifié(s) (patch partiel, ex. {defense: "Zone"}) par-dessus le plan
  // déjà en place.
  stagePlanForRound(round, patch, competition) {
    const key = planKey(round, competition);
    this.plannedTactics[key] = Object.assign(this.plannedTactics[key] || this.snapshotTactics(), patch);
    return this.plannedTactics[key];
  }

  // Existence pure d'un plan préparé pour `round`/`competition` (contrairement
  // à getPlanForRound, qui retombe toujours sur un instantané des ordres en
  // direct si rien n'est préparé) — utilisé côté navigateur pour
  // l'indicateur "(préparé) ●" sans avoir à connaître le format de la clé
  // composite (voir planKey) depuis l'UI.
  hasPlanForRound(round, competition) {
    return !!this.plannedTactics[planKey(round, competition)];
  }

  // Retire le plan préparé pour `round`/`competition` (ex. "revenir aux
  // ordres actuels") — sans effet sur les ordres en direct ni sur les
  // autres journées/tours.
  clearPlanForRound(round, competition) {
    delete this.plannedTactics[planKey(round, competition)];
  }

  // Point d'entrée appelé juste AVANT de simuler `round`/`competition` (voir
  // server/liveMatch.js finalizeRound/ensureLiveMatchStarted côté
  // championnat, finalizeCupRound/ensureCupLiveMatchStarted côté Coupe) : si
  // un plan a été préparé pour cette journée, il
  // devient les ordres EN DIRECT (deep clone, jamais de référence
  // partagée) puis le plan est "consommé" (supprimé de plannedTactics) —
  // une fois utilisé pour résoudre son match, il n'est plus une
  // "préparation à l'avance", il EST l'état courant, exactement comme si
  // le manager l'avait réglé directement cette semaine-là. Sans plan
  // préparé pour cette journée : no-op complet, les ordres en direct ne
  // sont pas touchés (comportement inchangé pour qui ne planifie jamais).
  applyPlannedTacticsForRound(round, competition) {
    const key = planKey(round, competition);
    const plan = this.plannedTactics[key];
    if (!plan) return;
    this.offensivePriorities = [...plan.offensivePriorities];
    this.defense = plan.defense;
    this.rhythm = plan.rhythm;
    // Tactique confirmée — voir Team.constructor. `?? <standard>` de secours
    // pour un plan préparé AVANT cette fonctionnalité (plannedTactics stocké
    // dans une sauvegarde plus ancienne) : sans ce filet, ces champs
    // resteraient `undefined` après application du plan, ce qui casserait la
    // règle "rien de fait => standard" pour un coach qui avait juste préparé
    // sa journée à l'avance avant la sortie de cette fonctionnalité.
    this.tacticalTier = plan.tacticalTier ?? "débutant";
    this.screenDefense = plan.screenDefense ?? "Aucune consigne";
    this.helpDefense = plan.helpDefense ?? "Moyenne";
    this.watchAssignments = (plan.watchAssignments ?? []).map(a => ({ ...a }));
    this.postDefense = plan.postDefense ?? "Classique";
    this.closeoutStyle = plan.closeoutStyle ?? "Contrôlé";
    this.offRebStyle = plan.offRebStyle ?? "Normal";
    this.endgameManagement = plan.endgameManagement ?? "Standard";
    this.lineup = {
      starters: { ...plan.lineup.starters },
      backupPositions: Object.fromEntries(
        Object.entries(plan.lineup.backupPositions).map(([id, positions]) => [id, [...positions]])
      ),
      ...(plan.lineup.minutes ? { minutes: Object.fromEntries(Object.entries(plan.lineup.minutes).map(([pos, m]) => [pos, { ...m }])) } : {}),
      ...(Array.isArray(plan.lineup.convoked) ? { convoked: [...plan.lineup.convoked] } : {}),
    };
    // Plan écrit avant le départ d'un joueur (ancienne sauvegarde) : réparé.
    this.repairLineupDepartures(this.lineup);
    delete this.plannedTactics[key];
  }

  // Joue `fn` (simulation d'un match de Coupe / Coupe nationale) avec le
  // plan préparé pour CE match, puis RESTAURE les ordres en direct (retour
  // utilisateur 2026-10-05 : « chaque match doit avoir ses propres ordres
  // […] une modification ne doit jamais modifier les ordres déjà définis
  // d'un autre match »). Avant ce correctif, applyPlannedTacticsForRound
  // remplaçait pour de bon les ordres en direct — qui sont ceux du PROCHAIN
  // MATCH DE CHAMPIONNAT, déjà validés : le plan de Coupe débordait sur le
  // championnat. Le championnat, lui, garde applyPlannedTacticsForRound (ses
  // ordres en direct SONT ceux du match joué). Ordres réellement joués notés
  // dans matchOrdersUsed pour l'historique (« Partir de », voir
  // recordOrdersHistory), puisque le direct est fini bien après la
  // restauration. Sans plan pour ce match : ordres en direct, rien à
  // restaurer.
  runWithMatchPlan(round, competition, fn) {
    const key = planKey(round, competition);
    if (!this.plannedTactics || !this.plannedTactics[key]) return fn();
    const saved = JSON.parse(JSON.stringify({
      offensivePriorities: this.offensivePriorities, defense: this.defense, rhythm: this.rhythm,
      tacticalTier: this.tacticalTier, screenDefense: this.screenDefense, helpDefense: this.helpDefense,
      watchAssignments: this.watchAssignments, postDefense: this.postDefense, closeoutStyle: this.closeoutStyle,
      offRebStyle: this.offRebStyle, endgameManagement: this.endgameManagement, lineup: this.lineup,
    }));
    this.applyPlannedTacticsForRound(round, competition);
    this.matchOrdersUsed = this.matchOrdersUsed && typeof this.matchOrdersUsed === "object" ? this.matchOrdersUsed : {};
    this.matchOrdersUsed[key] = tacticPresetOrdersFrom(this.snapshotTactics());
    try {
      return fn();
    } finally {
      Object.assign(this, saved);
      this.repairLineupDepartures(this.lineup);
    }
  }

  // Le remplaçant DÉJÀ désigné (via toggleBackupPosition) pour un poste
  // donné, le mieux noté d'abord si plusieurs joueurs le couvrent — utilisé
  // pour l'auto-promotion d'un remplaçant au départ d'un titulaire (voir
  // handleStarterDeparture ci-dessous), PAS pendant un match en cours (où
  // c'est backupsForSlot qui s'applique, avec ses critères de disponibilité
  // onCourt/disqualified/injured qui n'ont pas de sens hors match).
  designatedBackupForPosition(pos) {
    const candidates = this.players.filter(p => (this.lineup.backupPositions[p.id] || []).includes(pos));
    candidates.sort((a, b) => b.overall() - a.overall());
    return candidates[0] || null;
  }

  // N'IMPORTE QUEL remplaçant déjà désigné, à N'IMPORTE QUEL poste (le mieux
  // noté d'abord) — utilisé en dernier recours par handleStarterDeparture
  // quand aucun remplaçant n'est désigné PRÉCISÉMENT pour le poste vacant :
  // jouer hors de son poste de carte est déjà un mécanisme du jeu (voir
  // effectivePosition/le calcul du salaire), donc un remplaçant désigné à un
  // AUTRE poste peut quand même dépanner comme titulaire, plutôt que de
  // déclencher un forfait alors que l'effectif reste suffisant.
  anyDesignatedBackup() {
    const candidates = this.players.filter(p => (this.lineup.backupPositions[p.id] || []).length > 0);
    candidates.sort((a, b) => b.overall() - a.overall());
    return candidates[0] || null;
  }

  // Retour utilisateur (2026-09) : "si un titulaire est vendu, qu'il y a 4
  // joueurs titu et au moins un remplaçant, ça veut dire que le remplaçant
  // doit être aligné comme titu sur le poste laissé en blanc, il ne faut pas
  // mettre un forfait dans ce type de cas" — puis précision : "pour le
  // forfait, c'est uniquement si on a moins de 5 joueurs sur la feuille. si
  // on a 4 titu, mais [qu'il] manque le meneur titu par exemple, mais qu'on
  // a un pivot remplaçant [...] le pivot remplaçant est mis comme meneur
  // titulaire" — à appeler quand un joueur quitte définitivement l'effectif
  // (vente directe ou enchère conclue) : s'il était titulaire, promeut
  // AUTOMATIQUEMENT (setStarter s'occupe de retirer le remplaçant promu de
  // backupPositions au passage) :
  //   1. le remplaçant déjà désigné pour CE poste précis, s'il y en a un ;
  //   2. sinon N'IMPORTE QUEL AUTRE remplaçant déjà désigné (à un autre
  //      poste) — il vaut mieux le voir dépanner hors de son poste que
  //      déclencher un forfait alors qu'il reste du monde "sur la feuille".
  // Ce n'est que si AUCUN remplaçant n'est désigné nulle part (moins de 5
  // joueurs titulaires+remplaçants au total "sur la feuille") que le poste
  // reste vacant : c'est missingStarterPositions()/hasValidLineup() qui le
  // détecte ensuite, et qui déclenche un forfait si la feuille de match
  // n'est pas corrigée avant le coup d'envoi (voir POSITIONS_MISSING,
  // server/liveMatch.js). Volontairement PAS un rebuild complet façon
  // autoAssignLineup() (qui reconsidère TOUS les postes et pourrait déloger
  // d'autres choix déjà faits manuellement) : seul le poste du titulaire
  // parti est concerné.
  // Titulaires absents de l'effectif (joueur vendu/libéré depuis que la
  // feuille a été écrite) dans `lineup` : le remplaçant désigné à ce poste
  // prend la place s'il est toujours là, sinon le poste reste vide.
  repairLineupDepartures(lineup) {
    if (!lineup || !lineup.starters) return;
    const ids = new Set(this.players.map(p => p.id));
    const taken = new Set(Object.values(lineup.starters).filter(id => ids.has(id)));
    POSITIONS.forEach(pos => {
      const id = lineup.starters[pos];
      if (id == null || ids.has(id)) return;
      const backup = this.players
        .filter(p => !taken.has(p.id) && ((lineup.backupPositions || {})[p.id] || []).includes(pos))
        .sort((a, b) => b.overall() - a.overall())[0];
      lineup.starters[pos] = backup ? backup.id : null;
      if (backup) {
        taken.add(backup.id);
        delete lineup.backupPositions[backup.id];
      }
    });
    Object.keys(lineup.backupPositions || {}).forEach(id => { if (!ids.has(Number(id))) delete lineup.backupPositions[id]; });
    if (Array.isArray(lineup.convoked)) {
      lineup.convoked = lineup.convoked.filter(id => ids.has(id));
      Object.values(lineup.starters).forEach(id => { if (id != null && !lineup.convoked.includes(id)) lineup.convoked.push(id); });
    }
  }

  handleStarterDeparture(playerId) {
    // Ordres préparés à l'avance (retour utilisateur 2026-10-04) : un joueur
    // parti ne doit pas y rester titulaire (forfait au coup d'envoi sinon).
    Object.values(this.plannedTactics || {}).forEach(plan => { if (plan && plan.lineup) this.repairLineupDepartures(plan.lineup); });
    const vacatedPos = this.starterPosition(playerId);
    if (!vacatedPos) return; // le joueur parti n'était pas titulaire : rien à faire sur la feuille de match
    const backup = this.designatedBackupForPosition(vacatedPos) || this.anyDesignatedBackup();
    if (backup) {
      this.setStarter(vacatedPos, backup.id);
    } else {
      this.lineup.starters[vacatedPos] = null;
    }
  }

  // Postes pour lesquels un poste de titulaire n'a pas (ou plus) de joueur
  // valide assigné — la feuille de match doit couvrir les 5 postes (5
  // joueurs distincts minimum) pour pouvoir jouer le match.
  missingStarterPositions() {
    const ids = this.players.map(p => p.id);
    return POSITIONS.filter(pos => {
      const id = this.lineup.starters[pos];
      return !id || !ids.includes(id);
    });
  }

  hasValidLineup() {
    return this.missingStarterPositions().length === 0;
  }

  resetForMatch(now = Date.now()) {
    // Jours de repos écoulés depuis la dernière synchro (voir
    // applyRestDayRecovery) crédités AVANT de figer la forme du coup d'envoi.
    if (this.isHuman && typeof this.syncCollectiveTrainingLog === "function") this.syncCollectiveTrainingLog(now);
    // Alchimie d'équipe (voir Team.chemistryFactor plus haut) : snapshot
    // pris UNE FOIS par match, sur CHAQUE joueur (comme matchCondition côté
    // Player.resetForMatch) — c'est un multiplicateur d'ÉQUIPE, mais lu
    // individuellement par Player.eff() pendant le match.
    const chemistryFactor = this.chemistryFactor();
    // Connaissance tactique (voir Team.tacticalKnowledgeFactor plus haut) :
    // même snapshot d'ÉQUIPE, SÉPARÉ de chemistryFactor ci-dessus.
    if (this.isHuman) this.recomputeTacticalKnowledge();
    const tacticalKnowledgeFactor = this.tacticalKnowledgeFactor();
    // Récupération de forme physique (retour utilisateur, 2026-09, voir
    // Team.conditionRecoveryPerDay/collectiveTraining) : taux du club ;
    // l'intensité des plans individuels est déjà déduite jour par jour
    // (Team.applyTrainingIntensityDay).
    this.players.forEach(p => {
      p.resetForMatch(now, this.conditionRecoveryPerDay());
      p.matchChemistryFactor = chemistryFactor;
      // Club humain : chaque joueur joue avec SA maîtrise du système.
      p.matchTacticalKnowledgeFactor = this.isHuman ? this.playerTacticalKnowledgeFactor(p) : tacticalKnowledgeFactor;
    });
    // Convocation (voir Team.convokedIds) : seuls les convoqués peuvent jouer.
    const convokedNow = new Set(this.convokedIds());
    this.players.forEach(p => { p.convokedThisMatch = convokedNow.has(p.id); });
    POSITIONS.forEach(pos => {
      const id = this.lineup.starters[pos];
      let p = id && this.players.find(x => x.id === id);
      // Blessure PERSISTANTE encore en cours à l'entrée du match (voir
      // Player.matchInjuryLocked, posé juste au-dessus par p.resetForMatch) :
      // le titulaire désigné ne peut pas être aligné. On essaie
      // automatiquement le remplaçant désigné pour CE poste, exactement
      // comme s'il se blessait à la mise en jeu (même filet que le
      // "mustLeave" en cours de match, voir backupsForSlot ci-dessous et
      // MatchEngine.substituteIfNeeded plus bas) — jamais de forfait pour
      // cette seule raison tant qu'un remplaçant existe ; sinon (banc
      // épuisé), le poste reste vacant et l'équipe joue en infériorité,
      // comme une sortie en cours de match sans remplaçant disponible.
      if (p && (p.matchInjuryLocked || !p.convokedThisMatch)) {
        p = this.backupsForSlot(pos)[0] || this.emergencyForSlot(pos) || null;
      }
      if (p) {
        p.onCourt = true;
        p.matchPosition = pos;
        // Repos précoce planifié (voir Player.firstRestThreshold/
        // MatchEngine.substituteIfNeeded) : réservé aux 5 titulaires DU
        // MATCH (marqués ici, au moment où ils sont alignés) — un
        // remplaçant qui entre plus tard EST déjà l'événement de rotation
        // recherché, lui donner en plus un seuil de repos artificiellement
        // bas dès son entrée ne fait que le faire ressortir presque aussitôt
        // (mesuré : ça aplatissait tout le temps de jeu de l'effectif au
        // lieu d'avancer seulement le premier changement des titulaires,
        // voir le grand commentaire dans Player.resetForMatch).
        p.isStarterThisMatch = true;
        p.matchStartPosition = pos;
      }
    });
  }

  onCourtPlayers() {
    return this.players.filter(p => p.onCourt);
  }

  // Remplaçants disponibles pour UN poste donné (celui que le joueur sortant
  // occupait dans ce match — voir p.matchPosition), triés du plus frais au
  // plus fatigué. Un même joueur peut apparaître comme remplaçant pour
  // plusieurs postes ; une fois entré sur le terrain (onCourt=true) il n'est
  // plus disponible pour les autres postes qu'il couvre aussi. `matchInjuryLocked`
  // (voir son commentaire plus haut) exclut aussi un remplaçant encore sous
  // le coup d'une blessure persistante, pas seulement `injured` (transitoire,
  // blessé PENDANT ce match précis).
  backupsForSlot(pos) {
    return this.players.filter(p =>
      (this.lineup.backupPositions[p.id] || []).includes(pos) &&
      !p.onCourt && !p.disqualified && !p.injured && !p.matchInjuryLocked && p.convokedThisMatch !== false
    ).sort((a, b) => a.fatigue - b.fatigue);
  }

  offenseProfile() {
    const profs = this.offensivePriorities.map(t => OFFENSE_PROFILES[t]);
    const merged = { inside: 0, mid: 0, three: 0, tov: 0, assist: 0, tempo: 0, drawFoul: 0 };
    profs.forEach(p => {
      merged.inside += p.inside / profs.length;
      merged.mid += p.mid / profs.length;
      merged.three += p.three / profs.length;
      merged.tov += p.tov / profs.length;
      merged.assist += p.assist / profs.length;
      merged.tempo += p.tempo / profs.length;
      merged.drawFoul += (p.drawFoul || 0) / profs.length;
    });
    return merged;
  }
}

// ---------------------------------------------------------------------
// GÉNÉRATION DE JOUEURS / ÉQUIPES DE DÉMONSTRATION
// ---------------------------------------------------------------------
const FIRST_NAMES = ["Léo", "Hugo", "Nathan", "Malik", "Yanis", "Théo", "Amir", "Kevin",
  "Rayan", "Bastien", "Enzo", "Souleymane", "Diego", "Marc", "Karim", "Sacha",
  "Jordan", "Tom", "Adama", "Noé", "Elias", "Baptiste", "Milo", "Quentin"];
// Pool élargi le 2026-09-24 (retour Discord d'Ariane, relayé par
// l'utilisateur : "3 Fontaine, 2 Novak, 2 Petit, c'est la galère pour m'y
// retrouver" — avec seulement 22 noms de famille, un effectif de 15 joueurs
// (POSITIONS × 3, voir generateTeam/generateStartingRoster) tombait
// quasi-systématiquement sur des doublons, paradoxe des anniversaires
// oblige). Élargi à ~90 noms (toujours le même mélange français/
// international que l'original) plutôt que retenté avec un pool à peine
// plus grand — et voir pickUniqueLastName juste en dessous, qui évite en
// plus activement les répétitions AU SEIN d'un même effectif tant que le
// pool le permet (double filet, pas seulement "moins probable").
const LAST_NAMES = ["Dupont", "Martin", "Garcia", "Johnson", "N'Diaye", "Rossi", "Kovac",
  "Petit", "Silva", "Traoré", "Bernard", "Moreau", "Lefevre", "Diallo", "Novak",
  "Fontaine", "Girard", "Brooks", "Fournier", "Lopez", "Barros", "Chevalier",
  "Durand", "Leroy", "Simon", "Laurent", "Michel", "Legrand", "Roux", "Vidal",
  "Caron", "Perrin", "Morel", "Gauthier", "Renard", "Blanchard", "Guerin",
  "Muller", "Weber", "Schmidt", "Fischer", "Hoffmann", "Keita", "Cissé",
  "Toure", "Ouedraogo", "Kone", "Mbaye", "Sow", "Ndiaye", "Camara", "Fofana",
  "Kante", "Sy", "Diakite", "Sanogo", "Coulibaly", "Costa", "Ferreira",
  "Santos", "Oliveira", "Pereira", "Alves", "Ramos", "Nunes", "Almeida",
  "Ivanov", "Petrov", "Popov", "Horvat", "Novakovic", "Jankovic", "Dimitrov",
  "Rossetti", "Bianchi", "Ferrari", "Ricci", "Marino", "Greco", "Conti",
  "Hernandez", "Gonzalez", "Rodriguez", "Fernandez", "Morales", "Castillo",
  "Nakamura", "Sato", "Kobayashi", "Yamada", "Watanabe", "Suzuki",
  "Andersson", "Nilsson", "Larsen", "Hansen", "Kowalski", "Nowak",
  "O'Brien", "Murphy", "Walsh", "Kelly", "Cooper", "Bennett", "Wright"];

// Choisit un nom au hasard dans `list` en évitant de répéter un nom déjà
// utilisé DANS CET EFFECTIF (`used`, un Set) tant que le pool le permet.
// Si tous les noms disponibles ont déjà été pris (effectif plus grand que
// le pool, ou malchance), on retombe sur un tirage classique plutôt que de
// planter — un doublon occasionnel reste préférable à une erreur.
function pickUniqueLastName(list, used) {
  const available = list.filter(n => !used.has(n));
  const chosen = pick(available.length ? available : list);
  used.add(chosen);
  return chosen;
}

function heightForPosition(position) {
  const ranges = {
    "Meneur": [178, 192], "Arrière": [188, 200], "Ailier shooteur": [195, 205],
    "Ailier fort": [200, 210], "Pivot": [206, 222],
  };
  return Math.round(rand(...ranges[position]));
}

// Spécialité de chaque poste, caractéristique par caractéristique : "strong"
// (aptitude forte et attendue à ce poste), "base" (ordinaire) ou "weak"
// (pas le rôle de ce poste). SOURCE UNIQUE utilisée à la fois par la
// génération de joueurs (generateAttrsForPosition, juste en dessous — une
// caractéristique "strong" tire vers le haut de la fourchette, "weak" vers
// le bas) ET par le coefficient de niveau qui détermine le salaire (voir
// levelCoefficientFor plus bas) : les deux doivent s'accorder sur ce qui
// définit chaque poste, sinon la génération et la grille salariale
// raconteraient chacune une histoire différente du même joueur.
// "endurance"/"freeThrow" (voir leur commentaire au-dessus de ATTRS)
// N'APPARAISSENT PAS ci-dessous, à dessein : ce sont des qualités
// générales, pas propres à un poste (un Pivot encaisse aussi bien une
// mauvaise série qu'un Meneur), donc elles retombent sur "base" pour
// TOUS les postes via le filet `profile[a] || "base"` déjà en place plus
// bas (generateAttrsForPosition/weightedRatingForPosition) plutôt que de
// dupliquer "base" dans chacune des 5 entrées ci-dessous. "mental" n'est
// plus concerné : ce n'est plus une caractéristique stockée du tout (voir
// mentalAverage() au-dessus de PHYSICAL_ATTRS), donc rien à profiler ici.
// 9 dernières caractéristiques (retour utilisateur, 2026-09, "il en manque
// une partie") : seules Vitesse/Accélération/Force/Détente reçoivent une
// entrée ci-dessous, sur le même principe que Pénétration/Création de
// tir/Interceptions/Puissance plus haut (spécialisation par poste).
// Décision/Sang-froid/Détermination/Discipline/Vision n'ont volontairement
// aucune entrée ici, exactement comme Endurance/Lancer franc/
// Concentration/Anticipation/Leadership : des qualités générales, sans
// poste de prédilection (elles retombent sur "base" partout via le
// `profile[a] || "base"` de generateAttrsForPosition/weightedRatingForPosition).
const POSITION_ATTR_PROFILE = {
  "Meneur": { pass: "strong", dribble: "strong", agility: "strong", threePoint: "base",
    defOutside: "base", midRange: "base", inside: "weak", rebound: "weak", block: "weak", defInside: "weak",
    penetration: "strong", shotCreation: "strong", steal: "strong", power: "weak",
    speed: "strong", acceleration: "strong", strength: "weak", vertical: "weak" },
  // Dribble (retour utilisateur, 2026-09 : "signature du Meneur, mais aussi
  // signature de l'Arrière pour le dribble") : l'Arrière manie autant le
  // ballon en un-contre-un que le Meneur, seulement avec un but différent
  // (se créer SON tir plutôt que distribuer) - désormais "strong" pour
  // l'Arrière aussi, plus seulement "base".
  "Arrière": { threePoint: "strong", midRange: "strong", agility: "base", dribble: "strong",
    pass: "base", defOutside: "base", inside: "weak", rebound: "weak", block: "weak", defInside: "weak",
    penetration: "strong", shotCreation: "strong", steal: "strong", power: "weak",
    speed: "strong", acceleration: "strong", strength: "weak", vertical: "weak" },
  "Ailier shooteur": { threePoint: "strong", midRange: "base", agility: "base", defOutside: "strong",
    inside: "base", pass: "base", dribble: "base", rebound: "base", block: "weak", defInside: "weak",
    penetration: "base", shotCreation: "strong", steal: "base", power: "base" },
  "Ailier fort": { inside: "strong", rebound: "strong", midRange: "base", defInside: "strong",
    block: "base", defOutside: "weak", pass: "weak", dribble: "weak", agility: "base", threePoint: "weak",
    penetration: "weak", shotCreation: "base", steal: "base", power: "strong",
    speed: "weak", acceleration: "weak", strength: "strong", vertical: "strong" },
  "Pivot": { inside: "strong", rebound: "strong", block: "strong", defInside: "strong",
    midRange: "weak", threePoint: "weak", pass: "weak", dribble: "weak", agility: "weak", defOutside: "weak",
    penetration: "weak", shotCreation: "weak", steal: "weak", power: "strong",
    speed: "weak", acceleration: "weak", strength: "strong", vertical: "strong" },
};

// Génération corrélée (audit des attributs 2026-10-06) : les
// caractéristiques d'une même famille partagent un tirage commun (le
// « talent » du joueur dans ce domaine) mêlé à un tirage propre. Un bon
// défenseur extérieur a souvent de bonnes interceptions et une bonne
// anticipation ; un écart du type 81/38 reste possible mais devient rare.
// Mélange 60/40 : moyenne inchangée, valeurs extrêmes moins fréquentes.
const ATTR_FAMILIES = {
  shooting: ["threePoint", "midRange", "freeThrow", "shotCreation"],
  handle: ["dribble", "penetration"],
  playmaking: ["pass", "vision", "decision"],
  perimeterDefense: ["defOutside", "steal", "anticipation"],
  interior: ["inside", "rebound", "block", "defInside"],
  athleticism: ["speed", "acceleration", "agility", "vertical", "endurance"],
  physique: ["strength", "power"],
  mental: ["focus", "composure", "determination", "discipline", "leadership"],
};
const ATTR_FAMILY_SHARE = 0.6;
const ATTR_FAMILY_OF = {};
Object.keys(ATTR_FAMILIES).forEach(f => ATTR_FAMILIES[f].forEach(a => { ATTR_FAMILY_OF[a] = f; }));
// Renvoie a => u ∈ [0, 1] pour un joueur (un tirage latent par famille).
function correlatedUnitDraws() {
  const latent = {};
  return a => {
    const f = ATTR_FAMILY_OF[a];
    if (!f) return rand01();
    if (latent[f] == null) latent[f] = rand01();
    return ATTR_FAMILY_SHARE * latent[f] + (1 - ATTR_FAMILY_SHARE) * rand01();
  };
}

function generateAttrsForPosition(position, tier) {
  const u = correlatedUnitDraws();
  const ranges = { base: [30, 65], strong: [55, 92], weak: [15, 45] };
  const profile = POSITION_ATTR_PROFILE[position] || {};
  const attrs = {};
  ATTRS.forEach(a => {
    const [lo, hi] = ranges[profile[a] || "base"];
    attrs[a] = clamp(Math.round((lo + u(a) * (hi - lo)) * tier), 1, 99);
  });
  return attrs;
}

// Poids appliqué à une caractéristique selon sa catégorie pour un poste
// donné (voir POSITION_ATTR_PROFILE) — "strong" pèse plus, "weak" pèse
// moins, mais jamais zéro (même hors de sa spécialité, un peu de qualité
// compte toujours un peu). Utilisé pour l'aptitude de poste À L'ENTRAÎNEMENT
// (positionEfficiencyForSkill et consorts, plus haut) — voir
// weightedRatingForPosition ci-dessous pour la note salariale.
const ATTR_CATEGORY_WEIGHT = { strong: 1.5, base: 1.0, weak: 0.4 };

// Moyenne PONDÉRÉE des caractéristiques d'un joueur SI on l'évalue au poste
// `position` (voir POSITION_ATTR_PROFILE/ATTR_CATEGORY_WEIGHT) — contrairement
// à Player.overall() (moyenne BRUTE, tout compte pareil), une caractéristique
// hors-spécialité (ex : le tir à 3 points d'un Pivot) pèse moins. Utilisée
// pour déterminer le poste EFFECTIF d'un joueur (voir inferPosition) — PAS
// directement pour le salaire, qui ajoute par-dessus un bonus pour les
// caractéristiques signature exceptionnelles (voir peakBonusFor/
// levelCoefficientFor) : mélanger les deux dans une même moyenne avantageait
// à tort les postes ayant PLUS de caractéristiques "fortes" (ex : Pivot, 4
// caractéristiques signature, contre 2-3 pour les autres postes) — une
// caractéristique signature de plus dilue une moyenne, même quand elle est
// elle aussi excellente, ce qui faisait mal classer la majorité des Ailiers
// forts générés (trop souvent reclassés Pivot par ce seul artefact de calcul).
function weightedRatingForPosition(attrs, position) {
  const profile = POSITION_ATTR_PROFILE[position] || {};
  let sum = 0, totalW = 0;
  ATTRS.forEach(a => {
    const w = ATTR_CATEGORY_WEIGHT[profile[a] || "base"];
    sum += attrs[a] * w;
    totalW += w;
  });
  return totalW ? sum / totalW : 0;
}

// Marge en faveur du poste DE CARTE d'un joueur avant qu'un autre poste ne
// soit retenu comme "poste effectif" (voir inferPosition) : la génération
// (voir generateAttrsForPosition) comporte assez d'aléa pour qu'un joueur
// correctement généré à son poste obtienne, par pur hasard, un score
// légèrement meilleur à un poste voisin (Ailier fort/Pivot notamment, très
// proches) — sans cette marge, la majorité des joueurs se feraient
// "corriger" vers un autre poste sans raison réelle. Reste assez petite
// pour qu'un profil VRAIMENT typé autrement (voir l'exemple donné par
// l'utilisateur : gros rebond + grosse défense intérieure → Pivot, même sur
// une fiche Ailier fort) l'emporte quand même largement.
const CARD_POSITION_BIAS = 5;

// Détermine le poste EFFECTIF d'un joueur D'APRÈS SES CARACTÉRISTIQUES (pas
// forcément son poste "de carte" `cardPosition`, si fourni — voir
// Player.position et CARD_POSITION_BIAS ci-dessus) : celui qui donne la
// meilleure moyenne pondérée (voir weightedRatingForPosition). Sans
// `cardPosition` (ex : un profil de test isolé, sans joueur réel derrière),
// la meilleure moyenne l'emporte sans marge de tolérance.
function inferPosition(attrs, cardPosition) {
  let bestPosition = null, bestScore = -Infinity;
  POSITIONS.forEach(pos => {
    let score = weightedRatingForPosition(attrs, pos);
    if (cardPosition && pos === cardPosition) score += CARD_POSITION_BIAS;
    if (score > bestScore) { bestScore = score; bestPosition = pos; }
  });
  return bestPosition;
}

// ---------------------------------------------------------------------
// Note PAR POSTE (retour utilisateur 2026-09-30 : "il faudrait que le jeu
// calcule une note par poste"). Aide à la décision uniquement (écran
// Ordres, fiche joueur) : AUCUN effet sur la simulation.
//
// Ce que fait réellement le moteur de match : il ne pondère PAS les
// caractéristiques d'un joueur selon le poste qu'il occupe (un tir, un
// rebond, une passe se résolvent avec les mêmes caractéristiques qu'il
// soit aligné Meneur ou Pivot) et n'applique AUCUNE pénalité "hors poste".
// Le poste joué (Player.matchPosition) ne sert qu'aux remplacements (qui
// remplace qui, minutes visées), aux consignes « postes à surveiller »,
// au taux de fautes (FOUL_POSITION_MULT : Pivot ×1.3, Ailier fort ×1.15)
// et au temps de jeu par poste (entraînement).
//
// Refonte (retour utilisateur 2026-09-30 (téléphone) : "31 aux 5 postes
// alors qu'il est Meneur") : la première version reprenait
// weightedRatingForPosition (profil strong ×1.5 / base ×1 / weak ×0.4 sur
// les 28 caractéristiques). Trop peu discriminant pour un affichage : les
// 10 qualités générales (mental, endurance, lancer franc…) pèsent pareil
// partout et les poids restent proches de 1, si bien qu'un effectif à ~30
// de moyenne ne montrait que 4-6 points entre postes opposés, 1-2 (souvent
// 0 après arrondi) entre voisins. weightedRatingForPosition reste INCHANGÉE
// (salaire, poste effectif, frustration du banc) : seule la note AFFICHÉE
// change.
//
// Nouvelle formule, explicite :
//   note(poste) = (1 − k) × overall + k × clés(poste),  k = 0.65
// où overall = moyenne brute des 28 caractéristiques (Player.overall()) et
// clés(poste) = moyenne pondérée des 5 à 9 caractéristiques qui FONT le
// poste (POSITION_KEY_WEIGHTS ci-dessous, poids en %, total 100). Les clés
// sont choisies d'après ce que le moteur de match leur fait réellement
// jouer (passe/vision/décision pour le porteur, tir/création pour
// l'arrière, 3 pts + défense extérieure pour l'ailier shooteur, mi-distance
// + physique pour l'ailier fort, contre/rebond/défense intérieure pour le
// pivot), et de sorte qu'un Ailier fort généré ne soit pas presque
// toujours « meilleur Pivot » (le Pivot se distingue surtout par le
// Contre, l'Ailier fort par la mi-distance et le physique).
// Ordres de grandeur (effectif généré, tier 0.6, overall ~30) : un
// spécialiste gagne 12-16 points entre son poste et le poste opposé
// (ex : Meneur 36 / 35 / 33 / 28 / 22), 2-5 points avec un voisin ; un
// joueur polyvalent (toutes caractéristiques égales) a la même note
// partout, égale à son overall. Même échelle que Player.overall(), bornée
// à 0-100.
// ---------------------------------------------------------------------
// Recalé le 2026-10-06 (audit des attributs) : 75 % effet mesuré en match
// (+20 sur un attribut, milliers de matchs) × profil du poste, 25 % anciens
// poids (identité du poste). Voir DEV_NOTES.md.
const POSITION_KEY_WEIGHTS = {
  "Meneur": { dribble: 20, agility: 14, steal: 13, defOutside: 11, speed: 10, acceleration: 10, shotCreation: 7, pass: 6, threePoint: 6, vision: 3 },
  "Arrière": { dribble: 18, threePoint: 14, defOutside: 12, steal: 11, shotCreation: 10, speed: 9, midRange: 9, acceleration: 8, agility: 6, penetration: 3 },
  "Ailier shooteur": { defOutside: 27, threePoint: 14, shotCreation: 10, agility: 10, steal: 8, rebound: 8, dribble: 8, inside: 6, strength: 6, midRange: 3 },
  "Ailier fort": { rebound: 22, inside: 18, strength: 15, agility: 10, power: 9, steal: 7, defInside: 7, midRange: 5, shotCreation: 3, defOutside: 4 },
  "Pivot": { rebound: 25, inside: 20, block: 13, strength: 12, defInside: 11, power: 6, defOutside: 4, discipline: 3, dribble: 3, vertical: 3 },
};
// Part des caractéristiques clés du poste dans la note (le reste = overall).
const POSITION_RATING_KEY_SHARE = 0.65;

function positionRating(player, pos) {
  const attrs = player && player.attrs ? player.attrs : player;
  if (!attrs || !POSITIONS.includes(pos)) return 0;
  const val = a => (typeof attrs[a] === "number" ? attrs[a] : 0);
  const overall = ATTRS.reduce((s, a) => s + val(a), 0) / ATTRS.length;
  const weights = POSITION_KEY_WEIGHTS[pos];
  let sum = 0, totalW = 0;
  Object.keys(weights).forEach(a => { sum += val(a) * weights[a]; totalW += weights[a]; });
  const keys = totalW ? sum / totalW : overall;
  return clamp((1 - POSITION_RATING_KEY_SHARE) * overall + POSITION_RATING_KEY_SHARE * keys, 0, 100);
}

// Les 5 notes d'un joueur, { poste: note }.
function positionRatings(player) {
  const out = {};
  POSITIONS.forEach(pos => { out[pos] = positionRating(player, pos); });
  return out;
}

// Poste où la note est la plus haute. À égalité (à 0.001 près), le poste
// de carte du joueur l'emporte, puis l'ordre de POSITIONS.
function bestPosition(player) {
  const card = player && player.position;
  let best = null, bestScore = -Infinity;
  POSITIONS.forEach(pos => {
    const score = Math.round(positionRating(player, pos) * 1000) / 1000;
    if (score > bestScore || (score === bestScore && pos === card)) { bestScore = score; best = pos; }
  });
  return best;
}

// ---------------------------------------------------------------------
// Poste DE CARTE qui suit les caractéristiques (retour utilisateur
// 2026-09-30 : "Quand un joueur a son meilleur poste qui ne correspond plus
// à la réalité, il faut le changer. La seule chose qui ne doit changer qu'à
// l'intersaison est le salaire.").
// - Une seule notion de « meilleur poste » : bestPosition (note par poste
//   ci-dessus). Player.position (le poste de carte, badge partout) la suit.
// - Hystérésis : le poste change dès que la note au meilleur poste dépasse
//   celle du poste actuel d'AU MOINS 1 point (POSITION_CHANGE_MARGIN) ;
//   revenir au poste qu'on vient de quitter (Player.previousCardPosition,
//   sauvegardé) exige aussi 1 point (POSITION_RETURN_MARGIN, réglable à
//   part) : un aller-retour suppose que l'écart bouge d'au moins 2 points au
//   total (règle utilisateur 2026-09-30).
// - Quand : fin de chaque mise à jour hebdomadaire (Team.trainWeek pour les
//   clubs humains, Team.trainWeekCPU pour l'IA) et à chaque chargement de
//   sauvegarde (teamFromSave : migration des sauvegardes existantes, côté
//   serveur pour TOUS les clubs de la ligue, IA comprise). À la création
//   (voir attrsForCardPosition), le poste de carte EST déjà le meilleur.
// - Le salaire n'est PAS touché ici : il reste celui fixé à l'intersaison
//   (Team.recalculateSalaries, calculé au poste de carte du moment, voir
//   levelCoefficientFor) ; Player.effectivePosition garde le poste auquel
//   ce salaire a été calculé.
// - Composition : les postes de la feuille de match sont des CASES
//   (lineup.starters[poste] = id), indépendantes du poste de carte ; un
//   titulaire qui change de poste reste titulaire de sa case (l'alerte
//   « Hors poste » des Ordres se met à jour d'elle-même). Entraînement :
//   il compte le temps joué À CHAQUE poste en match
//   (trainingSecondsPlayedByPosition), pas le poste de carte — un
//   changement en cours de semaine ne fait rien perdre.
// ---------------------------------------------------------------------
// Règle utilisateur (2026-09-30) : le poste change dès que le meilleur poste
// dépasse le poste actuel d'AU MOINS 1 point, y compris pour revenir au poste
// qu'on vient de quitter (previousCardPosition) — un aller-retour demande
// donc que l'écart bouge d'au moins 2 points au total.
const POSITION_CHANGE_MARGIN = 1;
const POSITION_RETURN_MARGIN = 1;
const CARD_POSITION_SHORT = { "Meneur": "M", "Arrière": "A", "Ailier shooteur": "AS", "Ailier fort": "AF", "Pivot": "P" };
// Nombre de tirages de caractéristiques tentés à la création pour que le
// poste demandé soit bien le meilleur (sinon : poste = meilleur poste).
const GENERATION_POSITION_TRIES = 25;

// Changement de poste de carte dû (ou null) : { from, to, ratingFrom, ratingTo }.
function cardPositionChangeFor(player) {
  if (!player || !player.attrs || !POSITIONS.includes(player.position)) return null;
  const best = bestPosition(player);
  if (!best || best === player.position) return null;
  const ratingTo = positionRating(player, best), ratingFrom = positionRating(player, player.position);
  const margin = best === player.previousCardPosition ? POSITION_RETURN_MARGIN : POSITION_CHANGE_MARGIN;
  if (ratingTo - ratingFrom < margin) return null;
  return { from: player.position, to: best, ratingFrom, ratingTo };
}

// Création d'un joueur : retire les caractéristiques (`makeAttrs`) jusqu'à ce
// que `position` soit son meilleur poste (effectif équilibré : 3 joueurs par
// poste restent 3 joueurs par poste) ; au pire, le poste devient le
// meilleur poste des derniers tirages. Renvoie { attrs, position }.
function attrsForCardPosition(position, makeAttrs) {
  let attrs = makeAttrs();
  for (let i = 1; i < GENERATION_POSITION_TRIES && bestPosition({ attrs, position }) !== position; i++) attrs = makeAttrs();
  return { attrs, position: bestPosition({ attrs, position }) || position };
}

// Bonus salarial pour une caractéristique SIGNATURE exceptionnelle du poste
// retenu (voir POSITION_ATTR_PROFILE) : ADDITIF, appliqué APRÈS le choix du
// poste (voir levelCoefficientFor) — jamais mélangé dans une moyenne, pour
// ne pas réintroduire le biais lié au nombre de caractéristiques fortes du
// poste (voir weightedRatingForPosition). Sinon, même une caractéristique
// signature à 90+ finit noyée dans la moyenne pondérée de tout le reste du
// profil (constaté sur le cas concret signalé par l'utilisateur : 97 en tir
// à 3 points, reste du profil ordinaire → seulement 1848 $ malgré un tir de
// classe mondiale).
//
// Seuil volontairement très haut (90) : la génération normale d'un joueur
// (voir generateAttrsForPosition) plafonne une caractéristique "forte" à 92
// pour un effectif de tier 1.0, donc la quasi-totalité des joueurs générés
// fraîchement ne déclenchent JAMAIS ce bonus — seul un pic VRAIMENT
// exceptionnel (joueur entraîné au-delà de ce plafond au fil des saisons,
// ou généré dans une division/tier plus fort, où la génération peut
// dépasser 92 — voir DIVISIONS/tierMultiplier) le déclenche. Facteur élevé (6) pour qu'un
// tel pic se traduise en une vraie prime, pas un ajustement cosmétique : un
// joueur à 97 dans SA caractéristique signature — parmi les meilleurs au
// monde à CETTE compétence-là — est ainsi payé en conséquence, même si le
// reste de son profil est ordinaire (voir salaryForOverall).
//
// PLAFONNÉ (SALARY_PEAK_BONUS_MAX) : sans plafond, un joueur qui cumule PAR
// HASARD plusieurs caractéristiques fortes déjà très hautes (donc une
// moyenne pondérée déjà élevée à elle seule) ET un pic extrême verrait les
// deux effets se multiplier via la courbe exponentielle (voir
// salaryForOverall) et produire un salaire imprévisible, hors de toute
// grille cohérente — repéré en testant sur des effectifs générés réels
// (masse salariale d'un effectif entier s'envolant occasionnellement bien
// au-delà des joueurs vedettes du marché des transferts, par pur hasard de
// génération). Le plafond garantit une prime maximale prévisible et
// cohérente, atteinte dès qu'un pic est déjà nettement exceptionnel, sans
// dépendre du reste du profil.
// Puissance (voir MatchEngine.playPossession, powerFoulMod et
// finition au contact) : fautes provoquées près du cercle et finition
// malgré le contact. Recalés le 2026-10-06 (+20 de Puissance : +0,0 pt
// mesuré avant).
// Rôles de jeu, phase 3 (2026-10-06, voir assets/roles.js et
// MatchEngine.roleState) : la compatibilité du cinq en jeu est un
// MODIFICATEUR (un gros talent compense en partie), jamais une règle.
// Cohérence 65 % = neutre.
const ROLE_COHESION_PIVOT = 65;
const ROLE_TACTIC_WEIGHT = 0.15;
// Évolution des rôles (phase 5) : rôle principal noté à chaque passage de
// saison quand il change (Slasher à 20 ans, Shot Creator à 25, Gâchette à 31…).
const ROLE_HISTORY_MAX = 12;
function recordRoleHistory(p, seasonNo) {
  try {
    const prof = Roles.profileOf(p.attrs, positionRatings(p), 1, p.position);
    if (!prof) return;
    p.roleHistory = Array.isArray(p.roleHistory) ? p.roleHistory : [];
    const last = p.roleHistory[p.roleHistory.length - 1];
    if (last && last.role === prof.primary.role) return;
    p.roleHistory.push({ season: seasonNo, age: p.age, role: prof.primary.role, name: prof.primary.name, pos: prof.primary.position });
    if (p.roleHistory.length > ROLE_HISTORY_MAX) p.roleHistory = p.roleHistory.slice(-ROLE_HISTORY_MAX);
  } catch (e) { /* jamais bloquant */ }
}     // tactique adaptée aux rôles : ±4,5 pts de cohérence offensive aux extrêmes
const ROLE_MISMATCH_FORM_MALUS = 2;      // motivation perdue par un titulaire hors de son rôle préféré
const ROLE_MISMATCH_COOLDOWN_WEEKS = 2;  // au plus une fois toutes les 2 semaines par joueur
const ROLE_OFF_OPENNESS = 0.12;      // ouverture des tirs par point de cohérence offensive
const ROLE_OFF_TOV = 0.0003;         // pertes de balle en moins par point de cohérence offensive
const ROLE_DEF_BOOST = 0.001;        // contest défensif par point de cohérence défensive
const ROLE_USAGE_BASE = 0.7;         // part des tirs : ×0,7 (rôle qui ne demande pas le ballon) …
const ROLE_USAGE_SLOPE = 0.6;        // … à ×1,3 (rôle qui monopolise le ballon)
const ROLE_CREATE_BASE = 0.7;        // choix du passeur : ×0,7 à ×1,3 selon la création du rôle
const ROLE_CREATE_SLOPE = 0.6;
const ROLE_SPACING_THREE = 0.6;      // volume de tirs à 3 pts selon l'écartement du cinq
const POWER_FOUL_PER_POINT = 0.003;
// Audit des attributs (2026-10-06) : un rôle propre par attribut.
// Interceptions — pari défensif (MatchEngine.playPossession).
const STEAL_GAMBLE_BASE = 0.003;
const STEAL_GAMBLE_PER_POINT = 0.0006;  // par point d'Interception au-dessus de la Défense extérieure
const STEAL_GAMBLE_MAX = 0.035;
const STEAL_GAMBLE_SUCCESS_BASE = 0.4;
const STEAL_GAMBLE_SUCCESS_PER_POINT = 0.005;
const STEAL_GAMBLE_MISS_OPENNESS = 14;
function stealGambleRate(p) {
  return clamp(STEAL_GAMBLE_BASE + (p.eff("steal") - p.eff("defOutside")) * STEAL_GAMBLE_PER_POINT, 0, STEAL_GAMBLE_MAX);
}
const ACCEL_FIRST_STEP_PER_POINT = 0.12;
const PENETRATION_VOLUME_DIV = 50;
const BLOCK_DETERRENCE_PER_POINT = 0.0018;
// Écart moyen mesuré (meilleur protecteur − Jeu intérieur du tireur) : à
// ce niveau, aucun effet ; l'adresse moyenne près du cercle ne bouge pas.
const BLOCK_DETERRENCE_PIVOT = -4;
const DECISION_REFUSAL_PER_POINT = 0.012;
const COMPOSURE_PRESSURE_TOV_PER_POINT = 0.0012;
// Détermination : vitesse de progression à l'entraînement (×0,8 à ×1,25) et
// motivation après une défaite (Team.applyChemistryResult).
const DETERMINATION_LOSS_FORM_PER_POINT = 0.06;
function determinationTrainingMult(p) {
  const d = p && p.attrs && typeof p.attrs.determination === "number" ? p.attrs.determination : 45;
  return clamp(1 + (d - 45) * 0.006, 0.8, 1.25);
}
const POWER_AND_ONE_PER_POINT = 0.008;
const SALARY_PEAK_BONUS_THRESHOLD = 90;
// Réduit le 2026-10-04 (6/point, plafond 40 → 0,75/point, plafond 5) : une
// seule caractéristique au-dessus de 90 multipliait le salaire jusqu'à ×3,5
// et pesait plus que le niveau lui-même ; elle reste récompensée (jusqu'à
// +25-45 % selon le palier) sans faire exploser le salaire.
const SALARY_PEAK_BONUS_FACTOR = 0.75;
const SALARY_PEAK_BONUS_MAX = 5;
const LEGACY_SALARY_PEAK_BONUS_FACTOR = 6;
const LEGACY_SALARY_PEAK_BONUS_MAX = 40;

function peakBonusFor(attrs, position) {
  const profile = POSITION_ATTR_PROFILE[position] || {};
  const strongAttrs = ATTRS.filter(a => profile[a] === "strong");
  if (!strongAttrs.length) return 0;
  const peak = Math.max(...strongAttrs.map(a => attrs[a]));
  return Math.min(SALARY_PEAK_BONUS_MAX, Math.max(0, peak - SALARY_PEAK_BONUS_THRESHOLD) * SALARY_PEAK_BONUS_FACTOR);
}

// `coefficient` (moyenne pondérée au poste retenu + bonus de pic — voir
// weightedRatingForPosition/peakBonusFor) sert de base au salaire (voir
// salaryForOverall et Player.salary/Team.recalculateSalaries) : un vrai
// spécialiste bien évalué à son rôle, avec une vraie caractéristique
// signature, est mieux valorisé qu'une simple moyenne brute qui le
// pénaliserait pour des lacunes hors-spécialité pourtant normales à son poste.
// Poste retenu (retour utilisateur 2026-09-30 : une seule notion de poste) :
// le poste DE CARTE du joueur quand il est fourni (il suit désormais ses
// caractéristiques, voir cardPositionChangeFor), sinon son meilleur poste
// (bestPosition). Appelé uniquement à la création et à l'intersaison
// (Team.recalculateSalaries) : un changement de poste en cours de saison ne
// touche jamais au salaire.
// Salaire calculé sur le MEILLEUR poste (retour utilisateur 2026-10-03 :
// « le salaire doit être calculé sur base du meilleur poste », comme la note
// affichée) : la plus haute des notes par poste (positionRating) + bonus de
// pic de ce poste. `position` reste le poste de carte (ou le meilleur).
function legacyLevelCoefficientFor(attrs) {
  const best = bestPosition({ attrs });
  const profile = POSITION_ATTR_PROFILE[best] || {};
  const strong = ATTRS.filter(a => profile[a] === "strong");
  const peak = strong.length ? Math.max(...strong.map(a => attrs[a])) : 0;
  return positionRating(attrs, best) + Math.min(LEGACY_SALARY_PEAK_BONUS_MAX, Math.max(0, peak - SALARY_PEAK_BONUS_THRESHOLD) * LEGACY_SALARY_PEAK_BONUS_FACTOR);
}
function levelCoefficientFor(attrs, cardPosition) {
  const position = POSITIONS.includes(cardPosition) ? cardPosition : bestPosition({ attrs });
  const best = bestPosition({ attrs });
  const coefficient = positionRating(attrs, best) + peakBonusFor(attrs, best);
  return { position, coefficient };
}

// Génère un profil d'attributs "brut" dans la fourchette [lo,hi] (avant tier),
// rien de développé, tout reste à révéler par l'entraînement, mais
// désormais LÉGÈREMENT orienté vers `position` (voir POSITION_ATTR_PROFILE) :
// une caractéristique "forte" pour ce poste tire vers le haut de la
// fourchette, une "faible" vers le bas, une "de base" reste répartie sur
// toute son étendue. Correctif 2026-09 (retour utilisateur : "corrige pour
// que le poste reflète les caractéristiques dès le départ") : avant ça,
// generateRawYouthAttrs tirait les 10 caractéristiques uniformément dans
// [lo,hi] SANS AUCUN rapport avec le poste qu'on venait de lui assigner :
// un Pivot pouvait ainsi démarrer avec un profil qui n'avait jamais eu la
// moindre chance de ressembler à un Pivot (voir Player.effectivePosition/
// levelCoefficientFor, qui pouvaient alors s'écarter du poste de carte dès
// la toute première saison, sans qu'aucune caractéristique n'ait bougé).
// L'écart reste volontairement modeste (25% de la fourchette totale de
// chaque côté, jamais les vraies bornes 55-92/15-45 de generateAttrsForPosition
// utilisées pour un adulte confirmé) : un jeune n'a encore RIEN prouvé, ce
// n'est qu'un léger a priori cohérent avec son étiquette de poste, qui laisse
// toute leur place à l'entraînement et au hasard (voir CARD_POSITION_BIAS/
// inferPosition, qui garde volontairement une vraie marge d'erreur possible
// malgré ce biais : un profil VRAIMENT atypique peut toujours, plus rarement
// qu'avant, faire pencher le poste effectif d'un autre côté).
function generateRawAttrsInRange(position, lo, hi, tier) {
  const span = hi - lo;
  const u = correlatedUnitDraws();
  const ranges = { base: [lo, hi], strong: [lo + span * 0.25, hi], weak: [lo, hi - span * 0.25] };
  const profile = POSITION_ATTR_PROFILE[position] || {};
  const attrs = {};
  ATTRS.forEach(a => {
    const [a0, a1] = ranges[profile[a] || "base"];
    attrs[a] = clamp(Math.round((a0 + u(a) * (a1 - a0)) * tier), 1, 99);
  });
  return attrs;
}

// Un jeune joueur (prospect brut, pas encore de vraie draft/génération de
// nouveaux joueurs pour l'instant) démarre bas sur TOUTES ses caractéristiques
// (10-50, recalibré 2026-09, retour utilisateur : "sur les joueurs de
// départ, on ne devrait pas avoir plus de 50 sur une caractéristique / donc
// entre 10 et 50 sur les caracs / idem pour les joueurs draftés de 18/19
// ans"), désormais orienté vers `position` (voir generateRawAttrsInRange
// ci-dessus) : son potentiel caché, lui, peut être élevé, tout reste à
// révéler par l'entraînement.
const YOUNG_PROSPECT_MAX_AGE = 21;
function generateRawYouthAttrs(tier, position) {
  return generateRawAttrsInRange(position, 10, 50, tier);
}

// `usedLastNames` (optionnel) : Set partagé par TOUT un effectif en cours de
// génération (voir generateTeam), pour éviter les doublons de nom de
// famille au sein d'une même équipe (pickUniqueLastName) — absent (appel
// isolé, hors génération d'effectif complet), on retombe sur un tirage
// classique.
function generatePlayer(position, tier, usedLastNames, country = "fr") {
  const { name, nationality } = generatePlayerIdentity(usedLastNames, country);
  const age = Math.round(rand(18, 33));
  // Poste de carte = meilleur poste dès la création (retour utilisateur
  // 2026-09-30, voir attrsForCardPosition).
  const gen = attrsForCardPosition(position, () => (age <= YOUNG_PROSPECT_MAX_AGE
    ? generateRawYouthAttrs(tier, position)
    : generateAttrsForPosition(position, tier)));
  return new Player({
    name,
    nationality,
    position: gen.position,
    height: heightForPosition(gen.position),
    age,
    attrs: gen.attrs,
    aggressiveness: Math.round(rand(15, 95)),
  });
}

function generateTeam(name, tier = 1, country = "fr") {
  const players = [];
  const usedLastNames = new Set();
  POSITIONS.forEach(pos => {
    for (let i = 0; i < 3; i++) players.push(generatePlayer(pos, tier * rand(0.9, 1.1), usedLastNames, country));
  });
  return new Team({ name, players, country });
}

// Effectif de TOUTE NOUVELLE carrière (voir initGame) : contrairement aux
// équipes adverses générées (generateTeam, dont la force suit le niveau de
// division — voir DIVISIONS/tierMultiplier), le club du joueur démarre
// comme un vrai groupe de débutants, sans aucune caractéristique
// développée (10-50, comme generateRawYouthAttrs), QUEL QUE SOIT L'ÂGE
// affiché — un effectif "de départ" n'a encore rien prouvé, tout reste à
// construire par l'entraînement (retour utilisateur : un effectif de
// départ avec un joueur déjà à 97 dans une caractéristique n'a pas de sens,
// une telle caractéristique doit se mériter par le jeu, pas être offerte
// gratuitement à la création).
// `usedLastNames` optionnel, même rôle que dans generatePlayer ci-dessus.
function generateRookiePlayer(position, usedLastNames = null, country = "fr") {
  const { name, nationality } = generatePlayerIdentity(usedLastNames, country);
  const age = Math.round(rand(18, 33));
  const gen = attrsForCardPosition(position, () => generateRawYouthAttrs(1, position));
  return new Player({
    name,
    nationality,
    position: gen.position,
    height: heightForPosition(gen.position),
    age,
    attrs: gen.attrs,
    aggressiveness: Math.round(rand(15, 95)),
  });
}

// Remplaçant d'un retraité dans un club de l'IA (voir League.
// retireAnnouncedPlayers) : un jeune de 20 à 23 ans au même poste, ramené au
// niveau moyen actuel de l'effectif (légèrement en dessous), avec de la
// marge de progression, pour que la ligue garde son niveau.
function generateRetirementReplacement(team, position) {
  const p = generateRookiePlayer(position);
  p.age = Math.round(rand(20, 23));
  p.position = position;
  p.attrs = attrsForCardPosition(position, () => generateAttrsForPosition(position, 1)).attrs;
  const target = Math.max(20, (typeof team.averageOverall === "function" ? team.averageOverall() : p.overall()) * rand(0.88, 0.98));
  for (let pass = 0; pass < 2; pass++) {
    const scale = target / Math.max(p.overall(), 1);
    ATTRS.forEach(a => { p.attrs[a] = clamp(Math.round(p.attrs[a] * scale), 1, 99); });
  }
  p.potential = clamp(Math.round(p.overall() + rand(4, 12)), 1, 99);
  p.position = bestPosition(p) || position;
  if (typeof salaryForOverall === "function") p.salary = salaryForOverall(levelCoefficientFor(p.attrs, p.position).coefficient);
  return p;
}

function generateStartingRoster(name, country = "fr") {

  const players = [];
  const usedLastNames = new Set();
  POSITIONS.forEach(pos => {
    for (let i = 0; i < 3; i++) players.push(generateRookiePlayer(pos, usedLastNames, country));
  });
  return new Team({ name, players, country });
}

// ---------------------------------------------------------------------
// Académie de jeunes — génération d'un candidat (voir Team.youthCandidates/
// refreshYouthCandidates). `recruiterLevel` (1 à 5, voir TRAINER_LEVELS,
// réutilisé) pilote à la fois la qualité moyenne (YOUTH_QUALITY_TIER_BY_LEVEL)
// et la chance d'un "outil brut" (YOUTH_STANDOUT_CHANCE_BY_LEVEL) — voir ces
// deux constantes plus haut pour le détail du calibrage.
// ---------------------------------------------------------------------
function generateYouthCandidate(now, recruiterLevel, country = "fr") {
  const position = pick(POSITIONS);
  const age = pick([15, 16, 17]);
  const tier = YOUTH_QUALITY_TIER_BY_LEVEL[recruiterLevel] || 1;
  // Attributs ACTUELS, chacun 10-30 (avant tier), VOLONTAIREMENT visibles
  // tels quels dans l'UI dès la proposition (contraste délibéré avec le
  // scoutisme adverse, où c'est l'inverse : les attributs sont cachés, pas le
  // potentiel) : voir le commentaire sur Team.youthCandidates au constructeur.
  // Légèrement orienté vers `position` depuis 2026-09 (même correctif que
  // generateRawYouthAttrs, voir generateRawAttrsInRange) : avant ça, le poste
  // tiré au sort (pick(POSITIONS) ci-dessus) n'avait aucun rapport avec les
  // attributs générés.
  const attrs = generateRawAttrsInRange(position, 10, 30, tier);
  // "Outil brut" : 1 ou 2 attributs (jamais plus) reçoivent un tirage plus
  // haut (31-40 avant tier) pour représenter un talent déjà repéré par le
  // recruteur — voir YOUTH_STANDOUT_CHANCE_BY_LEVEL.
  const standoutChance = YOUTH_STANDOUT_CHANCE_BY_LEVEL[recruiterLevel] || 0.2;
  if (rand01() < standoutChance) {
    const count = rand01() < 0.5 ? 1 : 2;
    shuffleIndices(ATTRS).slice(0, count).forEach(a => {
      attrs[a] = clamp(Math.round(rand(31, 40) * tier), 1, 99);
    });
  }
  // Centre de formation : uniquement des jeunes du pays du club.
  const identity = generatePlayerIdentity(null, country);
  if (country && NATION_BY_CODE[country] && rand01() < YOUTH_HOME_NATIONALITY_SHARE && identity.nationality !== country) {
    const pool = namePoolOf(NATION_BY_CODE[country].pool);
    identity.nationality = country;
    identity.name = `${pick(pool.first)} ${pick(pool.last)}`;
  }
  // Poste affiché = meilleur poste d'après ces caractéristiques (retour
  // utilisateur 2026-09-30) : un « outil brut » tiré au hasard peut le
  // déplacer, le libellé suit.
  const shownPosition = bestPosition({ attrs, position }) || position;
  const candidate = new Player({
    name: identity.name,
    nationality: identity.nationality,
    position: shownPosition,
    height: heightForPosition(shownPosition),
    age,
    attrs,
    aggressiveness: Math.round(rand(15, 95)),
  });
  // AUCUN plafond spécifique sur le potentiel d'un prospect de l'académie
  // (correctif 2026-09, retour utilisateur explicite : "un joueur du centre
  // de formation doit pouvoir avoir un potentiel jusqu'à 99 [...] doit
  // pouvoir devenir une superstar") — le constructeur Player vient déjà de
  // tirer le potentiel EXACTEMENT comme pour n'importe quel joueur
  // (potentialHeadroom(age) + overall() + clamp(1,99), qui vaut [20,50]
  // d'ÉCART ajouté à l'overall pour cet âge — PAS un plafond de 50 sur le
  // potentiel lui-même). Le "50" dont parle l'utilisateur ne concerne QUE
  // les CARACTÉRISTIQUES pendant la phase académie (voir le plafond
  // caractéristique par caractéristique dans Team.growYouthPlayers plus
  // bas) — jamais le potentiel, qui reste cette valeur brute 1-99 tirée
  // ici, cachée derrière youthProspectLabel (3 bandes grossières) tant que
  // le joueur n'est pas promu en pro.
  candidate.createdAt = now;
  candidate.expiresAt = now + YOUTH_CANDIDATE_EXPIRY_MS;
  return candidate;
}

// ---------------------------------------------------------------------
// CALENDRIER DE SAISON — championnat à 10 équipes (aller-retour) + play-offs
// ---------------------------------------------------------------------
// 9 adversaires générés + le club du joueur ("Lyon") = 10 équipes. Un
// championnat complet aller-retour : chaque équipe affronte les 9 autres
// deux fois (une à domicile, une à l'extérieur) = 18 journées. Avec 2
// journées jouées par semaine d'entraînement, ça fait 9 semaines de
// championnat, puis les play-offs (4 premiers, demies + finale en 2 matchs
// gagnants) pour une saison d'environ 10 semaines au total (voir
// SEASON_LENGTH_WEEKS).
const CPU_TEAM_NAMES = ["Paris", "Marseille", "Toulouse", "Nice", "Nantes", "Strasbourg", "Bordeaux", "Lille", "Rennes"];

// ---------------------------------------------------------------------
// PAYS DES CHAMPIONNATS (retour utilisateur, 2026-09-28 : "partons sur
// France et US pour voir comment ça marche", "chaque pays a ses propres
// horaires", "on va dans la division la plus haute où il y a un bot").
// Chaque pays a sa propre pyramide de championnats (voir server/world.js),
// ses horaires dans SON fuseau (setCalendarTimeZone), ses clubs CPU nommés
// d'après ses villes (COUNTRY_CPU_TEAM_NAMES, tirées sans doublon dans tout
// le pays) et ~60 % de joueurs du pays dans ses effectifs générés
// (generatePlayerIdentity, `homeCountry`).
// ---------------------------------------------------------------------
