const SPONSOR_CATALOG = [
  ...SPONSOR_CATALOG_FR.map(r => [...r, "fr"]),
  ...SPONSOR_CATALOG_EN.map(r => [...r, "en"]),
].map(([name, tier, sector, icon, bg, ink, shape, short, lang]) => ({ name, tier, sector, icon, bg, ink, shape, short, lang }));
const SPONSOR_CATALOG_BY_NAME = Object.fromEntries(SPONSOR_CATALOG.map(s => [s.name, s]));
// Liste des noms par palier, dérivée du catalogue (le reste du code tire
// toujours ses noms dans SPONSOR_NAMES).
// SPONSOR_NAMES = catalogue français (clubs de France / Belgique),
// SPONSOR_NAMES_EN = catalogue anglais (tous les autres pays).
function sponsorNamesByTier(lang) {
  const out = {};
  ["local", "regional", "national"].forEach(t => { out[t] = SPONSOR_CATALOG.filter(s => s.lang === lang && s.tier === t).map(s => s.name); });
  return out;
}
const SPONSOR_NAMES = sponsorNamesByTier("fr");
const SPONSOR_NAMES_EN = sponsorNamesByTier("en");
const SPONSOR_FRENCH_COUNTRIES = ["fr", "be"];
function sponsorCatalogLangFor(country) {
  return !country || SPONSOR_FRENCH_COUNTRIES.includes(String(country).toLowerCase()) ? "fr" : "en";
}
function sponsorNamesFor(country) {
  return sponsorCatalogLangFor(country) === "fr" ? SPONSOR_NAMES : SPONSOR_NAMES_EN;
}
// Anciens noms (avant le catalogue, 2026-10-01) → nouveau nom du même
// palier : appliqué aux offres / contrats / historique au chargement d'une
// sauvegarde (teamFromSave). Les libellés de transactions déjà écrits
// gardent l'ancien texte.
const SPONSOR_LEGACY_NAMES = {
  "Boulangerie Martin": "Le Fournil d'Or", "Garage Dupuis": "Garage Turbo", "Pizzeria Da Marco": "Pizza Alley-Oop",
  "Pharmacie du Centre": "Pharma+ Centre", "Bar des Sports": "Le Rebond", "Auto-école Lefèvre": "Feu Vert Conduite",
  "Fleurs & Co": "Pétales & Co", "Café de la Gare": "Café du Parquet", "Menuiserie Roche": "Atelier Copeau", "Cycles Bertrand": "Cycles Rayon",
  "Brasserie du Nord": "Brasserie La Mousse", "Banque Régionale": "Crédit du Plateau", "Fromagerie Bel Air": "Bel'Alpe",
  "Transports Roux": "Roulez Transports", "Immo Sud-Ouest": "Clé d'Or Immo", "Énergie Plateau": "Vallée Énergie",
  "Coopérative Val d'Or": "Coop Les Moissons", "Radio Horizon": "Swish FM",
  "Volt Énergie": "Voltéo", "Nexo Télécom": "Nexo Mobile", "Mistral Airlines": "Altitude Air", "Nova Boissons": "Nova Pulse", "Zenith Auto": "Zénith Motors",
};
function sponsorCatalogEntry(name) {
  return (name && SPONSOR_CATALOG_BY_NAME[name]) || null;
}
function migrateSponsorName(name) {
  return (name && SPONSOR_LEGACY_NAMES[name]) || name;
}
function migrateSponsorList(list) {
  return Array.isArray(list) ? list.map(x => (x && SPONSOR_LEGACY_NAMES[x.sponsorName] ? { ...x, sponsorName: SPONSOR_LEGACY_NAMES[x.sponsorName] } : x)) : [];
}
const SPONSOR_OFFER_TTL_MS = 7 * 24 * 3600 * 1000;
const SPONSOR_OFFER_INTERVAL_MS = 3 * 24 * 3600 * 1000;
const SPONSOR_MAX_OFFERS_PER_SLOT = 2;
const SPONSOR_PRIME_BASE_RATIO = 0.15; // prime par victoire = 15 % du fixe "normal"
const SPONSOR_REPUTATION_DEFAULT = 50;
const SPONSOR_REPUTATION_MISS = -12;
const SPONSOR_TERMINATION_WEEKS = 4;
const SPONSOR_HISTORY_MAX = 20;
const SEASON_OBJECTIVE_KEYS_ORDERED = ["maintien", "milieu-tableau", "playoffs", "finale", "titre"];

function sponsorDivisionFactor(divisionLevel) {
  const top = SPONSOR_DIVISION_SCALE[1];
  const mine = SPONSOR_DIVISION_SCALE[divisionLevel] || Math.round(top * 0.3);
  return Math.max(0.3, mine / top);
}
function sponsorReputationOf(team) {
  return typeof team.sponsorReputation === "number" ? team.sponsorReputation : SPONSOR_REPUTATION_DEFAULT;
}
function sponsorTiersAvailable(team, divisionLevel) {
  const rep = sponsorReputationOf(team);
  return Object.keys(SPONSOR_TIERS).filter(k => rep >= SPONSOR_TIERS[k].minReputation && (divisionLevel || 1) <= SPONSOR_TIERS[k].maxDivisionLevel);
}
function sponsorActiveContractForSlot(team, slotKey) {
  return (team.sponsorContracts || []).find(c => c.slot === slotKey && c.status === "active") || null;
}
function sponsorNameForSlot(team, slotKey) {
  const c = sponsorActiveContractForSlot(team, slotKey);
  return c ? c.sponsorName : null;
}
// Montants de sponsor : à la centaine, mais à la dizaine sous 1 000 $ (les
// petites primes du panneau publicitaire, 2026-09-30, finissaient
// arrondies à la même valeur d'un profil à l'autre).
function roundToHundred(v) { return v >= 1000 ? Math.round(v / 100) * 100 : Math.max(10, Math.round(v / 10) * 10); }

// Palier d'une vague d'offres pour un emplacement : le meilleur disponible
// le plus souvent, parfois le cran en dessous — mais le MÊME pour toutes les
// offres de l'emplacement (retour utilisateur 2026-09-26 : "le sponsor
// normal propose plus que le sponsor ambitieux, c'est bizarre" — deux
// paliers mélangés rendaient les profils illisibles).
function pickSponsorTier(team, divisionLevel) {
  const tiers = sponsorTiersAvailable(team, divisionLevel);
  return tiers.length > 1 && rand01() < 0.35 ? tiers[Math.max(0, tiers.length - 2)] : tiers[tiers.length - 1];
}
function generateSponsorOffer(team, league, slotKey, profileKey, now, tierKey = null, sharedJitter = null) {
  const divisionLevel = league.divisionLevel || 1;
  const tier = tierKey && SPONSOR_TIERS[tierKey] ? tierKey : pickSponsorTier(team, divisionLevel);
  const slot = SPONSOR_SLOTS.find(s => s.key === slotKey);
  const profile = SPONSOR_PROFILES[profileKey];
  const used = new Set([...(team.sponsorOffers || []), ...(team.sponsorContracts || [])].map(x => x.sponsorName));
  // Catalogue selon le pays du club (France / Belgique → noms français,
  // sinon noms anglais), voir sponsorCatalogLangFor.
  const names = sponsorNamesFor(league.country || team.country)[tier];
  const pool = names.filter(n => !used.has(n));
  const sponsorName = pool.length ? pool[Math.floor(rand01() * pool.length)] : names[Math.floor(rand01() * names.length)];
  const baseKey = SEASON_OBJECTIVE_KEYS_ORDERED.includes(team.seasonObjective) ? team.seasonObjective : "maintien";
  const idx = clamp(SEASON_OBJECTIVE_KEYS_ORDERED.indexOf(baseKey) + profile.objectiveShift, 0, SEASON_OBJECTIVE_KEYS_ORDERED.length - 1);
  const objectiveKey = SEASON_OBJECTIVE_KEYS_ORDERED[idx];
  const jitter = sharedJitter != null ? sharedJitter : 0.9 + rand01() * 0.2;
  const normalWeekly = SPONSOR_TIERS[tier].baseWeekly * slot.mult * sponsorDivisionFactor(divisionLevel) * jitter;
  const weekly = roundToHundred(normalWeekly * profile.fixedMult);
  const winPrime = roundToHundred(normalWeekly * SPONSOR_PRIME_BASE_RATIO * profile.primeMult);
  const bonus = weekly * profile.bonusWeeks;
  const quote = profile.quotes[Math.floor(rand01() * profile.quotes.length)];
  return {
    id: `spo_${uid()}`, sponsorName, tier, tierLabel: SPONSOR_TIERS[tier].label,
    slot: slotKey, slotLabel: slot.label, profile: profileKey, profileLabel: profile.label, quote,
    weekly, winPrime, bonus, jitter,
    objectiveKey, objectiveTier: SEASON_OBJECTIVE_TIERS[objectiveKey], objectiveLabel: SEASON_OBJECTIVE_LABELS[objectiveKey],
    createdAt: now, expiresAt: now + SPONSOR_OFFER_TTL_MS,
  };
}
// Purge les offres expirées et en fait arriver de nouvelles sur les
// emplacements libres : tout de suite si le club n'a jamais été approché,
// sinon tous les 3 jours. Deux offres max par emplacement, de profils
// différents. Renvoie les offres créées.
function refreshSponsorOffers(team, league, now = Date.now()) {
  if (!team || !league) return [];
  team.sponsorOffers = (team.sponsorOffers || []).filter(o => o.expiresAt > now && !sponsorActiveContractForSlot(team, o.slot));
  const firstTime = !team.lastSponsorOfferAt;
  if (!firstTime && now - team.lastSponsorOfferAt < SPONSOR_OFFER_INTERVAL_MS) return [];
  const created = [];
  SPONSOR_SLOTS.forEach(slot => {
    if (sponsorActiveContractForSlot(team, slot.key)) return;
    const existing = team.sponsorOffers.filter(o => o.slot === slot.key);
    if (existing.length >= SPONSOR_MAX_OFFERS_PER_SLOT) return;
    if (!firstTime && existing.length > 0 && rand01() < 0.5) return;
    const usedProfiles = new Set(existing.map(o => o.profile));
    const candidates = SPONSOR_PROFILE_KEYS.filter(k => !usedProfiles.has(k));
    const want = Math.min(SPONSOR_MAX_OFFERS_PER_SLOT - existing.length, firstTime ? 2 : 1);
    // Même palier que les offres déjà présentes sur l'emplacement, sinon un
    // palier tiré une fois pour toute la vague.
    const tier = existing.length ? existing[0].tier : pickSponsorTier(team, league.divisionLevel || 1);
    // Même variation aléatoire pour les offres d'un même emplacement : sinon
    // une offre Prudente pouvait afficher un plus gros bonus qu'une Normale.
    const jitter = existing.length && existing[0].jitter ? existing[0].jitter : 0.9 + rand01() * 0.2;
    for (let i = 0; i < want && candidates.length; i++) {
      const k = candidates.splice(Math.floor(rand01() * candidates.length), 1)[0];
      const offer = generateSponsorOffer(team, league, slot.key, k, now, tier, jitter);
      team.sponsorOffers.push(offer);
      created.push(offer);
    }
  });
  team.lastSponsorOfferAt = now;
  return created;
}
function acceptSponsorOffer(team, league, offerId, now = Date.now()) {
  const offer = (team.sponsorOffers || []).find(o => o.id === offerId);
  if (!offer) return { ok: false, error: "Cette offre n'existe plus." };
  if (offer.expiresAt <= now) { team.sponsorOffers = team.sponsorOffers.filter(o => o.id !== offerId); return { ok: false, error: "Cette offre a expiré." }; }
  if (sponsorActiveContractForSlot(team, offer.slot)) return { ok: false, error: "Cet emplacement a déjà un sponsor." };
  const contract = { ...offer, id: `spc_${uid()}`, offerId: offer.id, signedAt: now, signedWeek: team.week, seasonId: league.seasonId || null, status: "active", weeksPaid: 0, wins: 0, primesPaid: 0, settledSeasonId: null };
  delete contract.expiresAt;
  team.sponsorContracts = [...(team.sponsorContracts || []), contract];
  team.sponsorOffers = team.sponsorOffers.filter(o => o.slot !== offer.slot);
  return { ok: true, contract };
}
function declineSponsorOffer(team, offerId) {
  const before = (team.sponsorOffers || []).length;
  team.sponsorOffers = (team.sponsorOffers || []).filter(o => o.id !== offerId);
  return team.sponsorOffers.length < before ? { ok: true } : { ok: false, error: "Cette offre n'existe plus." };
}
function sponsorTerminationFee(contract) { return contract.weekly * SPONSOR_TERMINATION_WEEKS; }
// Clause de rupture : le manager PAIE pour quitter un contrat en cours (la
// seule sortie d'argent liée aux sponsors). Aucun effet sur la réputation.
function terminateSponsorContract(team, contractId, now = Date.now()) {
  const contract = (team.sponsorContracts || []).find(c => c.id === contractId && c.status === "active");
  if (!contract) return { ok: false, error: "Contrat introuvable." };
  const fee = sponsorTerminationFee(contract);
  if ((team.budget || 0) < fee) return { ok: false, error: `Budget insuffisant pour la clause de rupture (${fee.toLocaleString("fr-FR")} $).` };
  team.recordTransaction(`Clause de rupture ${contract.sponsorName}`, -fee);
  contract.status = "terminated"; contract.endedAt = now;
  team.sponsorHistory = [{ ...contract }, ...(team.sponsorHistory || [])].slice(0, SPONSOR_HISTORY_MAX);
  team.sponsorContracts = team.sponsorContracts.filter(c => c.id !== contractId);
  return { ok: true, fee };
}
// Appelée par Team.trainWeek : fixe de chaque contrat actif.
function collectSponsorIncome(team) {
  let total = 0;
  (team.sponsorContracts || []).forEach(c => {
    if (c.status !== "active") return;
    team.recordTransaction(`Sponsor ${c.sponsorName} (${c.slotLabel})`, c.weekly);
    c.weeksPaid = (c.weeksPaid || 0) + 1;
    total += c.weekly;
  });
  return total;
}
// Prime par victoire officielle : appelée par League.recordResult /
// recordCupMatchResult / recordPlayoffGameResult pour le vainqueur (jamais
// pour une ligue privée, qui ne passe pas par là).
function applySponsorWinPrimes(team) {
  if (!team || !team.isHuman && !team.sponsorContracts) return 0;
  let total = 0;
  (team.sponsorContracts || []).forEach(c => {
    if (c.status !== "active" || !c.winPrime) return;
    team.recordTransaction(`Prime de victoire ${c.sponsorName}`, c.winPrime);
    c.wins = (c.wins || 0) + 1;
    c.primesPaid = (c.primesPaid || 0) + c.winPrime;
    total += c.winPrime;
  });
  return total;
}
// Règlement de fin de saison (idempotent par contrat) : objectif atteint →
// bonus versé + réputation en hausse selon le profil ; raté → pas de bonus,
// contrat rompu, réputation −12. Renvoie les verdicts.
function settleSponsorsAtSeasonEnd(league, teamIdx, now = Date.now()) {
  const team = league.teams[teamIdx];
  if (!team) return [];
  const achieved = seasonAchievementTier(league, teamIdx);
  if (achieved == null) return [];
  const seasonId = league.seasonId || `start:${league.calendarStartAt || 0}`;
  const verdicts = [];
  (team.sponsorContracts || []).forEach(c => {
    if (c.status !== "active" || c.settledSeasonId === seasonId) return;
    const met = achieved >= c.objectiveTier;
    c.settledSeasonId = seasonId; c.endedAt = now;
    const profile = SPONSOR_PROFILES[c.profile] || SPONSOR_PROFILES.normal;
    if (met) {
      team.recordTransaction(`Bonus d'objectif ${c.sponsorName} (${c.objectiveLabel})`, c.bonus);
      c.status = "completed";
      c.reputationDelta = profile.reputationMet;
    } else {
      c.status = "breached";
      c.reputationDelta = SPONSOR_REPUTATION_MISS;
    }
    team.sponsorReputation = clamp(sponsorReputationOf(team) + c.reputationDelta, 0, 100);
    verdicts.push({ contractId: c.id, sponsorName: c.sponsorName, slot: c.slot, met, bonus: met ? c.bonus : 0, reputationDelta: c.reputationDelta });
    team.sponsorHistory = [{ ...c }, ...(team.sponsorHistory || [])].slice(0, SPONSOR_HISTORY_MAX);
  });
  team.sponsorContracts = (team.sponsorContracts || []).filter(c => c.status === "active");
  return verdicts;
}

// Calendrier aller-retour par la "méthode du cercle" : une équipe reste
// fixe, les (n-1) autres tournent autour d'elle à chaque journée. n doit
// être pair (10 ici, donc jamais de journée de repos à gérer). Renvoie un
// tableau de journées, chacune un tableau de {home, away} (index dans le
// tableau d'équipes passé à League). Les (n-1) premières journées sont
// l'aller, les (n-1) suivantes le retour (mêmes duels, domicile/extérieur
// inversés).
function generateRoundRobinSchedule(n) {
  const idx = Array.from({ length: n }, (_, i) => i);
  const fixed = idx[0];
  let rotating = idx.slice(1);
  const firstLeg = [];
  for (let r = 0; r < n - 1; r++) {
    const ring = [fixed, ...rotating];
    const round = [];
    for (let i = 0; i < n / 2; i++) {
      const home = ring[i], away = ring[n - 1 - i];
      // Alterne qui reçoit à chaque journée pour ne pas toujours donner
      // l'avantage du terrain aux mêmes équipes sur l'aller.
      round.push(r % 2 === 0 ? { home, away } : { home: away, away: home });
    }
    firstLeg.push(round);
    rotating.unshift(rotating.pop());
  }
  const secondLeg = firstLeg.map(round => round.map(m => ({ home: m.away, away: m.home })));
  return [...firstLeg, ...secondLeg];
}

// ---------------------------------------------------------------------
// COUPE (retour utilisateur, 2026-09 — "la vraie saison de test" : "3 matchs
// par jour : Championnat 10h, Coupe 15h, Championnat 19h" + "une vraie
// compétition de Coupe" pour remplacer l'onglet "Coupe" jusqu'ici un simple
// placeholder côté navigateur) : élimination directe, TOUTES les équipes de
// la ligue multi-manager (humaines ET CPU, indiscernables dans le tirage —
// exactement comme un duel de championnat, voir Team.isHuman). Réservé à
// generateMultiManagerLeague (voir plus bas) — jamais pour generateLeague
// (carrière solo), qui n'a pas de calendrier ancré quotidien (voir
// League.calendarDailyAnchored) donc pas de créneau de 15h où faire vivre
// une coupe.
//
// Taille du tableau : la puissance de 2 immédiatement au-dessus du nombre
// d'équipes (16 pour 10 équipes) — 16-10 = 6 équipes tirées au sort reçoivent
// un "bye" (qualification directe, aucun match) pour le 1er tour, les 4
// restantes jouent 2 vrais matchs. Le tirage au sort (byes ET
// appariements, à CHAQUE tour) est purement aléatoire : aucune notion de
// tête de série n'a de sens avant le début de saison (pas encore de
// classement, voir le retour utilisateur explicite) — non déterministe par
// nature (voir shuffleIndices), les tests figent Math.random comme ailleurs
// dans ce projet (voir coach_market_test.js/transfer_market_test.js).
//
// 4 tours, nommés comme un VRAI tableau à 16 (même si le 1er n'est que
// partiel, 2 matchs sur 8 "places") : huitièmes (huitiemes) -> quarts
// (quarts) -> demies (demies) -> finale (finale). Le tour suivant n'est
// engendré qu'une fois le précédent ENTIÈREMENT résolu (voir
// League.advanceCup), jamais à l'avance — c'est ce qui fait "avancer" la
// coupe d'un jour à chaque tour joué (voir server/autoSim.js), et permet de
// savoir à tout instant qu'"aucun tour n'est dû" (league.cup.champion déjà
// connu, ou pendingCupRound() ci-dessous qui renvoie null) : le créneau de
// 15h reste alors simplement VIDE ce jour-là (voir server/liveMatch.js).
const CUP_BRACKET_SIZE = 16;
const CUP_STAGE_NAMES = ["huitiemes", "quarts", "demies", "finale"];
// Primes de Coupe (retour utilisateur 2026-09-28 : inspiré de BuzzerBeater,
// « modifie un peu le barème, ne fais pas un copié-collé ») :
// versée au club humain qui GAGNE un match de Coupe, selon le tour
// (distance à la finale : 0 = finale, 1 = demi-finale…). Un exempt ne
// rapporte rien.
const CUP_WIN_BONUS_BY_STAGE_FROM_END = [400000, 200000, 130000, 100000, 80000, 65000];
const CUP_WIN_BONUS_FLOOR = 50000; // 64e de finale et avant
const CUP_STAGE_LABELS_FROM_END = ["finale", "demi-finale", "quart de finale", "huitième de finale", "seizième de finale", "32e de finale", "64e de finale", "128e de finale", "256e de finale"];
function cupWinBonusFor(stageFromEnd) {
  return stageFromEnd >= 0 && stageFromEnd < CUP_WIN_BONUS_BY_STAGE_FROM_END.length ? CUP_WIN_BONUS_BY_STAGE_FROM_END[stageFromEnd] : CUP_WIN_BONUS_FLOOR;
}
function payCupWinBonus(team, stageFromEnd) {
  if (!team || !team.isHuman || typeof team.recordTransaction !== "function") return 0;
  const amount = cupWinBonusFor(stageFromEnd);
  team.recordTransaction(`Prime de Coupe (${CUP_STAGE_LABELS_FROM_END[stageFromEnd] || "tour"})`, amount);
  return amount;
}

function cupNextStageName(name) {
  return CUP_STAGE_NAMES[CUP_STAGE_NAMES.indexOf(name) + 1] || null;
}

// Mélange de Fisher-Yates (copie — ne modifie jamais `arr` en place) : même
// esprit que `pick` ci-dessus (Math.random direct, jamais de générateur
// seedé), pour rester testable en figeant Math.random comme le reste du
// projet.
function shuffleIndices(arr) {
  const out = [...arr];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand01() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

// 1er tour (huitièmes, partiel) — voir le grand commentaire ci-dessus pour
// le détail du tirage. `teamIdxs` : tous les index d'équipes de la ligue
// (0..9 pour 10 équipes) dans LEUR ordre naturel (this.teams) — le tirage au
// sort se fait ICI, pas en amont. Chaque bye est représenté par un "match"
// avec `away: null` (déjà `resolved`/`winner` posés, aucune diffusion ni
// simulation nécessaire — voir server/liveMatch.js) plutôt que par une
// entrée séparée, pour que `round.matches` reste la liste UNIQUE de toutes
// les places du tour (byes comprises) que l'UI (voir moteurbasket3.html)
// parcourt pour afficher le tableau complet, "Exempt" compris.
function generateCupBracket(teamIdxs) {
  const shuffled = shuffleIndices(teamIdxs);
  const byeCount = CUP_BRACKET_SIZE - teamIdxs.length;
  const byeTeams = shuffled.slice(0, byeCount);
  const playInTeams = shuffled.slice(byeCount);
  const matches = [];
  byeTeams.forEach(t => {
    matches.push({ home: t, away: null, scoreHome: null, scoreAway: null, forfeit: null, winner: t, resolved: true, bye: true });
  });
  for (let i = 0; i < playInTeams.length; i += 2) {
    matches.push({
      home: playInTeams[i], away: playInTeams[i + 1],
      scoreHome: null, scoreAway: null, forfeit: null, winner: null, resolved: false, bye: false,
    });
  }
  return { index: 0, name: CUP_STAGE_NAMES[0], dayIndex: 0, matches, resolved: false };
}

// Tour suivant : apparie aléatoirement les vainqueurs de `prevRound` (jamais
// de choix du joueur — retour utilisateur explicite, "no player choice
// involved in matchups") — toujours une puissance de 2 (8, 4, 2), donc
// jamais de bye à ce stade (uniquement au 1er tour, voir generateCupBracket).
// `dayIndex` = celui de `prevRound` + 1 : la coupe avance d'exactement un
// jour civil par tour joué (voir dailyAnchoredScheduledTimeForCupRound côté
// server/calendar.js).
function buildNextCupRound(prevRound, winners) {
  const shuffled = shuffleIndices(winners);
  const matches = [];
  for (let i = 0; i < shuffled.length; i += 2) {
    matches.push({
      home: shuffled[i], away: shuffled[i + 1],
      scoreHome: null, scoreAway: null, forfeit: null, winner: null, resolved: false, bye: false,
    });
  }
  return { index: prevRound.index + 1, name: cupNextStageName(prevRound.name), dayIndex: prevRound.dayIndex + 1, matches, resolved: false };
}

// Simule un match, ou déclare forfait si l'une des deux équipes (ou les
// deux) ne peut plus aligner les 5 postes de sa feuille de match — retour
// utilisateur explicite : "si on n'a plus suffisamment de joueurs sur la
// feuille de match, c'est forfait 20 à 0", en complément direct de la
// suppression du plancher de vente (voir Team.sellPlayer/
// League.listPlayerForSale) : un club qui a vendu trop de joueurs doit
// perdre son match, pas bloquer la suite de la saison. S'appuie sur
// Team.hasValidLineup (déjà maintenu à jour par Team.autoAssignLineup après
// chaque vente/achat — voir sellPlayer/_resolveListing) : AUCUNE
// vérification supplémentaire de taille d'effectif ici, uniquement "les 5
// postes ont-ils un titulaire valide ?". Si les DEUX équipes sont en défaut
// à la fois (cas limite), forfait mutuel 0-0 : aucune des deux ne peut
// matériellement disputer le match. Renvoie { scoreHome, scoreAway, forfeit }
// où `forfeit` vaut "home" | "away" | "both" | null (null = match normal,
// vraiment simulé par MatchEngine).
// Enregistre les stats de CE match dans le journal de chaque joueur ayant
// réellement joué (secondsPlayed > 0) — alimente les stats de saison / MVP
// de la dernière journée (onglet Ligue) et les pages joueur ("match par
// match + une moyenne", onglet Effectif). Un SEUL point d'écriture pour
// TOUT match réellement simulé (championnat OU coupe, diffusé en direct OU
// résolu directement par simulateOrForfeit) : voir server/liveMatch.js —
// finalizeRound/finalizeCupRound l'appellent juste après avoir déterminé
// scoreHome/scoreAway/forfeit, pour les DEUX équipes, et JAMAIS pour un
// forfait (qui n'a jamais appelé MatchEngine.simulate(), donc p.stats/
// p.secondsPlayed restent ceux — périmés — du match précédent de ce joueur).
// `quarterScores` (optionnel, {home:[...], away:[...]}, voir simulateOrForfeit
// ci-dessous) : simplement recopié tel quel sur CHAQUE entrée matchLog posée
// ici (identique côté home et côté away, ce n'est qu'une info sur LE match,
// pas sur ce joueur) — lu ensuite par boxscoreRowsFromMatchLog côté client
// pour afficher le score par quart-temps sur la feuille de match (retour
// Discord d'Ariane, relayé par l'utilisateur, 2026-09-24). `null`/absent
// pour tout appelant qui ne la fournit pas encore (aucune régression sur les
// matchs déjà persistés avant ce correctif, ni sur les appels de test qui
// ne s'en soucient pas).
function recordMatchStatsForTeam(team, round, competition, now = Date.now(), quarterScores = null, tacticsUsed = null, seed = null, meta = null) {
  // Connaissance tactique (voir Team.updateTacticalKnowledge) : une seule
  // fois par match RÉELLEMENT joué (pas par joueur), compare la tactique de
  // ce match à celle du précédent.
  // Amical : la coquille porte les VRAIS joueurs, leur connaissance est
  // gérée à part (Team.gainTacticalKnowledgeFromFriendly sur le vrai club).
  if (team.updateTacticalKnowledge && competition !== "friendly") team.updateTacticalKnowledge(now);
  // Alchimie : jouer ensemble soude le groupe (voir updateChemistryAfterMatch).
  if (team.updateChemistryAfterMatch) team.updateChemistryAfterMatch();
  team.players.forEach(p => {
    if (p.secondsPlayed > 0) {
      // Forme physique (voir CONDITION_STATES/conditionLossForMinutes plus
      // haut) : perte selon les minutes RÉELLEMENT jouées ce match,
      // appliquée sur matchCondition (déjà rattrapé des jours de repos par
      // resetForMatch), jamais sur l'ancien Player.condition stocké
      // directement, pour ne jamais compter deux fois la récupération.
      // `matchCondition ?? currentCondition(...)` en filet de sécurité si
      // cette fonction est appelée sans resetForMatch préalable (voir les
      // tests qui l'appellent directement sur un joueur déjà mis en jeu à
      // la main). `conditionUpdatedAt` posé à `now` : la prochaine
      // récupération (voir currentCondition) repartira de CE match.
      const baseCondition = p.matchCondition ?? currentCondition(p, now, team.conditionRecoveryPerDay());
      p.condition = clamp(Math.round(baseCondition - conditionLossForMinutes(p.secondsPlayed / 60)), 0, 100);
      p.conditionUpdatedAt = now;
      // Bonus temporaire de MVP consommé (voir Player.pendingMatchBoost/eff()
      // /MVP_ATTR_BONUS/awardMatchMvp) : ce joueur vient justement de
      // disputer un match (p.stats/p.secondsPlayed au-dessus en témoignent),
      // donc un bonus en attente a déjà fait effet PENDANT MatchEngine.
      // simulate() (eff() le lit en direct) — on l'efface maintenant pour
      // qu'il ne s'applique pas une deuxième fois au match suivant. Un seul
      // match "boosté" par élection au MVP, jamais plus.
      if (p.pendingMatchBoost) p.pendingMatchBoost = 0;
      if (!Array.isArray(p.matchLog)) p.matchLog = [];
      // Gros match (historique du joueur, voir BIG_GAME_THRESHOLDS).
      Object.entries(BIG_GAME_THRESHOLDS).forEach(([k, min]) => {
        const v = (p.stats && p.stats[k]) || 0;
        if (v >= min) recordPlayerEvent(p, { type: "game", stat: k, value: v, competition, round, team: team.name, at: now, season: teamSeasonNo(team) });
      });
      p.matchLog.push({
        // `week` = team.week AU MOMENT de ce match (avant tout trainWeek()
        // suivant qui l'incrémenterait) — même sémantique que
        // Team.recordTransaction/recordMoraleEvent (voir leur `week: this.week`
        // plus haut), pour pouvoir regrouper les matchs par semaine
        // d'entraînement (onglet 📈 Stats hebdo) sans dépendre des formules du
        // calendrier (classique/accéléré/ancré quotidien) : `team.week` est
        // déjà correct dans TOUS les modes, contrairement à un round/2.
        round, competition, week: team.week,
        // Club pour lequel ce match a été joué (retour utilisateur
        // 2026-10-03 : une recrue apportait ses matchs de son ancien club
        // dans la feuille de match de la même journée de son nouveau club).
        team: team.name,
        // Domicile/extérieur, adversaire et date (archives des saisons, voir
        // buildSeasonArchive) : absents des matchs d'avant le 2026-10-04.
        ...(meta ? { isHome: !!meta.isHome, opponent: meta.opponent || null } : null),
        at: now,
        min: Math.max(1, Math.round(p.secondsPlayed / 60)),
        pts: p.stats.pts || 0, reb: p.stats.reb || 0, oreb: p.stats.oreb || 0, dreb: p.stats.dreb || 0,
        ast: p.stats.ast || 0, stl: p.stats.stl || 0, blk: p.stats.blk || 0, tov: p.stats.tov || 0, pf: p.stats.pf || 0,
        fgm2: p.stats.fgm2 || 0, fga2: p.stats.fga2 || 0, fgm3: p.stats.fgm3 || 0, fga3: p.stats.fga3 || 0,
        ftm: p.stats.ftm || 0, fta: p.stats.fta || 0,
        // Voir emptyStats() : sous-ensemble de fga2/fgm2, uniquement les tirs
        // en zone "inside". `|| 0` de rigueur pour tout matchLog déjà persisté
        // avant cette fonctionnalité (jamais lu par du code plus ancien).
        paintAtt: p.stats.paintAtt || 0, paintMade: p.stats.paintMade || 0,
        // Tirs par emplacement précis (voir shotSpotFor), absents des matchs
        // d'avant le 2026-09-30 : { ra: [tentés, réussis], ... }.
        ...(p.stats.spots ? { spots: JSON.parse(JSON.stringify(p.stats.spots)) } : {}),
        // Origine des points (voir emptyStats), absente des matchs d'avant.
        ptsPaint: p.stats.ptsPaint || 0, ptsMid: p.stats.ptsMid || 0, pts3: p.stats.pts3 || 0,
        ptsSecondChance: p.stats.ptsSecondChance || 0, ptsTransition: p.stats.ptsTransition || 0,
        ptsAssisted: p.stats.ptsAssisted || 0, ptsSolo: p.stats.ptsSolo || 0,
        // +/- (voir MatchEngine.applyPlusMinusForPoints/emptyStats plus haut) :
        // figé ici pour survivre à la remise à zéro de p.stats au prochain
        // match (resetForMatch), tout comme le reste de cette entrée.
        plusMinus: p.stats.plusMinus || 0,
        // Score par quart-temps du MATCH (pas de ce joueur) — voir le grand
        // commentaire au-dessus de la signature de cette fonction.
        quarterScores,
        // Tactique utilisée par CETTE équipe pour ce match (retour
        // utilisateur, 2026-09 : "Scouting Pro" — graphiques de fréquence
        // des systèmes offensifs/défensifs adverses, voir
        // server/scouting.js:aggregateStrategyUsage) : `{defense, offense,
        // rhythm}`, capturée au moment RÉEL de la simulation (voir
        // Engine.simulateOrForfeit/server/liveMatch.js:computeLiveMatch),
        // PAS relue ici depuis `team.defense` — un manager peut avoir déjà
        // changé ses ordres pour son PROCHAIN match avant que cette
        // fonction ne s'exécute (diffusion en direct étalée dans le temps
        // réel), donc `team.defense` au moment de cet appel ne reflète pas
        // forcément ce qui a été RÉELLEMENT joué ce match-ci. `offense` =
        // SEULE la priorité offensive n°1 du moment (team.offensivePriorities
        // est un classement de 3, pas un choix unique comme la défense/le
        // rythme — voir Team.constructor) : simplification délibérée pour
        // ce graphique de fréquence, la priorité n°1 est la plus proche
        // équivalent d'un "système joué" au sens BuzzerBeater. `null` pour
        // un forfait (voir Engine.simulateOrForfeit, aucune tactique n'a
        // été réellement mise en œuvre) ou pour tout matchLog déjà persisté
        // avant cette fonctionnalité.
        tacticsUsed: tacticsUsed || null,
        // Titulaire sur ce match (6e homme, voir computeSeasonAwards).
        starter: !!p.isStarterThisMatch,
        // Graine du match (voir MatchEngine.simulate) : permet de rejouer
        // à l'identique un match signalé. Absente des anciens matchs.
        ...(seed != null ? { seed } : null),
      });
    }
  });
}

// MVP automatique du match (retour utilisateur, 2026-09, voir le grand
// commentaire de MVP_ATTR_BONUS/MVP_QUOTES plus haut) : meilleure évaluation
// PIR (statEvaluation) toutes équipes confondues, parmi les joueurs ayant
// réellement joué CE match (secondsPlayed > 0, exactement le même filtre que
// recordMatchStatsForTeam ci-dessus, qui DOIT avoir déjà été appelée pour
// `home` ET `away` avant cet appel — sinon `matchLog` n'a pas encore la
// nouvelle entrée à marquer). Fige la citation sur l'entrée matchLog du
// joueur élu (isMvp/mvpQuote, lue par boxscoreRowsFromMatchLog côté client
// pour le box score d'un match déjà joué) et pose Team.lastMatchMvp pour LES
// DEUX équipes (le MVP peut appartenir à l'une ou l'autre, voir son
// commentaire au constructeur), affiché sur le tableau de bord. Accorde
// aussi le bonus temporaire (voir Player.pendingMatchBoost/MVP_ATTR_BONUS).
// Ne fait rien (renvoie `null`) si aucun joueur n'a joué des deux côtés (cas
// théorique d'un double forfait, qui n'appelle jamais cette fonction en
// pratique — voir finalizeRound/finalizeCupRound, `if (!forfeit)`).
function awardMatchMvp(home, away, round, competition, now = Date.now()) {
  const rows = [];
  [home, away].forEach(team => {
    team.players.forEach(p => {
      if (p.secondsPlayed > 0) rows.push({ team, player: p, evalScore: statEvaluation(p.stats) });
    });
  });
  if (!rows.length) return null;
  let best = rows[0];
  rows.forEach(r => { if (r.evalScore > best.evalScore) best = r; });
  const { team: mvpTeam, player: p, evalScore } = best;
  const quote = pick(MVP_QUOTES);
  const lastEntry = Array.isArray(p.matchLog) ? p.matchLog[p.matchLog.length - 1] : null;
  if (lastEntry && lastEntry.round === round && lastEntry.competition === competition) {
    lastEntry.isMvp = true;
    lastEntry.mvpQuote = quote;
  }
  p.pendingMatchBoost = MVP_ATTR_BONUS;
  const mvpInfo = {
    playerName: p.name, teamName: mvpTeam.name, quote,
    evalScore: Math.round(evalScore * 10) / 10, round, competition, at: now,
  };
  home.lastMatchMvp = mvpInfo;
  away.lastMatchMvp = mvpInfo;
  return mvpInfo;
}

// Combine recordMatchStatsForTeam (les DEUX équipes) et awardMatchMvp en un
// seul point d'appel (retour utilisateur, voir le commentaire d'awardMatchMvp
// ci-dessus pour pourquoi l'ordre importe) : remplace les deux appels
// séparés à recordMatchStatsForTeam qu'utilisaient jusqu'ici finalizeRound/
// finalizeCupRound (server/liveMatch.js), pour qu'aucun futur appelant ne
// puisse oublier d'accorder le MVP après avoir enregistré les stats.
// `quarterScores` (optionnel, voir recordMatchStatsForTeam) : simplement
// relayé aux deux équipes. `tacticsUsed` (optionnel, voir
// recordMatchStatsForTeam et Engine.simulateOrForfeit) : `{home:{defense,
// offense,rhythm}, away:{...}}`, éclaté ici en un objet PLAT par équipe
// avant de le relayer (chaque matchLog ne porte que la tactique de SA
// PROPRE équipe, jamais celle de l'adversaire — contrairement à
// quarterScores, qui reste volontairement le même objet {home,away} des
// deux côtés pour l'affichage de la feuille de match).
// Ordres complets d'un match qui vient d'être joué (onglet Tactiques :
// « partir d'un match précédent »), clubs humains seulement. Appelé AVANT
// toute application du plan de la journée suivante : les ordres en direct
// sont bien ceux de ce match.
// Ordres d'un match hors championnat/coupe (ligue privée, amical, retour
// utilisateur 2026-10-03 : « il faut pouvoir récupérer une tactique depuis
// un match de LP, amical ou coupe ») : `entry` = { competition, round,
// at, opponentName, isHome, scoreFor, scoreAgainst, orders, revealAt? }.
function pushOrdersHistory(team, entry) {
  if (!team || !team.isHuman || !entry || !entry.orders) return;
  if (!Array.isArray(team.ordersHistory)) team.ordersHistory = [];
  team.ordersHistory.unshift({ ...entry, orders: tacticPresetOrdersFrom(entry.orders) });
  if (team.ordersHistory.length > ORDERS_HISTORY_MAX) team.ordersHistory.length = ORDERS_HISTORY_MAX;
}
function recordOrdersHistory(team, opponent, isHome, round, competition, now, quarterScores) {
  if (!team || !team.isHuman || !team.snapshotTactics) return;
  // Ordres réellement joués pour ce match (Coupe : voir Team.runWithMatchPlan),
  // sinon les ordres en direct.
  const usedKey = planKey(round, competition);
  const used = team.matchOrdersUsed && team.matchOrdersUsed[usedKey];
  if (used) delete team.matchOrdersUsed[usedKey];
  if (!Array.isArray(team.ordersHistory)) team.ordersHistory = [];
  const sum = arr => Array.isArray(arr) ? arr.reduce((a, b) => a + (b || 0), 0) : null;
  const qs = quarterScores || {};
  const mine = sum(isHome ? qs.home : qs.away), theirs = sum(isHome ? qs.away : qs.home);
  team.ordersHistory.unshift({
    round, competition: competition || "championship", at: now,
    opponentName: opponent ? opponent.name : null, isHome,
    scoreFor: mine, scoreAgainst: theirs,
    orders: tacticPresetOrdersFrom(used || team.snapshotTactics()),
  });
  if (team.ordersHistory.length > ORDERS_HISTORY_MAX) team.ordersHistory.length = ORDERS_HISTORY_MAX;
}

// ---------------------------------------------------------------------
// RIVALITÉS ET NOTE DES MANAGERS (2026-09-29, retour utilisateur : « un bilan
// face à face entre deux managers humains […] une émission Derby » et « un
// classement mondial des managers […] contre des adversaires humains »).
// À chaque match OFFICIEL (championnat, play-offs, barrage, Coupe, Coupe
// nationale, Supercoupe ; jamais les amicaux, qui passent ailleurs) entre
// deux clubs de managers humains :
// - Team.rivalries[clé du club adverse] : bilan V/D, points pour/contre et
//   les RIVALRY_RECENT_MAX derniers matchs ; clé = nom du club en minuscules
//   (unique dans le monde et jamais modifié après l'inscription) ;
// - Team.managerRating : note Elo (départ 1500, K = 24), managerRatedGames.
// Le score vient des quarts-temps (sans le handicap de Coupe nationale).
// Miroir identique engine.js ⇄ moteurbasket3.html.
// ---------------------------------------------------------------------
const RIVALRY_RECENT_MAX = 5;
// Derby (match de championnat contre son rival, voir League.isDerbyMatch) :
// humeur des supporters ×1,5 et affluence +15 % (plafonnée à la capacité).
const DERBY_MORALE_MULT = 1.5;
const DERBY_ATTENDANCE_BOOST = 1.15;
const MANAGER_RATING_START = 1500;
const MANAGER_RATING_K = 24;
function rivalryKeyFor(team) { return String((team && team.name) || "").trim().toLowerCase(); }
function rivalryBetween(team, opponent) {
  if (!team || !opponent || !team.rivalries) return null;
  return team.rivalries[rivalryKeyFor(opponent)] || null;
}
function managerRatingOf(team) { return team && typeof team.managerRating === "number" ? team.managerRating : MANAGER_RATING_START; }
function recordHumanRivalry(home, away, competition, now, quarterScores) {
  if (!home || !away || home === away || !home.isHuman || !away.isHuman) return;
  if (competition === "friendly") return;
  const sum = arr => Array.isArray(arr) ? arr.reduce((a, b) => a + (b || 0), 0) : null;
  const qs = quarterScores || {};
  const sh = sum(qs.home), sa = sum(qs.away);
  if (sh == null || sa == null || sh === sa) return;
  const one = (team, opp, pf, pa, isHome) => {
    if (!team.rivalries || typeof team.rivalries !== "object") team.rivalries = {};
    const key = rivalryKeyFor(opp);
    const r = team.rivalries[key] || { name: opp.name, w: 0, l: 0, pf: 0, pa: 0, recent: [] };
    r.name = opp.name;
    if (pf > pa) r.w += 1; else r.l += 1;
    r.pf += pf; r.pa += pa;
    r.recent = [{ at: now, competition: competition || "championship", pf, pa, isHome }].concat(r.recent || []).slice(0, RIVALRY_RECENT_MAX);
    team.rivalries[key] = r;
  };
  one(home, away, sh, sa, true);
  one(away, home, sa, sh, false);
  const ra = managerRatingOf(home), rb = managerRatingOf(away);
  const expectedHome = 1 / (1 + Math.pow(10, (rb - ra) / 400));
  const scoreHome = sh > sa ? 1 : 0;
  home.managerRating = Math.round(ra + MANAGER_RATING_K * (scoreHome - expectedHome));
  away.managerRating = Math.round(rb + MANAGER_RATING_K * ((1 - scoreHome) - (1 - expectedHome)));
  home.managerRatedGames = (home.managerRatedGames || 0) + 1;
  away.managerRatedGames = (away.managerRatedGames || 0) + 1;
}

// ---------------------------------------------------------------------
// MÉMOIRE HISTORIQUE (2026-10-06, assets/history.js). Rien n'est inventé :
// chaque événement vient d'un fait du match ou de la saison. Numéro de
// saison = celui de la page « Histoire du club » (saisons archivées + 1).
// ---------------------------------------------------------------------
function histSeasonOf(team) { return (team && Array.isArray(team.seasonHistory) ? team.seasonHistory.length : 0) + 1; }
function histFeed(team, ev, title, now) {
  if (!team || !team.isHuman || !team.feed || !ev) return;
  try {
    pushEntry(team.feed, { key: `hist_${ev.event_id}`, category: "club", week: team.week, createdAt: now, title, text: ev.description, action: { label: "Histoire du club", href: "/histoire" } });
  } catch (e) { /* confort */ }
}
const HIST_RECORD_KEYS = [["pts", "points", 25, "playerPoints"], ["reb", "rebonds", 12, "playerRebounds"], ["ast", "passes décisives", 10, "playerAssists"]];
// Meilleures performances individuelles du club (records de franchise) :
// initialisées une fois, sans événement, depuis les records archivés et la
// saison en cours ; ensuite chaque nouveau record devient un événement.
function histFranchiseBests(team) {
  if (team.franchiseBests && typeof team.franchiseBests === "object") return team.franchiseBests;
  const rec = team.clubRecords || {};
  const b = {};
  HIST_RECORD_KEYS.forEach(([k, , , rk]) => { b[k] = { value: (rec[rk] && rec[rk].value) || 0, name: null }; });
  (team.players || []).forEach(p => (p.matchLog || []).forEach(m => {
    if (!m || m.competition === "friendly" || m.competition === "lp") return;
    HIST_RECORD_KEYS.forEach(([k]) => { if ((m[k] || 0) > b[k].value) b[k] = { value: m[k], name: p.name }; });
  }));
  team.franchiseBests = b;
  return b;
}
function histRecords(team, oppName, competition, now) {
  // Un club sans saison archivée n'a pas encore d'histoire à battre.
  if (!team || !team.isHuman || !(team.seasonHistory || []).length) return;
  const fresh = !team.franchiseBests;
  const b = histFranchiseBests(team);
  if (fresh) return;
  (team.players || []).forEach(p => {
    if (!(p.secondsPlayed > 0) || !p.stats) return;
    HIST_RECORD_KEYS.forEach(([k, label, min]) => {
      const v = p.stats[k] || 0;
      if (v < min || v <= b[k].value) return;
      const old = b[k];
      b[k] = { value: v, name: p.name, playerId: p.id, season: histSeasonOf(team), at: now };
      const ev = History.push({
        type: "RECORD", importance: 3, season: histSeasonOf(team), at: now, teams: [team.name], players: [p.id], competition,
        description: `Nouveau record de franchise : ${p.name}, ${v} ${label} contre ${oppName}` + (old.value ? ` (ancien record : ${old.value}${old.name ? ", " + old.name : ""})` : "") + ".",
        statistics: { key: k, value: v, previous: old.value || 0 }, records: [k], tags: ["record", p.name],
      });
      histFeed(team, ev, "NOUVEAU RECORD DE FRANCHISE", now);
    });
  });
}
function historyAfterMatch(home, away, competition, now, quarterScores, seed) {
  if (!home || !away || competition === "friendly" || competition === "lp") return;
  const drama = History.takeDrama(seed);
  const sum = arr => Array.isArray(arr) ? arr.reduce((a, b) => a + (b || 0), 0) : null;
  const qs = quarterScores || {};
  const sh = sum(qs.home), sa = sum(qs.away);
  if (sh == null || sa == null || sh === sa) return;
  const winner = sh > sa ? home : away, loser = sh > sa ? away : home;
  const season = histSeasonOf(home.isHuman ? home : away.isHuman ? away : home);
  const score = `${home.name} ${sh}-${sa} ${away.name}`;
  const base = { season, at: now, teams: [home.name, away.name], competition, statistics: { home: home.name, away: away.name, scoreHome: sh, scoreAway: sa } };
  let pts = competition === "cup" ? 3 : 1;
  if (drama) {
    if (drama.buzzer) {
      pts += 5;
      const who = drama.buzzer.player || winner.name;
      const ev = History.push({ ...base, type: "BUZZER_BEATER", importance: 3, players: [drama.buzzer.playerId], description: `Buzzer-beater : ${who} offre la victoire à ${winner.name} face à ${loser.name} (${score}).`, tags: ["buzzer"] });
      histFeed(winner, ev, "Victoire au buzzer", now); histFeed(loser, ev, "Défaite au buzzer", now);
    }
    if (drama.maxDeficit >= History.CFG.comebackMin) {
      pts += 3;
      const ev = History.push({ ...base, type: "COMEBACK", importance: drama.maxDeficit >= 20 ? 3 : 2, description: `${winner.name} renverse un retard de ${drama.maxDeficit} points face à ${loser.name} (${score}).`, tags: ["remontée"] });
      histFeed(winner, ev, "Remontée historique", now);
    }
    if (drama.overtimes >= 2) {
      pts += 2;
      History.push({ ...base, type: "HISTORICAL_GAME", importance: 2, description: `${drama.overtimes} prolongations entre ${home.name} et ${away.name} (${score}).`, tags: ["prolongations"] });
    }
  }
  History.bumpRivalry(home, away, pts, now, season, null, sh > sa ? "a" : "b");
  histRecords(home, away.name, competition, now);
  histRecords(away, home.name, competition, now);
}

function recordMatchStatsAndAwardMvp(home, away, round, competition, now = Date.now(), quarterScores = null, tacticsUsed = null, seed = null) {
  try { historyAfterMatch(home, away, competition, now, quarterScores, seed); } catch (e) { /* l'histoire ne bloque jamais un match */ }
  recordHumanRivalry(home, away, competition, now, quarterScores);
  recordOrdersHistory(home, away, true, round, competition, now, quarterScores);
  recordOrdersHistory(away, home, false, round, competition, now, quarterScores);
  recordMatchStatsForTeam(home, round, competition, now, quarterScores, tacticsUsed && tacticsUsed.home, seed, { isHome: true, opponent: away.name });
  recordMatchStatsForTeam(away, round, competition, now, quarterScores, tacticsUsed && tacticsUsed.away, seed, { isHome: false, opponent: home.name });
  // Alchimie selon le résultat (voir Team.applyChemistryResult) : score par
  // quart-temps quand on l'a, sinon points des joueurs ayant joué.
  if (competition !== "friendly") {
    const sum = arr => Array.isArray(arr) ? arr.reduce((a, b) => a + (b || 0), 0) : null;
    const pts = team => (team.players || []).reduce((a, p) => a + ((p.secondsPlayed > 0 && p.stats && p.stats.pts) || 0), 0);
    const qs = quarterScores || {};
    const sh = sum(qs.home) ?? pts(home), sa = sum(qs.away) ?? pts(away);
    if (home.applyChemistryResult) home.applyChemistryResult(sh, sa);
    if (away.applyChemistryResult) away.applyChemistryResult(sa, sh);
  }
  const mvpInfo = awardMatchMvp(home, away, round, competition, now);
  // Succès : match officiel joué (les amicaux et ligues privées n'appellent
  // jamais cette fonction pour de vrai — garde-fou sur "friendly" / "lp").
  if (competition !== "friendly" && competition !== "lp") {
    const sum = arr => Array.isArray(arr) ? arr.reduce((a, b) => a + (b || 0), 0) : null;
    const pts = team => (team.players || []).reduce((a, p) => a + ((p.secondsPlayed > 0 && p.stats && p.stats.pts) || 0), 0);
    const qs = quarterScores || {};
    const sh = sum(qs.home) ?? pts(home), sa = sum(qs.away) ?? pts(away);
    [[home, sh > sa], [away, sa > sh]].forEach(([t, won]) => {
      if (!t || !t.isHuman) return;
      const last = (t.ordersHistory || [])[0];
      achRecordOfficialMatch(t, { won, competition, mvp: !!(mvpInfo && mvpInfo.teamName === t.name), orders: last && last.at === now ? last.orders : null }, now);
    });
  }
  return mvpInfo;
}

// Instantané des ordres "en direct" d'une équipe au moment précis où son
// match est simulé (voir simulateOrForfeit ci-dessous et
// server/liveMatch.js:computeLiveMatch, seuls appelants) — capturé à la
// source plutôt que relu plus tard depuis `team.defense`/etc. (voir le grand
// commentaire de recordMatchStatsForTeam sur `tacticsUsed` pour pourquoi
// c'est important pour un match diffusé en direct). `offense` = seulement la
// priorité offensive n°1 du moment (team.offensivePriorities est un
// classement de 3, pas un choix unique).
function tacticsSnapshotFor(team) {
  // `offenses` : les trois priorités offensives (retour utilisateur
  // 2026-10-03 : « il faut mettre les trois types d'attaque ») ; `offense`
  // (la n° 1) reste pour le scouting et les anciens matchs.
  const pr = (team.offensivePriorities || []).filter(Boolean);
  return { defense: team.defense, offense: pr[0] || null, offenses: pr.slice(0, 3), rhythm: team.rhythm };
}

function simulateOrForfeit(teamHome, teamAway, now = Date.now()) {
  const homeOk = teamHome.hasValidLineup();
  const awayOk = teamAway.hasValidLineup();
  if (homeOk && awayOk) {
    // Tactiques capturées AVANT simulate() (voir tacticsSnapshotFor ci-dessus)
    // — simulate() ne les modifie jamais, mais autant figer l'instantané au
    // plus près du moment qui compte vraiment.
    const tacticsUsed = { home: tacticsSnapshotFor(teamHome), away: tacticsSnapshotFor(teamAway) };
    // Avantage du terrain aussi pour les matchs joués « en différé » (voir
    // server/liveMatch.js:computeLiveMatch pour la version en direct).
    const result = new MatchEngine(teamHome, teamAway, { homeAdvantage: true }).simulate(now);
    // quarterScores (retour Discord d'Ariane, relayé par l'utilisateur,
    // 2026-09-24 : "afficher le score par quart-temps sur la boxscore du
    // match" — voir DEV_NOTES.md) : MatchEngine.simulate() la calcule déjà
    // ({A,B}, un tableau par équipe) mais elle n'était jusqu'ici jamais
    // propagée au-delà de cette fonction. Réorientée ici home/away (A =
    // teamHome, B = teamAway, voir le constructeur de MatchEngine juste
    // au-dessus) pour que tout le reste de la chaîne (recordMatchStats
    // AndAwardMvp -> matchLog -> boxscoreRowsFromMatchLog côté client)
    // n'ait plus jamais besoin de connaître A/B, seulement home/away.
    const quarterScores = { home: result.quarterScores.A, away: result.quarterScores.B };
    // Mémoire historique : buzzer-beater, remontée, prolongations, lus dans
    // le fil du match (A = domicile) et retrouvés par la graine.
    try { History.rememberDrama(result.seed, History.dramaFromEvents(result.events, result.finalScore.A, result.finalScore.B)); } catch (e) { /* confort */ }
    return { scoreHome: result.finalScore.A, scoreAway: result.finalScore.B, forfeit: null, quarterScores, tacticsUsed, seed: result.seed };
  }
  // Forfait : aucun quart-temps réellement joué, voir recordMatchStatsForTeam
  // (jamais appelée pour un forfait) — quarterScores/tacticsUsed restent
  // `null` ici pour que l'absence de la donnée soit explicite plutôt qu'un
  // tableau/objet vide trompeur.
  if (!homeOk && !awayOk) return { scoreHome: 0, scoreAway: 0, forfeit: "both", quarterScores: null, tacticsUsed: null };
  if (!homeOk) return { scoreHome: 0, scoreAway: FORFEIT_SCORE, forfeit: "home", quarterScores: null, tacticsUsed: null };
  return { scoreHome: FORFEIT_SCORE, scoreAway: 0, forfeit: "away", quarterScores: null, tacticsUsed: null };
}

// Championnat + phase finale. `teams[0]` est TOUJOURS le club du joueur (les
// autres sont les adversaires générés). Ne simule JAMAIS le match du joueur
// lui-même (voir simulateCpuMatchesForRound) : celui-là passe par l'écran de
// préparation/match classique comme avant, et son résultat est enregistré à
// part via recordResult.
class League {
  constructor(teams) {
    this.teams = teams;
    this.schedule = generateRoundRobinSchedule(teams.length);
    this.round = 0; // prochaine journée à jouer (0-indexée)
    // Championnat créé avec l'historique des transferts : rien à reprendre
    // (voir seedTransferHistoryFromPlayers ; leagueFromSave relit le drapeau).
    this.transferHistorySeeded = true;
    this.results = []; // { round, home, away, scoreHome, scoreAway }
    this.playoffs = null; // rempli une fois la saison régulière terminée

    // Marché des transferts (voir listPlayerForSale/placeBid/refreshMarket
    // plus bas) : enchères en cours pour cette ligue. Volontairement remis à
    // zéro à chaque régénération de ligue (nouvelle saison — voir
    // generateLeague) : les 9 adversaires sont intégralement régénérés
    // chaque saison, donc une enchère non conclue à cheval sur un changement
    // de saison référencerait des équipes qui n'existent plus — cas limite
    // assez rare (il faudrait ne pas se reconnecter pendant 3 jours PILE au
    // moment d'un changement de saison) pour ne pas valoir la peine de la
    // reporter.
    this.transferListings = [];
    this.lastCpuListingCheckAt = null;
    // Agents libres (fin de contrat, demande du 2026-10-01) : joueurs sans
    // club, chacun aux enchères (annonce `freeAgent`, voir
    // processContractExpiries).
    this.freeAgents = [];

    // Marché des entraîneurs (voir generateCoachCandidate/placeCoachBid/
    // refreshCoachMarket plus bas) : même remise à zéro à chaque
    // régénération de ligue que transferListings ci-dessus, pour la même
    // raison (les candidats d'une saison n'ont plus de sens une fois les
    // adversaires régénérés).
    this.coachListings = [];
    this.lastCoachGenerationCheckAt = 0;

    // Marché des analystes vidéo (voir Team.videoAnalyst/
    // League.generateAnalystCandidate/placeAnalystBid/_resolveAnalystListing/
    // refreshAnalystMarket/fireTeamVideoAnalyst/runVideoSession plus bas) :
    // même remise à zéro à chaque régénération de ligue que coachListings
    // ci-dessus, pour la même raison (les candidats d'une saison n'ont plus
    // de sens une fois les adversaires régénérés).
    this.analystListings = [];
    this.lastAnalystGenerationCheckAt = 0;

    // Marché des recruteurs (voir Team.recruiter/League.generateRecruiterCandidate/
    // placeRecruiterBid/_resolveRecruiterListing/refreshRecruiterMarket/
    // fireTeamRecruiter plus bas) : TROISIÈME marché de staff, même remise à
    // zéro à chaque régénération de ligue que coachListings/analystListings
    // ci-dessus, pour la même raison.
    this.recruiterListings = [];
    this.lastRecruiterGenerationCheckAt = 0;

    // Marchés du staff médical (voir MEDICAL_STAFF_ROLES/refreshMedicalMarket).
    this.doctorListings = [];
    this.physioListings = [];
    // Marché des entraîneurs adjoints (voir refreshAssistantCoachMarket).
    this.assistantCoachListings = [];

    // Calendrier RÉEL (retour utilisateur, 2026-09 : "le jeu va être online,
    // donc il faudra mettre un calendrier réel / dans une vraie semaine, 2
    // matchs de championnat + 1 de coupe") : `calendarStartAt` est l'instant
    // réel (epoch ms) où la saison a commencé — laissé à `null` tant que
    // rien ne le renseigne explicitement (généré par generateLeague), pour
    // rester rétro-compatible avec le mode "à la demande" actuel (aucun
    // calendrier réel, tout se joue au clic — voir server/README.md pour le
    // détail du calendrier réel côté serveur). `lastAutoTrainedWeek` évite
    // de faire tourner deux fois l'entraînement hebdomadaire (Team.trainWeek
    // fait bien plus que juste progresser des caractéristiques — finances,
    // moral, vieillissement...) pour une même semaine réelle déjà traitée.
    this.calendarStartAt = null;
    this.lastAutoTrainedWeek = -1;

    // Rythme du calendrier retenu pour CETTE ligue (retour utilisateur,
    // 2026-09 : pouvoir tester une saison entière en quelques jours plutôt
    // qu'en ~9 semaines réelles, avant d'ouvrir le jeu à plusieurs managers
    // — "on repartira sur un calendrier classique quand le jeu sera
    // opérationnel [...] on restera sur ce schéma [accéléré] aussi" pour les
    // tests solo). Figé UNE FOIS POUR TOUTES à la génération de la ligue
    // (voir generateLeague) plutôt que relu dynamiquement à chaque calcul :
    // redémarrer le serveur avec/sans le mode accéléré ne dérègle donc
    // jamais un calendrier déjà en cours, seule une toute nouvelle ligue
    // (nouvelle carrière, ou nouvelle saison qui hérite du réglage de la
    // précédente, voir startNewSeason côté navigateur) adopte le réglage
    // courant. `null` = calendrier classique (voir CALENDAR_WEEK_MS/
    // CALENDAR_CHAMPIONSHIP_SLOT_OFFSETS_MS ci-dessous), pour rester
    // rétro-compatible avec les sauvegardes d'avant ce réglage.
    this.calendarWeekMs = null;
    this.calendarSlotOffsetsMs = null;

    // Calendrier ANCRÉ QUOTIDIEN (retour utilisateur, 2026-09 — "3 matchs
    // par jour à heures fixes réelles, en heure de Paris") : `true`
    // uniquement pour la ligue multi-manager (voir generateMultiManagerLeague/
    // buildLeagueWithHumanTeams) — jamais pour la carrière solo historique,
    // qui garde son propre rythme (calendarWeekMs/calendarSlotOffsetsMs
    // ci-dessus, ou null = classique). Un rythme entièrement séparé des deux
    // ci-dessus, pas exprimable avec les mêmes champs (voir le grand
    // commentaire dans server/calendar.js, "CALENDRIER ANCRÉ QUOTIDIEN") :
    // calendarWeekMs/calendarSlotOffsetsMs restent `null` quand celui-ci est
    // actif. `lastAutoTrainedDay` (`-1` = aucun jour encore traité) joue le
    // même rôle que lastAutoTrainedWeek ci-dessus, mais au jour CIVIL près
    // (retour utilisateur : "toutes les 3 matchs", lu comme "une fois par
    // jour civil, juste après le créneau de 19h" — voir server/autoSim.js).
    this.calendarDailyAnchored = false;
    // Rythme hebdomadaire (mardi/samedi + coupe le jeudi, voir
    // weeklyRhythmCalendarStartAt) : variante du calendrier ancré, fixée à la création.
    this.calendarWeeklyRhythm = false;
    this.lastEconomyTick = 0; // dernière mise à jour économique hebdomadaire réglée (k >= 1)
    // Mise à jour du lundi qui suit la finale des play-offs (fin de saison :
    // vieillissement, salaires...) déjà réglée — voir
    // server/autoSim.js:catchUpWeeklyRhythm. Une seule par saison.
    this.seasonEndTickDone = false;
    this.calendarWeeklySwitch = null; // bascule en pleine saison, voir dailyAnchoredScheduledTimeForChampionshipRound
    this.lastAutoTrainedDay = -1;

    // Compétition de Coupe (retour utilisateur, 2026-09 — voir le grand
    // commentaire au-dessus de generateCupBracket) : `null` tant qu'aucune
    // coupe n'existe pour cette ligue (carrière solo, ou ligue multi-manager
    // pas encore passée par generateMultiManagerLeague/leagueFromSave) —
    // {rounds: [...], champion: null|idx} une fois créée (voir
    // generateCupBracket). Toujours reconstruite à zéro à chaque
    // régénération de la ligue multi-manager (nouvelle saison de test, voir
    // /api/admin/reset-multi-league côté serveur) — un nouveau tirage au
    // sort de byes à chaque fois, comme les 9 adversaires CPU.
    this.cup = null;

    // Ligues privées (Premium, retour communauté 2026-09 : "Ligues perso ?
    // comme LP sur BB [...] un truc à part qui ne joue pas sur la forme des
    // joueurs") : tableau de ligues créées par des managers humains de CETTE
    // ligue partagée, chacune {id, name, code, creatorTeamIndex, size, venue,
    // status, teamIndices, rounds[...]} — voir createPrivateLeague /
    // simulatePrivateLeagueMatch plus bas. Données JSON brutes (comme `cup`),
    // sérialisées telles quelles. Les matchs sont simulés sur des COPIES
    // des équipes : rien ici ne touche jamais les joueurs réels.
    this.privateLeagues = [];
    // Matchs amicaux (demande utilisateur 2026-09-27, voir
    // server/friendlies.js) : invitations et résultats, JSON brut sérialisé
    // tel quel. Simulés au tick serveur sur les vrais joueurs.
    this.friendlies = [];

    // Matchs en direct en cours de diffusion pour la journée courante (voir
    // server/liveMatch.js) : UNE entrée par match diffusé, indexée par une
    // clé stable "round:home:away" (voir liveMatchKey côté server/liveMatch.js)
    // — plusieurs managers humains peuvent chacun avoir LEUR match diffusé en
    // même temps (retour utilisateur, 2026-09 : "jusqu'à 10 vrais managers
    // humains dans une ligue partagée"). Un match CPU-vs-CPU n'a JAMAIS
    // d'entrée ici (voir ensureLiveMatchStarted). Chaque entrée est calculée
    // UNE SEULE FOIS par le serveur dès l'heure du coup d'envoi, puis étalée
    // dans le temps réel jusqu'à sa clôture (voir MATCH_BROADCAST_DURATION_MS).
    this.liveMatches = {};
    // Identifiant de SAISON (voir archiveSeasonForTeam) : posé par
    // buildLeagueWithHumanTeams, restauré par leagueFromSave.
    this.seasonId = null;

    // Stockage brut du service de pronostics des émissions avant-match/
    // mi-temps (voir serializeLeague/leagueFromSave, server/shows.js,
    // DEV_NOTES.md point 11) — jamais lu/écrit directement ici, seulement
    // transporté.
    this.showsPronostics = {};

    // Confort d'affichage UNIQUEMENT : le match en direct DE CELUI QUI A FAIT
    // LA REQUÊTE, déjà résolu depuis this.liveMatches par le serveur (voir
    // server/liveMatch.js:viewLiveMatchForTeam) avant de sérialiser la
    // réponse — jamais recalculé ni maintenu à jour ici même, jamais la
    // source de vérité (c'est this.liveMatches). `null` par défaut ; c'est ce
    // que lit tout l'affichage "en direct" côté navigateur (league.liveMatch
    // — voir enterLiveMatch), qui n'a pas besoin de connaître les diffusions
    // des AUTRES managers.
    this.liveMatch = null;
  }

  get totalRounds() { return this.schedule.length; }
  // Rivaux du championnat (2026-09-29, retour utilisateur : « il faut qu'une
  // équipe soit rivale avec une autre équipe du championnat (et chaque
  // équipe doit avoir son rival) et on aura nos derbys comme ça mais deux
  // max par saison (hors po et barrage) », « managers entre eux
  // d'abord »). Paires FIXÉES pour une saison (this.rivalPairs.season) :
  // - une paire de la saison précédente est gardée si ce sont toujours les
  //   deux mêmes clubs (même nom à ces index) et qu'elle réunit deux
  //   managers ou deux clubs de l'IA ;
  // - les autres clubs sont réappariés : managers entre eux d'abord, puis
  //   (s'il en reste un seul) un manager avec un club de l'IA, puis l'IA
  //   entre elle ; ordre mélangé de façon déterministe (saison + noms).
  // Le derby = match de CHAMPIONNAT (saison régulière) contre son rival :
  // aller + retour, donc deux au plus par saison ; jamais en play-offs, au
  // barrage ni en Coupe.
  ensureRivalPairs() {
    const season = this.seasonNumber || 1;
    const n = this.teams.length;
    const cur = this.rivalPairs;
    const inRange = p => p && Number.isInteger(p.a) && Number.isInteger(p.b) && p.a >= 0 && p.b >= 0 && p.a < n && p.b < n && p.a !== p.b;
    if (cur && cur.season === season && Array.isArray(cur.pairs) && cur.pairs.every(inRange)) {
      // En cours de saison, un manager qui reprend un club de l'IA prend sa
      // place telle quelle : même rival, derbys restants compris. Les noms
      // mémorisés suivent (reprise = nouveau nom), pour que la paire soit
      // reconnue comme « les deux mêmes clubs » à la saison suivante.
      cur.pairs.forEach(p => { p.names = [this.teams[p.a].name, this.teams[p.b].name]; });
      return cur;
    }
    const human = i => !!(this.teams[i] && this.teams[i].isHuman);
    const sameClubs = p => inRange(p) && Array.isArray(p.names) && this.teams[p.a].name === p.names[0] && this.teams[p.b].name === p.names[1];
    const used = new Set();
    const pairs = [];
    const add = (a, b) => { pairs.push({ a, b, names: [this.teams[a].name, this.teams[b].name] }); used.add(a); used.add(b); };
    (cur && Array.isArray(cur.pairs) ? cur.pairs : []).forEach(p => {
      if (sameClubs(p) && !used.has(p.a) && !used.has(p.b) && human(p.a) === human(p.b)) add(p.a, p.b);
    });
    // Mélange déterministe (même résultat sur le serveur et le navigateur).
    let seed = season * 2654435761 >>> 0;
    this.teams.forEach(t => { for (const ch of String(t.name || "")) seed = (Math.imul(seed ^ ch.charCodeAt(0), 16777619)) >>> 0; });
    const rnd = () => { seed = (seed + 0x6D2B79F5) >>> 0; let t = seed; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
    const shuffle = arr => { for (let i = arr.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [arr[i], arr[j]] = [arr[j], arr[i]]; } return arr; };
    const free = [...Array(n).keys()].filter(i => !used.has(i));
    const humans = shuffle(free.filter(human)), cpus = shuffle(free.filter(i => !human(i)));
    while (humans.length >= 2) add(humans.pop(), humans.pop());
    if (humans.length === 1 && cpus.length) {
      const h = humans.pop();
      // Garde son rival de l'IA de la saison précédente s'il est libre.
      const prev = (cur && Array.isArray(cur.pairs) ? cur.pairs : []).find(p => sameClubs(p) && (p.a === h || p.b === h));
      const other = prev ? (prev.a === h ? prev.b : prev.a) : null;
      const k = other != null && cpus.includes(other) ? cpus.indexOf(other) : cpus.length - 1;
      add(h, cpus.splice(k, 1)[0]);
    }
    while (cpus.length >= 2) add(cpus.pop(), cpus.pop());
    this.rivalPairs = { season, pairs };
    return this.rivalPairs;
  }

  // Index du rival de `teamIdx` cette saison (null si aucun).
  rivalOf(teamIdx) {
    const rp = this.ensureRivalPairs();
    const p = rp.pairs.find(x => x.a === teamIdx || x.b === teamIdx);
    return p ? (p.a === teamIdx ? p.b : p.a) : null;
  }

  // Match de championnat (saison régulière) entre deux rivaux = derby.
  isDerbyMatch(homeIdx, awayIdx) {
    return homeIdx != null && awayIdx != null && this.rivalOf(homeIdx) === awayIdx;
  }

  isRegularSeasonDone() { return this.round >= this.totalRounds; }
  matchesForRound(r) { return this.schedule[r] || []; }

  // Premier match à venir pour l'équipe `teamIdx` (index 0 par défaut,
  // comportement historique solo) à partir de la journée courante. Renvoie
  // null une fois la saison régulière terminée.
  // Correctif (généralisation multi-manager, 2026-09, retour utilisateur :
  // "probleme équipe qui joue contre elle même ? normalement l'adversaire
  // est gotham knight") : cette méthode cherchait encore, sans condition,
  // le match de `teams[0]` (comportement historique solo, où le club du
  // joueur est TOUJOURS à cet index), jamais celui du manager qui consulte
  // réellement l'écran (myTeamIndex côté navigateur, voir
  // enterNextMatchOrShowSeasonEnd). Pour tout manager d'une ligue partagée
  // dont l'équipe n'est PAS à l'index 0, le "prochain match" affiché était
  // donc celui de teams[0] : round correct par coïncidence (calendrier
  // sans exempt, tout le monde avance au même rythme), mais adversaire et
  // domicile/extérieur erronés, jusqu'à parfois afficher l'équipe du
  // manager elle-même comme son propre adversaire (si teams[0] jouait
  // justement contre lui ce tour-ci). Se réduit exactement au comportement
  // historique en solo, où myTeamIndex vaut toujours 0.
  // Correctif (ligue multi-manager, 2026-09, retour utilisateur : "le bug
  // d'absence de texte [...] sur la page ordre, apparait quand on clique sur
  // ordres (la première fois qu'on va sur la page), si on choisit qqch dans
  // le menu déroulant, ça apparait, et si on remet le match qu'on avait au
  // départ via le menu deroulant, ça reapparait aussi") : cette boucle
  // partait de `this.round` (le round GLOBAL de la ligue) et renvoyait le
  // premier round à partir de là où `teamIdx` a un match programmé, SANS
  // jamais vérifier s'il avait déjà été joué. En solo (un seul match humain
  // par round), `this.round` avance dès que CE match est résolu, donc ça ne
  // posait jamais de problème. En ligue multi-manager, `this.round` n'avance
  // QUE quand TOUS les matchs du round sont résolus (voir
  // League.isRegularSeasonDone/server/autoSim.js) — si le match de `teamIdx`
  // se termine (diffusion en direct achevée) alors que D'AUTRES matchs du
  // même round sont encore en cours ailleurs dans la ligue, `this.round`
  // reste sur ce round déjà joué pour `teamIdx`, et cette méthode le
  // renvoyait quand même comme "prochain match" (déjà dans this.results,
  // jamais vérifié). currentMatch (côté navigateur, voir
  // enterNextMatchOrShowSeasonEnd) pointait alors sur un round déjà résolu,
  // absent de upcomingRoundsForOrders() (qui, lui, exclut bien les rounds
  // déjà joués via league.results) : defaultOrdresRound() présélectionnait
  // ce round fantôme, le menu déroulant retombait alors sur son option par
  // défaut du navigateur (aucune <option> ne correspondant), mais le
  // bandeau #ordresRoundDateTime, lui, cherchait toujours l'ancien round et
  // ne trouvait rien — d'où un bandeau vide malgré un menu déroulant qui
  // semblait pourtant afficher une sélection valide. Choisir N'IMPORTE QUELLE
  // option du menu (même celle déjà affichée) appelle selectOrdresRound()
  // avec la VRAIE valeur de cette <option>, qui corrige `selectedOrdresRound`
  // au passage — d'où le bandeau qui "réapparaît" en rechoisissant le même
  // match. Corrigé en sautant, comme upcomingRoundsForOrders(), tout round
  // déjà résolu pour `teamIdx` d'après `this.results`, plutôt que de
  // supposer que `this.round` (global) reflète déjà son propre état.
  // BUG corrigé (retour utilisateur, 2026-09-24, capture d'écran du
  // calendrier : "le match devrait s'afficher en haut pour la coupe aussi
  // (il faut tjrs afficher le prochain match, et pas uniquement le prochain
  // match de championnat)") : cette méthode ne regardait QUE this.schedule
  // (championnat), jamais this.cup — un tour de Coupe programmé AVANT le
  // prochain match de championnat (même jour, horaire plus tôt, ou un jour
  // plus tôt, voir league.cup au créneau quotidien fixe de 15h) restait donc
  // invisible ici, alors que c'est cette méthode qui alimente currentMatch
  // (voir enterNextMatchOrShowSeasonEnd côté moteurbasket3.html), donc le
  // bandeau du haut, l'écran de préparation ET l'échéance de validation des
  // ordres. Cherche maintenant AUSSI le tour de Coupe actuellement en
  // attente (voir pendingCupRound) pour ce club, et renvoie celui des deux
  // (championnat ou Coupe) dont l'horaire RÉEL programmé est le plus proche
  // — jamais les deux mélangés, jamais un simple ordre de priorité fixe.
  // `competition` : ABSENTE pour un match de championnat (comportement
  // historique inchangé, {round, isHome, opponent} tel quel — voir le
  // commentaire de defaultOrdresRound côté moteurbasket3.html pour pourquoi
  // ne rien ajouter ici évite de casser la comparaison stricte déjà en place
  // ailleurs), posée à "cup" UNIQUEMENT pour un tour de Coupe — même
  // convention que league.liveMatch.competition (voir enterLiveMatch/
  // defaultOrdresRound : `.competition || "championship"` partout où c'est
  // lu).
  // Ordres préparés à l'avance pour la journée de championnat devenue le
  // match IMMÉDIAT du club (retour utilisateur 2026-09-26, capture du
  // calendrier : "de temps en temps, les ordres sautent"). Tant qu'une
  // journée est future, ses ordres vivent dans plannedTactics ; dès qu'elle
  // devient la prochaine (le match précédent vient d'être joué), l'écran
  // Ordres et le calendrier lisent les ordres EN DIRECT (+
  // ordresValidatedRound), qui ne contenaient pas encore ce plan : les ordres
  // préparés semblaient perdus (bouton "Ordres" au lieu de "Modifier vos
  // ordres", écran Ordres revenu aux anciens réglages), et pire, toute
  // retouche faite à ce moment-là était écrasée au coup d'envoi par
  // applyPlannedTacticsForRound. Ici, le plan est promu en ordres en direct
  // DÈS que sa journée devient la prochaine, et marqué validé. Idempotent,
  // appelé à chaque tick serveur (voir server/index.js:tick). Ne touche
  // jamais à la Coupe (ses ordres passent toujours par un plan, voir
  // cup_ordres_planning_test.js), ni à une journée dont le match en direct a
  // déjà commencé (le plan y est déjà appliqué et consommé).
  promoteImmediatePlan(teamIdx) {
    const team = this.teams[teamIdx];
    if (!team || !team.isHuman || !team.hasPlanForRound) return false;
    const next = this.nextUserMatch(teamIdx);
    if (!next || next.competition === "cup") return false;
    if (!team.hasPlanForRound(next.round)) return false;
    team.applyPlannedTacticsForRound(next.round);
    team.ordresValidatedRound = next.round;
    return true;
  }

  nextUserMatch(teamIdx = 0) {
    let champ = null;
    for (let r = this.round; r < this.totalRounds; r++) {
      const m = this.schedule[r].find(x => x.home === teamIdx || x.away === teamIdx);
      if (!m) continue;
      const alreadyPlayed = this.results.some(res => res.round === r && (res.home === teamIdx || res.away === teamIdx));
      if (alreadyPlayed) continue;
      const isHome = m.home === teamIdx;
      champ = { round: r, isHome, opponent: isHome ? m.away : m.home };
      break;
    }

    // Coupe : le SEUL tour qui puisse jamais être "à venir" pour ce club
    // (voir pendingCupRound/upcomingRoundsForOrders côté moteurbasket3.html,
    // même logique reprise ici) — absent si cette ligue n'a pas de Coupe, si
    // le tour en attente ne concerne pas ce club (déjà éliminé, ou exempt
    // sans adversaire réel), ou si son match a déjà été résolu.
    let cup = null;
    const cupRound = this.pendingCupRound();
    if (cupRound) {
      const m = cupRound.matches.find(x => (x.home === teamIdx || x.away === teamIdx) && !x.bye);
      if (m && !m.resolved) {
        const isHome = m.home === teamIdx;
        cup = { round: cupRound.index, isHome, opponent: isHome ? m.away : m.home, competition: "cup" };
      }
    }

    if (!champ) return cup;
    if (!cup) return champ;
    // Comparaison chronologique par horaire RÉEL programmé (mêmes formules
    // que scheduledTimeForLeagueRound/scheduledTimeForLeagueCupRound côté
    // server/calendar.js, et leurs équivalents côté moteurbasket3.html
    // scheduledTimeForChampionshipRound/scheduledTimeForCupRound) — seule une
    // ligue au calendrier ancré quotidien a jamais une Coupe (voir
    // generateMultiManagerLeague), donc calendarStartAt est toujours défini
    // ici si `cup` est non-null ; repli défensif sur le championnat (ancien
    // comportement) si ce n'est vraiment pas le cas (ancienne sauvegarde
    // atypique).
    if (typeof this.calendarStartAt !== "number") return champ;
    const champAt = this.calendarDailyAnchored
      ? dailyAnchoredScheduledTimeForChampionshipRound(this.calendarStartAt, champ.round, !!this.calendarWeeklyRhythm, this.calendarWeeklySwitch || null, typeof this.totalRounds === "number" ? this.totalRounds : null, this.timeZone || null)
      : calendarScheduledTimeForRound(this.calendarStartAt, champ.round, this.calendarWeekMs || undefined, this.calendarSlotOffsetsMs || undefined);
    const cupAt = dailyAnchoredScheduledTimeForCupRound(this.calendarStartAt, cupRound.dayIndex, !!this.calendarWeeklyRhythm, this.calendarWeeklySwitch || null, this.timeZone || null);
    return cupAt <= champAt ? cup : champ;
  }

  recordResult(round, home, away, scoreHome, scoreAway, seed = null) {
    this.results.push({ round, home, away, scoreHome, scoreAway, ...(seed != null ? { seed } : null) });
    applySponsorWinPrimes(this.teams[scoreHome > scoreAway ? home : away]);
  }

  // Classement : 2 points pour une victoire, 1 pour une défaite (pas de
  // match nul en basket). Départage par différence de points puis total de
  // points marqués.
  standings() {
    const table = this.teams.map((t, i) => ({
      idx: i, name: t.name, played: 0, wins: 0, losses: 0, pf: 0, pa: 0, points: 0,
    }));
    this.results.forEach(r => {
      const h = table[r.home], a = table[r.away];
      h.played++; a.played++;
      h.pf += r.scoreHome; h.pa += r.scoreAway;
      a.pf += r.scoreAway; a.pa += r.scoreHome;
      if (r.scoreHome > r.scoreAway) { h.wins++; a.losses++; h.points += 2; a.points += 1; }
      else { a.wins++; h.losses++; a.points += 2; h.points += 1; }
    });
    return table.sort((x, y) => y.points - x.points || (y.pf - y.pa) - (x.pf - x.pa) || y.pf - x.pf);
  }

  // Simule instantanément (moteur complet, sans écran dédié) tous les
  // matchs d'une journée qui NE concernent PAS le club du joueur, et
  // enregistre les résultats. Le match du joueur, lui, passe par l'écran de
  // match classique puis est enregistré séparément.
  // NOTE (généralisation multi-manager, 2026-09) : sautait à l'origine
  // uniquement `home === 0 || away === 0` (LE club du joueur, toujours à cet
  // index) — généralisé à "n'importe quel côté humain" (`isHuman`) pour
  // qu'un match entre DEUX managers humains (aucun des deux forcément à
  // l'index 0, voir Team.isHuman/buildLeagueWithHumanTeams) ne soit jamais
  // auto-résolu ici à leur place. Se réduit exactement au comportement
  // historique quand il n'y a qu'UN SEUL manager humain, à l'index 0.
  simulateCpuMatchesForRound(r) {
    this.matchesForRound(r).forEach(m => {
      if (this.teams[m.home].isHuman || this.teams[m.away].isHuman) return;
      const result = simulateOrForfeit(this.teams[m.home], this.teams[m.away]);
      this.recordResult(r, m.home, m.away, result.scoreHome, result.scoreAway, result.seed);
    });
  }

  // Fait progresser les 9 équipes adverses (CPU) d'une semaine
  // d'entraînement simplifiée (voir Team.trainWeekCPU), à appeler en
  // parallèle de Team.trainWeek pour le club du joueur (même cadence
  // hebdomadaire — désormais appliquée automatiquement une fois par semaine
  // réelle, voir catchUpLeague côté server/autoSim.js) : sans ça, un club bien
  // géré progresse semaine après semaine tandis que les adversaires restent
  // figés à leur niveau de génération, et l'écart se creuse sans limite au
  // fil d'une saison. Chaque adversaire reçoit en plus un "rattrapage"
  // proportionnel à son propre écart de niveau avec le club du joueur (voir
  // Team.trainWeekCPU) : ça referme aussi un écart déjà creusé (parties en
  // cours, ou après mise à jour du jeu), pas seulement empêcher qu'il
  // continue de grandir.
  // NOTE (généralisation multi-manager, 2026-09) : le "niveau du club du
  // joueur" auquel les CPU se comparent était `this.teams[0]` seul —
  // généralisé à la MOYENNE des équipes humaines (1 à 10, voir Team.isHuman)
  // pour rester représentatif quand plusieurs managers réels coexistent.
  // Se réduit exactement au comportement historique avec un seul manager
  // humain, à l'index 0.
  // Retraite (voir le grand commentaire de RETIREMENT_ANNOUNCE_CHANCE_BY_AGE),
  // à la mise à jour qui clôt la saison, AVANT le vieillissement : les
  // joueurs qui avaient annoncé leur dernière saison quittent leur club.
  // Enchère en cours annulée ; un club de l'IA reçoit un jeune de niveau
  // comparable ; un club humain sous MIN_ROSTER_SIZE reçoit des joueurs de
  // complément. Renvoie la liste des retraités.
  retireAnnouncedPlayers(now = Date.now()) {
    const retired = [];
    this.teams.forEach((team, idx) => {
      if (!team || !Array.isArray(team.players)) return;
      const leaving = team.players.filter(p => p.retiringAfterSeason);
      if (!leaving.length) return;
      leaving.forEach(p => {
        (this.transferListings || []).forEach(l => {
          if (l.status === "open" && l.playerId === p.id && l.sellerIdx === idx) { l.status = "cancelled"; l.result = "retired"; }
        });
        const i = team.players.findIndex(x => x.id === p.id);
        if (i !== -1) {
          team.players.splice(i, 1); archiveDepartedMatchLog(team, p);
          recordTeamTransfer(team, { id: `${this.leagueId || "lg"}:T${p.id}`, at: now, kind: "retire", player: p, from: transferTeamRef(team, this.leagueId, idx), to: null, fee: 0, human: false });
        }
        if (team.isHuman) team.handleStarterDeparture(p.id);
        retired.push({ teamIdx: idx, playerId: p.id, name: p.name, age: p.age, position: p.position });
        if (team.isHuman && team.feed) {
          pushEntry(team.feed, {
            key: `retiring_${p.id}`, category: "club", week: team.week, createdAt: now,
            title: `${p.name} prend sa retraite`,
            text: `À ${p.age} ans, ${p.name} raccroche après sa dernière saison. Il reste dans l'histoire du club.`,
            action: { label: "Effectif", href: "/effectif" },
          });
        }
        if (!team.isHuman) team.players.push(generateRetirementReplacement(team, p.position));
      });
      if (!team.isHuman) {
        team.autoAssignLineup();
      } else {
        while (team.players.length < MIN_ROSTER_SIZE) {
          const pos = POSITIONS.find(ps => !team.players.some(x => x.position === ps)) || POSITIONS[team.players.length % POSITIONS.length];
          const rookie = generateRookiePlayer(pos);
          rookie.age = 19;
          resetPlayerTacticalKnowledge(rookie);
          team.players.push(rookie);
          if (team.feed) {
            pushEntry(team.feed, {
              key: `retire_filler_${rookie.id}`, category: "club", week: team.week, createdAt: now,
              title: `${rookie.name} rejoint l'effectif`,
              text: `Après les départs à la retraite, la ligue complète votre effectif avec un jeune ${pos.toLowerCase()}.`,
              action: { label: "Effectif", href: "/effectif" },
            });
          }
        }
      }
    });
    return retired;
  }

  // Les joueurs des clubs de l'IA vieillissent eux aussi d'un an à chaque
  // fin de saison (les clubs humains le font dans Team.trainWeek), sans quoi
  // aucun d'eux n'atteindrait jamais l'âge de la retraite.
  ageCpuPlayers(seasonNo = null) {
    this.teams.forEach(t => {
      if (!t || t.isHuman) return;
      t.players.forEach(p => {
        if (seasonNo != null) {
          if (p.lastAgedSeasonNo === seasonNo) return;
          p.lastAgedSeasonNo = seasonNo;
        }
        p.age += 1;
        recordRoleHistory(p, seasonNo);
      });
      if (typeof t.recalculateSalaries === "function") t.recalculateSalaries();
    });
  }

  // Annonces de dernière saison, APRÈS le vieillissement de fin de saison.
  // Renvoie la liste des annonces. `rng` injectable pour les tests.
  announceRetirements(now = Date.now(), rng = Math.random) {
    const announced = [];
    this.teams.forEach((team, idx) => {
      if (!team || !Array.isArray(team.players)) return;
      team.players.forEach(p => {
        if (p.retiringAfterSeason) return;
        const chance = retirementAnnounceChance(p.age, team.playerRoleKey(p.id));
        if (!(chance > 0) || rng() >= chance) return;
        p.retiringAfterSeason = true;
        p.retirementWeeks = 0;
        p.retirementTalks = [];
        p.retirementQuote = retirementAnnounceQuoteFor(p.name);
        announced.push({ teamIdx: idx, playerId: p.id, name: p.name, age: p.age });
        if (team.isHuman && team.feed) {
          const canTalk = p.age < RETIREMENT_FORCED_AGE;
          pushEntry(team.feed, {
            key: `retiring_${p.id}`, category: "presse", week: team.week, createdAt: now,
            title: `${p.name} annonce sa dernière saison`,
            text: p.retirementQuote + (canTalk ? " Vous pouvez tenter de le convaincre de continuer depuis sa fiche." : ""),
            action: { label: "Effectif", href: "/effectif" },
          });
        }
      });
    });
    return announced;
  }

  // Historique hebdomadaire des joueurs (voir PLAYER_HISTORY_SEASONS) : un
  // instantané de chaque joueur de la ligue, appelé par server/autoSim.js
  // juste après l'entraînement de la semaine. La semaine est comptée par
  // saison (`playerHistoryWeek`, sauvegardé avec la ligue).
  recordPlayerHistory() {
    const season = typeof this.seasonNumber === "number" ? this.seasonNumber : 1;
    const cur = this.playerHistoryWeek;
    const week = cur && cur.s === season ? (cur.w || 0) + 1 : 1;
    this.playerHistoryWeek = { s: season, w: week };
    this.teams.forEach(t => ((t && t.players) || []).forEach(p => pushPlayerHistory(p, season, week)));
    return { season, week };
  }

  trainCpuTeams() {
    const humanTeams = this.teams.filter(t => t.isHuman);
    const userAvg = humanTeams.length
      ? humanTeams.reduce((s, t) => s + t.averageOverall(), 0) / humanTeams.length
      : this.teams[0].averageOverall();
    this.teams.forEach(t => {
      if (t.isHuman) return;
      const gap = userAvg - t.averageOverall();
      t.trainWeekCPU(gap, CPU_IMPLICIT_COACH_LEVEL);
    });
  }

  // Passe à la journée suivante (à appeler une fois TOUS les matchs de la
  // journée courante enregistrés, joueur compris).
  advanceRound() {
    this.round += 1;
  }

  // ---------------------------------------------------------------------
  // COUPE — voir le grand commentaire au-dessus de generateCupBracket pour
  // le format de league.cup. Ces 3 méthodes sont au tableau de coupe ce que
  // matchesForRound/recordResult/advanceRound sont au championnat
  // ci-dessus : de simples primitives de données, appelées depuis
  // server/liveMatch.js (voir finalizeCupRound) — jamais depuis ici (ce
  // moteur ne connaît ni le direct ni l'heure réelle).
  // ---------------------------------------------------------------------

  // Le tour de coupe actuellement EN ATTENTE (pas encore résolu) — `null` si
  // cette ligue n'a pas de coupe, ou si son dernier tour connu (la finale)
  // est déjà résolu (this.cup.champion posé) : dans les deux cas, "aucun
  // tour dû", le créneau de 15h reste vide ce jour-là (voir
  // server/liveMatch.js/server/autoSim.js).
  pendingCupRound() {
    if (!this.cup || this.cup.champion != null) return null;
    const round = this.cup.rounds[this.cup.rounds.length - 1];
    return round && !round.resolved ? round : null;
  }

  // Enregistre le résultat d'UN match réel (jamais un bye, déjà résolu à sa
  // création — voir generateCupBracket) du tour actuellement en attente,
  // repéré par son index DANS round.matches (stable, voir
  // server/liveMatch.js:finalizeCupRound). Égalité stricte (forfait mutuel
  // 0-0, les deux équipes incapables d'aligner un cinq — cas limite déjà géré
  // à part par simulateOrForfeit) : l'équipe À DOMICILE est arbitrairement
  // déclarée gagnante plutôt que de laisser un tableau bloqué sans vainqueur
  // — aussi rare que le même cas en barrage de relégation (voir
  // runRelegationBarrage), qui n'a pas non plus vraiment de règle dédiée.
  recordCupMatchResult(matchIndex, scoreHome, scoreAway, forfeit) {
    const round = this.pendingCupRound();
    if (!round) return;
    const m = round.matches[matchIndex];
    if (!m || m.bye) return;
    m.scoreHome = scoreHome;
    m.scoreAway = scoreAway;
    m.forfeit = forfeit;
    m.winner = scoreAway > scoreHome ? m.away : m.home;
    applySponsorWinPrimes(this.teams[m.winner]);
    // Prime de Coupe par match gagné (retour utilisateur 2026-09-28), selon
    // la distance à la finale.
    payCupWinBonus(this.teams[m.winner], CUP_STAGE_NAMES.length - 1 - CUP_STAGE_NAMES.indexOf(round.name));
    m.resolved = true;
  }

  // Clôt le tour en attente une fois TOUS ses matchs réels enregistrés (voir
  // recordCupMatchResult) : marque le tour résolu puis, soit couronne le
  // champion (c'était la finale), soit engendre le tour suivant en appariant
  // les vainqueurs (voir buildNextCupRound) — jamais les deux à la fois.
  // No-op silencieux si aucun tour n'est en attente (ligue sans coupe, ou
  // coupe déjà terminée).
  advanceCup(now = Date.now()) {
    const round = this.pendingCupRound();
    if (!round) return;
    round.resolved = true;
    const winners = round.matches.map(m => m.winner);
    if (round.name === CUP_STAGE_NAMES[CUP_STAGE_NAMES.length - 1]) {
      this.cup.champion = winners[0];
      // Mémoire historique : finale de Coupe (rivalité, finale perdue).
      try {
        const m = round.matches[0];
        const w = this.teams[winners[0]], l = m && this.teams[m.home === winners[0] ? m.away : m.home];
        if (w && l) {
          const season = histSeasonOf(w.isHuman ? w : l.isHuman ? l : w);
          History.bumpRivalry(w, l, 10, now, season, { type: "FINAL", text: `${w.name} a battu ${l.name} en finale de la Coupe, saison ${season}.` });
          const ev = History.push({ type: "FINAL_LOSS", importance: 3, season, at: now, teams: [l.name, w.name], competition: "cup", description: `Finale de la Coupe perdue face à ${w.name}.`, tags: ["finale"] });
          histFeed(l, ev, "Finale perdue", now);
        }
      } catch (e) { /* confort */ }
      this.recordTrophy(winners[0], "cup", now);
    } else {
      this.cup.rounds.push(buildNextCupRound(round, winners));
    }
  }

  // Trophée du club (retour utilisateur, voir le grand commentaire sur
  // generateFoundedYear/MAX_TEAM_TROPHIES plus haut) : hook UNIQUE partagé
  // par les deux couronnes d'une saison, coupe (voir advanceCup ci-dessus) et
  // championnat (voir runPlayoffs plus bas), pour ne pas dupliquer la même
  // construction de libellé aux deux endroits. `now` par défaut à Date.now()
  // (temps RÉEL, jamais le calendrier simulé) : un trophée est un souvenir
  // daté pour l'affichage, pas une donnée lue par le moteur de simulation.
  // Fonctionne identiquement en solo (seule teamA survit d'une saison à
  // l'autre, voir startNewSeason côté moteurbasket3.html — les trophées des
  // adversaires régénérés sont perdus avec eux, sans conséquence) et en
  // ligue multi-manager (toutes les équipes persistent).
  recordTrophy(teamIdx, type, now = Date.now()) {
    const team = this.teams[teamIdx];
    if (!team) return;
    const info = divisionInfo(this.divisionLevel);
    const label = type === "cup"
      ? `Vainqueur de la Coupe (${info.name})`
      : `Champion (${info.name})`;
    team.trophies = team.trophies || [];
    const firstOfKind = !team.trophies.some(t => t.type === type);
    team.trophies.unshift({ at: now, type, divisionLevel: this.divisionLevel || null, label, seasonId: this.seasonId || null });
    try {
      const ev = History.push({
        type: firstOfKind ? "FIRST_TITLE" : "TITLE", importance: firstOfKind || type === "championship" ? 4 : 3,
        season: histSeasonOf(team), at: now, teams: [team.name], competition: type,
        description: firstOfKind ? `Premier titre de l'histoire du club : ${label}.` : `${label}.`, tags: ["titre"],
      });
      histFeed(team, ev, firstOfKind ? "Premier titre de l'histoire du club" : "Nouveau titre", now);
    } catch (e) { /* confort */ }
    // Succès « Coupe en poche » (le titre de champion est compté en fin de
    // saison, avec la série « Dynastie », voir achSeasonEnd).
    if (type === "cup") achAddOnce(team, "cups", `cup:${this.leagueId || "lg"}:${this.seasonId || now}`, now);
    if (team.trophies.length > MAX_TEAM_TROPHIES) team.trophies.length = MAX_TEAM_TROPHIES;
  }

  // Phase finale : les 4 premiers du classement, demi-finales (1er-4e,
  // 2e-3e) puis finale, chaque tour en deux matchs gagnants. Retour
  // utilisateur (2026-09) : "les play offs doivent être comme les matchs de
  // saisons régulières, avec un live [...] sur plusieurs jours réels (et pas
  // tout simulés d'un coup)" : chaque MATCH de play-offs est donc résolu un
  // par un, à son propre tour de calendrier (voir playoffs.round plus bas),
  // exactement comme un match de championnat (voir server/liveMatch.js
  // ensurePlayoffLiveMatchStarted/finalizePlayoffRound, server/autoSim.js).
  // `startPlayoffsIfNeeded` ne fait QUE poser l'état initial (tirage au sort
  // des têtes de série, les deux demi-finales encore vides) ; c'est
  // recordPlayoffGameResult ci-dessous qui fait progresser chaque série
  // match par match. No-op si les play-offs existent déjà, ou si la saison
  // régulière n'est pas terminée.
  startPlayoffsIfNeeded(now = Date.now()) {
    if (this.playoffs || !this.isRegularSeasonDone()) return this.playoffs;
    const seeds = this.standings().slice(0, 4).map(s => s.idx);
    const makeSeries = (idxA, idxB) => ({
      idxA, idxB, games: [], winsA: 0, winsB: 0, winner: null, resolved: false,
    });
    this.playoffs = {
      seeds,
      // Continuation de l'index de journée du championnat (voir
      // League.round/totalRounds) : le premier match de play-offs tombe
      // donc, sans le moindre changement à scheduledTimeForLeagueRound
      // (calendrier classique comme ancré quotidien), au tout prochain
      // créneau réel après le dernier match de saison régulière. Compteur
      // SÉPARÉ de this.round (qui reste figé à totalRounds une fois la
      // saison régulière terminée) pour ne jamais perturber
      // matchesForRound/nextUserMatch, qui ne connaissent que le
      // championnat.
      round: this.totalRounds,
      series: [makeSeries(seeds[0], seeds[3]), makeSeries(seeds[1], seeds[2])],
      finalSeries: null,
      champion: null,
      // Instantané des joueurs ayant disputé la demi-finale de CHAQUE
      // équipe (voir _queuePlayoffSeriesInterview ci-dessous), keyed par idx
      // d'équipe : alimenté série par série, au moment précis où elle se
      // termine, jamais en bloc à la fin comme l'ancienne v1 synchrone.
      semiPlayerIds: {},
    };
    // Récompenses de la saison régulière (voir awardRegularSeasonAwards).
    if (typeof awardRegularSeasonAwards === "function") awardRegularSeasonAwards(this, now);
    return this.playoffs;
  }

  // Paires à jouer POUR CE TOUR de play-offs (en pratique toujours appelé
  // avec playoffs.round lui-même, voir server/liveMatch.js) : au plus une
  // par demi-finale encore vivante tant que la finale n'est pas encore
  // constituée, sinon la seule paire de la finale. Ne renvoie un tableau
  // vide QUE une fois le champion connu (voir isPlayoffsDone) : tant que les
  // play-offs sont en cours, il y a toujours au moins une série vivante à ce
  // tour (au plus 3 tours par série, voir recordPlayoffGameResult, donc
  // jamais de tour "creux").
  playoffMatchesForRound(round) {
    const po = this.playoffs;
    if (!po || po.champion != null || round !== po.round) return [];
    const out = [];
    const addIfLive = (series, seriesId) => {
      if (!series || series.resolved) return;
      const gameIndex = series.games.length;
      const aHome = gameIndex % 2 === 0; // alternance stricte, tête de série à domicile au match 1
      const home = aHome ? series.idxA : series.idxB;
      const away = aHome ? series.idxB : series.idxA;
      out.push({ home, away, seriesId, gameIndex });
    };
    if (!po.finalSeries) {
      addIfLive(po.series[0], "semi0");
      addIfLive(po.series[1], "semi1");
    } else {
      addIfLive(po.finalSeries, "final");
    }
    return out;
  }

  // true une fois la finale jouée (champion connu) : c'est CE flag, et non
  // plus la simple existence de league.playoffs (posée dès
  // startPlayoffsIfNeeded, avant le moindre match joué), qui signale la
  // vraie fin de la saison côté server/autoSim.js et navigateur.
  isPlayoffsDone() {
    return !!(this.playoffs && this.playoffs.champion != null);
  }

  // Enregistre le résultat d'UN match de play-offs (identifié par
  // `seriesId`, voir playoffMatchesForRound) : fait progresser la série
  // correspondante, la clôt à 2 victoires, puis soit prépare la finale (les
  // deux demies terminées), soit couronne le champion (finale terminée).
  // Voir server/liveMatch.js:finalizePlayoffRound (chemin normal, un match à
  // la fois, en direct) et League.runPlayoffsInstantly (tests/repli) pour
  // les deux seuls appelants.
  // Mémoire historique (assets/history.js) : série de play-offs décidée —
  // rivalité, exploit d'une tête de série plus faible, finale perdue.
  _historySeries(series, seriesId, now) {
    const po = this.playoffs;
    const w = this.teams[series.winner], loserIdx = series.winner === series.idxA ? series.idxB : series.idxA, l = this.teams[loserIdx];
    if (!w || !l) return;
    const season = histSeasonOf(w.isHuman ? w : l.isHuman ? l : w);
    const seedW = po.seeds.indexOf(series.winner) + 1, seedL = po.seeds.indexOf(loserIdx) + 1;
    const final = seriesId === "final";
    const res = `${series.winsA === 2 ? series.winsA : series.winsB}-${series.winsA === 2 ? series.winsB : series.winsA}`;
    History.bumpRivalry(w, l, final ? 12 : 8, now, season, {
      type: final ? "FINAL" : "SERIES",
      text: final ? `${w.name} a battu ${l.name} en finale des play-offs (${res}), saison ${season}.` : `${w.name} a éliminé ${l.name} en demi-finale des play-offs (${res}), saison ${season}.`,
    });
    if (seedW > seedL && seedL > 0) {
      History.push({ type: "PLAYOFF_UPSET", importance: final ? 3 : 2, season, at: now, teams: [w.name, l.name], competition: "playoffs",
        description: `Exploit en play-offs : ${w.name} (${seedW}e) élimine ${l.name} (${seedL}e) ${res}${final ? " en finale" : ""}.`, statistics: { seedWinner: seedW, seedLoser: seedL }, tags: ["exploit"] });
    }
    if (final) {
      const ev = History.push({ type: "FINAL_LOSS", importance: 3, season, at: now, teams: [l.name, w.name], competition: "playoffs",
        description: `Finale des play-offs perdue face à ${w.name} (${res}).`, tags: ["finale"] });
      histFeed(l, ev, "Finale perdue", now);
    }
  }

  recordPlayoffGameResult(seriesId, home, away, scoreHome, scoreAway, now = Date.now()) {
    const po = this.playoffs;
    if (!po) return;
    const series = seriesId === "semi0" ? po.series[0]
      : seriesId === "semi1" ? po.series[1]
      : po.finalSeries;
    if (!series || series.resolved) return;
    series.games.push({ home, away, scoreHome, scoreAway });
    const aWon = home === series.idxA ? scoreHome > scoreAway : scoreAway > scoreHome;
    if (aWon) series.winsA++; else series.winsB++;
    applySponsorWinPrimes(this.teams[aWon ? series.idxA : series.idxB]);
    if (series.winsA < 2 && series.winsB < 2) return; // série pas encore décidée
    series.resolved = true;
    series.winner = series.winsA === 2 ? series.idxA : series.idxB;
    try { this._historySeries(series, seriesId, now); } catch (e) { /* confort */ }
    if (seriesId === "final") {
      po.champion = series.winner;
      this.recordTrophy(series.winner, "championship", now);
      // Interview de jalon "finale de PO" (retour utilisateur, 2026-09 :
      // "on peut ajouter un interview post finale de PO, en cas de victoire
      // ou défaite") : même mécanique que la demi-finale ci-dessous, pour
      // CHAQUE finaliste humain. Pas de snapshot semiPlayerIds équivalent
      // ici (inutile : la finale est le dernier match de la saison, rien ne
      // resimule plus ces joueurs avant la saison prochaine).
      this._queuePlayoffSeriesInterview(series, now, "finale-po");
      return;
    }
    // Demi-finale décidée : interview de jalon (voir
    // _queuePlayoffSeriesInterview ci-dessous) pour CETTE série, capturée
    // IMMÉDIATEMENT (donc jamais écrasée par une future série, contrairement
    // à l'ancien compromis synchrone) puis, si les DEUX demies sont
    // désormais résolues, constitution de la finale.
    this._queuePlayoffSeriesInterview(series, now, "demi-finale-po", "semiPlayerIds");
    if (po.series[0].resolved && po.series[1].resolved && !po.finalSeries) {
      po.finalSeries = {
        idxA: po.series[0].winner, idxB: po.series[1].winner,
        games: [], winsA: 0, winsB: 0, winner: null, resolved: false,
      };
    }
  }

  // Interview de jalon "demi-finale de PO" OU "finale de PO" (retour
  // utilisateur, 2026-09, voir le grand commentaire de
  // MILESTONE_INTERVIEW_TYPES plus haut) pour CHAQUE équipe humaine de
  // `series` (qu'elle ait gagné ou perdu) : appelée par
  // recordPlayoffGameResult dès que cette série se termine, jamais en bloc
  // après coup comme l'ancienne v1 synchrone. `round` volontairement `null`
  // (aucune journée de calendrier ne correspond à une série de play-offs à
  // proprement parler, elle s'étale sur plusieurs) : cette interview n'est
  // donc jamais retrouvée par round (contrairement aux jalons de saison
  // régulière), uniquement par `milestone` (voir
  // showCatchupSummaryIfAny/showSeasonEnd côté navigateur). `snapshotKey`
  // (optionnel, ex. "semiPlayerIds") : nom du dictionnaire `this.playoffs`
  // où figer l'instantané des joueurs ayant disputé CETTE série, capturé
  // MAINTENANT (avant qu'une autre série, y compris la finale, ne resimule
  // ces mêmes joueurs et n'écrase leur secondsPlayed) ; omis pour la finale,
  // qui n'a besoin d'aucun instantané (dernier match de la saison).
  _queuePlayoffSeriesInterview(series, now, milestone, snapshotKey = null) {
    [series.idxA, series.idxB].forEach(idx => {
      const team = this.teams[idx];
      const playerIds = team ? team.players.filter(p => p.secondsPlayed > 0).map(p => p.id) : [];
      if (snapshotKey) this.playoffs[snapshotKey][idx] = playerIds;
      if (!team || !team.isHuman) return;
      const opponentIdx = idx === series.idxA ? series.idxB : series.idxA;
      const opponent = this.teams[opponentIdx];
      const won = series.winner === idx;
      const lastGame = series.games[series.games.length - 1];
      const isHomeLastGame = lastGame.home === idx;
      const scoreDiff = isHomeLastGame
        ? lastGame.scoreHome - lastGame.scoreAway
        : lastGame.scoreAway - lastGame.scoreHome;
      team.applyMoraleForResult(won, scoreDiff, opponent ? opponent.name : "l'adversaire", null, now, milestone, playerIds);
    });
  }

  // Prochain match de play-offs de `teamIdx` (index 0 par défaut) au tour
  // COURANT (playoffs.round) : équivalent de nextUserMatch, mais pour la
  // phase finale. `null` si les play-offs n'existent pas encore, sont déjà
  // terminés, ou si `teamIdx` n'est engagé dans AUCUNE série vivante ce
  // tour-ci (éliminé, ou pas qualifié) : contrairement à nextUserMatch, ne
  // cherche jamais au-delà du tour courant, puisqu'un tour de play-offs
  // n'avance que lorsque TOUTES ses séries vivantes ont joué (voir
  // finalizePlayoffRound côté server/liveMatch.js) : il n'y a donc jamais de
  // tour "déjà joué" à sauter.
  nextUserPlayoffMatch(teamIdx = 0) {
    const po = this.playoffs;
    if (!po || po.champion != null) return null;
    const m = this.playoffMatchesForRound(po.round).find(x => x.home === teamIdx || x.away === teamIdx);
    if (!m) return null;
    const isHome = m.home === teamIdx;
    return { round: po.round, isHome, opponent: isHome ? m.away : m.home, seriesId: m.seriesId };
  }

  // Résout les play-offs entièrement, tour par tour, en simulant chaque
  // match (jamais de diffusion en direct) : utilisé par les tests, et par le
  // repli défensif côté navigateur (voir enterNextMatchOrShowSeasonEnd) pour
  // le cas rare où l'écran de fin de saison est atteint sans être passé par
  // le rattrapage serveur normal (voir server/autoSim.js:catchUpLeague, le
  // chemin RÉEL, un match à la fois/en direct, qui n'appelle jamais cette
  // méthode). `competition` posé à "championship" comme pour un match de
  // championnat classique (voir le même choix côté finalizePlayoffRound) :
  // les stats/MVP/box-score des play-offs vivent dans le même flux que la
  // saison régulière, seul `round` (>= totalRounds) les distingue.
  runPlayoffsInstantly(now = Date.now()) {
    this.startPlayoffsIfNeeded(now);
    while (this.playoffs && this.playoffs.champion == null) {
      const round = this.playoffs.round;
      const matches = this.playoffMatchesForRound(round);
      matches.forEach(m => {
        const result = simulateOrForfeit(this.teams[m.home], this.teams[m.away], now);
        if (!result.forfeit) {
          recordMatchStatsAndAwardMvp(this.teams[m.home], this.teams[m.away], round, "championship", now, result.quarterScores, result.tacticsUsed, result.seed);
        }
        this.recordPlayoffGameResult(m.seriesId, m.home, m.away, result.scoreHome, result.scoreAway, now);
      });
      this.playoffs.round += 1;
    }
    return this.playoffs;
  }

  // Barrage de relégation : le 7e et le 8e de la saison régulière
  // s'affrontent en un match sec, le perdant rejoint le 9e et le 10e parmi
  // les équipes reléguées (voir relegatedTeamIndexes) — le 9e et le 10e,
  // eux, descendent toujours directement, sans barrage.
  runRelegationBarrage() {
    // Barrage programmé en direct (voir scheduleRelegationBarrage) pas
    // encore joué : simulé tout de suite (rattrapage tardif, montées et
    // descentes à calculer).
    const pending = this.relegationBarrage && this.relegationBarrage.pending ? this.relegationBarrage : null;
    const table = this.standings();
    const idx7 = pending ? pending.idx7 : table[6].idx, idx8 = pending ? pending.idx8 : table[7].idx; // 7e et 8e (0-indexé)
    const result = simulateOrForfeit(this.teams[idx7], this.teams[idx8]);
    if (pending) return this.resolveRelegationBarrage(result.scoreHome, result.scoreAway);
    const scoreHome = result.scoreHome, scoreAway = result.scoreAway;
    const loser = scoreHome > scoreAway ? idx8 : idx7;
    const winner = loser === idx7 ? idx8 : idx7;
    this.relegationBarrage = { idx7, idx8, scoreHome, scoreAway, winner, loser };
    return this.relegationBarrage;
  }

  // Barrage EN DIRECT (retour utilisateur 2026-09-28 : « barrage en 1 match
  // sec », en direct comme les autres matchs) : programmé à `at` (premier
  // créneau des play-offs, les 7e et 8e n'y jouent pas), le 7e reçoit ;
  // joué par server/autoSim.js:stepRelegationBarrage.
  scheduleRelegationBarrage(at) {
    const table = this.standings();
    this.relegationBarrage = {
      idx7: table[6].idx, idx8: table[7].idx, at,
      scoreHome: null, scoreAway: null, winner: null, loser: null, pending: true, started: false,
    };
    return this.relegationBarrage;
  }

  resolveRelegationBarrage(scoreHome, scoreAway) {
    const b = this.relegationBarrage;
    if (!b) return null;
    b.scoreHome = scoreHome;
    b.scoreAway = scoreAway;
    b.loser = scoreHome > scoreAway ? b.idx8 : b.idx7;
    b.winner = b.loser === b.idx7 ? b.idx8 : b.idx7;
    b.pending = false;
    return b;
  }

  // Indices (dans this.teams) des équipes reléguées cette saison : le 9e et
  // le 10e automatiquement, plus le perdant du barrage 7e-8e (voir
  // runRelegationBarrage — doit avoir été joué avant, sinon renvoie juste le
  // 9e et le 10e).
  relegatedTeamIndexes() {
    const table = this.standings();
    // Championnats par pays (server/world.js:divisionMovesFor, 2026-09-30) :
    // autant de descentes que de championnats ouverts juste en dessous
    // (10e, puis 9e, puis perdant du barrage) — aucune s'il n'y en a pas.
    const dm = this.divisionMoves;
    if (dm && typeof dm === "object") {
      const n = Math.max(0, Math.min(3, Number(dm.relegations) || 0));
      const out = [];
      if (n >= 1 && table[table.length - 1]) out.push(table[table.length - 1].idx);
      if (n >= 2 && table[table.length - 2]) out.push(table[table.length - 2].idx);
      if (n >= 3 && this.relegationBarrage && this.relegationBarrage.loser != null) out.push(this.relegationBarrage.loser);
      return out;
    }
    const auto = [table[8].idx, table[9].idx]; // 9e, 10e (0-indexé : rangs 8,9)
    return this.relegationBarrage && this.relegationBarrage.loser != null ? [...auto, this.relegationBarrage.loser] : auto;
  }

  // Résultat de promotion/relégation pour le club du joueur (index 0) dans
  // la pyramide de divisions, une fois les play-offs ET le barrage de
  // relégation joués : le champion des play-offs monte d'un niveau (sauf
  // s'il est déjà en Division I, la plus haute) ; sinon, s'il fait partie
  // des équipes reléguées, il descend d'un niveau (sauf s'il est déjà en
  // Division VI, la plus basse). Renvoie { outcome: "promoted"|"relegated"|
  // "stay", fromLevel, toLevel }.
  divisionOutcomeForUserTeam() {
    return this.divisionOutcomeForTeam(0);
  }

  // Même calcul pour n'importe quelle équipe de la ligue (multi-manager).
  divisionOutcomeForTeam(teamIdx) {
    const fromLevel = this.divisionLevel || MAX_DIVISION_LEVEL;
    const champion = this.playoffs ? this.playoffs.champion : null;
    let outcome = "stay", toLevel = fromLevel;
    const canPromote = this.divisionMoves && typeof this.divisionMoves === "object" ? !!this.divisionMoves.promotes : fromLevel > 1;
    if (champion === teamIdx && fromLevel > 1 && canPromote) {
      outcome = "promoted";
      toLevel = fromLevel - 1;
    } else if (this.relegatedTeamIndexes().includes(teamIdx) && fromLevel < MAX_DIVISION_LEVEL) {
      outcome = "relegated";
      toLevel = fromLevel + 1;
    }
    // Champion de Division I : aucune montée possible (déjà tout en haut de
    // la pyramide), mais mérite quand même sa propre prime (voir
    // CHAMPION_BONUS_DIVISION_I / seasonEndBonusFor) — à détecter à part,
    // puisque l'outcome ci-dessus reste "stay" dans ce cas précis.
    const championDivisionI = champion === teamIdx && fromLevel === 1;
    return { outcome, fromLevel, toLevel, championDivisionI };
  }

  // ---------------------------------------------------------------------
  // NOUVELLE SAISON AUTOMATIQUE (retour utilisateur 2026-09-28 : effectifs
  // conservés d'une saison à l'autre, "laisser une semaine d'intersaison
  // [...] on a le temps de faire ses changements de joueurs", "à
  // l'intersaison les formes doivent être remises à 0", motivation ramenée
  // à « Neutre » pour ceux qui sont en dessous). Cycle de 12 semaines :
  // 9 de championnat + 2 de play-offs + 1 d'intersaison.
  //  - Lundi qui suit la finale (mise à jour de fin de saison, voir
  //    server/autoSim.js:runWeeklyEconomyTick) : vieillissement, salaires,
  //    retraites, primes de fin de saison, puis startIntersaison ci-dessous.
  //  - Lundi suivant : mise à jour hebdomadaire normale (salaires de la
  //    semaine, entraînement sur les minutes des amicaux d'intersaison),
  //    puis startNextSeason : nouveau calendrier, nouvelle Coupe, classement
  //    remis à zéro, MÊMES clubs et MÊMES effectifs.
  // ---------------------------------------------------------------------

  // Début d'intersaison : forme physique de TOUS les joueurs remise à 100,
  // motivation relevée à INTERSAISON_MOTIVATION_FLOOR pour ceux qui sont en
  // dessous (les demandes de transfert en cours se referment donc).
  startIntersaison(now = Date.now()) {
    this.intersaisonStartedAt = now;
    this.teams.forEach(t => {
      (t.players || []).forEach(p => {
        p.condition = 100;
        p.conditionUpdatedAt = now;
        if (p.form < INTERSAISON_MOTIVATION_FLOOR) p.form = INTERSAISON_MOTIVATION_FLOOR;
        p.weeksAtLowMotivation = 0;
        p.transferRequestActive = false;
        p.transferRequestQuote = null;
        p.transferRequestDiscussed = false;
      });
    });
  }

  // Primes de fin de saison pour chaque club humain (champion de Division I ;
  // prime de montée quand la montée est réellement appliquée, voir la
  // pyramide). Une seule fois par saison et par club (seasonId).
  paySeasonEndBonuses(now = Date.now()) {
    const paid = [];
    const seasonId = this.seasonId || `start:${this.calendarStartAt || 0}`;
    this.teams.forEach((t, idx) => {
      if (!t || !t.isHuman || t.lastSeasonBonusSeasonId === seasonId) return;
      t.lastSeasonBonusSeasonId = seasonId;
      const outcome = this.divisionOutcomeForTeam(idx);
      if (!outcome.championDivisionI) return; // montées : voir la pyramide
      const bonus = seasonEndBonusFor(outcome);
      if (!bonus) return;
      t.recordTransaction(bonus.label, bonus.amount);
      paid.push({ teamIdx: idx, ...bonus });
    });
    return paid;
  }

  // Nouvelle saison avec les MÊMES clubs et effectifs. `now` = lundi 0h de
  // la reprise ; le championnat reprend le mardi suivant à 20h (même rythme
  // hebdomadaire). Renvoie le numéro de la nouvelle saison.
  startNextSeason(now = Date.now()) {
    this.seasonNumber = (typeof this.seasonNumber === "number" ? this.seasonNumber : 1) + 1;
    this.seasonId = randomHexToken(4);
    this.schedule = generateRoundRobinSchedule(this.teams.length);
    this.round = 0;
    this.results = [];
    this.playoffs = null;
    this.relegationBarrage = null;
    this.liveMatches = {};
    this.liveMatch = null;
    this.seasonEndTickDone = false;
    this.intersaisonStartedAt = null;
    this.calendarWeeklySwitch = null;
    this.lastEconomyTick = 0;
    this.lastAutoTrainedWeek = -1;
    this.lastAutoTrainedDay = -1;
    if (this.calendarDailyAnchored) {
      this.calendarStartAt = dailyAnchoredCalendarStartAt(now, this.calendarWeeklyRhythm, this.timeZone || null);
      // Championnats du monde (leagueId posé, voir server/world.js) : la
      // Coupe est NATIONALE (server/nationalCup.js), plus de Coupe interne.
      this.cup = this.leagueId ? null : { rounds: [generateCupBracket(this.teams.map((_, i) => i))], champion: null };
    }
    this.teams.forEach(t => {
      // Stats de saison : la saison écoulée est déjà archivée (histoire du
      // club) ; les amicaux d'intersaison ne comptent pas dans la nouvelle.
      (t.players || []).forEach(p => { p.matchLog = []; });
      t.departedMatchLog = [];
      // Ordres préparés : la clé « compétition:journée » repart de zéro à
      // chaque saison — un plan resté inutilisé (ex. finale de play-offs non
      // atteinte) s'appliquerait sinon à la même journée de la saison
      // suivante.
      t.plannedTactics = {};
      t.matchOrdersUsed = {};
      if (!t.isHuman) t.autoAssignLineup();
    });
    assignSeasonObjectives(this);
    this.teams.forEach(t => {
      if (!t.isHuman) return;
      if (typeof t.queueSeasonPreviewInterview === "function") t.queueSeasonPreviewInterview(now);
      if (t.feed) {
        pushEntry(t.feed, {
          key: "season_start", category: "ligue", week: t.week, createdAt: now,
          title: `La saison ${this.seasonNumber} est lancée`,
          text: "Nouveau calendrier, nouvelle Coupe : premier match mardi à 20:00. Votre effectif est conservé.",
          action: { label: "Calendrier", href: "/calendrier" },
        });
      }
    });
    return this.seasonNumber;
  }

  // ---------------------------------------------------------------------
  // CONTRATS DES JOUEURS (demande validée 2026-10-01, voir
  // CONTRACT_MIN_SEASONS). La saison de contrat courante passe à la
  // suivante dès la mise à jour de fin de saison (intersaison comprise).
  // ---------------------------------------------------------------------
  contractSeason() {
    return (typeof this.seasonNumber === "number" ? this.seasonNumber : 1) + (this.seasonEndTickDone ? 1 : 0);
  }

  // Semaine de la saison en cours (1 = avant la première mise à jour du
  // lundi), sur SEASON_LENGTH_WEEKS (9 de championnat + 2 de play-offs).
  seasonWeek() {
    if (this.seasonEndTickDone) return 1;
    if (this.calendarWeeklyRhythm) return Math.min(SEASON_LENGTH_WEEKS, (this.lastEconomyTick || 0) + 1);
    const rounds = (this.schedule && this.schedule.length) || 1;
    if (typeof this.isRegularSeasonDone === "function" && this.isRegularSeasonDone()) return SEASON_LENGTH_WEEKS;
    return Math.min(SEASON_LENGTH_WEEKS, Math.floor((this.round || 0) * (SEASON_LENGTH_WEEKS - 2) / rounds) + 1);
  }

  isSecondHalfOfSeason() {
    return this.seasonWeek() > SEASON_LENGTH_WEEKS / 2;
  }

  // Vente interdite d'un joueur en DERNIÈRE saison de contrat pendant la
  // seconde moitié de saison (il partira libre).
  contractSaleBlocked(player) {
    return !!player && isLastContractSeason(player, this.contractSeason()) && this.isSecondHalfOfSeason();
  }

  // Contrat attribué à tout joueur qui n'en a pas (ancienne sauvegarde,
  // effectif généré, recrue de complément) : durée selon l'âge, déterministe
  // par id ; salaire inchangé. Renvoie le nombre de contrats posés.
  ensureContracts() {
    const season = this.contractSeason();
    let n = 0;
    (this.teams || []).forEach(t => {
      ((t && t.players) || []).forEach(p => {
        if (typeof p.contractUntilSeason === "number") return;
        p.contractUntilSeason = season + initialContractSeasonsFor(p.age, p.id) - 1;
        n++;
      });
    });
    return n;
  }

  freeAgentById(playerId) {
    return (this.freeAgents || []).find(p => p.id === playerId) || null;
  }

  // Joueur d'une annonce (club vendeur ou agent libre).
  listingPlayer(listing) {
    if (!listing) return null;
    if (listing.freeAgent) return this.freeAgentById(listing.playerId);
    const seller = this.teams[listing.sellerIdx];
    return (seller && seller.players.find(p => p.id === listing.playerId)) || null;
  }

  // Ancien club d'un agent libre : jamais autorisé à enchérir sur lui.
  _isFormerClub(listing, team, idx) {
    if (!listing || !listing.freeAgent || !team) return false;
    if (idx != null && idx >= 0 && idx === listing.formerTeamIdx) return true;
    return !!listing.formerTeamName && team.name === listing.formerTeamName;
  }

  // Durée de contrat choisie avec l'offre (enchère ou plafond automatique),
  // mémorisée par club sur l'annonce.
  _rememberContractTerms(listing, key, seasons) {
    if (seasons == null) return;
    listing.contractTerms = listing.contractTerms || {};
    listing.contractTerms[key] = normalizeContractSeasons(seasons);
  }
  _contractSeasonsFor(listing, key) {
    const v = listing.contractTerms && listing.contractTerms[key];
    return normalizeContractSeasons(v);
  }

  // Signature au salaire demandé (gelé sur l'annonce) pour la durée choisie
  // avec l'enchère ; message de confirmation au club humain.
  _applyTransferContract(listing, buyer, player, buyerSeason, now) {
    const key = listing.currentBidderIdx === FOREIGN_BIDDER_IDX ? autoBidKey(FOREIGN_BIDDER_IDX, listing.currentBidderRef) : autoBidKey(listing.currentBidderIdx, null);
    // Accord négocié avant l'enchère (voir negotiateTransferContract) ;
    // sans accord (club de l'IA) : salaire demandé, durée de l'offre.
    const deal = this._transferAgreementFor(listing, key);
    const seasons = deal && deal.seasons ? normalizeContractSeasons(deal.seasons)
      : buyer.isHuman ? this._contractSeasonsFor(listing, key) : normalizeContractSeasons(listing.contractTerms && listing.contractTerms[key], 2 + Math.floor(rand01() * 3));
    const agreed = deal && typeof deal.salary === "number" ? deal.salary : (typeof listing.askedSalary === "number" ? listing.askedSalary : askedSalary(player));
    // Visite médicale : antécédents → salaire revu de 5 à 10 %.
    const medical = medicalCheckFor(player, now != null ? now : Date.now());
    const salary = medical.rate ? Math.max(SALARY_MIN, Math.round(agreed * (1 - medical.rate) / 10) * 10) : agreed;
    signNewContract(player, seasons, buyerSeason, salary);
    const result = { seasons, salary, agreedSalary: agreed, medicalRate: medical.rate, medicalEntries: medical.entries };
    listing.signed = { seasons, salary, agreedSalary: agreed, medicalRate: medical.rate };
    if (buyer.isHuman && buyer.feed) {
      const pct = Math.round(medical.rate * 100);
      const what = medical.entries.slice(0, 2).map(e => `${e.type}${e.days ? ` (${e.days} j)` : ""}`).join(", ");
      pushEntry(buyer.feed, {
        key: `contract_signed_${player.id}`, category: "marche", week: buyer.week, createdAt: now,
        title: `${player.name} a signé`,
        text: `${player.name} rejoint le club pour ${seasons} saison${seasons > 1 ? "s" : ""}, à ${salary.toLocaleString("fr-FR")} $/sem.` +
          (medical.rate ? ` Visite médicale : antécédents (${what}), salaire convenu de ${agreed.toLocaleString("fr-FR")} $ revu de -${pct} %.` : " Visite médicale : rien à signaler."),
        action: { label: "Fiche joueur", href: `/joueur/${player.id}` },
      });
    }
    return result;
  }

  // Annonce « agent libre » : départ à 1 $, la mise est une prime de
  // signature payée au joueur. L'ancien club n'y a pas accès.
  createFreeAgentListing(player, formerTeamIdx, formerTeamName, now) {
    this.transferListings = this.transferListings || [];
    const listing = {
      id: uid(), playerId: player.id, sellerIdx: null, freeAgent: true,
      formerTeamIdx: typeof formerTeamIdx === "number" ? formerTeamIdx : null, formerTeamName: formerTeamName || null,
      askedSalary: askedSalary(player),
      startPrice: 1, currentBid: null, currentBidderIdx: null, bids: [],
      createdAt: now, closesAt: now + FREE_AGENT_AUCTION_DURATION_MS, lastCpuCheckAt: now,
      status: "open", result: null, finalPrice: null,
    };
    this.transferListings.push(listing);
    return listing;
  }

  // Licenciement d'un joueur par un club humain (retour utilisateur
  // 2026-10-03) : indemnité payée (releaseIndemnityFor), puis le joueur part
  // agent libre comme en fin de contrat.
  releasePlayer(teamIdx, playerId, now = Date.now()) {
    const team = this.teams[teamIdx];
    const p = team && team.players.find(x => x.id === playerId);
    if (!p) return { ok: false, reason: "not-found" };
    const fee = releaseIndemnityFor(p, this.contractSeason(), this.seasonWeek());
    if (team.isHuman && fee > (team.budget || 0)) return { ok: false, reason: "budget", fee };
    if (fee) team.recordTransaction(`Indemnité de licenciement de ${p.name}`, -fee);
    this._releaseToFreeAgency(team, teamIdx, p, now, { released: true, fee });
    return { ok: true, fee, playerName: p.name };
  }

  // Joueur qui quitte `team` en fin de contrat : agent libre mis aux enchères.
  _releaseToFreeAgency(team, teamIdx, p, now, opts = null) {
    const i = team.players.findIndex(x => x.id === p.id);
    if (i === -1) return;
    team.players.splice(i, 1);
    archiveDepartedMatchLog(team, p);
    // Historique : licenciement (décision du manager) ou fin de contrat.
    const released = !!(opts && opts.released);
    recordTeamTransfer(team, {
      id: `${this.leagueId || "lg"}:${released ? "R" : "X"}${p.id}:${now}`, at: now, kind: released ? "release" : "expiry", player: p,
      from: transferTeamRef(team, this.leagueId, teamIdx), to: null, fee: 0, human: released && team.isHuman,
      indemnity: released ? (opts.fee || 0) : 0,
    });
    (this.transferListings || []).forEach(l => {
      if (l.status === "open" && !l.freeAgent && l.playerId === p.id && l.sellerIdx === teamIdx) { l.status = "cancelled"; l.result = "contract-ended"; }
    });
    if (team.isHuman) team.handleStarterDeparture(p.id);
    p.contractUntilSeason = null;
    p.nextSalary = null;
    p.raiseRequest = null;
    p.lastContractOfferWeek = null;
    p.contractRefusals = 0;
    p.forSale = false;
    p.salePrice = null;
    p.retiringAfterSeason = false;
    p.transferRequestActive = false;
    p.transferRequestQuote = null;
    p.transferRequestDiscussed = false;
    if (p.form < INTERSAISON_MOTIVATION_FLOOR) p.form = INTERSAISON_MOTIVATION_FLOOR;
    this.freeAgents = this.freeAgents || [];
    this.freeAgents.push(p);
    this.createFreeAgentListing(p, teamIdx, team.name, now);
    if (team.isHuman && team.feed) {
      removeByKey(team.feed, `contract_ext_${p.id}`);
      pushEntry(team.feed, {
        key: `contract_left_${p.id}`, category: "club", week: team.week, createdAt: now,
        title: opts && opts.released ? `${p.name} licencié` : `${p.name} quitte le club libre`,
        text: opts && opts.released
          ? `${p.name} a été licencié (indemnité de ${Math.round(opts.fee || 0).toLocaleString("fr-FR")} $) et devient agent libre.`
          : `Son contrat est arrivé à échéance sans prolongation : ${p.name} part libre et devient agent libre.`,
        action: { label: "Effectif", href: "/effectif" },
      });
    }
  }

  // Fin de saison (mise à jour qui clôt la saison, voir
  // server/autoSim.js:runWeeklyEconomyTick) : les contrats arrivés à
  // échéance prennent fin. Club humain : le joueur part libre (sauf
  // prolongation déjà signée). Club IA : prolonge la plupart de ses joueurs
  // utiles (pas tous), laisse partir les autres et complète son effectif si
  // besoin. Renvoie la liste des départs.
  processContractExpiries(now = Date.now(), rng = rand01) {
    const season = this.contractSeason();
    const left = [];
    this.teams.forEach((team, idx) => {
      if (!team || !Array.isArray(team.players)) return;
      const expiring = team.players.filter(p => typeof p.contractUntilSeason === "number" && p.contractUntilSeason <= season);
      if (!expiring.length) return;
      expiring.forEach(p => {
        if (!team.isHuman) {
          const role = team.playerRoleKey(p.id);
          let chance = role === "starter" ? 0.9 : role === "rotation" ? 0.75 : 0.45;
          if (p.age >= FREE_AGENT_RETIRE_AGE) chance *= 0.6;
          if (rng() < chance) {
            signNewContract(p, 1 + Math.floor(rng() * 4), season + 1, askedSalary(p));
            return;
          }
        }
        this._releaseToFreeAgency(team, idx, p, now);
        left.push({ teamIdx: idx, playerId: p.id, name: p.name });
      });
      if (!team.isHuman) {
        while (team.players.length < CPU_MIN_ROSTER_AFTER_CONTRACTS) {
          const pos = POSITIONS.find(ps => !team.players.some(x => x.position === ps)) || POSITIONS[team.players.length % POSITIONS.length];
          const rookie = generateRetirementReplacement(team, pos);
          signNewContract(rookie, 1 + Math.floor(rng() * 3), season + 1, rookie.salary);
          team.players.push(rookie);
        }
        team.autoAssignLineup();
      } else {
        while (team.players.length < MIN_ROSTER_SIZE) {
          const pos = POSITIONS.find(ps => !team.players.some(x => x.position === ps)) || POSITIONS[team.players.length % POSITIONS.length];
          const rookie = generateRookiePlayer(pos);
          rookie.age = 19;
          signNewContract(rookie, 2, season + 1, rookie.salary);
          resetPlayerTacticalKnowledge(rookie);
          team.players.push(rookie);
        }
      }
    });
    return left;
  }

  // Mise à jour hebdomadaire des contrats (après l'économie du lundi) :
  // demandes de prolongation des joueurs en dernière saison (club humain),
  // demandes d'augmentation de mi-saison (club humain : message ; club IA :
  // acceptée d'office), demandes restées sans réponse. Renvoie le nombre de
  // messages envoyés.
  weeklyContractsTick(now = Date.now()) {
    this.ensureContracts();
    this.expireRaiseRequests(now);
    const season = this.contractSeason();
    const week = this.seasonWeek();
    let sent = 0;
    this.teams.forEach(team => {
      if (!team || !Array.isArray(team.players)) return;
      team.players.forEach(p => {
        const left = contractSeasonsLeft(p, season);
        if (team.isHuman && left === 1 && p.extensionRequestSeason !== season && !p.retiringAfterSeason) {
          p.extensionRequestSeason = season;
          if (team.feed) {
            pushEntry(team.feed, {
              key: `contract_ext_${p.id}`, category: "club", week: team.week, createdAt: now,
              title: `${p.name} souhaite prolonger`,
              text: `${p.name} entame la dernière saison de son contrat et attend une offre de prolongation. Sans accord, il partira libre en fin de saison.`,
              action: { label: "Fiche joueur", href: `/joueur/${p.id}` },
            });
            sent++;
          }
        }
        if (week !== CONTRACT_RAISE_WEEK || this.seasonEndTickDone) return;
        if (!(left >= 2) || p.raiseRequest || p.raiseRequestSeason === season || typeof p.nextSalary === "number") return;
        // Contrat signé avant la grille du 2026-10-04 : demande calculée sur
        // l'ancienne grille (pas de vague de demandes due au seul changement).
        const asked = askedSalary(p, p.salaryGrid !== 2);
        if (asked < p.salary * (1 + CONTRACT_RAISE_THRESHOLD)) return;
        p.raiseRequestSeason = season;
        if (!team.isHuman) { p.nextSalary = asked; return; }
        p.raiseRequest = { asked, at: now, season };
        if (team.feed) {
          pushEntry(team.feed, {
            key: `contract_raise_${p.id}`, category: "club", week: team.week, createdAt: now,
            title: `${p.name} demande une augmentation`,
            text: `${p.name} a beaucoup progressé et demande ${asked.toLocaleString("fr-FR")} $/sem. (contre ${p.salary.toLocaleString("fr-FR")} $/sem. aujourd'hui), à partir de la saison prochaine. Répondez sous 1 semaine sur sa fiche.`,
            action: { label: "Fiche joueur", href: `/joueur/${p.id}` },
          });
          sent++;
        }
      });
    });
    return sent;
  }

  // Demandes d'augmentation sans réponse depuis CONTRACT_RAISE_RESPONSE_MS :
  // valent refus (motivation en baisse).
  expireRaiseRequests(now = Date.now()) {
    let n = 0;
    this.teams.forEach(team => {
      ((team && team.players) || []).forEach(p => {
        if (p.raiseRequest && typeof p.raiseRequest.at === "number" && now - p.raiseRequest.at >= CONTRACT_RAISE_RESPONSE_MS) {
          team.respondToRaiseRequest(p.id, false);
          n++;
        }
      });
    });
    return n;
  }

  // Signature d'un agent libre par `buyer` (ce championnat ou un autre, voir
  // server/worldMarket.js) : la mise gagnante est une prime de signature
  // (débitée, créditée à personne), contrat au salaire demandé pour la
  // durée choisie. Renvoie { result: "sold" | "buyer-failed" | "player-missing", player? }.
  signFreeAgentFromListing(listing, buyer, buyerSeason, now, buyerRef = null) {
    const amount = listing.currentBid || 0;
    if (!buyer || buyer.players.length >= MAX_ROSTER_SIZE || (buyer.isHuman && amount > buyer.budget)) return { result: "buyer-failed" };
    const i = (this.freeAgents || []).findIndex(p => p.id === listing.playerId);
    if (i === -1) return { result: "player-missing" };
    const [player] = this.freeAgents.splice(i, 1);
    if (buyer.isHuman && amount > 0) buyer.recordTransaction(`${FREE_AGENT_SIGNING_LABEL} : ${player.name}`, -amount);
    buyer.players.push(player);
    recordPlayerEvent(player, { type: "transfer", at: now != null ? now : Date.now(), season: teamSeasonNo(buyer), from: listing.formerTeamName || null, to: buyer.name, fee: amount, freeAgent: true });
    Vestiaire.noteRoster(buyer, player, "arrival", now);
    // Historique : signature d'un agent libre (provenance « Agent libre »,
    // ancien club noté à part). `buyerRef` : club d'un autre championnat
    // (marché mondial).
    const bRef = buyerRef || { leagueId: this.leagueId || null, idx: this.teams.indexOf(buyer) };
    recordTeamTransfer(buyer, {
      id: `${this.leagueId || "lg"}:L${listing.id}`, at: now, kind: "free_in", player, from: null,
      to: transferTeamRef(buyer, bRef.leagueId, bRef.idx), fee: amount, human: buyer.isHuman,
      formerClub: listing.formerTeamName ? transferTeamRef({ name: listing.formerTeamName }, this.leagueId, listing.formerTeamIdx) : null,
    });
    resetPlayerTacticalKnowledge(player);
    if (player.form < TRANSFER_NEW_CLUB_MOTIVATION_FLOOR) player.form = TRANSFER_NEW_CLUB_MOTIVATION_FLOOR;
    player.weeksAtLowMotivation = 0;
    this._applyTransferContract(listing, buyer, player, buyerSeason, now);
    if (buyer.isHuman) ensureJerseyNumbers(buyer); else buyer.autoAssignLineup();
    buyer.applyChemistryDelta(-CHEMISTRY_ROSTER_CHANGE_BASE * CHEMISTRY_ARRIVAL_SHARE * chemistryRosterImportance(rosterRankOf(buyer.players, player.id)));
    return { result: "sold", player };
  }

  // Agent libre sans preneur à la clôture : un vétéran (33 ans et plus)
  // prend sa retraite, les autres signent dans un club de l'IA de ce
  // championnat (celui qui a le plus petit effectif).
  _placeUnsoldFreeAgent(listing, now) {
    const i = (this.freeAgents || []).findIndex(p => p.id === listing.playerId);
    if (i === -1) return "player-missing";
    const player = this.freeAgents[i];
    const cpu = this.teams.map((t, idx) => ({ t, idx })).filter(x => x.t && !x.t.isHuman && x.t.players.length < MAX_ROSTER_SIZE && x.idx !== listing.formerTeamIdx)
      .sort((a, b) => a.t.players.length - b.t.players.length)[0];
    this.freeAgents.splice(i, 1);
    if (player.age >= FREE_AGENT_RETIRE_AGE || !cpu) return "retired";
    signNewContract(player, 1 + Math.floor(rand01() * 2), this.contractSeason(), askedSalary(player));
    cpu.t.players.push(player);
    recordPlayerEvent(player, { type: "transfer", at: now, season: teamSeasonNo(cpu.t), from: listing.formerTeamName || null, to: cpu.t.name, fee: 0, freeAgent: true });
    recordTeamTransfer(cpu.t, {
      id: `${this.leagueId || "lg"}:L${listing.id}`, at: now, kind: "free_in", player, from: null,
      to: transferTeamRef(cpu.t, this.leagueId, cpu.idx), fee: 0, human: false,
      formerClub: listing.formerTeamName ? transferTeamRef({ name: listing.formerTeamName }, this.leagueId, listing.formerTeamIdx) : null,
    });
    cpu.t.autoAssignLineup();
    return "cpu-signed";
  }

  _resolveFreeAgentListing(listing, now) {
    listing.status = "closed";
    if (listing.currentBidderIdx === FOREIGN_BIDDER_IDX) { listing.result = "foreign-pending"; return; }
    if (listing.currentBidderIdx != null) {
      const buyer = this.teams[listing.currentBidderIdx];
      const res = this.signFreeAgentFromListing(listing, buyer, this.contractSeason(), now);
      if (res.result === "sold") {
        listing.result = "sold";
        listing.finalPrice = listing.currentBid;
        return;
      }
      if (res.result === "player-missing") { listing.result = res.result; return; }
    }
    listing.result = this._placeUnsoldFreeAgent(listing, now) === "retired" ? "retired" : "unsold";
  }

  // ---------------------------------------------------------------------
  // Marché des transferts — voir le commentaire sur this.transferListings
  // (constructeur) et sur les constantes TRANSFER_* plus haut. `now`
  // (millisecondes, comme Date.now()) est TOUJOURS un paramètre explicite
  // plutôt qu'un appel direct à Date.now() à l'intérieur de ces méthodes :
  // ça permet de tester le passage du temps (avance de plusieurs jours)
  // sans avoir à réellement attendre, et laisse l'appelant (l'UI) rester la
  // seule source de vérité sur "maintenant".
  // ---------------------------------------------------------------------

  // Cherche un joueur par id, TOUTES équipes confondues (utile pour une
  // enchère : le joueur listé peut appartenir à n'importe laquelle des 10
  // équipes de la ligue, pas seulement celle du joueur).
  // Joueur d'une annonce du marché, cherché CHEZ SON VENDEUR (bug du
  // 2026-10-06 : un joueur de BC DIA affiché « aux enchères » sans raison —
  // deux joueurs d'une même ligue pouvaient porter le même id après un
  // transfert entre championnats ; playerById renvoyait le premier trouvé).
  listingPlayer(listing) {
    if (!listing) return null;
    if (listing.freeAgent) return this.freeAgentById(listing.playerId) || null;
    const seller = this.teams[listing.sellerIdx];
    const own = seller && seller.players.find(pl => pl.id === listing.playerId);
    return own || (seller ? null : this.listingPlayer(listing));
  }

  playerById(playerId) {
    for (const team of this.teams) {
      const p = team.players.find(pl => pl.id === playerId);
      if (p) return p;
    }
    // Agents libres (voir processContractExpiries).
    return this.freeAgentById(playerId);
  }

  // Met un joueur de sellerIdx aux enchères pour TRANSFER_AUCTION_DURATION_MS.
  // AUCUN plancher d'effectif pour le vendeur (retour utilisateur explicite :
  // "on peut vendre tout son effectif si on le souhaite" — voir aussi
  // Team.sellPlayer) : refuse seulement si le joueur n'existe pas dans cette
  // équipe, ou s'il est déjà listé (une seule enchère active à la fois par
  // joueur). Renvoie l'annonce créée, ou `null`. (Le plancher qui subsiste
  // pour les NOUVELLES annonces générées automatiquement par une équipe CPU
  // est une prudence distincte côté génération — voir refreshMarket — pas
  // une limite sur cette méthode elle-même.)
  listPlayerForSale(sellerIdx, playerId, startPrice, now) {
    const seller = this.teams[sellerIdx];
    if (!seller) return null;
    const player = seller.players.find(p => p.id === playerId);
    if (!player) return null;
    if (this.transferListings.some(l => l.status === "open" && l.playerId === playerId && l.sellerIdx === sellerIdx)) return null;
    // Contrats (demande du 2026-10-01) : pas de vente d'un joueur en
    // dernière saison de contrat pendant la seconde moitié de saison.
    if (this.contractSaleBlocked(player)) return null;
    const listing = {
      id: uid(),
      playerId,
      sellerIdx,
      // Salaire demandé affiché sur l'annonce, gelé : celui que signera
      // l'acheteur (voir _applyTransferContract).
      askedSalary: askedSalary(player),
      startPrice: Math.max(1, Math.round(startPrice)),
      currentBid: null,
      currentBidderIdx: null,
      bids: [],
      createdAt: now,
      closesAt: now + TRANSFER_AUCTION_DURATION_MS,
      lastCpuCheckAt: now,
      status: "open", // "open" | "sold" | "unsold" | "cancelled"
      result: null,
      finalPrice: null,
    };
    this.transferListings.push(listing);
    return listing;
  }

  // Annule une annonce SANS enchère encore posée (sécurité pour une erreur
  // de manipulation) — une fois qu'une enchère existe, plus d'annulation
  // possible (comme un vrai marché). Réservé au vendeur lui-même.
  cancelListing(listingId, teamIdx) {
    const listing = this.transferListings.find(l => l.id === listingId);
    if (!listing || listing.status !== "open") return false;
    if (listing.sellerIdx !== teamIdx) return false;
    if (listing.currentBidderIdx != null) return false;
    listing.status = "cancelled";
    return true;
  }

  // Pose une enchère sur une annonce ouverte. Renvoie { ok: true, listing }
  // ou { ok: false, reason, minBid? } — reasons : "closed" (annonce fermée ou
  // échéance déjà passée), "own-listing" (on ne peut pas enchérir sur son
  // propre joueur), "invalid-bidder", "roster-full" (déjà au plafond
  // d'effectif), "too-low" (sous l'enchère minimale — voir minNextBidFor),
  // "insufficient-budget" (club du joueur uniquement — voir plus bas).
  // Enchères automatiques (voir AUTO_BID_FIELDS) : plafond effectif d'une
  // entrée (budget d'un club humain, effectif plein), null = hors jeu. Un
  // club d'un autre championnat : plafond tel quel (budget vérifié quand il
  // l'a fixé, puis au transfert, voir resolveForeignTransfers).
  _autoBidCap(listing, kind, a) {
    if (a.bidderIdx === FOREIGN_BIDDER_IDX) return a.max;
    const team = this.teams[a.bidderIdx];
    if (!team) return null;
    if (kind === "player" && (a.bidderIdx === listing.sellerIdx || team.players.length >= MAX_ROSTER_SIZE || this._isFormerClub(listing, team, a.bidderIdx))) return null;
    return team.isHuman ? Math.min(a.max, Math.floor(team.budget - (kind === "player" ? this.reservedBidsFor(a.bidderIdx, listing.id) : 0))) : a.max;
  }

  _recordAutoBid(listing, kind, a, amount, now) {
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = a.bidderIdx;
    if (a.bidderIdx === FOREIGN_BIDDER_IDX) {
      listing.currentBidderRef = { ...a.bidderRef };
      listing.bids.push({ bidderIdx: a.bidderIdx, bidderRef: { ...a.bidderRef }, amount: rounded, at: now, auto: true });
    } else {
      if (kind === "player") listing.currentBidderRef = null;
      listing.bids.push({ bidderIdx: a.bidderIdx, amount: rounded, at: now, auto: true });
    }
  }

  // Fait jouer les plafonds après une nouvelle offre. Renvoie true si le
  // club en tête a changé.
  _applyAutoBids(listing, kind, now) {
    if (!listing || !Array.isArray(listing.autoBids) || !listing.autoBids.length) return false;
    if (listing.status !== "open" || now >= listing.closesAt) return false;
    const keyOfLeader = () => (listing.currentBidderIdx == null ? null : autoBidKey(listing.currentBidderIdx, listing.currentBidderRef));
    const before = keyOfLeader();
    for (let guard = 0; guard < 20; guard++) {
      const leaderKey = keyOfLeader();
      const entries = listing.autoBids.map(a => ({ a, key: autoBidKey(a.bidderIdx, a.bidderRef), cap: this._autoBidCap(listing, kind, a) }))
        .filter(e => e.cap != null && e.cap > 0);
      const leader = entries.find(e => e.key === leaderKey) || null;
      const minBid = minNextBidFor(listing);
      const challengers = entries.filter(e => e.key !== leaderKey && e.cap >= minBid)
        .sort((x, y) => y.cap - x.cap || (x.a.at || 0) - (y.a.at || 0));
      if (!challengers.length) break;
      const top = challengers[0];
      if (leader && top.cap <= leader.cap) {
        // Le plafond du club en tête tient : le challenger monte à son
        // plafond, le club en tête répond d'un palier (sans dépasser le sien).
        this._recordAutoBid(listing, kind, top.a, top.cap, now);
        this._recordAutoBid(listing, kind, leader.a, Math.max(top.cap, Math.min(leader.cap, minNextBidFor(listing))), now);
        continue;
      }
      // Le challenger l'emporte : le club en tête monte d'abord à son plafond.
      if (leader && leader.cap > (listing.currentBid || 0)) this._recordAutoBid(listing, kind, leader.a, leader.cap, now);
      const need = minNextBidFor(listing);
      this._recordAutoBid(listing, kind, top.a, Math.min(top.cap, need), now);
    }
    return keyOfLeader() !== before;
  }

  // Fixe (max > 0) ou retire (max nul) le plafond d'enchère automatique d'un
  // club sur l'annonce `listingId` du marché `field` (voir AUTO_BID_FIELDS).
  // `foreign` = { ref: { leagueId, idx, name }, team } pour un club d'un
  // autre championnat (marché mondial). Renvoie { ok, listing, leading } ou
  // { ok: false, reason, minBid? } (mêmes raisons que placeBid).
  // `seasons` (marché des joueurs) : durée de contrat choisie avec le plafond.
  setAutoBid(field, listingId, bidderIdx, max, now, foreign = null, seasons = null) {
    const kind = AUTO_BID_FIELDS[field];
    const listing = kind ? (this[field] || []).find(l => l.id === listingId) : null;
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    const idx = foreign ? FOREIGN_BIDDER_IDX : bidderIdx;
    const ref = foreign ? { leagueId: foreign.ref.leagueId, idx: foreign.ref.idx, name: foreign.ref.name || (foreign.team && foreign.team.name) } : null;
    const team = foreign ? foreign.team : this.teams[bidderIdx];
    if (!team) return { ok: false, reason: "invalid-bidder" };
    const key = autoBidKey(idx, ref);
    const others = (listing.autoBids || []).filter(a => autoBidKey(a.bidderIdx, a.bidderRef) !== key);
    const leaderKey = listing.currentBidderIdx == null ? null : autoBidKey(listing.currentBidderIdx, listing.currentBidderRef);
    if (!max) {
      if (others.length) listing.autoBids = others; else delete listing.autoBids;
      return { ok: true, listing, leading: leaderKey === key, removed: true };
    }
    if (typeof max !== "number" || !(max > 0)) return { ok: false, reason: "too-low", minBid: minNextBidFor(listing) };
    if (kind === "player" && !foreign && listing.sellerIdx === bidderIdx) return { ok: false, reason: "own-listing" };
    if (kind === "player" && team.players.length >= MAX_ROSTER_SIZE) return { ok: false, reason: "roster-full" };
    if (kind === "player" && this._isFormerClub(listing, team, foreign ? null : bidderIdx)) return { ok: false, reason: "former-club" };
    if (kind === "player" && team.isHuman && !this._hasAgreementForBid(listing, key, idx, ref)) return { ok: false, reason: "no-agreement" };
    const minMax = leaderKey === key ? (listing.currentBid || 0) : minNextBidFor(listing);
    if (max < minMax) return { ok: false, reason: "too-low", minBid: minMax };
    if (team.isHuman && max > team.budget - (kind === "player" && !foreign ? this.reservedBidsFor(bidderIdx, listing.id) : 0)) return { ok: false, reason: "insufficient-budget" };
    const entry = { bidderIdx: idx, max: Math.round(max), at: now };
    if (ref) entry.bidderRef = ref;
    listing.autoBids = others.concat([entry]);
    if (kind === "player") this._rememberContractTerms(listing, key, seasons);
    this._applyAutoBids(listing, kind, now);
    const leadingNow = listing.currentBidderIdx != null && autoBidKey(listing.currentBidderIdx, listing.currentBidderRef) === key;
    return { ok: true, listing, leading: leadingNow };
  }

  // `seasons` : durée du contrat (1 à 5 saisons) choisie avec l'enchère,
  // signée au salaire demandé si l'enchère est remportée (demande du
  // 2026-10-01) ; absente = CONTRACT_DEFAULT_SEASONS.
  // Somme des enchères (joueurs, agents libres) où le club `teamIdx` est en
  // tête, hors annonce `exceptId` : argent réservé, non dépensable ailleurs.
  reservedBidsFor(teamIdx, exceptId = null) {
    return (this.transferListings || []).reduce((s, l) => s + (
      l.status === "open" && l.currentBidderIdx === teamIdx && !l.currentBidderRef && l.id !== exceptId ? (l.currentBid || 0) : 0), 0);
  }
  // Pose la réserve sur chaque club (Team.spendableBudget).
  syncReservedBids() {
    (this.teams || []).forEach((t, idx) => { if (t) t.reservedForBids = this.reservedBidsFor(idx); });
  }

  // Accord de contrat d'un club (clé autoBidKey) sur l'annonce, ou null.
  _transferAgreementFor(listing, key) {
    return (listing && listing.agreements && listing.agreements[key]) || null;
  }
  // Un club humain ne peut enchérir qu'avec un accord. Club qui avait déjà
  // misé avant cette règle (annonce ouverte au déploiement) : accord
  // implicite au salaire demandé, durée déjà choisie — rien ne casse.
  _hasAgreementForBid(listing, key, idx, ref) {
    if (this._transferAgreementFor(listing, key)) return true;
    const already = (listing.bids || []).some(b => autoBidKey(b.bidderIdx, b.bidderRef) === key) ||
      (listing.autoBids || []).some(a => autoBidKey(a.bidderIdx, a.bidderRef) === key);
    if (!already) return false;
    listing.agreements = listing.agreements || {};
    listing.agreements[key] = { salary: typeof listing.askedSalary === "number" ? listing.askedSalary : null, seasons: this._contractSeasonsFor(listing, key), at: null, legacy: true };
    return true;
  }

  // Négociation du contrat avec le joueur d'une annonce (marché des
  // joueurs, agents libres compris) : `offer` = { salary, seasons }. Au
  // salaire demandé : accord immédiat ; jusqu'à -10 % : tirage
  // (contractAcceptanceChance, comme une prolongation) ; refus : demande
  // +3 %, après 3 refus seulement au salaire demandé. Accord figé jusqu'à la
  // fin de l'enchère. `foreign` = { ref, team } (club d'un autre
  // championnat, marché mondial). Renvoie { ok, accepted, salary, seasons,
  // demand, refusals } ou { ok: false, reason }.
  negotiateTransferContract(listingId, bidderIdx, offer, now, foreign = null, rng = rand01) {
    const listing = (this.transferListings || []).find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    const idx = foreign ? FOREIGN_BIDDER_IDX : bidderIdx;
    const ref = foreign ? { leagueId: foreign.ref.leagueId, idx: foreign.ref.idx, name: foreign.ref.name || (foreign.team && foreign.team.name) } : null;
    const team = foreign ? foreign.team : this.teams[bidderIdx];
    if (!team) return { ok: false, reason: "invalid-bidder" };
    if (!foreign && listing.sellerIdx === bidderIdx) return { ok: false, reason: "own-listing" };
    if (this._isFormerClub(listing, team, foreign ? null : bidderIdx)) return { ok: false, reason: "former-club" };
    const player = this.listingPlayer(listing);
    if (!player) return { ok: false, reason: "closed" };
    const key = autoBidKey(idx, ref);
    if (this._transferAgreementFor(listing, key)) return { ok: false, reason: "already-agreed" };
    listing.negotiations = listing.negotiations || {};
    const neg = listing.negotiations[key] || { refusals: 0, demand: typeof listing.askedSalary === "number" ? listing.askedSalary : askedSalary(player) };
    const seasons = normalizeContractSeasons(offer && offer.seasons, null);
    if (seasons == null) return { ok: false, reason: "invalid-seasons" };
    const salary = Math.round(Number(offer && offer.salary));
    if (!Number.isFinite(salary) || salary <= 0) return { ok: false, reason: "invalid-salary", demand: neg.demand };
    const firm = neg.refusals >= CONTRACT_FIRM_AFTER_REFUSALS;
    const floor = firm ? neg.demand : contractOfferFloor(neg.demand);
    if (salary < floor) return { ok: false, reason: "invalid-salary", demand: neg.demand, floor };
    const offered = Math.min(salary, neg.demand);
    if (offered >= neg.demand || rng() < contractAcceptanceChance(neg.demand, offered, player.form, team.prestige)) {
      listing.agreements = listing.agreements || {};
      listing.agreements[key] = { salary: offered, seasons, at: now };
      delete listing.negotiations[key];
      return { ok: true, accepted: true, salary: offered, seasons, demand: neg.demand, refusals: neg.refusals };
    }
    neg.refusals += 1;
    neg.demand = Math.max(SALARY_MIN, Math.round(neg.demand * (1 + CONTRACT_REFUSAL_DEMAND_BUMP) / 10) * 10);
    listing.negotiations[key] = neg;
    return { ok: true, accepted: false, demand: neg.demand, refusals: neg.refusals, firm: neg.refusals >= CONTRACT_FIRM_AFTER_REFUSALS };
  }

  placeBid(listingId, bidderIdx, amount, now, seasons = null) {
    const listing = this.transferListings.find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    if (listing.sellerIdx === bidderIdx) return { ok: false, reason: "own-listing" };
    const bidder = this.teams[bidderIdx];
    if (!bidder) return { ok: false, reason: "invalid-bidder" };
    if (this._isFormerClub(listing, bidder, bidderIdx)) return { ok: false, reason: "former-club" };
    if (bidder.players.length >= MAX_ROSTER_SIZE) return { ok: false, reason: "roster-full" };
    if (bidder.isHuman && !this._hasAgreementForBid(listing, autoBidKey(bidderIdx, null), bidderIdx, null)) return { ok: false, reason: "no-agreement" };
    const minBid = minNextBidFor(listing);
    if (amount < minBid) return { ok: false, reason: "too-low", minBid };
    // Le budget des équipes CPU n'est pas suivi de façon réaliste (elles ne
    // jouent jamais Team.trainWeek, donc ne touchent ni recettes ni droits
    // TV) : seule une équipe HUMAINE (voir Team.isHuman — n'importe laquelle,
    // plus seulement l'index 0) est bloquée par son budget réel. Voir
    // refreshMarket pour la logique d'enchère CPU (valeur marchande estimée,
    // pas un vrai budget).
    if (bidder.isHuman && amount > bidder.budget - this.reservedBidsFor(bidderIdx, listingId)) return { ok: false, reason: "insufficient-budget" };
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = bidderIdx;
    listing.currentBidderRef = null; // marché mondial : plus d'enchérisseur d'ailleurs en tête
    listing.bids.push({ bidderIdx, amount: rounded, at: now });
    this._rememberContractTerms(listing, autoBidKey(bidderIdx, null), seasons == null ? CONTRACT_DEFAULT_SEASONS : seasons);
    const autoOutbid = this._applyAutoBids(listing, "player", now);
    return { ok: true, listing, autoOutbid };
  }

  // Un adversaire CPU est-il intéressé par ce joueur ? Simplification :
  // intéressé s'il n'a personne à ce poste, ou si le joueur listé est
  // meilleur (overall()) que son plus faible joueur à ce poste — comme une
  // vraie équipe qui ne renforce que ce qui l'améliore.
  _cpuWantsPlayer(teamIdx, player) {
    // Un bot ne garde aucun joueur à CPU_STAR_SELL_OVERALL ou plus (voir
    // refreshMarket) : il n'en achète donc pas non plus.
    if (player.overall() >= CPU_STAR_SELL_OVERALL) return false;
    const team = this.teams[teamIdx];
    const samePos = team.players.filter(p => p.position === player.position);
    if (!samePos.length) return true;
    const weakest = Math.min(...samePos.map(p => p.overall()));
    return player.overall() > weakest;
  }

  // Résout une enchère arrivée à échéance : transfère le joueur au plus
  // offrant (s'il y a une enchère), encaisse/débite une VRAIE transaction
  // budgétaire uniquement pour le club du joueur (voir placeBid — le budget
  // CPU n'est pas suivi), sinon la laisse invendue.
  _resolveListing(listing, now) {
    if (listing.freeAgent) { this._resolveFreeAgentListing(listing, now); return; }
    listing.status = "closed";
    if (listing.currentBidderIdx == null) {
      listing.result = "unsold";
      return;
    }
    // Enchérisseur d'un AUTRE championnat (marché mondial, voir
    // placeForeignBid) : le transfert se fait au niveau du monde, qui seul
    // a les deux ligues en main (server/world.js:resolveForeignTransfers).
    if (listing.currentBidderIdx === FOREIGN_BIDDER_IDX) {
      listing.result = "foreign-pending";
      return;
    }
    const buyerIdx = listing.currentBidderIdx;
    const buyer = this.teams[buyerIdx];
    const seller = this.teams[listing.sellerIdx];
    const amount = listing.currentBid;
    const res = transferPlayerBetweenTeams(seller, buyer, listing.playerId, amount, now);
    listing.result = res.result;
    if (res.result === "sold") {
      listing.finalPrice = amount;
      this._applyTransferContract(listing, buyer, res.player, this.contractSeason(), now);
      if (seller.isHuman && buyer.isHuman) this.logHumanTransfer(seller.name, buyer.name, res.player, amount, now);
      // Historique des transferts : chez l'acheteur ET chez le vendeur.
      const mvId = `${this.leagueId || "lg"}:L${listing.id}`;
      const fromRef = transferTeamRef(seller, this.leagueId, listing.sellerIdx);
      const toRef = transferTeamRef(buyer, this.leagueId, buyerIdx);
      recordTeamTransfer(buyer, { id: mvId, at: now, kind: "buy", player: res.player, from: fromRef, to: toRef, fee: amount, human: buyer.isHuman });
      recordTeamTransfer(seller, { id: mvId, at: now, kind: "sell", player: res.player, from: fromRef, to: toRef, fee: amount, human: seller.isHuman });
    }
  }

  // Anti-triche (voir /api/admin/accounts/anticheat) : ventes entre deux
  // clubs de managers, avec la valeur estimée du joueur (200 dernières).
  logHumanTransfer(sellerName, buyerName, player, price, now) {
    this.humanTransferLog = this.humanTransferLog || [];
    this.humanTransferLog.push({ at: now, sellerName, buyerName, playerName: player.name, price, value: Math.round(estimateMarketValue(player)) });
    if (this.humanTransferLog.length > 200) this.humanTransferLog = this.humanTransferLog.slice(-200);
  }

  // Marché mondial (2026-09-28, « marché des transferts mondial ») :
  // enchère d'un club d'un AUTRE championnat sur une annonce de celui-ci.
  // `bidderRef` = { leagueId, idx, name } ; `bidder` = son objet Team (chargé
  // par le serveur dans sa propre ligue) pour les mêmes contrôles que
  // placeBid (effectif, budget). L'annonce retient l'enchérisseur par sa
  // référence (currentBidderIdx = FOREIGN_BIDDER_IDX).
  placeForeignBid(listingId, bidderRef, bidder, amount, now, seasons = null) {
    const listing = this.transferListings.find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    if (!bidder || !bidderRef) return { ok: false, reason: "invalid-bidder" };
    if (this._isFormerClub(listing, bidder, null)) return { ok: false, reason: "former-club" };
    if (bidder.players.length >= MAX_ROSTER_SIZE) return { ok: false, reason: "roster-full" };
    const ref = { leagueId: bidderRef.leagueId, idx: bidderRef.idx, name: bidderRef.name || bidder.name };
    if (bidder.isHuman && !this._hasAgreementForBid(listing, autoBidKey(FOREIGN_BIDDER_IDX, ref), FOREIGN_BIDDER_IDX, ref)) return { ok: false, reason: "no-agreement" };
    const minBid = minNextBidFor(listing);
    if (amount < minBid) return { ok: false, reason: "too-low", minBid };
    if (bidder.isHuman && amount > bidder.budget) return { ok: false, reason: "insufficient-budget" };
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = FOREIGN_BIDDER_IDX;
    listing.currentBidderRef = ref;
    listing.bids.push({ bidderIdx: FOREIGN_BIDDER_IDX, bidderRef: ref, amount: rounded, at: now });
    this._rememberContractTerms(listing, autoBidKey(FOREIGN_BIDDER_IDX, ref), seasons == null ? CONTRACT_DEFAULT_SEASONS : seasons);
    const autoOutbid = this._applyAutoBids(listing, "player", now);
    return { ok: true, listing, autoOutbid };
  }

  // À appeler à intervalles réguliers côté UI (chargement de la page,
  // ouverture de l'onglet Marché, validation d'une semaine d'entraînement) —
  // PAS en continu, puisqu'il n'y a pas de vraie horloge serveur ici : fait
  // vivre le marché (nouvelles annonces CPU, enchères CPU sur les annonces
  // ouvertes, au rythme de TRANSFER_CPU_CHECK_INTERVAL_MS) et résout toute
  // enchère dont l'échéance (3 jours réels) est dépassée.
  // Alertes du marché (Premium, voir MARKET_WATCHLIST_MAX) : parcourt les
  // annonces ouvertes pour chaque club humain Premium et pousse dans son fil
  // d'actualité — joueur suivi mis en vente, fin d'enchère proche d'un joueur
  // suivi, nouvelle annonce correspondant à une alerte. Chaque annonce n'est
  // signalée qu'une fois par type (Team.marketAlertSeen, purgé des annonces
  // closes). Renvoie le nombre d'entrées ajoutées.
  checkMarketAlerts(now) {
    let pushed = 0;
    this.teams.forEach((team, idx) => {
      if (!team || !team.isHuman || !team.feed || typeof team.hasActivePremium !== "function" || !team.hasActivePremium(now)) return;
      const watch = new Map((team.marketWatchlist || []).map(w => [String(w.playerId), w.since || 0]));
      const alerts = team.marketAlerts || [];
      if (!watch.size && !alerts.length) return;
      if (!team.marketAlertSeen || typeof team.marketAlertSeen !== "object") team.marketAlertSeen = {};
      const seen = team.marketAlertSeen;
      const openIds = new Set();
      const push = (key, title, text) => {
        pushEntry(team.feed, { key, category: "marche", week: team.week, createdAt: now, title, text, action: { label: "Marché", href: "/marche" } });
        pushed++;
      };
      this.transferListings.forEach(l => {
        if (l.status !== "open" || l.sellerIdx === idx) return;
        const k = String(l.id);
        openIds.add(k);
        const player = this.listingPlayer(l);
        if (!player) return;
        const since = watch.get(String(player.id));
        if (since != null) {
          if (!seen[k] && (l.createdAt || 0) >= since) {
            push(`mkt_watch_${k}`, `Joueur suivi en vente : ${player.name}`, `${player.name} (${player.position}, ${player.age} ans) est aux enchères, départ à ${Math.round(l.startPrice).toLocaleString("fr-FR")} $.`);
          }
          if (!seen[k]) seen[k] = 1;
          if (seen[k] < 2 && l.closesAt - now <= MARKET_ALERT_ENDING_MS && l.closesAt > now) {
            push(`mkt_end_${k}`, `Fin d'enchère proche : ${player.name}`, `L'enchère sur ${player.name}, joueur que vous suivez, se termine dans moins d'une heure.`);
            seen[k] = 2;
          }
          return;
        }
        if (seen[k]) return;
        const alert = alerts.find(a => (l.createdAt || 0) >= (a.createdAt || 0) && marketAlertMatches(a, player, l, team.budget));
        if (!alert) return;
        push(`mkt_alert_${k}`, `Alerte marché : ${player.name}`, `${player.name} (${player.position}, ${player.age} ans) correspond à votre alerte « ${marketAlertLabel(alert)} ».`);
        seen[k] = 1;
      });
      Object.keys(seen).forEach(k => { if (!openIds.has(k)) delete seen[k]; });
    });
    return pushed;
  }

  refreshMarket(now) {
    this.transferListings = this.transferListings || [];

    // 1) Enchères CPU sur les annonces ouvertes.
    this.transferListings.forEach(listing => {
      if (listing.status !== "open") return;
      if (now - (listing.lastCpuCheckAt || listing.createdAt) < TRANSFER_CPU_CHECK_INTERVAL_MS) return;
      listing.lastCpuCheckAt = now;
      const player = this.listingPlayer(listing);
      if (!player) return;
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return; // une équipe humaine enchérit elle-même (voir placeBid), pas simulé ici
        if (idx === listing.sellerIdx || idx === listing.currentBidderIdx) return;
        if (team.players.length >= MAX_ROSTER_SIZE) return;
        if (this._isFormerClub(listing, team, idx)) return;
        if (!this._cpuWantsPlayer(idx, player)) return;
        if (rand01() >= TRANSFER_CPU_BID_CHANCE) return;
        const minBid = minNextBidFor(listing);
        // Agent libre : la mise est une prime de signature, bien plus modeste
        // qu'une indemnité de transfert.
        const maxWilling = Math.round(estimateMarketValue(player) * (listing.freeAgent ? rand(0.1, 0.35) : rand(0.9, 1.35)));
        if (minBid > maxWilling) return; // déjà trop cher pour cette équipe
        const bidAmount = Math.min(maxWilling, Math.round(minBid * rand(1, 1.15)));
        listing.currentBid = bidAmount;
        listing.currentBidderIdx = idx;
        listing.currentBidderRef = null;
        listing.bids.push({ bidderIdx: idx, amount: bidAmount, at: now });
        this._applyAutoBids(listing, "player", now);
      });
    });

    // 2) Nouvelles annonces CPU (un adversaire met occasionnellement son
    // joueur le plus faible aux enchères) — vérifié pour toute la ligue à la
    // fois, au même rythme que les enchères CPU ci-dessus.
    if (now - (this.lastCpuListingCheckAt || 0) >= TRANSFER_CPU_CHECK_INTERVAL_MS) {
      this.lastCpuListingCheckAt = now;
      // Joueurs à 50 de général ou plus détenus par un bot : tous mis en
      // vente à 1 $ (retour utilisateur 2026-10-01), sans descendre sous
      // l'effectif minimum.
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return;
        const listed = new Set(this.transferListings.filter(l => l.status === "open" && l.sellerIdx === idx).map(l => String(l.playerId)));
        let remaining = team.players.length - listed.size;
        team.players
          .filter(p => p.overall() >= CPU_STAR_SELL_OVERALL && !listed.has(String(p.id)) && !this.contractSaleBlocked(p))
          .sort((a, b) => b.overall() - a.overall())
          .forEach(p => {
            if (remaining <= MIN_ROSTER_SIZE) return;
            if (this.listPlayerForSale(idx, p.id, 1, now)) remaining--;
          });
      });
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return;
        if (team.players.length <= MIN_ROSTER_SIZE) return;
        if (this.transferListings.some(l => l.status === "open" && l.sellerIdx === idx)) return; // une annonce à la fois par CPU
        if (rand01() >= TRANSFER_CPU_LIST_CHANCE) return;
        const sellable = team.players.filter(p => !this.contractSaleBlocked(p));
        if (!sellable.length) return;
        const weakest = sellable.reduce((w, p) => (p.overall() < w.overall() ? p : w), sellable[0]);
        // Prix de départ à 1 $ (retour utilisateur 2026-10-01 : « les bots
        // qui vendent des joueurs doivent mettre 1 $ comme prix »).
        this.listPlayerForSale(idx, weakest.id, 1, now);
      });
    }

    // 3) Résout toute enchère dont l'échéance est dépassée.
    this.transferListings
      .filter(l => l.status === "open" && now >= l.closesAt)
      .forEach(listing => this._resolveListing(listing, now));
  }

  // ---------------------------------------------------------------------
  // Marché des entraîneurs — voir le commentaire sur this.coachListings
  // (constructeur) et sur les constantes COACH_* plus haut. Même convention
  // `now` explicite que le marché des transferts ci-dessus.
  // ---------------------------------------------------------------------

  // Construit et pousse dans this.coachListings l'objet "annonce" d'un
  // candidat entraîneur au niveau et prix de départ donnés — factorisé pour
  // que generateCoachCandidate ci-dessous (tarif fixe TRAINER_BASE_SALARY) et
  // fireTeamTrainer plus bas (salaire déjà atteint, réduit de 30%) ne
  // laissent jamais diverger la FORME de l'annonce (les mêmes champs, values
  // par défaut identiques) entre les deux origines possibles d'un candidat.
  // Construit l'objet "annonce" (forme commune) d'un candidat de staff —
  // factorisé pour que _makeCoachListing (entraîneur) ET _makeAnalystListing
  // (analyste vidéo — marché structurellement identique, voir
  // Team.videoAnalyst/League.analystListings plus bas) ne puissent jamais
  // laisser diverger la FORME d'une annonce entre les deux marchés : mêmes
  // champs, mêmes valeurs par défaut, des deux côtés. Ne pousse PAS
  // elle-même dans une liste (contrairement à l'ancienne _makeCoachListing,
  // avant l'ajout du marché des analystes) : c'est aux deux petites méthodes
  // ci-dessous de le faire, chacune dans SA propre liste.
  _makeStaffListing(now, level, startPrice) {
    return {
      id: uid(),
      level,
      startPrice,
      currentBid: null,
      currentBidderIdx: null,
      bids: [],
      createdAt: now,
      closesAt: now + COACH_AUCTION_DURATION_MS,
      lastCpuCheckAt: now,
      status: "open", // "open" | "sold" | "unsold"
      result: null,
      finalPrice: null,
    };
  }

  // Construit et pousse dans this.coachListings l'objet "annonce" d'un
  // candidat entraîneur au niveau et prix de départ donnés — factorisé (voir
  // _makeStaffListing ci-dessus) pour que generateCoachCandidate ci-dessous
  // (tarif fixe TRAINER_BASE_SALARY) et fireTeamTrainer plus bas (salaire
  // déjà atteint, réduit de 30%) ne laissent jamais diverger la FORME de
  // l'annonce (les mêmes champs, valeurs par défaut identiques) entre les
  // deux origines possibles d'un candidat.
  _makeCoachListing(now, level, startPrice, specialty = null) {
    const listing = this._makeStaffListing(now, level, startPrice);
    // Spécialité visible sur le marché (retour utilisateur 2026-10-01).
    listing.specialty = COACH_SPECIALTIES[specialty] ? specialty : pick(COACH_SPECIALTY_KEYS);
    this.coachListings.push(listing);
    return listing;
  }

  // Équivalent pour le marché des analystes vidéo (voir this.analystListings/
  // generateAnalystCandidate/fireTeamVideoAnalyst plus bas) — même rôle que
  // _makeCoachListing ci-dessus, juste une liste différente.
  _makeAnalystListing(now, level, startPrice) {
    const listing = this._makeStaffListing(now, level, startPrice);
    this.analystListings.push(listing);
    return listing;
  }

  // Génère un nouveau candidat entraîneur et le met aux enchères pour
  // COACH_AUCTION_DURATION_MS. Niveau tiré au sort avec un biais vers les
  // niveaux bas (plus fréquents) — un niveau 5 doit rester rare, un peu
  // comme un très bon joueur sur le marché des transferts.
  generateCoachCandidate(now) {
    const weights = [40, 28, 18, 10, 4]; // poids des niveaux 1 à 5
    const total = weights.reduce((s, w) => s + w, 0);
    let roll = rand01() * total;
    let level = TRAINER_LEVELS[TRAINER_LEVELS.length - 1];
    for (let i = 0; i < weights.length; i++) {
      if (roll < weights[i]) { level = i + 1; break; }
      roll -= weights[i];
    }
    return this._makeCoachListing(now, level, TRAINER_BASE_SALARY[level] || 0);
  }

  // Pose une enchère sur un candidat entraîneur ouvert. Même convention de
  // retour que placeBid : { ok: true, listing } ou { ok: false, reason,
  // minBid? } — reasons : "closed" (annonce fermée ou échéance dépassée),
  // "invalid-bidder", "too-low" (sous l'enchère minimale — voir
  // minNextBidFor), "insufficient-budget" (club du joueur uniquement, même
  // logique que placeBid). Contrairement à placeBid : PAS de "own-listing"
  // (aucune équipe ne "possède" un candidat entraîneur) ni de "roster-full"
  // (un entraîneur n'occupe pas une place d'effectif — gagner l'enchère
  // remplace simplement l'entraîneur actuel de l'équipe, gratuitement,
  // exactement comme le bouton "Congédier" aujourd'hui).
  placeCoachBid(listingId, bidderIdx, amount, now) {
    const listing = this.coachListings.find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    const bidder = this.teams[bidderIdx];
    if (!bidder) return { ok: false, reason: "invalid-bidder" };
    const minBid = minNextBidFor(listing);
    if (amount < minBid) return { ok: false, reason: "too-low", minBid };
    // Comme placeBid : seul le budget d'une équipe humaine est réel/suivi.
    if (bidder.isHuman && amount > bidder.budget - this.reservedBidsFor(bidderIdx, listingId)) return { ok: false, reason: "insufficient-budget" };
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = bidderIdx;
    listing.bids.push({ bidderIdx, amount: rounded, at: now });
    const autoOutbid = this._applyAutoBids(listing, "staff", now);
    return { ok: true, listing, autoOutbid };
  }

  // Résout une enchère de candidat entraîneur arrivée à échéance. La mise
  // gagnante devient le SALAIRE DE DÉPART (baseSalary) du nouvel entraîneur
  // — voir Team.hireTrainer — PAS un débit ponctuel en plus : le salaire
  // hebdomadaire progressif (trainerWeeklySalary) EST le coût de l'enchère,
  // le débiter aussi en une fois reviendrait à facturer deux fois la même
  // chose. Si le club a déjà un entraîneur, il est simplement remplacé, sans
  // indemnité de départ (comme fireTrainer aujourd'hui).
  _resolveCoachListing(listing, now) {
    listing.status = "closed";
    if (listing.currentBidderIdx == null) {
      listing.result = "unsold";
      return;
    }
    const buyerIdx = listing.currentBidderIdx;
    const buyer = this.teams[buyerIdx];
    const amount = listing.currentBid;
    // Revérifie le budget à la clôture (le budget a pu changer entre-temps)
    // — simplification volontaire, comme _resolveListing : pas de
    // repêchage du 2e enchérisseur si le 1er n'a plus les moyens.
    if (buyer.isHuman && amount > buyer.budget) {
      listing.result = "buyer-failed";
      return;
    }
    buyer.hireTrainer(listing.level, amount, listing.specialty);
    tagStaffIdentity(buyer.trainer, listing);
    if (buyer.isHuman && buyer.feed) {
      handleGameEvent(buyer.feed, {
        type: "staff_hired", week: buyer.week,
        name: feedStaffPlaceholderName(listing.level), role: FEED_STAFF_ROLE_LABELS.coach,
      }, { clubName: buyer.name });
    }
    listing.result = "sold";
    listing.finalPrice = amount;
  }

  // À appeler au même rythme que refreshMarket (chargement de la page,
  // ouverture de l'onglet Staff...) — méthode VOLONTAIREMENT distincte (pas
  // fusionnée avec refreshMarket) pour que les deux marchés restent
  // lisibles indépendamment l'un de l'autre.
  refreshCoachMarket(now) {
    this.coachListings = this.coachListings || [];

    // 1) Enchères CPU sur les candidats ouverts — "intéressée" = équipe CPU
    // sans entraîneur du tout, ou dont l'entraîneur actuel est d'un niveau
    // inférieur à celui du candidat (même esprit que _cpuWantsPlayer).
    this.coachListings.forEach(listing => {
      if (listing.status !== "open") return;
      if (now - (listing.lastCpuCheckAt || listing.createdAt) < COACH_MARKET_GENERATE_CHECK_INTERVAL_MS) return;
      listing.lastCpuCheckAt = now;
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return; // une équipe humaine enchérit elle-même via placeCoachBid
        if (idx === listing.currentBidderIdx) return;
        const interested = !team.trainer || team.trainer.level < listing.level;
        if (!interested) return;
        if (rand01() >= COACH_CPU_BID_CHANCE) return;
        const minBid = minNextBidFor(listing);
        const maxWilling = Math.round((TRAINER_BASE_SALARY[listing.level] || 0) * rand(1.0, 1.5));
        if (minBid > maxWilling) return; // déjà trop cher pour cette équipe
        const bidAmount = Math.min(maxWilling, Math.round(minBid * rand(1, 1.15)));
        listing.currentBid = bidAmount;
        listing.currentBidderIdx = idx;
        listing.bids.push({ bidderIdx: idx, amount: bidAmount, at: now });
        this._applyAutoBids(listing, "staff", now);
      });
    });

    // 2) Renouvelle les candidats pour garder au moins
    // COACH_MARKET_MIN_OPEN_LISTINGS annonces ouvertes en permanence (voir
    // le commentaire sur cette constante), personne ne "vend" son
    // entraîneur spontanément comme sur le marché des transferts, donc ce
    // plancher est généré directement plutôt que probable. Vérifié à CHAQUE
    // appel, plus seulement une fois par COACH_MARKET_GENERATE_CHECK_INTERVAL_MS
    // (retour utilisateur, 2026-09 : "on fait des tests et on ne peut
    // acheter personne") : ce délai d'une journée réelle reste adapté aux
    // enchères CPU ci-dessus (pas la peine qu'une équipe CPU consulte le
    // marché plus souvent), mais laissait le marché vide pendant des heures
    // dès que plusieurs managers humains vidaient les annonces ouvertes le
    // même jour. this.lastCoachGenerationCheckAt reste posé (simple suivi
    // informatif) mais ne conditionne plus rien ici.
    this.lastCoachGenerationCheckAt = now;
    {
      let openCount = this.coachListings.filter(l => l.status === "open").length;
      while (openCount < this.staffMarketMinOpenListings()) {
        this.generateCoachCandidate(now);
        openCount++;
      }
    }

    // 3) Résout toute enchère dont l'échéance est dépassée.
    this.coachListings
      .filter(l => l.status === "open" && now >= l.closesAt)
      .forEach(listing => this._resolveCoachListing(listing, now));
  }

  // Congédie l'entraîneur de `teamIndex` et le remet AUSSITÔT sur le marché
  // des entraîneurs, à un prix de départ réduit (retour utilisateur, 2026-09 :
  // "dès qu'un staff est viré parce que devenu trop cher, il faut qu'il
  // retourne sur le marché avec un salaire baissé de 30%"). Le prix de
  // départ de cette nouvelle annonce est calculé à partir du salaire
  // HEBDOMADAIRE DÉJÀ ATTEINT par ce club pour cet entraîneur (voir
  // Team.trainerSalary — la valeur escaladée par TRAINER_WEEKLY_GROWTH,
  // "devenu trop cher"), PAS le tarif fixe TRAINER_BASE_SALARY[level] d'un
  // tout nouveau candidat (voir generateCoachCandidate/_makeCoachListing
  // ci-dessus) — sinon un entraîneur congédié à un salaire déjà élevé
  // reviendrait moins cher qu'un inconnu du même niveau, ce qui n'aurait pas
  // de sens. `trainerSalary()` DOIT être lu AVANT team.fireTrainer() : une
  // fois l'entraîneur parti, elle retombe à 0 (voir Team.trainerSalary), il
  // n'y aurait alors plus rien à réduire de 30%. Une fois relistée, cette
  // annonce vit comme n'importe quel autre candidat (enchères CPU/humaines,
  // échéance...) — voir refreshCoachMarket/placeCoachBid — sans plus aucun
  // lien avec le club qui vient de le congédier.
  //
  // Règle de gameplay PARTAGÉE solo/multi-manager (contrairement aux points
  // d'entrée réseau eux-mêmes, elle vit directement ici sur League, pas
  // seulement dans server/actions.js) : appelée aussi bien par le bouton
  // "Congédier" côté navigateur en solo que par l'action serveur
  // "fireTrainer" en mode multi-manager (voir server/actions.js).
  //
  // `teamIndex` invalide (défensif, ne devrait jamais arriver côté appelants
  // réels qui résolvent déjà l'équipe avant d'appeler ceci) : no-op, renvoie
  // relisted:false plutôt que de planter. Pas d'entraîneur en poste : la
  // fonction reste un no-op complet côté marché (rien à congédier, rien à
  // relister), mais renvoie tout de même { ok: true, relisted: false } —
  // jamais une erreur, pour que l'appelant (bouton "Congédier") reste
  // simple à écrire sans avoir à distinguer ce cas.
  fireTeamTrainer(teamIndex, now) {
    const team = this.teams[teamIndex];
    if (!team) return { ok: false, relisted: false };
    const firedTrainer = team.trainer;
    const currentSalary = team.trainerSalary(); // AVANT fireTrainer() — voir commentaire ci-dessus
    team.fireTrainer();
    if (!firedTrainer) return { ok: true, relisted: false };
    const discountedStartPrice = Math.max(1, Math.round(currentSalary * 0.7));
    tagStaffIdentity(this._makeCoachListing(now, firedTrainer.level, discountedStartPrice, firedTrainer.specialty), firedTrainer);
    return { ok: true, relisted: true };
  }

  // ---------------------------------------------------------------------
  // Marché des analystes vidéo — retour utilisateur (2026-09) : "en
  // engageant un staff plus ou moins compétent, on peut voir plus ou moins
  // de caractéristiques de l'adversaire". DEUXIÈME marché de staff,
  // structurellement identique au marché des entraîneurs ci-dessus (voir
  // generateCoachCandidate/placeCoachBid/_resolveCoachListing/
  // refreshCoachMarket/fireTeamTrainer plus haut) — même mécanique
  // d'enchères en temps réel, mêmes constantes COACH_* réutilisées telles
  // quelles (COACH_AUCTION_DURATION_MS, COACH_MARKET_MIN_OPEN_LISTINGS,
  // COACH_MARKET_GENERATE_CHECK_INTERVAL_MS, COACH_CPU_BID_CHANCE) : aucune
  // raison connue de faire tourner ce marché à un rythme différent de celui
  // des entraîneurs — seul l'EFFET du staff recruté diffère (voir
  // Team.videoAnalyst/League.runVideoSession), pas la mécanique du marché
  // lui-même. Si un jour ce marché doit évoluer différemment de celui des
  // entraîneurs, lui donner ses propres constantes ANALYST_* sera trivial
  // (même forme que les COACH_* ci-dessus) — pas la peine de les dupliquer
  // par avance sans besoin réel.
  // ---------------------------------------------------------------------
  generateAnalystCandidate(now) {
    const weights = [40, 28, 18, 10, 4]; // même biais vers les niveaux bas que generateCoachCandidate
    const total = weights.reduce((s, w) => s + w, 0);
    let roll = rand01() * total;
    let level = TRAINER_LEVELS[TRAINER_LEVELS.length - 1];
    for (let i = 0; i < weights.length; i++) {
      if (roll < weights[i]) { level = i + 1; break; }
      roll -= weights[i];
    }
    return this._makeAnalystListing(now, level, TRAINER_BASE_SALARY[level] || 0);
  }

  // Même convention de retour que placeCoachBid — voir son commentaire pour
  // le détail des reasons ("closed"/"invalid-bidder"/"too-low"/
  // "insufficient-budget"), identiques ici.
  placeAnalystBid(listingId, bidderIdx, amount, now) {
    const listing = this.analystListings.find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    const bidder = this.teams[bidderIdx];
    if (!bidder) return { ok: false, reason: "invalid-bidder" };
    const minBid = minNextBidFor(listing);
    if (amount < minBid) return { ok: false, reason: "too-low", minBid };
    if (bidder.isHuman && amount > bidder.budget - this.reservedBidsFor(bidderIdx, listingId)) return { ok: false, reason: "insufficient-budget" };
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = bidderIdx;
    listing.bids.push({ bidderIdx, amount: rounded, at: now });
    const autoOutbid = this._applyAutoBids(listing, "staff", now);
    return { ok: true, listing, autoOutbid };
  }

  // Voir _resolveCoachListing ci-dessus pour le détail du raisonnement (la
  // mise gagnante devient le salaire de départ, pas un débit ponctuel en
  // plus) — identique ici, juste appliqué à Team.hireVideoAnalyst.
  _resolveAnalystListing(listing, now) {
    listing.status = "closed";
    if (listing.currentBidderIdx == null) {
      listing.result = "unsold";
      return;
    }
    const buyerIdx = listing.currentBidderIdx;
    const buyer = this.teams[buyerIdx];
    const amount = listing.currentBid;
    if (buyer.isHuman && amount > buyer.budget) {
      listing.result = "buyer-failed";
      return;
    }
    buyer.hireVideoAnalyst(listing.level, amount);
    tagStaffIdentity(buyer.videoAnalyst, listing);
    if (buyer.isHuman && buyer.feed) {
      handleGameEvent(buyer.feed, {
        type: "staff_hired", week: buyer.week,
        name: feedStaffPlaceholderName(listing.level), role: FEED_STAFF_ROLE_LABELS.analyst,
      }, { clubName: buyer.name });
    }
    listing.result = "sold";
    listing.finalPrice = amount;
  }

  // À appeler au même rythme que refreshCoachMarket (chargement de la page,
  // ouverture de l'onglet Staff...) — méthode VOLONTAIREMENT distincte, même
  // esprit que refreshCoachMarket vs refreshMarket.
  refreshAnalystMarket(now) {
    this.analystListings = this.analystListings || [];

    // 1) Enchères CPU sur les candidats ouverts — "intéressée" = équipe CPU
    // sans analyste du tout, ou dont l'analyste actuel est d'un niveau
    // inférieur à celui du candidat (même esprit que refreshCoachMarket).
    this.analystListings.forEach(listing => {
      if (listing.status !== "open") return;
      if (now - (listing.lastCpuCheckAt || listing.createdAt) < COACH_MARKET_GENERATE_CHECK_INTERVAL_MS) return;
      listing.lastCpuCheckAt = now;
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return; // une équipe humaine enchérit elle-même via placeAnalystBid
        if (idx === listing.currentBidderIdx) return;
        const interested = !team.videoAnalyst || team.videoAnalyst.level < listing.level;
        if (!interested) return;
        if (rand01() >= COACH_CPU_BID_CHANCE) return;
        const minBid = minNextBidFor(listing);
        const maxWilling = Math.round((TRAINER_BASE_SALARY[listing.level] || 0) * rand(1.0, 1.5));
        if (minBid > maxWilling) return; // déjà trop cher pour cette équipe
        const bidAmount = Math.min(maxWilling, Math.round(minBid * rand(1, 1.15)));
        listing.currentBid = bidAmount;
        listing.currentBidderIdx = idx;
        listing.bids.push({ bidderIdx: idx, amount: bidAmount, at: now });
        this._applyAutoBids(listing, "staff", now);
      });
    });

    // 2) Renouvelle les candidats pour garder au moins
    // COACH_MARKET_MIN_OPEN_LISTINGS annonces ouvertes en permanence, même
    // plancher que le marché des entraîneurs (voir son commentaire), pour la
    // même raison (personne ne "vend" spontanément son analyste). Vérifié à
    // CHAQUE appel, même raisonnement que refreshCoachMarket ci-dessus (voir
    // son commentaire, retour utilisateur "on fait des tests et on ne peut
    // acheter personne").
    this.lastAnalystGenerationCheckAt = now;
    {
      let openCount = this.analystListings.filter(l => l.status === "open").length;
      while (openCount < this.staffMarketMinOpenListings()) {
        this.generateAnalystCandidate(now);
        openCount++;
      }
    }

    // 3) Résout toute enchère dont l'échéance est dépassée.
    this.analystListings
      .filter(l => l.status === "open" && now >= l.closesAt)
      .forEach(listing => this._resolveAnalystListing(listing, now));
  }

  // Congédie l'analyste vidéo de `teamIndex` et le remet AUSSITÔT sur le
  // marché des analystes, à un prix de départ réduit — EXACTEMENT le même
  // mécanisme que fireTeamTrainer ci-dessus (voir son commentaire pour le
  // détail complet du raisonnement, identique ici) : prix de départ = 70%
  // du salaire HEBDOMADAIRE DÉJÀ ATTEINT (lu AVANT fireVideoAnalyst(),
  // sinon il n'y aurait plus rien à réduire), borné à 1 minimum. Même
  // convention de retour : { ok: true, relisted: boolean } (jamais une
  // erreur, y compris `teamIndex` invalide ou aucun analyste en poste).
  // Appelée aussi bien par le bouton "Congédier" du panneau analyste côté
  // navigateur en solo que par l'action serveur "fireVideoAnalyst" en mode
  // multi-manager (voir server/actions.js).
  fireTeamVideoAnalyst(teamIndex, now) {
    const team = this.teams[teamIndex];
    if (!team) return { ok: false, relisted: false };
    const firedAnalyst = team.videoAnalyst;
    const currentSalary = team.videoAnalystSalary(); // AVANT fireVideoAnalyst() — voir commentaire ci-dessus
    team.fireVideoAnalyst();
    if (!firedAnalyst) return { ok: true, relisted: false };
    const discountedStartPrice = Math.max(1, Math.round(currentSalary * 0.7));
    tagStaffIdentity(this._makeAnalystListing(now, firedAnalyst.level, discountedStartPrice), firedAnalyst);
    return { ok: true, relisted: true };
  }

  // ---------------------------------------------------------------------
  // Marché des recruteurs — TROISIÈME marché de staff, structurellement
  // identique aux marchés de l'entraîneur/de l'analyste vidéo ci-dessus (voir
  // generateCoachCandidate/placeCoachBid/_resolveCoachListing/
  // refreshCoachMarket/fireTeamTrainer, et leur pendant analyste) — mêmes
  // constantes COACH_* réutilisées telles quelles (aucune raison connue de
  // faire tourner ce marché à un rythme différent). Seul l'EFFET du staff
  // recruté diffère (voir Team.recruiter/refreshYouthCandidates ci-dessus),
  // pas la mécanique du marché lui-même.
  // ---------------------------------------------------------------------
  _makeRecruiterListing(now, level, startPrice) {
    const listing = this._makeStaffListing(now, level, startPrice);
    this.recruiterListings.push(listing);
    return listing;
  }

  generateRecruiterCandidate(now) {
    const weights = [40, 28, 18, 10, 4]; // même biais vers les niveaux bas que generateCoachCandidate
    const total = weights.reduce((s, w) => s + w, 0);
    let roll = rand01() * total;
    let level = TRAINER_LEVELS[TRAINER_LEVELS.length - 1];
    for (let i = 0; i < weights.length; i++) {
      if (roll < weights[i]) { level = i + 1; break; }
      roll -= weights[i];
    }
    return this._makeRecruiterListing(now, level, TRAINER_BASE_SALARY[level] || 0);
  }

  // Même convention de retour que placeCoachBid/placeAnalystBid — voir leur
  // commentaire pour le détail des reasons ("closed"/"invalid-bidder"/
  // "too-low"/"insufficient-budget"), identiques ici.
  placeRecruiterBid(listingId, bidderIdx, amount, now) {
    const listing = this.recruiterListings.find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    const bidder = this.teams[bidderIdx];
    if (!bidder) return { ok: false, reason: "invalid-bidder" };
    const minBid = minNextBidFor(listing);
    if (amount < minBid) return { ok: false, reason: "too-low", minBid };
    if (bidder.isHuman && amount > bidder.budget - this.reservedBidsFor(bidderIdx, listingId)) return { ok: false, reason: "insufficient-budget" };
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = bidderIdx;
    listing.bids.push({ bidderIdx, amount: rounded, at: now });
    const autoOutbid = this._applyAutoBids(listing, "staff", now);
    return { ok: true, listing, autoOutbid };
  }

  // Voir _resolveCoachListing pour le détail du raisonnement (la mise
  // gagnante devient le salaire de départ, pas un débit ponctuel en plus) —
  // identique ici, juste appliqué à Team.hireRecruiter.
  _resolveRecruiterListing(listing, now) {
    listing.status = "closed";
    if (listing.currentBidderIdx == null) {
      listing.result = "unsold";
      return;
    }
    const buyerIdx = listing.currentBidderIdx;
    const buyer = this.teams[buyerIdx];
    const amount = listing.currentBid;
    if (buyer.isHuman && amount > buyer.budget) {
      listing.result = "buyer-failed";
      return;
    }
    buyer.hireRecruiter(listing.level, amount);
    tagStaffIdentity(buyer.recruiter, listing);
    if (buyer.isHuman && buyer.feed) {
      handleGameEvent(buyer.feed, {
        type: "staff_hired", week: buyer.week,
        name: feedStaffPlaceholderName(listing.level), role: FEED_STAFF_ROLE_LABELS.scout,
      }, { clubName: buyer.name });
    }
    listing.result = "sold";
    listing.finalPrice = amount;
  }

  // À appeler au même rythme que refreshCoachMarket/refreshAnalystMarket
  // (chargement de la page, ouverture de l'onglet Staff...).
  refreshRecruiterMarket(now) {
    this.recruiterListings = this.recruiterListings || [];

    // 1) Enchères CPU sur les candidats ouverts — "intéressée" = équipe CPU
    // sans recruteur du tout, ou dont le recruteur actuel est d'un niveau
    // inférieur à celui du candidat (même esprit que refreshCoachMarket).
    this.recruiterListings.forEach(listing => {
      if (listing.status !== "open") return;
      if (now - (listing.lastCpuCheckAt || listing.createdAt) < COACH_MARKET_GENERATE_CHECK_INTERVAL_MS) return;
      listing.lastCpuCheckAt = now;
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return; // une équipe humaine enchérit elle-même via placeRecruiterBid
        if (idx === listing.currentBidderIdx) return;
        const interested = !team.recruiter || team.recruiter.level < listing.level;
        if (!interested) return;
        if (rand01() >= COACH_CPU_BID_CHANCE) return;
        const minBid = minNextBidFor(listing);
        const maxWilling = Math.round((TRAINER_BASE_SALARY[listing.level] || 0) * rand(1.0, 1.5));
        if (minBid > maxWilling) return; // déjà trop cher pour cette équipe
        const bidAmount = Math.min(maxWilling, Math.round(minBid * rand(1, 1.15)));
        listing.currentBid = bidAmount;
        listing.currentBidderIdx = idx;
        listing.bids.push({ bidderIdx: idx, amount: bidAmount, at: now });
        this._applyAutoBids(listing, "staff", now);
      });
    });

    // 2) Renouvelle les candidats pour garder au moins
    // COACH_MARKET_MIN_OPEN_LISTINGS annonces ouvertes en permanence, même
    // plancher que les deux autres marchés de staff. Vérifié à CHAQUE appel,
    // même raisonnement que refreshCoachMarket plus haut (voir son
    // commentaire, retour utilisateur "on fait des tests et on ne peut
    // acheter personne").
    this.lastRecruiterGenerationCheckAt = now;
    {
      let openCount = this.recruiterListings.filter(l => l.status === "open").length;
      while (openCount < this.staffMarketMinOpenListings()) {
        this.generateRecruiterCandidate(now);
        openCount++;
      }
    }

    // 3) Résout toute enchère dont l'échéance est dépassée.
    this.recruiterListings
      .filter(l => l.status === "open" && now >= l.closesAt)
      .forEach(listing => this._resolveRecruiterListing(listing, now));
  }

  // Congédie le recruteur de `teamIndex` et le remet AUSSITÔT sur le marché
  // des recruteurs, à un prix de départ réduit — EXACTEMENT le même
  // mécanisme que fireTeamTrainer/fireTeamVideoAnalyst ci-dessus (voir leur
  // commentaire pour le détail complet du raisonnement, identique ici) :
  // prix de départ = 70% du salaire HEBDOMADAIRE DÉJÀ ATTEINT (lu AVANT
  // fireRecruiter(), sinon il n'y aurait plus rien à réduire), borné à 1
  // minimum. Même convention de retour : { ok: true, relisted: boolean }.
  fireTeamRecruiter(teamIndex, now) {
    const team = this.teams[teamIndex];
    if (!team) return { ok: false, relisted: false };
    const firedRecruiter = team.recruiter;
    const currentSalary = team.recruiterSalary(); // AVANT fireRecruiter() — voir commentaire ci-dessus
    team.fireRecruiter();
    if (!firedRecruiter) return { ok: true, relisted: false };
    const discountedStartPrice = Math.max(1, Math.round(currentSalary * 0.7));
    tagStaffIdentity(this._makeRecruiterListing(now, firedRecruiter.level, discountedStartPrice), firedRecruiter);
    return { ok: true, relisted: true };
  }

  // Plancher de candidats ouverts de CHAQUE marché de staff : 2 par manager
  // humain (voir STAFF_MARKET_LISTINGS_PER_MANAGER).
  staffMarketMinOpenListings() {
    return staffMarketMinOpenListingsFor(this.teams);
  }

  // ---------------------------------------------------------------------
  // Marchés du staff médical (médecin/kiné, voir MEDICAL_STAFF_ROLES) —
  // mêmes règles que les marchés entraîneur/analyste/recruteur ci-dessus
  // (enchère d'un jour, CPU intéressés s'ils n'ont personne ou moins bien,
  // plancher de candidats ouverts, congédiement relisté à -30 %), écrites
  // une seule fois pour les deux rôles (`role` = "doctor" | "physio").
  // ---------------------------------------------------------------------
  _medicalListings(role) {
    const cfg = MEDICAL_STAFF_ROLES[role];
    if (!cfg) return null;
    if (!Array.isArray(this[cfg.listKey])) this[cfg.listKey] = [];
    return this[cfg.listKey];
  }

  _makeMedicalListing(role, now, level, startPrice) {
    const listings = this._medicalListings(role);
    if (!listings) return null;
    const listing = this._makeStaffListing(now, level, startPrice);
    listings.push(listing);
    return listing;
  }

  generateMedicalCandidate(role, now) {
    const weights = [40, 28, 18, 10, 4]; // poids des niveaux 1 à 5, comme les autres rôles
    const total = weights.reduce((s, w) => s + w, 0);
    let roll = rand01() * total;
    let level = TRAINER_LEVELS[TRAINER_LEVELS.length - 1];
    for (let i = 0; i < weights.length; i++) {
      if (roll < weights[i]) { level = i + 1; break; }
      roll -= weights[i];
    }
    return this._makeMedicalListing(role, now, level, TRAINER_BASE_SALARY[level] || 0);
  }

  placeMedicalBid(role, listingId, bidderIdx, amount, now) {
    const listings = this._medicalListings(role);
    if (!listings) return { ok: false, reason: "invalid-role" };
    const listing = listings.find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    const bidder = this.teams[bidderIdx];
    if (!bidder) return { ok: false, reason: "invalid-bidder" };
    const minBid = minNextBidFor(listing);
    if (amount < minBid) return { ok: false, reason: "too-low", minBid };
    if (bidder.isHuman && amount > bidder.budget - this.reservedBidsFor(bidderIdx, listingId)) return { ok: false, reason: "insufficient-budget" };
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = bidderIdx;
    listing.bids.push({ bidderIdx, amount: rounded, at: now });
    const autoOutbid = this._applyAutoBids(listing, "staff", now);
    return { ok: true, listing, autoOutbid };
  }

  _resolveMedicalListing(role, listing, now) {
    listing.status = "closed";
    if (listing.currentBidderIdx == null) {
      listing.result = "unsold";
      return;
    }
    const buyer = this.teams[listing.currentBidderIdx];
    const amount = listing.currentBid;
    if (!buyer || (buyer.isHuman && amount > buyer.budget)) {
      listing.result = "buyer-failed";
      return;
    }
    buyer.hireMedicalStaff(role, listing.level, amount);
    tagStaffIdentity(buyer[role], listing);
    if (buyer.isHuman && buyer.feed) {
      handleGameEvent(buyer.feed, {
        type: "staff_hired", week: buyer.week,
        name: feedStaffPlaceholderName(listing.level), role: FEED_STAFF_ROLE_LABELS[MEDICAL_STAFF_ROLES[role].feedKey],
      }, { clubName: buyer.name });
    }
    listing.result = "sold";
    listing.finalPrice = amount;
  }

  refreshMedicalMarket(role, now) {
    const listings = this._medicalListings(role);
    if (!listings) return;

    listings.forEach(listing => {
      if (listing.status !== "open") return;
      if (now - (listing.lastCpuCheckAt || listing.createdAt) < COACH_MARKET_GENERATE_CHECK_INTERVAL_MS) return;
      listing.lastCpuCheckAt = now;
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return; // une équipe humaine enchérit elle-même via placeMedicalBid
        if (idx === listing.currentBidderIdx) return;
        const current = team[role];
        const interested = !current || current.level < listing.level;
        if (!interested) return;
        if (rand01() >= COACH_CPU_BID_CHANCE) return;
        const minBid = minNextBidFor(listing);
        const maxWilling = Math.round((TRAINER_BASE_SALARY[listing.level] || 0) * rand(1.0, 1.5));
        if (minBid > maxWilling) return;
        const bidAmount = Math.min(maxWilling, Math.round(minBid * rand(1, 1.15)));
        listing.currentBid = bidAmount;
        listing.currentBidderIdx = idx;
        listing.bids.push({ bidderIdx: idx, amount: bidAmount, at: now });
        this._applyAutoBids(listing, "staff", now);
      });
    });

    let openCount = listings.filter(l => l.status === "open").length;
    const minOpen = this.staffMarketMinOpenListings();
    while (openCount < minOpen) {
      this.generateMedicalCandidate(role, now);
      openCount++;
    }

    listings
      .filter(l => l.status === "open" && now >= l.closesAt)
      .forEach(listing => this._resolveMedicalListing(role, listing, now));
  }

  // Congédie le médecin/kiné de `teamIndex` et le remet aussitôt sur le
  // marché à 70 % de son salaire actuel (même règle que fireTeamTrainer).
  fireTeamMedicalStaff(role, teamIndex, now) {
    const team = this.teams[teamIndex];
    if (!team || !MEDICAL_STAFF_ROLES[role]) return { ok: false, relisted: false };
    const fired = team[role];
    const currentSalary = team.medicalStaffSalary(role); // AVANT fireMedicalStaff()
    team.fireMedicalStaff(role);
    if (!fired) return { ok: true, relisted: false };
    const discountedStartPrice = Math.max(1, Math.round(currentSalary * 0.7));
    tagStaffIdentity(this._makeMedicalListing(role, now, fired.level, discountedStartPrice), fired);
    return { ok: true, relisted: true };
  }

  placeDoctorBid(listingId, bidderIdx, amount, now) { return this.placeMedicalBid("doctor", listingId, bidderIdx, amount, now); }
  placePhysioBid(listingId, bidderIdx, amount, now) { return this.placeMedicalBid("physio", listingId, bidderIdx, amount, now); }
  refreshDoctorMarket(now) { this.refreshMedicalMarket("doctor", now); }
  refreshPhysioMarket(now) { this.refreshMedicalMarket("physio", now); }
  fireTeamDoctor(teamIndex, now) { return this.fireTeamMedicalStaff("doctor", teamIndex, now); }
  fireTeamPhysio(teamIndex, now) { return this.fireTeamMedicalStaff("physio", teamIndex, now); }

  // ---------------------------------------------------------------------
  // Marché des entraîneurs adjoints (voir ASSISTANT_SPECIALTIES) — mêmes
  // règles que le staff médical ci-dessus (enchère, CPU intéressés s'ils
  // n'ont personne ou moins bien, plancher de candidats, congédiement
  // relisté à -30 %) ; chaque candidat a en plus une SPÉCIALITÉ, tirée au
  // hasard. Plancher doublé (4 spécialités au choix).
  // ---------------------------------------------------------------------
  _assistantCoachListings() {
    if (!Array.isArray(this.assistantCoachListings)) this.assistantCoachListings = [];
    return this.assistantCoachListings;
  }
  _makeAssistantCoachListing(now, level, specialty, startPrice) {
    const listing = this._makeStaffListing(now, level, startPrice);
    listing.specialty = specialty;
    this._assistantCoachListings().push(listing);
    return listing;
  }
  generateAssistantCoachCandidate(now, specialty = null) {
    const weights = [40, 28, 18, 10, 4];
    const total = weights.reduce((s, w) => s + w, 0);
    let roll = rand01() * total;
    let level = TRAINER_LEVELS[TRAINER_LEVELS.length - 1];
    for (let i = 0; i < weights.length; i++) {
      if (roll < weights[i]) { level = i + 1; break; }
      roll -= weights[i];
    }
    const keys = Object.keys(ASSISTANT_SPECIALTIES);
    const spec = ASSISTANT_SPECIALTIES[specialty] ? specialty : keys[Math.floor(rand01() * keys.length)];
    return this._makeAssistantCoachListing(now, level, spec, ASSISTANT_BASE_SALARY[level] || 0);
  }
  placeAssistantCoachBid(listingId, bidderIdx, amount, now) {
    const listing = this._assistantCoachListings().find(l => l.id === listingId);
    if (!listing || listing.status !== "open" || now >= listing.closesAt) return { ok: false, reason: "closed" };
    const bidder = this.teams[bidderIdx];
    if (!bidder) return { ok: false, reason: "invalid-bidder" };
    const minBid = minNextBidFor(listing);
    if (amount < minBid) return { ok: false, reason: "too-low", minBid };
    if (bidder.isHuman && amount > bidder.budget - this.reservedBidsFor(bidderIdx, listingId)) return { ok: false, reason: "insufficient-budget" };
    const rounded = Math.round(amount);
    listing.currentBid = rounded;
    listing.currentBidderIdx = bidderIdx;
    listing.bids.push({ bidderIdx, amount: rounded, at: now });
    const autoOutbid = this._applyAutoBids(listing, "staff", now);
    return { ok: true, listing, autoOutbid };
  }
  _resolveAssistantCoachListing(listing, now) {
    listing.status = "closed";
    if (listing.currentBidderIdx == null) { listing.result = "unsold"; return; }
    const buyer = this.teams[listing.currentBidderIdx];
    const amount = listing.currentBid;
    if (!buyer || (buyer.isHuman && amount > buyer.budget)) { listing.result = "buyer-failed"; return; }
    buyer.hireAssistantCoach(listing.specialty, listing.level, amount);
    tagStaffIdentity(buyer.assistantCoach, listing);
    if (buyer.isHuman && buyer.feed) {
      handleGameEvent(buyer.feed, {
        type: "staff_hired", week: buyer.week,
        name: feedStaffPlaceholderName(listing.level), role: FEED_STAFF_ROLE_LABELS.assistant,
      }, { clubName: buyer.name });
    }
    listing.result = "sold";
    listing.finalPrice = amount;
  }
  refreshAssistantCoachMarket(now) {
    const listings = this._assistantCoachListings();
    listings.forEach(listing => {
      if (listing.status !== "open") return;
      if (now - (listing.lastCpuCheckAt || listing.createdAt) < COACH_MARKET_GENERATE_CHECK_INTERVAL_MS) return;
      listing.lastCpuCheckAt = now;
      this.teams.forEach((team, idx) => {
        if (team.isHuman) return;
        if (idx === listing.currentBidderIdx) return;
        const current = team.assistantCoach;
        if (current && current.level >= listing.level) return;
        if (rand01() >= COACH_CPU_BID_CHANCE) return;
        const minBid = minNextBidFor(listing);
        const maxWilling = Math.round((ASSISTANT_BASE_SALARY[listing.level] || 0) * rand(1.0, 1.5));
        if (minBid > maxWilling) return;
        const bidAmount = Math.min(maxWilling, Math.round(minBid * rand(1, 1.15)));
        listing.currentBid = bidAmount;
        listing.currentBidderIdx = idx;
        listing.bids.push({ bidderIdx: idx, amount: bidAmount, at: now });
        this._applyAutoBids(listing, "staff", now);
      });
    });
    let openCount = listings.filter(l => l.status === "open").length;
    const minOpen = 2 * this.staffMarketMinOpenListings();
    while (openCount < minOpen) {
      this.generateAssistantCoachCandidate(now);
      openCount++;
    }
    listings
      .filter(l => l.status === "open" && now >= l.closesAt)
      .forEach(listing => this._resolveAssistantCoachListing(listing, now));
  }
  // Congédie l'adjoint et le remet sur le marché à 70 % de son salaire actuel.
  fireTeamAssistantCoach(teamIndex, now) {
    const team = this.teams[teamIndex];
    if (!team) return { ok: false, relisted: false };
    const fired = team.assistantCoach;
    const currentSalary = team.assistantCoachSalary();
    team.fireAssistantCoach();
    if (!fired) return { ok: true, relisted: false };
    tagStaffIdentity(this._makeAssistantCoachListing(now, fired.level, fired.specialty, Math.max(1, Math.round(currentSalary * 0.7))), fired);
    return { ok: true, relisted: true };
  }

  // ---------------------------------------------------------------------
  // Séance vidéo (retour utilisateur, 2026-09) : "il faudrait pouvoir
  // scouter l'effectif de son adversaire. L'idée est d'avoir une vue au
  // moins sur les salaires, taille, poste... mais pas sur les
  // caractéristiques. En engageant un staff plus ou moins compétent, on
  // peut voir plus ou moins de caractéristiques de l'adversaire en faisant
  // une séance vidéo de l'adversaire." Action DÉLIBÉRÉE et ponctuelle par
  // adversaire choisi par le manager (pas une révélation passive
  // permanente) : nom/poste/taille/salaire restent, eux, TOUJOURS visibles
  // pour n'importe quel adversaire, sans staff — c'est uniquement l'accès
  // aux 10 caractéristiques (ATTRS) qui est gating derrière cette séance.
  //
  // Plafonnée à UNE séance par jour CIVIL à Paris (tous adversaires
  // confondus pour ce club — voir Team.lastVideoSessionAt et
  // sameParisCalendarDay plus bas dans ce fichier, qui réutilise
  // directement parisLocalDateParts) : même ancrage "jour civil" que le
  // reste du rythme quotidien entraînement/économie de la ligue
  // multi-manager (voir le grand bloc "CALENDRIER ANCRÉ QUOTIDIEN" plus bas)
  // plutôt qu'une fenêtre glissante de 24h, pour rester cohérent avec cette
  // même notion de "jour" partout ailleurs dans le jeu.
  //
  // Nombre de caractéristiques révélées = ANALYST_REVEAL_COUNT_BY_LEVEL[level]
  // (voir cette constante plus haut, à côté de TRAINER_LEVELS — plafonné
  // volontairement SOUS 10, retour utilisateur : "il faut trouver un système
  // qui ne permet pas de voir toutes les caractéristiques des joueurs sinon
  // c'est trop facile"). Le choix des caractéristiques révélées parmi les 10
  // est tiré au sort (shuffleIndices — comme le reste du moteur, jamais de
  // générateur seedé, testable en figeant Math.random()) plutôt qu'un ordre
  // fixe : rien dans la demande utilisateur n'indique qu'un type de
  // caractéristique devrait systématiquement sortir avant un autre.
  //
  // Renvoie { ok: true, opponentIdx, revealed, analystLevel } ou
  // { ok: false, reason } — reasons : "invalid-team" (défensif, teamIndex
  // hors bornes), "no-analyst" (aucun analyste sous contrat),
  // "already-scouted" (CET adversaire a déjà été scouté cette saison — voir
  // plus bas), "cooldown" (une séance a déjà été utilisée aujourd'hui, pour
  // un AUTRE adversaire pas encore scouté), "invalid-opponent" (index hors
  // bornes ou égal à teamIndex — on ne scoute pas sa propre équipe).
  //
  // Un même adversaire ne peut être scouté qu'UNE SEULE FOIS PAR SAISON,
  // point final (retour utilisateur, 2026-09 : "un même adversaire ne doit
  // pouvoir être scouté qu'une fois par saison parce que sinon en PO chacun
  // connaît les caracs de l'autre et c'est pas le but") — DÈS que
  // Team.scoutedAttrs[opponentIdx] contient au moins une entrée, toute
  // NOUVELLE séance vidéo contre CE MÊME adversaire est refusée
  // ("already-scouted"), pour le reste de la saison, MÊME des jours/semaines
  // plus tard (contrairement au cooldown quotidien ci-dessous, qui lui EST
  // temporaire), et MÊME si l'analyste est entre-temps monté en niveau — un
  // meilleur analyste débloque plus de caractéristiques sur un NOUVEL
  // adversaire, jamais plus sur un adversaire déjà scouté (l'ancienne
  // logique d'UNION entre deux séances sur le même adversaire a donc
  // disparu : elle est désormais inatteignable, une 2e séance sur le même
  // adversaire étant toujours rejetée avant même d'atteindre ce calcul).
  // Remise à zéro naturelle à chaque nouvelle saison (Team.scoutedAttrs fait
  // partie de l'état Team, régénéré comme le reste — voir generateLeague).
  //
  // Cooldown quotidien INCHANGÉ par ailleurs (voir Team.lastVideoSessionAt/
  // sameParisCalendarDay) : sert uniquement à limiter le RYTHME (un NOUVEL
  // adversaire scouté par jour civil à Paris maximum, tous adversaires
  // confondus) — pas à autoriser une 2e séance sur un adversaire déjà
  // scouté une fois ce cooldown écoulé, c'est justement ce que
  // "already-scouted" empêche en permanence, indépendamment du temps passé.
  runVideoSession(teamIndex, opponentIdx, now) {
    const team = this.teams[teamIndex];
    if (!team) return { ok: false, reason: "invalid-team" };
    if (!team.videoAnalyst) return { ok: false, reason: "no-analyst" };
    if (opponentIdx === teamIndex || !this.teams[opponentIdx]) return { ok: false, reason: "invalid-opponent" };
    // Brouillard de guerre (2026-10-06) : un rapport par club adverse et par
    // saison, rangé par NOM de club (stable malgré montées/descentes, et
    // remis à zéro naturellement par la saison suivante).
    const opp = this.teams[opponentIdx];
    const season = this.seasonNumber || 1;
    if (Fog.reportFor(team, opp.name, season)) return { ok: false, reason: "already-scouted" };
    if (team.lastVideoSessionAt != null && sameParisCalendarDay(team.lastVideoSessionAt, now)) {
      return { ok: false, reason: "cooldown" };
    }
    const level = team.videoAnalyst.level;
    const report = Fog.makeReport(opp, { level, season, now, attrs: ATTRS, overall: p => p.overall() });
    Fog.addReport(team, report);
    team.lastVideoSessionAt = now;
    return { ok: true, opponentIdx, revealed: report.keys, analystLevel: level, season };
  }
}

// Calcule la prime de fin de saison à verser au club du joueur d'après le
// résultat de la saison (voir League.divisionOutcomeForUserTeam ci-dessus) :
// montée = prime de montée fonction de la division D'ARRIVÉE (voir
// PROMOTION_BONUS_BY_LEVEL), champion de Division I sans montée possible =
// prime de champion, plus modeste (voir CHAMPION_BONUS_DIVISION_I). Renvoie
// `null` si aucune prime n'est due (relégation, ou maintien sans titre).
function seasonEndBonusFor(outcome) {
  if (outcome.outcome === "promoted") {
    return { label: `Prime de montée (${divisionInfo(outcome.toLevel).name})`, amount: PROMOTION_BONUS_BY_LEVEL[outcome.toLevel] || PROMOTION_BONUS_FLOOR };
  }
  if (outcome.championDivisionI) {
    return { label: "Prime de champion (Division I)", amount: CHAMPION_BONUS_DIVISION_I };
  }
  return null;
}

// ---------------------------------------------------------------------
// Objectif de saison du conseil d'administration (retour utilisateur,
// 2026-09) : "En début de saison, le conseil d'administration doit donner
// un objectif de classement (maintien, milieu de tableau, PO, finale,
// titre). [...] Si l'objectif n'est pas respecté pendant la saison, cela
// impact l'humeur des supporters. Une équipe qui est dernière alors qu'elle
// devait jouer la finale, doit voir ses supporters mécontents. L'objectif
// du CA doit être posé sur base du niveau des différentes équipes du
// championnat."
//
// Conception : `assignSeasonObjectives` (appelée par
// buildLeagueWithHumanTeams, donc pour toute nouvelle carrière ET chaque
// nouvelle saison, humaine ou CPU) classe les 10 équipes de la ligue par
// force pré-saison (Team.averageOverall) et découpe ce classement en 5
// paliers de 2 équipes, du plus faible (Team.seasonObjective = "maintien")
// au plus fort ("titre") : c'est la lecture la plus directe de "posé sur
// base du niveau des différentes équipes du championnat". `seasonObjective`
// reste figé tout le reste de la saison (jamais recalculé en cours de
// route), et le verdict n'est établi qu'une fois la saison ENTIÈREMENT
// terminée (saison régulière + barrage de relégation + play-offs jusqu'au
// champion, voir seasonAchievementTier) : c'est à ce moment-là,
// symétriquement à League.divisionOutcomeForUserTeam/seasonEndBonusFor déjà
// résolus au même endroit (voir startNewSeason côté moteurbasket3.html),
// que seasonObjectiveVerdict compare l'ambition de départ au résultat réel
// et calcule l'impact sur l'humeur des supporters (Team.recordMoraleEvent),
// exactement l'exemple donné : une équipe attendue en finale qui termine
// reléguée doit voir ses supporters mécontents.
const SEASON_OBJECTIVE_TIERS = { "maintien": 1, "milieu-tableau": 2, "playoffs": 3, "finale": 4, "titre": 5 };
const SEASON_OBJECTIVE_LABELS = {
  "maintien": "Maintien",
  "milieu-tableau": "Milieu de tableau",
  "playoffs": "Qualification en play-offs",
  "finale": "Finale des play-offs",
  "titre": "Titre de champion",
};
// Ce que l'équipe a RÉELLEMENT obtenu à l'issue de la saison, sur la même
// échelle ordinale que SEASON_OBJECTIVE_TIERS (0 = pire que le pire
// objectif possible, la relégation, jamais elle-même une aspiration) : voir
// seasonAchievementTier pour le calcul.
const SEASON_ACHIEVEMENT_LABELS = {
  0: "une relégation",
  1: "un maintien tout juste assuré",
  2: "une saison milieu de tableau",
  3: "une élimination en demi-finale des play-offs",
  4: "une finale des play-offs perdue",
  5: "le titre de champion",
};
// Barème de l'impact sur l'humeur des supporters (voir
// Team.recordMoraleEvent), fonction de l'écart entre le palier visé
// (SEASON_OBJECTIVE_TIERS) et le palier réellement atteint
// (seasonAchievementTier) : un objectif manqué coûte plus cher, par palier
// d'écart, qu'un objectif dépassé n'en rapporte (les supporters sont plus
// sévères face à un échec qu'indulgents face à une bonne surprise, même
// logique que MILESTONE_INTERVIEW_TONES fanWin/fanLoss). Un objectif
// exactement atteint (écart nul) rapporte un petit bonus : le mérite d'avoir
// fait ce qui était demandé, ni plus ni moins.
const SEASON_OBJECTIVE_MISS_MALUS_PER_TIER = 6;
const SEASON_OBJECTIVE_EXCEED_BONUS_PER_TIER = 4;
const SEASON_OBJECTIVE_MET_BONUS = 3;

// Classe les 10 équipes de `league` par force pré-saison (Team.
// averageOverall décroissant) et assigne à CHACUNE (pas seulement l'équipe
// du joueur : voir la généralisation multi-manager déjà en place ailleurs
// dans ce fichier) l'un des 5 paliers de SEASON_OBJECTIVE_TIERS, par
// tranches de 2 (rangs 1-2 -> "titre", ..., rangs 9-10 -> "maintien").
// Appelée une seule fois, à la création/régénération de la ligue (voir
// buildLeagueWithHumanTeams, seul appelant), jamais recalculée en cours de
// saison.
function assignSeasonObjectives(league) {
  const tierKeysStrongToWeak = ["titre", "finale", "playoffs", "milieu-tableau", "maintien"];
  const ranked = league.teams
    .map((t, idx) => ({ idx, avg: t.averageOverall() }))
    .sort((a, b) => b.avg - a.avg);
  ranked.forEach((entry, rankIdx) => {
    const tierIndex = Math.min(tierKeysStrongToWeak.length - 1, Math.floor(rankIdx / 2));
    league.teams[entry.idx].seasonObjective = tierKeysStrongToWeak[tierIndex];
    // Nouvelle saison, nouveau verdict à venir (voir Team.
    // seasonObjectiveVerdictSettled plus haut).
    league.teams[entry.idx].seasonObjectiveVerdictSettled = false;
  });
}

// Ce que l'équipe `teamIdx` a RÉELLEMENT obtenu à l'issue de la saison,
// 0 à 5 sur la même échelle que SEASON_OBJECTIVE_TIERS (voir
// SEASON_ACHIEVEMENT_LABELS pour le libellé de chaque valeur) : la
// relégation prime sur tout le reste (0, même pour une équipe par ailleurs
// allée loin en Coupe ou bien classée avant le barrage), sinon le parcours
// en play-offs (champion 5, finaliste 4, éliminé en demi-finale 3), sinon
// le classement de saison régulière (rang 5-6 -> 2 "milieu de tableau",
// rang 7-8 -> 1 "maintien", ces deux-là ayant nécessairement évité la
// relégation pour arriver jusqu'ici, voir la garde tout en haut).
// Retour utilisateur (2026-09) : "pour les équipes de milieu de classement
// (ni PO ni barrage) et celles qui descendent tout de suite [...] la fin de
// la saison régulière correspond à la fin de la saison pour ces équipes
// là" : un rang 5-6 (jamais en play-offs ni au barrage) ou 9-10 (relégation
// AUTOMATIQUE, voir relegatedTeamIndexes : le barrage ne concerne que les
// rangs 7-8, jamais 9-10) a donc un palier définitif dès que le classement
// de saison régulière est figé (League.round a atteint son dernier round,
// il y reste ensuite figé pour de bon, jamais ré-avancé par les play-offs
// ni le barrage, voir le commentaire de League.startPlayoffsIfNeeded),
// SANS attendre que les play-offs et le barrage des AUTRES équipes de la
// ligue se terminent à leur tour. Pour toute autre équipe (rang 1-4 en lice
// pour les play-offs, rang 7-8 au barrage), `null` tant que la saison n'est
// pas ENTIÈREMENT terminée (pas de play-offs, ou champion pas encore connu,
// voir League.isPlayoffsDone) : appeler cette fonction plus tôt pour
// celles-ci donnerait un verdict prématuré et faux.
function seasonAchievementTier(league, teamIdx) {
  if (league.round >= league.totalRounds - 1) {
    const lockedRank = league.standings().findIndex(s => s.idx === teamIdx) + 1; // 1-10, 0 si absent
    if (lockedRank === 9 || lockedRank === 10) return 0;
    if (lockedRank === 5 || lockedRank === 6) return 2;
  }
  if (!league.playoffs || league.playoffs.champion == null) return null;
  if (league.relegatedTeamIndexes().includes(teamIdx)) return 0;
  const po = league.playoffs;
  if (po.champion === teamIdx) return 5;
  if (po.finalSeries && po.finalSeries.resolved && (po.finalSeries.idxA === teamIdx || po.finalSeries.idxB === teamIdx)) return 4;
  for (const series of po.series) {
    if (series.resolved && (series.idxA === teamIdx || series.idxB === teamIdx) && series.winner !== teamIdx) return 3;
  }
  const rank = league.standings().findIndex(s => s.idx === teamIdx) + 1; // 1-10
  return rank <= 6 ? 2 : 1;
}

// Verdict complet de fin de saison pour `teamIdx` (objectif du CA vs
// résultat réel, voir le grand commentaire de SEASON_OBJECTIVE_TIERS
// au-dessus) : fonction PURE (aucune mutation, contrairement à
// Team.recordMoraleEvent), utilisée à la fois pour l'AFFICHAGE (voir
// renderSeasonEnd/renderHumeurSection côté moteurbasket3.html, appelée à
// chaque rendu, purement en lecture) et pour l'APPLICATION réelle (voir
// startNewSeason côté moteurbasket3.html, qui appelle ENSUITE
// Team.recordMoraleEvent(verdict.label, verdict.delta) avec le résultat),
// même patron que seasonEndBonusFor/Team.recordTransaction juste au-dessus.
// Renvoie `null` si l'équipe n'a pas encore d'objectif assigné, ou si la
// saison n'est pas encore terminée (voir seasonAchievementTier).
function seasonObjectiveVerdict(league, teamIdx) {
  const team = league.teams[teamIdx];
  if (!team || !team.seasonObjective) return null;
  const achievedTier = seasonAchievementTier(league, teamIdx);
  if (achievedTier == null) return null;
  const objective = team.seasonObjective;
  const objectiveTier = SEASON_OBJECTIVE_TIERS[objective];
  const gap = objectiveTier - achievedTier; // > 0 = objectif manqué, <= 0 = atteint ou dépassé
  const delta = gap > 0
    ? -SEASON_OBJECTIVE_MISS_MALUS_PER_TIER * gap
    : SEASON_OBJECTIVE_MET_BONUS + SEASON_OBJECTIVE_EXCEED_BONUS_PER_TIER * (-gap);
  const achievedLabel = SEASON_ACHIEVEMENT_LABELS[achievedTier];
  const objectiveLabel = SEASON_OBJECTIVE_LABELS[objective];
  const label = gap > 0
    ? `Objectif de la saison manqué (${objectiveLabel}) : l'équipe termine avec ${achievedLabel}. Les supporters sont déçus.`
    : gap === 0
      ? `Objectif de la saison rempli (${objectiveLabel}) : l'équipe termine avec ${achievedLabel}, exactement ce qui était demandé.`
      : `Objectif de la saison largement dépassé (${objectiveLabel} espéré) : l'équipe termine avec ${achievedLabel} ! Les supporters sont aux anges.`;
  return { objective, objectiveTier, achievedTier, achievedLabel, gap, delta, label };
}

// ---------------------------------------------------------------------
// Signaux INTERMÉDIAIRES pour l'objectif du conseil d'administration (retour
// utilisateur, 2026-09, en complément du verdict de fin de saison ci-dessus).
// D'abord la mi-saison ("Ajoute un signal à la mi saison ouais ça serait pas
// mal"), puis un second, juste après la saison régulière ("Juste après la
// saison régulière (avant PO et barrage) aussi") : contrairement à
// seasonObjectiveVerdict, aucun résultat DÉFINITIF n'existe encore à aucun
// de ces deux moments (ni barrage de relégation, ni play-offs, la mi-saison
// n'ayant en plus même pas la saison régulière complète) : on se contente
// donc de comparer le classement PROVISOIRE actuel (League.standings(), à
// cet instant précis) à l'objectif du CA (Team.seasonObjective), avec
// EXACTEMENT le même découpage par tranches de 2 équipes que
// assignSeasonObjectives (rangs 1-2 -> "titre", ..., rangs 9-10 ->
// "maintien") : réutilise ainsi la même échelle
// (SEASON_OBJECTIVE_TIERS/SEASON_OBJECTIVE_LABELS) plutôt que d'inventer de
// nouveaux seuils arbitraires à chaque étape intermédiaire.
//
// Les deux signaux partagent EXACTEMENT le même calcul (voir
// computeSeasonObjectivePaceSignal ci-dessous), seuls le barème et le
// libellé diffèrent, par ordre de fiabilité CROISSANTE (jamais autant que le
// verdict final, qui reste la vraie sanction/récompense, pour éviter de
// compter deux fois le même écart) : la mi-saison est la moins fiable
// (saison régulière encore à moitié jouée), la fin de saison régulière la
// plus fiable des deux (classement définitif de la phase régulière, mais
// barrage/play-offs encore à venir, susceptibles de faire encore bouger le
// palier réellement atteint).
const SEASON_OBJECTIVE_MIDSEASON_MISS_MALUS_PER_TIER = 3;
const SEASON_OBJECTIVE_MIDSEASON_EXCEED_BONUS_PER_TIER = 2;
const SEASON_OBJECTIVE_MIDSEASON_MET_BONUS = 1;
const SEASON_OBJECTIVE_ENDREG_MISS_MALUS_PER_TIER = 4;
const SEASON_OBJECTIVE_ENDREG_EXCEED_BONUS_PER_TIER = 3;
const SEASON_OBJECTIVE_ENDREG_MET_BONUS = 2;

// Palier de classement ACTUEL (une des clés de SEASON_OBJECTIVE_TIERS) pour
// `teamIdx`, d'après son rang dans League.standings() À CET INSTANT (donc
// utilisable EN COURS de saison régulière, contrairement à
// seasonAchievementTier qui exige la saison entièrement terminée) : même
// découpage par tranches de 2 que assignSeasonObjectives (rangs 1-2 ->
// "titre", ..., rangs 9-10 -> "maintien"). `null` si `teamIdx` est introuvable
// dans le classement (garde défensive, ne devrait jamais arriver en pratique).
function currentStandingsPaceObjective(league, teamIdx) {
  const tierKeysStrongToWeak = ["titre", "finale", "playoffs", "milieu-tableau", "maintien"];
  const rank = league.standings().findIndex(s => s.idx === teamIdx) + 1; // 1-10, 0 si absent
  if (rank <= 0) return null;
  const tierIndex = Math.min(tierKeysStrongToWeak.length - 1, Math.floor((rank - 1) / 2));
  return tierKeysStrongToWeak[tierIndex];
}

// Calcul COMMUN aux deux signaux intermédiaires (objectif du CA vs
// classement PROVISOIRE actuel) : même forme que seasonObjectiveVerdict
// ci-dessus (fonction PURE, aucune mutation), factorisée ici pour que
// seasonObjectiveMidSeasonSignal/seasonObjectiveEndOfRegularSeasonSignal
// n'aient chacune qu'à lui passer leur propre barème (voir les constantes
// MIDSEASON_*/ENDREG_* plus haut) et le préfixe de leur libellé. Renvoie
// `null` si l'équipe n'a pas encore d'objectif assigné, ou si son rang est
// introuvable dans le classement (voir currentStandingsPaceObjective).
function computeSeasonObjectivePaceSignal(league, teamIdx, missMalusPerTier, exceedBonusPerTier, metBonus, stagePrefix) {
  const team = league.teams[teamIdx];
  if (!team || !team.seasonObjective) return null;
  const paceObjective = currentStandingsPaceObjective(league, teamIdx);
  if (!paceObjective) return null;
  const objective = team.seasonObjective;
  const objectiveTier = SEASON_OBJECTIVE_TIERS[objective];
  const paceTier = SEASON_OBJECTIVE_TIERS[paceObjective];
  const gap = objectiveTier - paceTier; // > 0 = en dessous de l'objectif, <= 0 = sur la bonne voie ou au-dessus
  const delta = gap > 0
    ? -missMalusPerTier * gap
    : metBonus + exceedBonusPerTier * (-gap);
  const objectiveLabel = SEASON_OBJECTIVE_LABELS[objective];
  const paceLabel = SEASON_OBJECTIVE_LABELS[paceObjective];
  const label = gap > 0
    ? `${stagePrefix} : le rythme actuel (${paceLabel}) est en dessous de l'objectif (${objectiveLabel}). Les supporters s'inquiètent déjà.`
    : gap === 0
      ? `${stagePrefix} : le rythme actuel colle exactement à l'objectif (${objectiveLabel}). Les supporters restent confiants.`
      : `${stagePrefix} : le rythme actuel (${paceLabel}) dépasse largement l'objectif (${objectiveLabel} espéré). Les supporters sont optimistes.`;
  return { objective, objectiveTier, paceObjective, paceTier, gap, delta, label };
}

// Signal de mi-saison (voir server/liveMatch.js:finalizeRound, seul
// appelant en production, qui l'applique via
// Team.recordMoraleEvent(signal.label, signal.delta) pour CHAQUE équipe
// humaine impliquée dans la journée de mi-saison, solo comme multi-manager).
function seasonObjectiveMidSeasonSignal(league, teamIdx) {
  return computeSeasonObjectivePaceSignal(league, teamIdx,
    SEASON_OBJECTIVE_MIDSEASON_MISS_MALUS_PER_TIER, SEASON_OBJECTIVE_MIDSEASON_EXCEED_BONUS_PER_TIER,
    SEASON_OBJECTIVE_MIDSEASON_MET_BONUS, "Mi-saison");
}

// Signal de FIN DE SAISON RÉGULIÈRE (retour utilisateur, 2026-09 : "Juste
// après la saison régulière (avant PO et barrage) aussi") : même mécanique
// que le signal de mi-saison ci-dessus, appelé au moment du jalon
// "fin-saison-reguliere" (voir milestoneTypeForRound, round = totalRounds -
// 1), donc AVANT League.startPlayoffsIfNeeded/runRelegationBarrage (voir
// server/autoSim.js:catchUpPlayoffs, appelée seulement APRÈS que la
// dernière journée de championnat a été réglée) : League.standings() reflète
// ici le classement DÉFINITIF de la saison régulière, plus fiable qu'à la
// mi-saison, mais encore susceptible de changer une fois le barrage et les
// play-offs joués (d'où un barème plus franc que la mi-saison, voir
// ENDREG_* plus haut, mais toujours strictement en retrait du verdict final).
function seasonObjectiveEndOfRegularSeasonSignal(league, teamIdx) {
  return computeSeasonObjectivePaceSignal(league, teamIdx,
    SEASON_OBJECTIVE_ENDREG_MISS_MALUS_PER_TIER, SEASON_OBJECTIVE_ENDREG_EXCEED_BONUS_PER_TIER,
    SEASON_OBJECTIVE_ENDREG_MET_BONUS, "Fin de saison régulière");
}

// ---------------------------------------------------------------------
// Bonus de qualification SURPRISE en play-offs (retour utilisateur, 2026-09,
// ultérieur aux deux signaux ci-dessus : "une équipe qui est en PO alors que
// le CA ne visait que le milieu de tableau/maintien doit avoir un petit
// surplus des supporters pour les PO" puis, en précision, "elle doit avoir
// un petit bonus au moment des PO pas à la fin de la saison") : DISTINCT du
// signal de fin de saison régulière ci-dessus (qui compare déjà objectif et
// rythme provisoire, avec un barème par écart de palier, voir
// computeSeasonObjectivePaceSignal) et du verdict final (seasonObjectiveVerdict
// plus haut) : un troisième événement, à un troisième moment (le tout début
// des play-offs, voir server/autoSim.js:catchUpPlayoffs, League.
// startPlayoffsIfNeeded), un montant FIXE et modeste (jamais calculé par
// écart de palier comme les deux autres, sciemment "petit" comme demandé),
// réservé aux deux objectifs les plus modestes (maintien/milieu-tableau,
// palier 1-2) : une équipe déjà censée jouer les play-offs ou mieux n'a rien
// de "surprise" à se qualifier, ce bonus ne la concerne donc jamais.
const SEASON_OBJECTIVE_SURPRISE_PLAYOFFS_BONUS = 5;

// `null` si l'équipe n'a pas d'objectif assigné, si son objectif n'est pas
// l'un des deux plus modestes (maintien/milieu-tableau), ou si elle ne fait
// pas partie des 4 têtes de série de play-offs (League.playoffs.seeds, posé
// par startPlayoffsIfNeeded) : jamais recalculable a posteriori dans une
// saison sans play-offs pour elle, contrairement aux deux signaux ci-dessus.
function seasonObjectiveSurprisePlayoffsBonus(league, teamIdx) {
  const team = league.teams[teamIdx];
  if (!team || !team.seasonObjective) return null;
  if (team.seasonObjective !== "maintien" && team.seasonObjective !== "milieu-tableau") return null;
  if (!league.playoffs || !Array.isArray(league.playoffs.seeds) || !league.playoffs.seeds.includes(teamIdx)) return null;
  const objectiveLabel = SEASON_OBJECTIVE_LABELS[team.seasonObjective];
  const label = `Qualification surprise en play-offs : personne ne l'attendait vu l'objectif de départ (${objectiveLabel}), les supporters sont agréablement surpris.`;
  return { label, delta: SEASON_OBJECTIVE_SURPRISE_PLAYOFFS_BONUS };
}

// Génère une ligue complète : le club du joueur (déjà créé) + 9 adversaires
// neufs, de force à peu près comparable (légère variation aléatoire). Sans
// niveau de division précisé, on démarre le plus haut possible dans la
// pyramide (Division I) : une nouvelle carrière n'est encore assignée nulle
// part, donc elle prend la place la plus haute disponible plutôt que de
// partir du bas.
//
// NOTE DE CONCEPTION (2026-09, confirmé par l'utilisateur) : ce placement en
// haut de la pyramide est voulu pour la phase actuelle du projet (prototype
// solo, un seul manager réel — le joueur — face à des adversaires générés,
// aucune autre ligue de la pyramide n'étant réellement peuplée/simulée). La
// logique visée pour plus tard, une fois un vrai système multi-utilisateurs
// en place (plusieurs vrais managers, plusieurs ligues par division, un pays
// par pyramide) : au tout début, quand une pyramide ne compte encore aucun
// manager, on peuple PAR LE HAUT (Division I d'abord) pour amorcer le monde ;
// ensuite, une fois des managers déjà en place, un nouveau venu doit plutôt
// atterrir en bas (Division V/VI), le niveau exact dépendant du pays et du
// nombre de managers déjà inscrits dans SA pyramide — jamais recommencer en
// Division I par défaut comme aujourd'hui. Cette logique de placement des
// nouveaux venus n'est pas encore implémentée ici : elle suppose un vrai
// backend multi-ligues/multi-pays qui n'existe pas dans ce prototype (à
// construire quand ce système-là sera à l'ordre du jour).
// ---------------------------------------------------------------------
// CALENDRIER RÉEL — copie CLIENT de la formule pure de server/calendar.js
// (2 matchs de championnat/semaine réelle), pour que moteurbasket3.html
// puisse afficher un compte à rebours ("Prochain match dans Xj Xh") SANS
// dépendre du serveur pour ce simple calcul d'affichage. Ce module
// (engine.js) est ce qui est réellement embarqué côté navigateur (voir la
// synchronisation avec moteurbasket3.html) ; server/calendar.js, lui, reste
// le module autoritaire réellement utilisé par le serveur pour décider
// quand une journée est due (voir server/autoSim.js) — CES DEUX COPIES
// DOIVENT RESTER IDENTIQUES, voir le test croisé dans server/calendar_test.js
// qui compare directement les deux implémentations sur une plage de
// journées.
//
// Le navigateur n'a PAS besoin de recalculer lui-même si un match est "en
// direct" (voir MATCH_BROADCAST_DURATION_MS côté serveur) : c'est le
// serveur qui calcule et stocke la diffusion (`league.liveMatch`, voir
// server/liveMatch.js/serializeLeague ci-dessous) — le navigateur se
// contente de vérifier sa présence pour la journée en préparation.
// ---------------------------------------------------------------------
const CALENDAR_DAY_MS = 24 * 60 * 60 * 1000;
// Calendrier CLASSIQUE (calendrier réel de production) — 2 matchs de
// championnat par semaine réelle, espacés (pas dos à dos). Reste la valeur
// par défaut pour toute ligue qui ne précise pas explicitement un autre
// rythme (voir League.calendarWeekMs/calendarSlotOffsetsMs ci-dessus, et
// generateLeague ci-dessous) — en particulier pour toutes les anciennes
// sauvegardes (calendarWeekMs === null).
const CALENDAR_WEEK_MS = 7 * CALENDAR_DAY_MS;
const CALENDAR_CHAMPIONSHIP_SLOT_OFFSETS_MS = [2 * CALENDAR_DAY_MS, 5 * CALENDAR_DAY_MS];
const CALENDAR_ROUNDS_PER_REAL_WEEK = CALENDAR_CHAMPIONSHIP_SLOT_OFFSETS_MS.length;

// `weekMs`/`slotOffsetsMs` explicites (au lieu des constantes CLASSIQUES
// ci-dessus directement) : c'est ce qui permet à une ligue individuelle de
// tourner sur un rythme différent (voir League.calendarWeekMs/
// calendarSlotOffsetsMs, mode accéléré de test côté serveur) sans jamais
// changer cette formule elle-même — CALENDAR_ROUNDS_PER_REAL_WEEK (le
// NOMBRE de matchs par semaine), lui, ne varie jamais d'un mode à l'autre.
function calendarScheduledTimeForRound(calendarStartAt, round, weekMs = CALENDAR_WEEK_MS, slotOffsetsMs = CALENDAR_CHAMPIONSHIP_SLOT_OFFSETS_MS) {
  const week = Math.floor(round / CALENDAR_ROUNDS_PER_REAL_WEEK);
  const slot = round % CALENDAR_ROUNDS_PER_REAL_WEEK;
  // Correctif (2026-09-25, capture d'écran du calendrier : "07:57" jusqu'au
  // 24 octobre puis "06:57" à partir du 27) : additionner des millisecondes
  // fixes faisait glisser l'heure affichée d'1 h au changement d'heure
  // (heure d'été → hiver le 25 octobre, l'inverse fin mars). Quand le rythme
  // se compte en JOURS entiers (calendrier classique : semaine de 7 jours,
  // créneaux à J+2/J+5), on avance donc en jours CIVILS à Paris en gardant
  // l'heure murale de calendarStartAt — même principe que le calendrier
  // ancré quotidien. Rien ne change hors période de changement d'heure, ni
  // pour le mode accéléré (créneaux de quelques heures, pas des jours
  // entiers). CES COPIES DOIVENT RESTER IDENTIQUES (server/calendar.js,
  // engine.js, moteurbasket3.html, live_2d_demo.html — voir
  // server/calendar_test.js, test croisé).
  if (calendarCountsWholeDays(weekMs, slotOffsetsMs)) {
    return parisWallClockPlusDays(calendarStartAt, (week * weekMs + slotOffsetsMs[slot]) / CALENDAR_DAY_MS);
  }
  return calendarStartAt + week * weekMs + slotOffsetsMs[slot];
}

// Même heure murale (Paris) que `startMs`, `days` jours civils plus tard.
function parisWallClockPlusDays(startMs, days) {
  const p = parisLocalDateParts(startMs);
  const d = addParisCalendarDays(p, days);
  return parisEpochForLocalTime(d.year, d.month, d.day, p.hour, p.minute, p.second) + (((startMs % 1000) + 1000) % 1000);
}
function calendarCountsWholeDays(weekMs, slotOffsetsMs) {
  return weekMs % CALENDAR_DAY_MS === 0 && slotOffsetsMs.every(o => o % CALENDAR_DAY_MS === 0);
}

// Ancre calendarStartAt sur un horaire "propre" (minuit) UNIQUEMENT quand le
// rythme de calendrier tient dans EXACTEMENT une journée (weekMs ===
// CALENDAR_DAY_MS) — ce qui n'est PAS le cas du mode accéléré actuel (voir
// server/calendar.js "MODE ACCÉLÉRÉ", un intervalle glissant de 5h entre
// matchs, weekMs = 10h) : cette fonction ne s'y déclenche donc jamais et
// calendarStartAt y reste l'instant de création exact, ce qui est
// EXACTEMENT ce qu'on veut pour un intervalle glissant (le 1er match tombe
// systématiquement "dans 5h", quelle que soit l'heure de création — pas
// d'ancrage sur une heure de la journée à respecter). Cette fonction reste
// utile si un futur rythme redevenait "N matchs répartis sur UNE journée à
// heures fixes" façon calendrier (ex. 10h/15h, l'ancienne version de ce mode
// accéléré, retour utilisateur 2026-09) : sans cet ancrage sur minuit, les
// créneaux tomberaient à un horaire arbitraire dépendant de l'instant EXACT
// de création (une carrière créée à 14h52 se serait retrouvée avec un 1er
// match à minuit 52 le lendemain plutôt qu'à 10h comme annoncé). L'ancrage
// se fait sur minuit en heure LOCALE de la machine qui exécute ce code — ce
// qui est correct pour un usage solo/local (client et serveur tournent sur
// la même machine, donc le même fuseau horaire), mais resterait à revoir
// pour un vrai multijoueur hébergé (voir server/README.md, "Prochaines
// étapes"). Si le 1er créneau du jour est déjà passé au moment de la
// création, bascule sur le jour suivant pour que le tout premier match
// reste à venir plutôt que déjà écoulé dès la création. Ne change RIEN au
// calendrier classique (semaine de 7 jours) : celui-ci garde l'instant de
// création exact, comme avant.
function anchoredCalendarStartAt(now, calendarConfig) {
  if (!calendarConfig || calendarConfig.weekMs !== CALENDAR_DAY_MS) return now;
  const d = new Date(now);
  d.setHours(0, 0, 0, 0);
  let startOfDay = d.getTime();
  const firstSlotOffset = Array.isArray(calendarConfig.slotOffsetsMs) ? calendarConfig.slotOffsetsMs[0] : 0;
  if (startOfDay + firstSlotOffset <= now) startOfDay += CALENDAR_DAY_MS;
  return startOfDay;
}

// ---------------------------------------------------------------------
// CALENDRIER ANCRÉ QUOTIDIEN — copie CÔTÉ NAVIGATEUR des mêmes formules
// pures que server/calendar.js ("CALENDRIER ANCRÉ QUOTIDIEN", voir le grand
// commentaire là-bas pour pourquoi ce rythme n'est PAS exprimable en simple
// décalage ms fixe comme calendarScheduledTimeForRound ci-dessus) —
// nécessaire au navigateur pour afficher un horaire/compte à rebours de la
// ligue multi-manager sans dépendre du réseau. CES DEUX COPIES DOIVENT
// RESTER IDENTIQUES (voir le test croisé dans server/calendar_test.js, sur
// des dates choisies de part et d'autre d'un changement d'heure à Paris).
// ---------------------------------------------------------------------
const CALENDAR_PARIS_TIME_ZONE = "Europe/Paris";

// Fuseau horaire du calendrier (retour utilisateur, 2026-09-28 : "chaque pays
// a ses propres horaires") : celui de la ligue en cours de traitement — Paris
// par défaut (toutes les ligues d'avant les pays). Posé par le serveur pour
// chaque requête (une seule à la fois, voir le verrou de server/index.js) et
// par le navigateur au chargement de sa ligue (leagueFromSave). Les noms
// "paris…" des fonctions ci-dessous sont historiques : elles travaillent
// dans CE fuseau.
let calendarTimeZone = CALENDAR_PARIS_TIME_ZONE;
function setCalendarTimeZone(tz) { calendarTimeZone = tz || CALENDAR_PARIS_TIME_ZONE; }
function getCalendarTimeZone() { return calendarTimeZone; }
const CALENDAR_DAILY_ANCHORED_CHAMPIONSHIP_HOURS = [10, 19];
const CALENDAR_DAILY_ANCHORED_CUP_HOUR = 15;

// Jour civil visé pour le "jour 0" (voir dailyAnchoredCalendarStartAt plus
// bas), convention Date#getUTCDay (0 = dimanche ... 6 = samedi) : copie de la
// même constante côté serveur (server/calendar.js), retour utilisateur,
// 2026-09, à la réinitialisation d'une ligue multi-manager, "il faut que les
// matchs commencent à partir de mercredi, ça laissera le temps à tout le
// monde pour prendre ses marques et faire des emplettes".
const CALENDAR_DAILY_ANCHORED_FIRST_MATCH_WEEKDAY = 3; // mercredi

function parisUtcOffsetMs(utcMs) {
  const parts = parisLocalDateParts(utcMs);
  const asUtc = Date.UTC(parts.year, parts.month - 1, parts.day, parts.hour, parts.minute, parts.second);
  return asUtc - utcMs;
}

function parisLocalDateParts(utcMs) {
  const dtf = zonedDtf(calendarTimeZone);   // formateur gardé par fuseau

  const map = {};
  dtf.formatToParts(new Date(utcMs)).forEach(p => { if (p.type !== "literal") map[p.type] = p.value; });
  return {
    year: Number(map.year), month: Number(map.month), day: Number(map.day),
    hour: Number(map.hour), minute: Number(map.minute), second: Number(map.second),
  };
}

function addParisCalendarDays(dateParts, days) {
  const d = new Date(Date.UTC(dateParts.year, dateParts.month - 1, dateParts.day));
  d.setUTCDate(d.getUTCDate() + days);
  return { year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate() };
}

// `aMs`/`bMs` tombent-ils le MÊME jour civil à Paris ? Utilisé par
// League.runVideoSession (séance vidéo, voir plus haut) pour son plafond "une
// séance par jour" — même définition de "jour" que le reste du calendrier
// ancré quotidien (parisLocalDateParts ci-dessus), jamais une fenêtre
// glissante de 24h qui dériverait d'une séance à l'autre.
function sameParisCalendarDay(aMs, bMs) {
  const a = parisLocalDateParts(aMs);
  const b = parisLocalDateParts(bMs);
  return a.year === b.year && a.month === b.month && a.day === b.day;
}

// Entier COMPARABLE/TRIABLE identifiant un jour civil à Paris (retour
// utilisateur, 2026-09, voir Team.collectiveTrainingLog/syncCollectiveTrainingLog/
// tacticsCycleStartDayIndex plus haut) : minuit UTC du triplet
// année/mois/jour Paris de `ms` — PAS un vrai instant réel (ignore
// volontairement l'heure locale/le décalage horaire), juste une clé stable
// et strictement croissante d'un jour civil au suivant (toujours exactement
// 24h = 86 400 000 ms d'écart, même autour d'un changement d'heure Paris,
// puisqu'aucune vraie conversion de fuseau n'entre plus en jeu à ce stade).
function parisCalendarDayIndex(ms) {
  const p = parisLocalDateParts(ms);
  return Date.UTC(p.year, p.month - 1, p.day);
}

function parisEpochForLocalTime(year, month, day, hour, minute = 0, second = 0) {
  let guess = Date.UTC(year, month - 1, day, hour, minute, second);
  for (let i = 0; i < 4; i++) {
    const offset = parisUtcOffsetMs(guess);
    const candidate = Date.UTC(year, month - 1, day, hour, minute, second) - offset;
    if (candidate === guess) return candidate;
    guess = candidate;
  }
  return guess;
}

// Fuseau horaire d'un pays (retour utilisateur 2026-09-28 : matchs à 20:00
// heure locale, "oui heure de new york" pour les USA ; la mise à jour
// hebdomadaire reste, elle, à une heure UNIQUE pour tous : lundi 6h à
// Paris). Mêmes principes que parisLocalDateParts/parisEpochForLocalTime
// ci-dessus, pour n'importe quel fuseau IANA. `timeZone` absent = Paris.
// Formateur gardé par fuseau (performance, 2026-10-09 : en recréer un à
// chaque appel coûtait ~40 % du rattrapage du monde).
const ZONED_DTF = new Map();
function zonedDtf(timeZone) {
  const tz = timeZone || "Europe/Paris";
  let dtf = ZONED_DTF.get(tz);
  if (!dtf) {
    dtf = new Intl.DateTimeFormat("en-US", {
      timeZone: tz, hourCycle: "h23",
      year: "numeric", month: "2-digit", day: "2-digit",
      hour: "2-digit", minute: "2-digit", second: "2-digit",
    });
    ZONED_DTF.set(tz, dtf);
  }
  return dtf;
}
function zonedLocalDateParts(utcMs, timeZone) {
  const dtf = zonedDtf(timeZone);
  const map = {};
  dtf.formatToParts(new Date(utcMs)).forEach(p => { if (p.type !== "literal") map[p.type] = p.value; });
  return {
    year: Number(map.year), month: Number(map.month), day: Number(map.day),
    hour: Number(map.hour), minute: Number(map.minute), second: Number(map.second),
  };
}
function zonedEpochForLocalTime(timeZone, year, month, day, hour, minute = 0, second = 0) {
  const wall = Date.UTC(year, month - 1, day, hour, minute, second);
  let guess = wall;
  for (let i = 0; i < 4; i++) {
    const p = zonedLocalDateParts(guess, timeZone);
    const offset = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - guess;
    const candidate = wall - offset;
    if (candidate === guess) return candidate;
    guess = candidate;
  }
  return guess;
}
// Jour civil `dayIndex` après celui de `calendarStartAt`, à l'heure `hour`,
// dans le fuseau `timeZone` (Paris si absent : même résultat que
// dailyAnchoredScheduledTimeForSlot).
function zonedScheduledTimeForSlot(calendarStartAt, dayIndex, hour, timeZone) {
  // Toujours le fuseau EXPLICITE de la ligue (jamais le fuseau « courant »
  // réglé par setCalendarTimeZone, quand il existe) : Paris si absent.
  const tz = timeZone || "Europe/Paris";
  const day0 = zonedLocalDateParts(calendarStartAt, tz);
  const target = dayIndex > 0 ? addParisCalendarDays(day0, dayIndex) : day0;
  return zonedEpochForLocalTime(tz, target.year, target.month, target.day, hour);
}


function dailyAnchoredCalendarConfig() {
  return { dailyAnchored: true, weekly: true };
}

// Nombre de jours civils entre `dateParts` et le prochain jour tombant sur
// `targetWeekday` (convention Date#getUTCDay, 0 = dimanche ... 6 = samedi) :
// 0 si `dateParts` est déjà ce jour-là, sinon 1 à 6. Copie de la même
// fonction côté serveur (server/calendar.js).
function daysUntilParisWeekday(dateParts, targetWeekday) {
  const currentWeekday = new Date(Date.UTC(dateParts.year, dateParts.month - 1, dateParts.day)).getUTCDay();
  return (targetWeekday - currentWeekday + 7) % 7;
}

// Instant réel (epoch ms) du tout premier créneau ("jour 0", 10h à Paris) :
// ancré sur le prochain CALENDAR_DAILY_ANCHORED_FIRST_MATCH_WEEKDAY (mercredi)
// à compter du jour de création `now`, création comprise si elle tombe déjà
// un mercredi avant 10h. Si ce mercredi est aujourd'hui mais que 10h est déjà
// passé, bascule sur le mercredi SUIVANT (+7 jours) plutôt que le lendemain
// (jeudi) : le rythme reste toujours "championnat à partir d'un mercredi".
// Copie de la même fonction côté serveur (server/calendar.js).
function dailyAnchoredCalendarStartAt(now, weekly = false, timeZone = null) {
  if (weekly) return weeklyRhythmCalendarStartAt(now, timeZone);
  const today = parisLocalDateParts(now);
  const daysAhead = daysUntilParisWeekday(today, CALENDAR_DAILY_ANCHORED_FIRST_MATCH_WEEKDAY);
  const nextWednesday = daysAhead > 0 ? addParisCalendarDays(today, daysAhead) : today;
  const firstSlot = parisEpochForLocalTime(nextWednesday.year, nextWednesday.month, nextWednesday.day, CALENDAR_DAILY_ANCHORED_CHAMPIONSHIP_HOURS[0]);
  if (firstSlot > now) return firstSlot;
  const followingWednesday = addParisCalendarDays(today, daysAhead + 7);
  return parisEpochForLocalTime(followingWednesday.year, followingWednesday.month, followingWednesday.day, CALENDAR_DAILY_ANCHORED_CHAMPIONSHIP_HOURS[0]);
}

function dailyAnchoredScheduledTimeForSlot(calendarStartAt, dayIndex, hour) {
  const day0 = parisLocalDateParts(calendarStartAt);
  const target = dayIndex > 0 ? addParisCalendarDays(day0, dayIndex) : day0;
  return parisEpochForLocalTime(target.year, target.month, target.day, hour);
}

function dailyAnchoredDayIndexForChampionshipRound(round) {
  return Math.floor(round / CALENDAR_DAILY_ANCHORED_CHAMPIONSHIP_HOURS.length);
}
function dailyAnchoredSlotIndexForChampionshipRound(round) {
  return round % CALENDAR_DAILY_ANCHORED_CHAMPIONSHIP_HOURS.length;
}
// Bascule EN PLEINE SAISON (retour utilisateur, 2026-09-27 : "bascule en
// pleine saison oui") : une ligue lancée au rythme quotidien passe au rythme
// hebdomadaire sans perdre ce qui est déjà joué. `sw` =
// League.calendarWeeklySwitch = { fromRound, fromCupRound, anchorAt } : les
// journées < fromRound (et tours de coupe < fromCupRound) gardent leur date
// quotidienne d'origine ; la suite suit le rythme hebdomadaire à partir du
// mardi `anchorAt` (journée fromRound = ce mardi, etc.). null pour une ligue
// créée directement au rythme hebdomadaire.
// `poFromRound` (optionnel) : première journée de play-offs (= nombre de
// journées de saison régulière, League.totalRounds) — au rythme
// hebdomadaire, les play-offs se jouent mardi, jeudi et samedi (voir
// weeklyRhythmDayIndexForChampionshipRound). Absent : même règle que la
// saison régulière (mardi/samedi).
function dailyAnchoredScheduledTimeForChampionshipRound(calendarStartAt, round, weekly = false, sw = null, poFromRound = null, timeZone = null) {
  if (weekly && sw && typeof sw.anchorAt === "number") {
    if (round >= sw.fromRound) return weeklyRhythmScheduledTimeForChampionshipRound(sw.anchorAt, round - sw.fromRound, poFromRound != null ? Math.max(0, poFromRound - sw.fromRound) : null, timeZone);
  } else if (weekly) return weeklyRhythmScheduledTimeForChampionshipRound(calendarStartAt, round, poFromRound, timeZone);
  const dayIndex = dailyAnchoredDayIndexForChampionshipRound(round);
  const hour = CALENDAR_DAILY_ANCHORED_CHAMPIONSHIP_HOURS[dailyAnchoredSlotIndexForChampionshipRound(round)];
  return dailyAnchoredScheduledTimeForSlot(calendarStartAt, dayIndex, hour);
}
function dailyAnchoredScheduledTimeForCupRound(calendarStartAt, cupDayIndex, weekly = false, sw = null, timeZone = null) {
  if (weekly && sw && typeof sw.anchorAt === "number") {
    if (cupDayIndex >= sw.fromCupRound) return weeklyRhythmScheduledTimeForCupRound(sw.anchorAt, cupDayIndex - sw.fromCupRound, timeZone);
  } else if (weekly) return weeklyRhythmScheduledTimeForCupRound(calendarStartAt, cupDayIndex, timeZone);
  return dailyAnchoredScheduledTimeForSlot(calendarStartAt, cupDayIndex, CALENDAR_DAILY_ANCHORED_CUP_HOUR);
}

// ---------------------------------------------------------------------
// RYTHME HEBDOMADAIRE (retour utilisateur, 2026-09-27 : "on va changer le
// code pour que les matchs de championnat soient [...] mardi et samedi, la
// coupe le jeudi", "matchs à 20h", "l'économie est à mettre à jour dans la
// nuit du dimanche au lundi", play-offs "2 matchs par semaine" pour laisser
// le jeudi à la coupe) — variante du calendrier ancré ci-dessus, activée par
// League.calendarWeeklyRhythm (posé à la création de la ligue, jamais changé
// en cours de saison : les dates sont recalculées à partir de calendarStartAt,
// une ligue déjà lancée garde donc son rythme quotidien jusqu'au reset).
//   - jour 0 = un MARDI à 20h (calendarStartAt) ;
//   - journée r : semaine floor(r/2), mardi (r pair) ou samedi (r impair),
//     20h ; play-offs (journées >= totalRounds) : mardi, jeudi et samedi à
//     partir du mardi suivant (voir weeklyRhythmDayIndexForChampionshipRound) ;
//   - tour de coupe k : jeudi de la semaine k, 20h ;
//   - mise à jour économique k (k >= 1) : lundi 0h00 de la semaine k (nuit
//     du dimanche au lundi), voir server/autoSim.js:catchUpWeeklyRhythm.
// CES COPIES DOIVENT RESTER IDENTIQUES (server/calendar.js, engine.js,
// moteurbasket3.html, live_2d_demo.html).
// ---------------------------------------------------------------------
const WEEKLY_RHYTHM_MATCH_HOUR = 20;
const WEEKLY_RHYTHM_FIRST_MATCH_WEEKDAY = 2; // mardi (Date#getUTCDay)
const WEEKLY_RHYTHM_CHAMPIONSHIP_DAY_OFFSETS = [0, 4]; // mardi, samedi (depuis le mardi)
const WEEKLY_RHYTHM_PLAYOFF_DAY_OFFSETS = [0, 2, 4]; // play-offs : mardi, jeudi, samedi
const WEEKLY_RHYTHM_CUP_DAY_OFFSET = 2; // jeudi
const WEEKLY_RHYTHM_ECONOMY_DAY_OFFSET = 6; // lundi (fin de la nuit du dimanche)
const WEEKLY_RHYTHM_ECONOMY_HOUR = 6; // lundi 6h à Paris, pour tous les pays (validé 2026-09-28)

// Prochain mardi à 20h (Paris) à compter de `now`, aujourd'hui compris si
// l'on est mardi avant 20h.
function weeklyRhythmCalendarStartAt(now, timeZone = null) {
  const tz = timeZone || "Europe/Paris";
  const today = zonedLocalDateParts(now, tz);
  const weekday = new Date(Date.UTC(today.year, today.month - 1, today.day)).getUTCDay();
  const daysAhead = (WEEKLY_RHYTHM_FIRST_MATCH_WEEKDAY - weekday + 7) % 7;
  const day = daysAhead > 0 ? addParisCalendarDays(today, daysAhead) : today;
  const first = zonedEpochForLocalTime(tz, day.year, day.month, day.day, WEEKLY_RHYTHM_MATCH_HOUR);
  if (first > now) return first;
  const next = addParisCalendarDays(today, daysAhead + 7);
  return zonedEpochForLocalTime(tz, next.year, next.month, next.day, WEEKLY_RHYTHM_MATCH_HOUR);
}
// Play-offs (retour utilisateur, 2026-09-27 : "les PO doivent se jouer le
// mardi jeudi et samedi" ; "la coupe sera tjrs terminée pour les PO car max
// 512 équipes") : à partir de `poFromRound`, 3 matchs par semaine (mardi,
// jeudi, samedi) en commençant le mardi qui suit la dernière journée de
// saison régulière — demi-finales puis finale en deux matchs gagnants
// tiennent donc toujours en 2 semaines (saison = 9 + 2 = 11 semaines).
function weeklyRhythmDayIndexForChampionshipRound(round, poFromRound = null) {
  const n = WEEKLY_RHYTHM_CHAMPIONSHIP_DAY_OFFSETS.length;
  if (poFromRound != null && round >= poFromRound) {
    const m = WEEKLY_RHYTHM_PLAYOFF_DAY_OFFSETS.length;
    const i = round - poFromRound;
    return 7 * (Math.ceil(poFromRound / n) + Math.floor(i / m)) + WEEKLY_RHYTHM_PLAYOFF_DAY_OFFSETS[i % m];
  }
  return 7 * Math.floor(round / n) + WEEKLY_RHYTHM_CHAMPIONSHIP_DAY_OFFSETS[round % n];
}
function weeklyRhythmScheduledTimeForChampionshipRound(calendarStartAt, round, poFromRound = null, timeZone = null) {
  return zonedScheduledTimeForSlot(calendarStartAt, weeklyRhythmDayIndexForChampionshipRound(round, poFromRound), WEEKLY_RHYTHM_MATCH_HOUR, timeZone);
}
function weeklyRhythmScheduledTimeForCupRound(calendarStartAt, cupRoundIndex, timeZone = null) {
  return zonedScheduledTimeForSlot(calendarStartAt, 7 * cupRoundIndex + WEEKLY_RHYTHM_CUP_DAY_OFFSET, WEEKLY_RHYTHM_MATCH_HOUR, timeZone);
}
// Instant de la k-ième mise à jour économique (k >= 1).
// Heure UNIQUE pour tous les pays (lundi 6h à Paris, soit minuit à New
// York) : le lundi est pris dans le fuseau de la ligue (celui de son mardi
// de départ), l'heure à Paris — toutes les ligues du monde basculent donc au
// même instant, sans joueur qui vieillit deux fois ou pas du tout.
function weeklyRhythmEconomyTickAt(calendarStartAt, k, timeZone = null) {
  const day0 = zonedLocalDateParts(calendarStartAt, timeZone || "Europe/Paris");
  const monday = addParisCalendarDays(day0, 7 * (k - 1) + WEEKLY_RHYTHM_ECONOMY_DAY_OFFSET);
  return zonedEpochForLocalTime("Europe/Paris", monday.year, monday.month, monday.day, WEEKLY_RHYTHM_ECONOMY_HOUR);
}

// Bascule EN PLEINE SAISON d'une ligue au rythme quotidien vers le rythme
// hebdomadaire (retour utilisateur, 2026-09-27 : "bascule en pleine saison
// oui"), appelée par server/index.js:tick. Idempotente (no-op si la ligue
// est déjà hebdomadaire, sans calendrier ancré, ou saison terminée). Ce qui
// est déjà joué garde sa date ; un match dont le créneau quotidien a déjà
// commencé (diffusion en cours) se termine à son heure d'origine ; tout le
// reste repart du prochain mardi 20h. Renvoie le réglage appliqué ou null.
// Remise à 100 de la forme physique de TOUS les joueurs (toutes les équipes,
// humaines et CPU, pour rester équitable), en une seule fois par ligue —
// retour utilisateur, 2026-09-27 : "peux-tu réinitialiser les formes des
// joueurs ?" (fatigue accumulée pendant le rythme quotidien, 2 matchs par
// jour, avant la bascule hebdomadaire). `key` identifie l'opération dans
// League.maintenanceDone pour ne jamais la rejouer. Renvoie le nombre de
// joueurs remis à neuf, ou 0 si déjà fait.
function resetAllPlayerConditionsOnce(league, key, now = Date.now()) {
  if (!league || !Array.isArray(league.teams)) return 0;
  if (!league.maintenanceDone) league.maintenanceDone = {};
  if (league.maintenanceDone[key]) return 0;
  let n = 0;
  league.teams.forEach(team => (team.players || []).forEach(p => {
    p.condition = 100;
    p.conditionUpdatedAt = now;
    n++;
  }));
  league.maintenanceDone[key] = now;
  return n;
}

function migrateLeagueToWeeklyRhythm(league, now = Date.now()) {
  if (!league || !league.calendarDailyAnchored || league.calendarWeeklyRhythm) return null;
  if (typeof league.calendarStartAt !== "number") return null;
  if (league.isPlayoffsDone && league.isPlayoffsDone()) return null;
  const start = league.calendarStartAt;
  let fromRound;
  if (!league.isRegularSeasonDone()) fromRound = league.round;
  else fromRound = league.playoffs ? league.playoffs.round : league.totalRounds;
  if (dailyAnchoredScheduledTimeForChampionshipRound(start, fromRound) <= now) fromRound += 1;
  let fromCupRound;
  const pending = league.pendingCupRound ? league.pendingCupRound() : null;
  if (pending) {
    fromCupRound = pending.dayIndex;
    if (dailyAnchoredScheduledTimeForCupRound(start, fromCupRound) <= now) fromCupRound += 1;
  } else {
    const rounds = (league.cup && league.cup.rounds) || [];
    fromCupRound = rounds.length ? rounds[rounds.length - 1].dayIndex + 1 : 0;
  }
  // Prochain mardi 20h, après le dernier créneau quotidien conservé (un match
  // en cours de diffusion garde son heure).
  const keptUntil = Math.max(now,
    fromRound > 0 ? dailyAnchoredScheduledTimeForChampionshipRound(start, fromRound - 1) : now,
    fromCupRound > 0 ? dailyAnchoredScheduledTimeForCupRound(start, fromCupRound - 1) : now);
  const anchorAt = weeklyRhythmCalendarStartAt(keptUntil);
  league.calendarWeeklySwitch = { fromRound, fromCupRound, anchorAt, switchedAt: now };
  league.calendarWeeklyRhythm = true;
  league.lastEconomyTick = 0;
  return league.calendarWeeklySwitch;
}

// `calendarConfig` optionnel ({weekMs, slotOffsetsMs}) : le rythme de
// calendrier à figer pour CETTE ligue (voir League.calendarWeekMs/
// calendarSlotOffsetsMs) — `null`/absent = calendrier classique. Permet au
// serveur (voir server/store.js, mode accéléré de test) de générer une
// ligue sur un autre rythme, et à une nouvelle saison (voir startNewSeason
// côté navigateur) d'hériter explicitement du rythme de la saison
// précédente plutôt que de retomber sur le classique par défaut.
// Coeur commun à generateLeague (UN seul manager humain, historique — son
// équipe est déjà construite/personnalisée par l'appelant) et
// generateMultiManagerLeague (1 à 10 managers humains, équipes construites à
// la volée à partir de simples noms, voir plus bas) : construit une ligue à
// 10 équipes à partir d'équipes humaines DÉJÀ CONSTRUITES (`humanTeams`,
// isHuman déjà à `true` dessus) complétées par autant d'adversaires CPU que
// nécessaire pour arriver à 10 (voir CPU_TEAM_NAMES — au plus 9 nécessaires,
// exactement ce tableau contient). Les deux chemins d'appel restent ainsi
// IDENTIQUES sur tout ce qui ne concerne pas la construction de l'équipe
// humaine elle-même : génération des adversaires CPU, calendrier réel...
// — un seul endroit à faire évoluer si ça change.
// `opts` (2026-09-28, championnats par pays, voir generateCountryLeague) :
// { country, cpuNames } — pays du championnat (joueurs et clubs CPU) et noms
// des clubs CPU à utiliser ; `humanTeams` peut alors être vide (championnat
// entièrement CPU, en attente de managers).
function buildLeagueWithHumanTeams(humanTeams, divisionLevel, now, calendarConfig, opts = {}) {
  const allowEmpty = !!opts.country;
  if (!Array.isArray(humanTeams) || humanTeams.length < (allowEmpty ? 0 : 1) || humanTeams.length > 10) {
    throw new Error("humanTeams doit contenir entre 1 et 10 équipes.");
  }
  const country = opts.country || "fr";
  const info = divisionInfo(divisionLevel);
  const cpuCount = 10 - humanTeams.length;
  const cpuNames = Array.isArray(opts.cpuNames) ? opts.cpuNames : CPU_TEAM_NAMES;
  const opponents = cpuNames.slice(0, cpuCount).map(name => {
    const t = generateTeam(name, info.tierMultiplier * rand(0.9, 1.15), country);
    t.offensivePriorities = pick([
      ["Jeu extérieur", "Jeu en mouvement", "Équilibrée"],
      ["Jeu en pénétration", "Pick & Roll", "Transition rapide"],
      ["Jeu intérieur", "Équilibrée", "Jeu en mouvement"],
    ]);
    return t;
  });
  const league = new League([...humanTeams, ...opponents]);
  league.seasonId = randomHexToken(4);
  // Interview d'avant-saison (correctif 2026-09, voir le grand commentaire
  // de Team.queueSeasonPreviewInterview) : posée ici plutôt que dans
  // generateLeague/generateMultiManagerLeague séparément pour couvrir
  // UNIFORMÉMENT les trois chemins qui passent par ce point commun (nouvelle
  // carrière solo, nouvelle saison solo via startNewSeason, ET création
  // d'une ligue partagée à plusieurs managers).
  humanTeams.forEach(team => team.queueSeasonPreviewInterview(now));
  // Objectif de saison du conseil d'administration (voir le grand
  // commentaire au-dessus de SEASON_OBJECTIVE_TIERS) : posé ici pour la
  // même raison que l'interview d'avant-saison juste au-dessus, une fois
  // TOUTES les équipes (humaines ET CPU) présentes dans `league.teams`,
  // seul moment où l'on peut comparer leur niveau les unes aux autres.
  assignSeasonObjectives(league);
  league.divisionLevel = info.level;
  league.country = country;
  // Contrats de départ (demande du 2026-10-01) : 1 à 5 saisons selon l'âge.
  league.ensureContracts();
  // Le calendrier réel d'une nouvelle saison démarre maintenant (voir
  // League.calendarStartAt ci-dessus, et server/calendar.js pour le détail
  // du rythme réel qui s'appuie dessus) — `now` explicite (comme
  // partout ailleurs pour tout ce qui touche au temps réel, voir
  // TRANSFER_AUCTION_DURATION_MS) plutôt qu'un Date.now() implicite, pour
  // rester testable de façon déterministe.
  // Calendrier ancré quotidien (voir League.calendarDailyAnchored et le
  // grand commentaire au-dessus de dailyAnchoredCalendarConfig ci-dessus) :
  // un rythme à part, jamais exprimable via calendarWeekMs/
  // calendarSlotOffsetsMs (qui restent `null` dans ce cas) — voir
  // generateMultiManagerLeague, seul appelant qui passe jamais ce marqueur.
  league.calendarDailyAnchored = !!(calendarConfig && calendarConfig.dailyAnchored);
  league.calendarWeeklyRhythm = league.calendarDailyAnchored && !!(calendarConfig && calendarConfig.weekly);
  if (league.calendarDailyAnchored) {
    league.calendarStartAt = dailyAnchoredCalendarStartAt(now, league.calendarWeeklyRhythm, (opts && opts.timeZone) || null);
    league.calendarWeekMs = null;
    league.calendarSlotOffsetsMs = null;
  } else {
    league.calendarStartAt = anchoredCalendarStartAt(now, calendarConfig);
    league.calendarWeekMs = calendarConfig && typeof calendarConfig.weekMs === "number" ? calendarConfig.weekMs : null;
    league.calendarSlotOffsetsMs = calendarConfig && Array.isArray(calendarConfig.slotOffsetsMs) ? calendarConfig.slotOffsetsMs : null;
  }
  return league;
}

function generateLeague(userTeam, divisionLevel = 1, now = Date.now(), calendarConfig = null) {
  userTeam.isHuman = true;
  // Ne régénère JAMAIS un jeton si l'appelant en avait déjà un (ex. une
  // équipe reconstruite depuis une sauvegarde, voir server/store.js) — voir
  // Team.managerLinkToken.
  if (!userTeam.managerLinkToken) userTeam.managerLinkToken = randomHexToken(24);
  return buildLeagueWithHumanTeams([userTeam], divisionLevel, now, calendarConfig);
}

// Ligue à PLUSIEURS managers humains (retour utilisateur, 2026-09 : "jusqu'à
// 10 vrais managers humains dans une ligue partagée à la fois, le reste
// comblé par des adversaires CPU"). `managerTeamNames` : 1 à 10 noms de club
// (un par manager réel qui s'est inscrit) — chacun devient une équipe humaine
// fraîche (effectif de débutants, voir generateStartingRoster) avec SON
// PROPRE managerLinkToken (voir randomHexToken), complétée par autant
// d'adversaires CPU (CPU_TEAM_NAMES, dans l'ordre) qu'il en faut pour
// atteindre 10 équipes au total. Partage tout le reste (adversaires CPU,
// calendrier réel) avec generateLeague via buildLeagueWithHumanTeams
// ci-dessus.
// Championnat ENTIÈREMENT CPU d'un pays (2026-09-28, voir WORLD_COUNTRIES et
// server/world.js) : 10 clubs CPU du pays, au niveau `divisionLevel`, groupe
// `group` (0 = A, 1 = B… quand la division compte plusieurs championnats).
// `usedNames` (Set) : noms de clubs déjà pris dans le pays, jamais réutilisés.
// Le calendrier (rythme hebdomadaire de la ligue partagée) est calculé dans
// le fuseau du pays : l'appelant n'a rien à régler.
function generateCountryLeague(country, divisionLevel = 1, group = 0, now = Date.now(), usedNames = new Set(), calendarConfig = { dailyAnchored: true, weekly: true }) {
  const info = countryInfo(country);
  const pool = COUNTRY_CPU_TEAM_NAMES[info.code] || [];
  const names = pool.filter(n => !usedNames.has(n));
  let k = 2;
  while (names.length < 10) names.push(`${pool[names.length % pool.length] || "Club"} ${k++}`);
  const chosen = names.slice(0, 10);
  chosen.forEach(n => usedNames.add(n));
  const previousTz = getCalendarTimeZone();
  setCalendarTimeZone(info.timeZone);
  try {
    const league = buildLeagueWithHumanTeams([], divisionLevel, now, calendarConfig, { country: info.code, cpuNames: chosen, timeZone: info.timeZone });
    league.timeZone = info.timeZone;
    league.divisionGroup = group;
    league.leagueId = worldLeagueId(info.code, divisionLevel, group);
    if (league.calendarDailyAnchored) league.cup = null; // coupe nationale : plus tard (réunit tout le pays)
    return league;
  } finally {
    setCalendarTimeZone(previousTz);
  }
}

// Identifiant stable d'un championnat du monde : "fr-1", "fr-2b", "us-3c"…
// (lettre du groupe dès qu'une division compte plusieurs championnats ; la
// Division I n'en a qu'un). "fr-1" est la ligue partagée historique.
function worldLeagueId(country, divisionLevel, group = 0) {
  // Numérotation BuzzerBeater (2026-09-28) : fr-1, fr-2.1, fr-2.2… fr-6.243.
  return divisionLevel === 1 ? `${country}-1` : `${country}-${divisionLevel}.${group + 1}`;
}

function generateMultiManagerLeague(managerTeamNames, divisionLevel = 1, now = Date.now(), calendarConfig = null) {
  if (!Array.isArray(managerTeamNames) || managerTeamNames.length < 1 || managerTeamNames.length > 10) {
    throw new Error("generateMultiManagerLeague : managerTeamNames doit contenir entre 1 et 10 noms.");
  }
  const humanTeams = managerTeamNames.map(name => {
    const team = generateStartingRoster(name);
    team.isHuman = true;
    team.managerLinkToken = randomHexToken(24);
    return team;
  });
  const league = buildLeagueWithHumanTeams(humanTeams, divisionLevel, now, calendarConfig);
  // Coupe (voir le grand commentaire au-dessus de generateCupBracket) :
  // seulement pour le calendrier ancré quotidien (League.calendarDailyAnchored
  // — voir buildLeagueWithHumanTeams), qui seul lui réserve un créneau réel
  // (15h) où la faire vivre. Toujours les 10 équipes de la ligue (humaines
  // ET CPU, voir buildLeagueWithHumanTeams qui complète toujours à 10) —
  // jamais seulement managerTeamNames.
  if (league.calendarDailyAnchored) {
    league.cup = { rounds: [generateCupBracket(league.teams.map((_, i) => i))], champion: null };
  }
  return league;
}

// ---------------------------------------------------------------------
// SÉRIALISATION (sauvegarde/chargement) — partagée entre le client
// (navigateur, via l'API du serveur : voir saveMyTeam/loadMyTeam dans
// moteurbasket3.html) et le serveur lui-même (voir server/store.js, qui
// écrit un fichier JSON) : UNE SEULE version de cette logique, ici dans le
// moteur, plutôt que
// deux copies qui risquent de diverger. C'est exactement ce genre de
// divergence qui a causé le bug "mes joueurs ne progressent pas avec
// l'entrainement" (retour utilisateur, 2026-09) : `secondsPlayedByPosition`
// oublié dans UNE des deux copies (celle-ci n'existait alors que côté
// client) suffisait à casser l'entraînement après chaque rechargement. En la
// centralisant ici, un correctif ne peut plus être appliqué à une copie et
// oublié dans l'autre.
// ---------------------------------------------------------------------
// Forme commune d'un joueur sauvegardé — factorisée pour que serializeTeam
// (effectif pro, ci-dessous) ET l'académie de jeunes (youthCandidates/
// youthPlayers, mêmes champs) ne laissent jamais diverger la forme d'un
// enregistrement de joueur entre les deux. Voir playerFromSave plus bas pour
// la restauration (même logique de repli, partagée elle aussi).
function serializePlayerRecord(p) {
  return {
    name: p.name, nationality: p.nationality, position: p.position, height: p.height, age: p.age,
    attrs: { ...p.attrs }, potential: p.potential, salary: p.salary,
    // Numéro de maillot, apparence choisie, club formateur (voir le bloc
    // PREMIUM « personnalisation »).
    number: Number.isInteger(p.number) ? p.number : null, look: normalizePlayerLook(p.look), homegrownClub: p.homegrownClub || null,
    roleHistory: Array.isArray(p.roleHistory) ? p.roleHistory.slice(-ROLE_HISTORY_MAX) : [],
    // Plafonds physique/mental, caractéristique par caractéristique (voir
    // Player.physicalPotential/mentalPotential, retour utilisateur 2026-09 :
    // "le physique ne bouge qu'un peu [...] le mental peut bien évoluer") :
    // fixés une fois pour toutes à la génération, comme `potential`
    // ci-dessus, DOIVENT survivre au rechargement, sinon la progression
    // naturelle hebdomadaire (Player.trainWeek) viserait un plafond redéfini
    // au hasard à chaque chargement de la sauvegarde.
    physicalPotential: { ...p.physicalPotential }, mentalPotential: { ...p.mentalPotential },
    // Connaissance tactique individuelle (voir PLAYER_TACTICAL_KNOWLEDGE_GAIN_BASE).
    ...(p.tacticalKnowledge && p.tacticalKnowledge.offense ? { tacticalKnowledge: copyTacticalKnowledge(p.tacticalKnowledge) } : {}),
    // `effectivePosition` (voir Player.constructor/levelCoefficientFor) :
    // DOIT être sauvegardé au même rythme que `salary` juste au-dessus
    // (retour utilisateur, 2026-09 : "le poste est fixé en début de saison
    // selon les caracs et il ne doit ensuite plus bouger [...] corrigé
    // seulement lors de l'intersaison"), sans ce champ, playerFromSave
    // restaurait bien `salary` mais PAS `effectivePosition`, qui repartait
    // alors du constructeur Player, lequel le recalcule TOUJOURS d'après les
    // attributs ACTUELS (voir plus bas) : un simple rechargement de page en
    // cours de saison (après quelques gains d'entraînement) suffisait à
    // faire "changer de poste" l'étiquette/l'infobulle du salaire affichées,
    // alors que le salaire réellement payé restait, lui, correctement figé.
    effectivePosition: p.effectivePosition,
    previousCardPosition: p.previousCardPosition || null,
    _trainProgress: { ...p._trainProgress },
    aggressiveness: p.aggressiveness, form: p.form,
    // Forme physique (voir CONDITION_STATES/currentCondition plus haut) :
    // conditionUpdatedAt DOIT être persisté avec condition (pas juste la
    // valeur brute), sinon la récupération se rattraperait d'un coup, en
    // trop, au prochain chargement (calculée depuis "maintenant" au lieu du
    // dernier vrai point de mise à jour).
    condition: p.condition, conditionUpdatedAt: p.conditionUpdatedAt,
    // Blessure PERSISTANTE (voir INJURY_TYPES/rollInjury/isCurrentlyInjured
    // plus haut) : DOIT survivre au rechargement, sinon un simple
    // redémarrage suffirait à "guérir" instantanément un joueur, contraire
    // au principe même d'une indisponibilité qui dure plusieurs jours
    // réels. `null` par défaut (pas blessé) — jamais omis, contrairement à
    // `injured` (état de match transitoire, jamais sérialisé).
    injuryType: p.injuryType ?? null, injuryUntil: p.injuryUntil ?? null,
    forSale: p.forSale, salePrice: p.salePrice,
    // Temps de jeu du DERNIER match, ventilé par poste (voir
    // Player.secondsPlayedByPosition) : sans ces deux champs, un
    // redémarrage/rechargement entre un match joué et le prochain effacerait
    // le détail du dernier match (matchLog, box-score) — un rechargement de
    // page ne devrait jamais, à lui seul, effacer le mérite du dernier match
    // joué (retour utilisateur d'origine : "mes joueurs ne progressent pas
    // avec l'entrainement").
    secondsPlayed: p.secondsPlayed,
    secondsPlayedByPosition: { ...p.secondsPlayedByPosition },
    // Même raison, mais pour Player.trainingSecondsPlayedByPosition (voir son
    // commentaire au constructeur) : SEUL champ désormais lu par
    // Team.trainablySecondsFor, cumulé sur tout un cycle d'entraînement
    // (jusqu'à 3 matchs, calendrier ancré quotidien). Sans lui, un
    // rechargement entre deux des trois matchs du jour effacerait la part
    // déjà accumulée.
    trainingSecondsPlayedByPosition: { ...p.trainingSecondsPlayedByPosition },
    // Retour utilisateur (2026-09) : "le match 3 n'affiche aucune stats
    // hormis les minutes [...] généralisé à d'autres équipes et autres
    // joueurs". Cause : p.stats n'était JAMAIS sauvegardé alors que
    // p.secondsPlayed l'est déjà (voir commentaire ci-dessus). Un
    // redémarrage serveur survenant entre le coup d'envoi d'un match EN
    // DIRECT (qui remplit p.stats/p.secondsPlayed via MatchEngine.simulate,
    // voir computeLiveMatch) et sa finalisation (qui lit CES MÊMES champs,
    // voir recordMatchStatsForTeam) faisait perdre p.stats au rechargement
    // (reparti de emptyStats() via le constructeur Player) sans toucher
    // p.secondsPlayed (restauré ci-dessous) : d'où des entrées de
    // matchLog avec des minutes correctes mais toutes les autres stats à
    // zéro. Même rythme de persistance que secondsPlayed ci-dessus.
    stats: { ...p.stats },
    id: p.id,
    // Journal des matchs de la saison (voir Player.matchLog/
    // recordMatchStatsForTeam) : DOIT survivre au rechargement, sinon les
    // stats de saison/MVP (onglet Ligue) et les pages joueur repartiraient
    // de zéro à chaque redémarrage du serveur. Chaque entrée peut désormais
    // porter isMvp/mvpQuote (voir awardMatchMvp) : déjà inclus par ce spread
    // superficiel, aucun champ à lister explicitement.
    matchLog: Array.isArray(p.matchLog) ? p.matchLog.map(m => ({ ...m })) : [],
    // Lignes de match d'un autre championnat (voir pruneForeignMatchLogs) :
    // jamais supprimées, seulement mises de côté.
    ...(Array.isArray(p.archivedMatchLog) && p.archivedMatchLog.length ? { archivedMatchLog: p.archivedMatchLog.map(m => ({ ...m })) } : {}),
    // Bonus temporaire de MVP (voir Player.pendingMatchBoost/MVP_ATTR_BONUS/
    // awardMatchMvp) : DOIT survivre au rechargement, sinon un redémarrage
    // serveur entre l'élection au MVP et le prochain match de ce joueur lui
    // ferait perdre le bonus promis.
    pendingMatchBoost: p.pendingMatchBoost || 0,
    // Demande de transfert (voir le grand commentaire de
    // TRANSFER_REQUEST_MOTIVATION_THRESHOLD) : DOIT survivre au
    // rechargement, sinon un simple redémarrage "réconcilierait" à tort un
    // joueur qui a publiquement demandé son transfert.
    weeksAtLowMotivation: p.weeksAtLowMotivation || 0,
    transferRequestActive: !!p.transferRequestActive,
    transferRequestQuote: p.transferRequestQuote ?? null,
    transferRequestDiscussed: !!p.transferRequestDiscussed,
    // Distinctions de fin de saison et carrière saison par saison (voir
    // awardSeasonHonours).
    awards: Array.isArray(p.awards) ? p.awards.map(a => ({ ...a })) : [],
    careerSeasons: Array.isArray(p.careerSeasons) ? p.careerSeasons.map(c => ({ ...c })) : [],
    progressLog: Array.isArray(p.progressLog) ? p.progressLog.map(x => ({ ...x })) : [],
    // Historique hebdomadaire (permaliens joueur, 2026-10-01) : [saison,
    // semaine, note, ...caractéristiques dans l'ordre d'ATTRS], voir
    // pushPlayerHistory. Suit le joueur d'un club à l'autre.
    weeklyHistory: Array.isArray(p.weeklyHistory) ? p.weeklyHistory.map(e => e.slice()) : [],
    ...(Array.isArray(p.historyLog) && p.historyLog.length ? { historyLog: p.historyLog.map(e => ({ ...e })) } : {}),
    ...(typeof p.clubSinceSeason === "number" ? { clubSinceSeason: p.clubSinceSeason } : {}),
    ...(Array.isArray(p.injuryHistory) && p.injuryHistory.length ? { injuryHistory: p.injuryHistory.map(e => ({ ...e })) } : {}),
    // Retraite (voir RETIREMENT_ANNOUNCE_CHANCE_BY_AGE).
    retiringAfterSeason: !!p.retiringAfterSeason,
    // Périodes avec sa sélection nationale (voir isOnNationalDuty).
    ...(Array.isArray(p.nationalDuty) && p.nationalDuty.length ? { nationalDuty: p.nationalDuty.map(d => ({ from: d.from, to: d.to, gid: d.gid || null, team: d.team || null })) } : {}),
    retirementWeeks: p.retirementWeeks || 0,
    retirementTalks: Array.isArray(p.retirementTalks) ? p.retirementTalks.slice() : [],
    retirementQuote: p.retirementQuote ?? null,
    // Garde-fou de vieillissement (voir Team.trainWeek, opts.seasonNo).
    lastAgedSeasonNo: typeof p.lastAgedSeasonNo === "number" ? p.lastAgedSeasonNo : null,
    // Contrat (voir CONTRACT_MIN_SEASONS, demande du 2026-10-01).
    contractUntilSeason: typeof p.contractUntilSeason === "number" ? p.contractUntilSeason : null,
    nextSalary: typeof p.nextSalary === "number" ? p.nextSalary : null,
    lastContractOfferWeek: typeof p.lastContractOfferWeek === "number" ? p.lastContractOfferWeek : null,
    contractRefusals: p.contractRefusals || 0,
    ...(p.salaryGrid ? { salaryGrid: p.salaryGrid } : {}),
    raiseRequest: p.raiseRequest ? { ...p.raiseRequest } : null,
    raiseRequestSeason: typeof p.raiseRequestSeason === "number" ? p.raiseRequestSeason : null,
    extensionRequestSeason: typeof p.extensionRequestSeason === "number" ? p.extensionRequestSeason : null,
  };
}

// Copie du rapport hebdomadaire d'entraînement (voir Team.lastTrainingReport/
